def cleanup_ibid_state():

    """Clean ibid_state.json by removing old data, large entries, and redundant keys.
    Returns number of keys removed and bytes saved."""

    if not os.path.exists(PERSIST_FILE):
        return 0, 0

    try:
        with open(PERSIST_FILE, "r", encoding="utf-8") as f:
            state = json.load(f)

        original_size = os.path.getsize(PERSIST_FILE)
        keys_before = len(state)

        # Keys to remove (old data, large objects, temp state)
        KEYS_TO_REMOVE = {
            # Large data (loaded from JSON files)
            "DAILY_DATA", "daily_data", "WEEKLY_DATA", "weekly_data",
            "BD_BROYEUR_DAILY", "BD_BROYEUR_WEEKLY", "BD_BROYEUR_MONTHLY",
            "BD_CONSO_MATIERES_DAILY", "BD_CONSO_MATIERES_WEEKLY", "BD_CONSO_MATIERES_MONTHLY",
            "BD_EXPEDITION_DAILY", "BD_EXPEDITION_WEEKLY", "BD_EXPEDITION_MONTHLY",
            "HISTORICAL_FINANCIAL_DATA", "SCENARIO_HISTORY", "BUDGET_SCENARIOS",
            "ibid_evolution_records", "ibid_data_records", "ibid_all_records",
            "ibid_silo_stock_records",
            # Temp/cache keys
            "_daily_data_json_mtime", "_cache_version",
            # Old/legacy keys
            "ibid_kpis_charts", "ibid_full_charts_html", "ibid_export_html",
            # AI search results (regenerated each time)
            "ai_search_result", "ai_search_query", "ai_search_show_result",
            # Button/widget states
            "ibid_logout_btn", "ibid_login_btn", "ibid_unlock_btn", "ibid_lock_btn",
            "ibid_lock_from_active_btn",
        }

        # Remove keys
        removed = 0
        for key in KEYS_TO_REMOVE:
            if key in state:
                del state[key]
                removed += 1

        # Remove large values (>100KB each)
        for key in list(state.keys()):
            val_str = json.dumps(state[key], default=str)
            if len(val_str) > 100_000:  # 100KB
                del state[key]
                removed += 1

        # Remove keys with old timestamps (>90 days)
        import time
        cutoff = time.time() - 90 * 86400
        for key in list(state.keys()):
            val = state[key]
            if isinstance(val, dict) and "timestamp" in val:
                try:
                    ts = time.mktime(time.strptime(val["timestamp"], "%Y-%m-%d %H:%M:%S"))
                    if ts < cutoff:
                        del state[key]
                        removed += 1
                except (ValueError, TypeError):
                    pass

        # Save cleaned state
        with open(PERSIST_FILE, "w", encoding="utf-8") as f:
            json.dump(state, f, ensure_ascii=False, indent=2, default=str)

        new_size = os.path.getsize(PERSIST_FILE)
        bytes_saved = original_size - new_size

        return removed, bytes_saved

    except Exception as e:
        st.toast(f"Erreur nettoyage: {e}", icon="⚠️")
        return 0, 0



