def _init_auth_state():

    if "_ibid_auth_initialized" not in st.session_state:

        st.session_state["_ibid_auth_initialized"] = True

        st.session_state["ibid_authenticated"] = False

        st.session_state["ibid_username"] = None

        st.session_state["ibid_role"] = None

        st.session_state["ibid_scci_edit_unlocked"] = False

        st.session_state["ibid_security_key_input"] = ""
        st.session_state["ibid_show_about_dialog"] = False
        st.session_state["ibid_show_contact_dialog"] = False



def _check_login(username, password):
    user = I_BID_USERS.get(username)
    if user and user["password"] == password:
        return True, user["role"], user["label"], user.get("entity", "SC CI"), user.get("access", "")
    return False, None, None, None, None



def _login_user(username, role, label, entity="I-BID", access=""):
    st.session_state["ibid_authenticated"] = True
    st.session_state["ibid_username"] = username
    st.session_state["ibid_role"] = role
    st.session_state["ibid_user_label"] = label
    st.session_state["ibid_user_entity"] = entity
    st.session_state["ibid_user_access"] = access



def _logout_user():
    keys_to_clear = [
        "ibid_authenticated", "ibid_username", "ibid_role", "ibid_user_label",
        "ibid_user_entity", "ibid_user_access",
        "ibid_scci_edit_unlocked", "ibid_security_key_input", "ibid_login_username",
        "ibid_login_password", "ibid_security_key_input_widget"
    ]
    for k in keys_to_clear:
        if k in st.session_state:
            del st.session_state[k]
    st.session_state["_ibid_auth_initialized"] = False



def _is_owner():
    return st.session_state.get("ibid_role") == "owner"

def _is_atlantic_group():
    return st.session_state.get("ibid_user_entity") == "Atlantic Group"

def _is_scci():
    return st.session_state.get("ibid_user_entity") == "SC CI"

def _is_scci_dg():
    return st.session_state.get("ibid_role") == "scci_dg"

def _get_role():
    return st.session_state.get("ibid_role", "")

def _get_entity():
    return st.session_state.get("ibid_user_entity", "SC CI")

def _get_role_color():
    role = _get_role()
    return ROLE_COLORS.get(role, ROLE_COLORS["scci_dg"])



def _can_access_tab(tab_index):

    role = _get_role()

    allowed = ROLE_TAB_ACCESS.get(role, set())

    return tab_index in allowed



def _can_edit_section(section):

    role = _get_role()

    allowed = ROLE_SIDEBAR_EDIT.get(role, set())

    return section in allowed



def _can_edit_sidebar():

    """Return True if the user can edit at least one sidebar section."""

    role = _get_role()

    return len(ROLE_SIDEBAR_EDIT.get(role, set())) > 0



def _is_authenticated():

    return st.session_state.get("ibid_authenticated", False)



def render_cover_page():
    """Render the I-BiD cover page with the official design image."""

    st.html("""
    <style>
    /* Hide sidebar on cover page */
    div[data-testid="stSidebar"] {
        display: none !important;
        width: 0px !important; min-width: 0px !important; max-width: 0px !important;
        visibility: hidden !important; opacity: 0 !important;
    }
    /* Full-width main area */
    section[data-testid="stAppViewContainer"] > .main {
        max-width: 100% !important; margin-left: 0 !important;
        padding-left: 0 !important; padding-right: 0 !important;
    }
    .block-container { padding: 0 !important; max-width: 100% !important; }
    .brand-watermark, .brand-header { display: none !important; }
    /* Cover page buttons — unified sizing */
    .cover-enter-btn button {
        background: linear-gradient(135deg, #F58220 0%, #E85D04 100%) !important;
        border: none !important;
        border-radius: 14px !important;
        color: #FFFFFF !important;
        font-weight: 700 !important;
        font-size: 1.1rem !important;
        letter-spacing: 0.06em !important;
        text-transform: uppercase !important;
        padding: 16px 24px !important;
        box-shadow: 0 8px 32px rgba(245,130,32,0.4) !important;
        transition: all 0.3s ease !important;
        height: auto !important;
        min-height: 56px !important;
        white-space: nowrap !important;
    }
    .cover-enter-btn button:hover {
        background: linear-gradient(135deg, #FF9A3C 0%, #F06B1A 100%) !important;
        box-shadow: 0 12px 40px rgba(245,130,32,0.55) !important;
        transform: translateY(-2px) !important;
    }
    /* Cover page secondary buttons — match primary size */
    .cover-secondary-btn button {
        background: rgba(255,255,255,0.06) !important;
        border: 1px solid rgba(30,77,143,0.5) !important;
        color: #E6E9ED !important;
        border-radius: 14px !important;
        font-weight: 600 !important;
        font-size: 1.0rem !important;
        letter-spacing: 0.04em !important;
        padding: 16px 24px !important;
        transition: all 0.3s ease !important;
        height: auto !important;
        min-height: 56px !important;
        white-space: nowrap !important;
    }
    .cover-secondary-btn button:hover {
        background: rgba(255,255,255,0.12) !important;
        border-color: rgba(245,130,32,0.5) !important;
        box-shadow: 0 0 16px rgba(245,130,32,0.2) !important;
        transform: translateY(-2px) !important;
    }
    </style>
    """)

    # Full-screen cover image
    st.html("""
    <div style="position:fixed;top:0;left:0;width:100vw;height:100vh;z-index:0;
         background: #0B1F3A;
         overflow:hidden;">
    </div>
    """)

    # Center the cover image
    left_spacer, center_col, right_spacer = st.columns([1, 10, 1])

    with center_col:
        # Display the cover page image full width
        try:
            st.image("I-BID page acceuil background.png", use_container_width=True)
        except Exception:
            st.info("Image de couverture non disponible")

    # Buttons row: À PROPOS | Entrer | Contact
    st.markdown("<div style='height:20px;'></div>", unsafe_allow_html=True)

    left_btn, center_btn, right_btn = st.columns([2, 2, 2])

    with left_btn:
        st.markdown('<div class="cover-secondary-btn">', unsafe_allow_html=True)
        if st.button("ℹ️  À PROPOS DE I-BID", key="ibid_cover_about_btn", use_container_width=True):
            st.session_state["ibid_show_about_dialog"] = True
            st.session_state["ibid_show_login_dialog"] = False
            st.session_state["ibid_show_contact_dialog"] = False
            st.rerun()
        st.markdown('</div>', unsafe_allow_html=True)

    with center_btn:
        st.markdown('<div class="cover-enter-btn">', unsafe_allow_html=True)
        if st.button("🚀 Entrer", key="ibid_cover_enter_btn", use_container_width=True, type="primary"):
            st.session_state["ibid_show_login_dialog"] = True
            st.session_state["ibid_show_about_dialog"] = False
            st.session_state["ibid_show_contact_dialog"] = False
            st.rerun()
        st.markdown('</div>', unsafe_allow_html=True)

    with right_btn:
        st.markdown('<div class="cover-secondary-btn">', unsafe_allow_html=True)
        if st.button("📧 Contact", key="ibid_cover_contact_btn", use_container_width=True):
            st.session_state["ibid_show_contact_dialog"] = True
            st.session_state["ibid_show_login_dialog"] = False
            st.session_state["ibid_show_about_dialog"] = False
            st.rerun()
        st.markdown('</div>', unsafe_allow_html=True)

    # Version info at bottom
    st.markdown("<div style='height:10px;'></div>", unsafe_allow_html=True)
    st.html("""
    <div style="text-align:center;">
        <div style="font-family:'Inter',sans-serif;font-size:0.75rem;color:rgba(91,103,112,0.6);
             letter-spacing:0.12em;text-transform:uppercase;">
            I-BiD® v2.5.0 | Industrial Intelligence Platform | Données Marché 2026
        </div>
    </div>
    """)

    # ═══════════════════════════════════════════
    # DIALOGS
    # ═══════════════════════════════════════════
    if st.session_state.get("ibid_show_login_dialog", False):
        _show_login_dialog()
    elif st.session_state.get("ibid_show_about_dialog", False):
        _show_about_dialog()
    elif st.session_state.get("ibid_show_contact_dialog", False):
        _show_contact_dialog()


def _show_login_dialog():
    """Login dialog content - rendered inline, not as @st.dialog."""
    with st.container():
        st.html("""
        <style>
        .login-modal-box {
            background: linear-gradient(135deg, rgba(11,31,58,0.98) 0%, rgba(30,77,143,0.98) 50%, rgba(11,31,58,0.98) 100%) !important;
            border: 2px solid #F58220 !important;
            border-radius: 20px !important;
            padding: 24px;
            max-width: 500px;
            margin: 0 auto;
        }
        .login-modal-box h3 {
            color: #F58220 !important;
            font-size: 1.1rem !important;
            font-weight: 700 !important;
            text-align: center !important;
            letter-spacing: 0.05em !important;
            text-transform: uppercase !important;
            margin-bottom: 20px;
        }
        .login-divider {
            height: 1px;
            background: linear-gradient(90deg, transparent, #5B6770, transparent);
            margin: 16px 0;
        }
        .login-hint {
            color: #5B6770;
            font-size: 0.75rem;
            text-align: center;
            line-height: 1.6;
        }
        .login-error {
            background: rgba(239,68,68,0.1);
            border: 1px solid #ef4444;
            border-radius: 8px;
            padding: 10px 14px;
            color: #fca5a5;
            font-size: 0.85rem;
            text-align: center;
            margin-top: 12px;
        }
        </style>
        <div class="login-modal-box">
            <h3>🔐 Connexion</h3>
        </div>
        """)

        if "ibid_login_error" not in st.session_state:
            st.session_state["ibid_login_error"] = ""

        username = st.selectbox(
            "Identifiant",
            options=list(I_BID_USERS.keys()),
            key="ibid_login_username_dialog",
            index=0,
            format_func=lambda x: I_BID_USERS[x]["label"]
        )

        password = st.text_input(
            "Mot de passe",
            key="ibid_login_password_dialog",
            type="password",
            placeholder="Entrez votre mot de passe..."
        )

        if st.session_state.get("ibid_login_error"):
            st.markdown(
                f"""<div class="login-error">❌ {st.session_state["ibid_login_error"]}</div>""",
                unsafe_allow_html=True
            )

        col1, col2 = st.columns(2)
        with col1:
            if st.button("Se Connecter", key="ibid_login_btn_dialog", use_container_width=True, type="primary"):
                success, role, label, entity, access = _check_login(username, password)
                if success:
                    _login_user(username, role, label, entity, access)
                    st.session_state["ibid_show_login_dialog"] = False
                    st.session_state["ibid_login_error"] = ""
                    st.toast(f"Bienvenue, {label}!", icon="✅")
                    st.rerun()
                else:
                    st.session_state["ibid_login_error"] = "Identifiant ou mot de passe incorrect"
                    st.rerun()

        with col2:
            if st.button("Annuler", key="ibid_cancel_login_dialog", use_container_width=True):
                st.session_state["ibid_show_login_dialog"] = False
                st.session_state["ibid_login_error"] = ""
                st.rerun()

        st.markdown('<div class="login-divider"></div>', unsafe_allow_html=True)
        st.markdown(
            """<div class="login-hint">
            🔧 <b>Owner</b> : Accès Complet I-BID &nbsp;|&nbsp;
            👑 <b>AG Chairman/DG</b> : Vue Stratégique Groupe &nbsp;|&nbsp;
            👑 <b>SC CI DG</b> : Opérationnel Complet<br>
            💳 <b>DFC</b> : Finance &nbsp;|&nbsp;
            🏭 <b>DEX</b> : Exploitation &nbsp;|&nbsp;
            📢 <b>DCM</b> : Commercial &nbsp;|&nbsp;
            🚛 <b>DAL</b> : Achats & Logistique
            </div>""",
            unsafe_allow_html=True
        )

        if st.button("✕ Fermer", key="btn_close_login_dialog", use_container_width=True):
            st.session_state["ibid_show_login_dialog"] = False
            st.session_state["ibid_login_error"] = ""
            st.rerun()

def _show_about_dialog():
    """Popover dialog with About info and Platform Capabilities."""
    st.html("""
    <style>
    div[data-testid="stDialog"] > div > div {
        background: linear-gradient(135deg, rgba(11,31,58,0.98) 0%, rgba(30,77,143,0.98) 50%, rgba(11,31,58,0.98) 100%) !important;
        border: 2px solid #F58220 !important;
        border-radius: 20px !important;
    }
    div[data-testid="stDialog"] h2 {
        color: #F58220 !important;
        font-size: 1.2rem !important;
        font-weight: 700 !important;
        text-align: center !important;
        letter-spacing: 0.05em !important;
        text-transform: uppercase !important;
    }
    </style>
    """)

    st.markdown("""
    <div style="color:#E6E9ED; font-size:0.9rem; line-height:1.8; margin-bottom:24px;">
    <b style="color:#F58220;">I-BiD</b> est un tableau de bord d'intelligence économique et de modélisation financière
    sophistiqué appliqué spécifiquement au secteur industriel en Afrique. L'application
    intègre les paramètres de production et les données du marché avec la modélisation de
    la performance financière pour fournir un support décisionnel stratégique aux opérateurs
    dans le secteur industriel.
    </div>
    """, unsafe_allow_html=True)

    st.markdown("""
    <div style="border-top: 1px solid rgba(30,77,143,0.4); padding-top: 20px; margin-top: 20px;">
        <div style="color:#F58220; font-size:1rem; font-weight:700; margin-bottom:16px; text-align:center; letter-spacing:0.05em; text-transform:uppercase;">
            🚀 Capacités de la Plateforme
        </div>
    </div>
    """, unsafe_allow_html=True)

    col1, col2 = st.columns(2)

    features = [
        ("📊", "Tableau de Bord DG", "KPIs en temps réel, analyses comparatives et suivi de performance multi-sites"),
        ("⚙️", "Modélisation Financière", "Scénarios pessimistes, optimistes, point mort et personnalisés avec IA"),
        ("🗄️", "Données Marché CI", "Prix plafonds, concurrence, surcapacité et tendances du marché ivoirien"),
        ("🔧", "Optimisation IA", "Suggestions actionnables pour la trésorerie, l'énergie et la logistique"),
        ("📈", "Données Historiques", "Intégration des données 2020-2026 avec analyse évolutive et projections"),
        ("🗺️", "Cartographie Valeur", "Visualisation complète de la chaîne de valeur cimentière"),
    ]

    for i, (icon, title, desc) in enumerate(features):
        with col1 if i % 2 == 0 else col2:
            st.markdown(f"""
            <div style="background:rgba(255,255,255,0.03);border:1px solid rgba(30,77,143,0.3);
                 border-radius:12px;padding:16px;margin-bottom:10px;">
                <div style="font-size:1.5rem;margin-bottom:8px;">{icon}</div>
                <div style="color:#FFFFFF;font-size:0.85rem;font-weight:700;margin-bottom:6px;">{title}</div>
                <div style="color:#5B6770;font-size:0.78rem;line-height:1.5;">{desc}</div>
            </div>
            """, unsafe_allow_html=True)

    if st.button("✕ Fermer", key="btn_close_about_dialog", use_container_width=True):
        st.session_state["ibid_show_about_dialog"] = False


