# ============================================================

# SCROLL POSITION PRESERVATION - Fix sidebar scroll issue

# Uses localStorage for persistence across re-renders

# ============================================================

scroll_preservation_js = """

<script>

(function() {

    'use strict';

    if (window.__ibid_scroll_init) return;

    window.__ibid_scroll_init = true;

    var parentDoc = window.parent.document;

    var parentWin = window.parent;

    var STORAGE_KEY_MAIN = 'miif_main_scroll_v2';

    var STORAGE_KEY_SIDEBAR = 'miif_sidebar_scroll_v2';

    var isRestoring = false;



    function getMainContainer() {

        return parentDoc.querySelector('.main') || parentDoc.querySelector('[data-testid="stAppViewContainer"] > .main') || parentDoc.querySelector('section.main');

    }

    function getSidebarContainer() {

        return parentDoc.querySelector('[data-testid="stSidebar"]') || parentDoc.querySelector('section[data-testid="stSidebar"]');

    }



    function saveScroll() {

        try {

            var mc = getMainContainer();

            var sc = getSidebarContainer();

            if (mc) localStorage.setItem(STORAGE_KEY_MAIN, String(mc.scrollTop));

            if (sc) localStorage.setItem(STORAGE_KEY_SIDEBAR, String(sc.scrollTop));

            localStorage.setItem(STORAGE_KEY_MAIN + '_win', String(parentWin.scrollY || parentDoc.documentElement.scrollTop));

        } catch(e) {}

    }



    function restoreScroll(force) {

        if (isRestoring && !force) return;

        isRestoring = true;

        try {

            var mc = getMainContainer();

            var sc = getSidebarContainer();

            var ms = localStorage.getItem(STORAGE_KEY_MAIN);

            var ss = localStorage.getItem(STORAGE_KEY_SIDEBAR);

            var ws = localStorage.getItem(STORAGE_KEY_MAIN + '_win');

            if (ms && mc) mc.scrollTop = parseInt(ms);

            if (ss && sc) sc.scrollTop = parseInt(ss);

            if (ws) parentWin.scrollTo(0, parseInt(ws));

        } catch(e) {}

        setTimeout(function() { isRestoring = false; }, 200);

    }



    // Throttled scroll save

    var st;

    function onScroll() { clearTimeout(st); st = setTimeout(saveScroll, 50); }



    var mc = getMainContainer();

    var sc = getSidebarContainer();

    if (mc) mc.addEventListener('scroll', onScroll, {passive: true});

    if (sc) sc.addEventListener('scroll', onScroll, {passive: true});

    parentWin.addEventListener('scroll', onScroll, {passive: true});



    // CRITICAL: Save before resize (sidebar width change) and restore after

    var rt;

    parentWin.addEventListener('resize', function() {

        saveScroll();

        clearTimeout(rt);

        rt = setTimeout(function() { restoreScroll(true); }, 50);

        setTimeout(function() { restoreScroll(true); }, 150);

        setTimeout(function() { restoreScroll(true); }, 300);

        setTimeout(function() { restoreScroll(true); }, 600);

    });



    // Restore on load - multiple attempts

    if (parentDoc.readyState === 'loading') {

        parentDoc.addEventListener('DOMContentLoaded', function() { restoreScroll(true); });

    } else {

        restoreScroll(true);

    }

    setTimeout(function() { restoreScroll(true); }, 50);

    setTimeout(function() { restoreScroll(true); }, 200);

    setTimeout(function() { restoreScroll(true); }, 500);

    setTimeout(function() { restoreScroll(true); }, 1000);

    setTimeout(function() { restoreScroll(true); }, 2000);



    // Watch for DOM changes (Streamlit re-renders)

    var observer = new MutationObserver(function() {

        setTimeout(function() { restoreScroll(true); }, 100);

    });

    if (mc) observer.observe(mc, { childList: true, subtree: true });

})();

</script>

"""



st.html(scroll_preservation_js)





tooltip_js_html = """
<script>
/* I-BiD® Smart Tooltip System v2.0 — Robust cross-context execution */
(function() {
    'use strict';
    if (window.__ibid_tooltip_init) return;
    window.__ibid_tooltip_init = true;

    // Robust document/window access with multi-layer fallback
    var parentDoc, parentWin;
    try {
        parentDoc = window.parent.document;
        parentWin = window.parent;
    } catch (e) {
        try {
            parentDoc = document;
            parentWin = window;
        } catch (e2) {
            console.error('I-BiD Tooltip: Cannot access document');
            return;
        }
    }

    if (!parentDoc || !parentDoc.body) {
        console.error('I-BiD Tooltip: Document body not available');
        return;
    }

    // Measurement clones registry (for cleanup)
    var _clones = [];

    function initTooltips() {
        var wrappers = parentDoc.querySelectorAll('.tooltip-wrapper:not([data-tooltip-init="true"])');
        if (wrappers.length === 0) return;

        wrappers.forEach(function(wrapper) {
            wrapper.dataset.tooltipInit = 'true';

            var tooltip = wrapper.querySelector('.kpi-hover-tooltip');
            if (!tooltip) return;

            // Create a clone for measurement to avoid flicker on the real tooltip
            var measureClone = tooltip.cloneNode(true);
            measureClone.style.cssText = 'visibility:hidden;position:fixed;top:-9999px;left:-9999px;opacity:1;height:auto;max-height:500px;padding:12px 14px;pointer-events:none;';
            measureClone.classList.add('tooltip-visible');
            parentDoc.body.appendChild(measureClone);
            _clones.push(measureClone);

            function getTooltipSize() {
                var rect = measureClone.getBoundingClientRect();
                return {
                    width: Math.max(rect.width, 280),
                    height: rect.height
                };
            }

            function positionAndShow() {
                var rect = wrapper.getBoundingClientRect();
                var vw = parentWin.innerWidth || parentDoc.documentElement.clientWidth || 1024;
                var vh = parentWin.innerHeight || parentDoc.documentElement.clientHeight || 768;

                var size = getTooltipSize();
                var ttW = size.width;
                var ttH = size.height;

                // Default: below trigger, centered horizontally
                var top = rect.bottom + 10;
                var left = rect.left + rect.width / 2;
                var arrowClass = '';

                // Determine best position based on available space
                var spaceBelow = vh - rect.bottom - 20;
                var spaceAbove = rect.top - 20;

                // Check if we should place above (not enough space below, or more space above)
                if (ttH > spaceBelow && spaceAbove > spaceBelow) {
                    top = rect.top - ttH - 10;
                    arrowClass = 'tooltip-above';
                }

                // Check right edge (near sidebar) - shift left if needed
                var rightEdge = left + ttW / 2;
                if (rightEdge > vw - 15) {
                    left = vw - ttW / 2 - 15;
                }

                // Check left edge
                var leftEdge = left - ttW / 2;
                if (leftEdge < 15) {
                    left = ttW / 2 + 15;
                }

                // Check top edge (if placed above but still goes off-screen)
                if (top < 15) {
                    top = rect.bottom + 10;
                    arrowClass = '';
                }

                // Check bottom edge (if placed below but goes off-screen)
                if (top + ttH > vh - 15) {
                    top = rect.top - ttH - 10;
                    arrowClass = 'tooltip-above';
                    if (top < 15) {
                        top = 15;
                        arrowClass = '';
                    }
                }

                // Apply position via CSS custom properties
                tooltip.style.setProperty('--tt-top', Math.round(top));
                tooltip.style.setProperty('--tt-left', Math.round(left));

                // Apply arrow class
                tooltip.classList.remove('tooltip-above', 'tooltip-left', 'tooltip-right');
                if (arrowClass) tooltip.classList.add(arrowClass);

                // Show tooltip
                tooltip.classList.add('tooltip-visible');
            }

            function hideTooltip() {
                tooltip.classList.remove('tooltip-visible');
                tooltip.classList.remove('tooltip-above', 'tooltip-left', 'tooltip-right');
            }

            wrapper.addEventListener('mouseenter', positionAndShow);
            wrapper.addEventListener('mouseleave', hideTooltip);

            var icon = wrapper.querySelector('.kpi-info-icon');
            if (icon) {
                icon.addEventListener('mouseenter', function(e) {
                    e.stopPropagation();
                    positionAndShow();
                });
                icon.addEventListener('mouseleave', hideTooltip);
            }
        });
    }

    // Run when DOM is ready
    function runInit() {
        try {
            if (parentDoc.body) {
                initTooltips();
            } else {
                setTimeout(runInit, 100);
                return;
            }
        } catch (e) {
            console.error('I-BiD Tooltip init error:', e);
        }
    }

    try {
        if (parentDoc.readyState === 'loading') {
            parentDoc.addEventListener('DOMContentLoaded', runInit);
        } else {
            runInit();
        }
    } catch (e) {
        console.error('I-BiD Tooltip readyState error:', e);
    }

    // Re-init periodically for dynamic content (Streamlit re-renders)
    var reinitInterval = setInterval(function() {
        try {
            var newWrappers = parentDoc.querySelectorAll('.tooltip-wrapper:not([data-tooltip-init="true"])');
            if (newWrappers.length > 0) {
                initTooltips();
            }
        } catch (e) {
            clearInterval(reinitInterval);
        }
    }, 1500);

    // Hide on scroll/resize
    try {
        parentWin.addEventListener('scroll', function() {
            try {
                parentDoc.querySelectorAll('.kpi-hover-tooltip.tooltip-visible').forEach(function(t) {
                    t.classList.remove('tooltip-visible');
                });
            } catch (e) {}
        }, true);
    } catch (e) {}

    try {
        parentWin.addEventListener('resize', function() {
            try {
                parentDoc.querySelectorAll('.kpi-hover-tooltip.tooltip-visible').forEach(function(t) {
                    t.classList.remove('tooltip-visible');
                });
            } catch (e) {}
        });
    } catch (e) {}

    console.log('I-BiD® Tooltip system v2.0 initialized');
})();
</script>
"""



st.html(tooltip_js_html)







