def get_historical_monthly(year, month):
    """Retourne les données historiques pour un mois donné."""
    key = f"{year}-{month:02d}"
    return HISTORICAL_SALES_MONTHLY.get(key, {})


def get_historical_annual(year):
    """Retourne les données historiques agrégées pour une année."""
    return HISTORICAL_SALES_ANNUAL.get(year, {})


def get_historical_years():
    """Retourne la liste des années disponibles."""
    return sorted(HISTORICAL_SALES_ANNUAL.keys())


def get_historical_months_for_year(year):
    """Retourne la liste des mois disponibles pour une année."""
    months = []
    for key in sorted(HISTORICAL_SALES_MONTHLY.keys()):
        if key.startswith(f"{year}-"):
            month = int(key.split("-")[1])
            months.append(month)
    return months


def compute_historical_kpis(year):
    """Calcule les KPIs à partir des données historiques annuelles."""
    data = get_historical_annual(year)
    if not data:
        return {}

    total_tonnes = data.get("total_tonnes", 0)
    ventes_exo = data.get("ventes_exo", 0)

    # Mix produit
    mix = {}
    for p in HISTORICAL_PRODUCT_COLS:
        vol = data.get(p, 0)
        mix[p] = {
            "volume": vol,
            "pct": (vol / total_tonnes * 100) if total_tonnes > 0 else 0,
        }

    return {
        "ca_total": ventes_exo,
        "ca_ttc": data.get("ventes_ttc", 0),
        "volume_total": total_tonnes,
        "prix_moyen_tonne": ventes_exo / total_tonnes if total_tonnes > 0 else 0,
        "mix_produit": mix,
        "sacs": data.get("sacs", 0),
        "vrac": data.get("vrac", 0),
        "kd": data.get("kd", 0),
        "multicarte": data.get("multicarte", 0),
        "technique": data.get("technique", 0),
        "export": data.get("export", 0),
        "exw": data.get("exw", 0),
        "ddp": data.get("ddp", 0),
    }


def compute_historical_evolution():
    """Calcule l'évolution annuelle des KPIs clés."""
    years = get_historical_years()
    evolution = {}
    for year in years:
        evolution[year] = compute_historical_kpis(year)
    return evolution


def compare_historical_with_model(model_data, year=2024):
    """Compare les données du modèle avec les données historiques."""
    hist = get_historical_annual(year)
    if not hist:
        return None

    comparison = {}
    total_tonnes = hist.get("total_tonnes", 0)

    # Mapping modèle -> historique
    product_map = {
        "vol_cpj32": "cpj32",
        "vol_cpj42": "cpj42",
        "vol_cpa42": "cpa42",  # si existe dans modèle
        "vol_cpa52": "cpa52",
        "vol_mc12": "mc12",
        "vol_chf": "chf",
    }

    for model_key, hist_key in product_map.items():
        hist_vol = hist.get(hist_key, 0)
        model_vol = model_data.get(model_key, 0)
        comparison[hist_key] = {
            "historique": hist_vol,
            "modele": model_vol,
            "ecart_pct": ((model_vol - hist_vol) / hist_vol * 100) if hist_vol > 0 else 0,
            "ecart_tonnes": model_vol - hist_vol,
        }

    # Comparaison CA
    hist_ca = hist.get("ventes_exo", 0)
    model_ca = model_data.get("ca_total", 0)
    comparison["ca_total"] = {
        "historique": hist_ca,
        "modele": model_ca,
        "ecart_pct": ((model_ca - hist_ca) / hist_ca * 100) if hist_ca > 0 else 0,
    }

    return comparison


def get_historical_seasonality():
    """Calcule les facteurs de saisonnalité à partir des données historiques."""
    monthly_volumes = {}
    for key, data in HISTORICAL_SALES_MONTHLY.items():
        month = int(key.split("-")[1])
        total = sum(data.get(p, 0) for p in HISTORICAL_PRODUCT_COLS)
        if month not in monthly_volumes:
            monthly_volumes[month] = []
        monthly_volumes[month].append(total)

    # Moyenne par mois
    seasonality = {}
    for month in range(1, 13):
        volumes = monthly_volumes.get(month, [])
        seasonality[month] = sum(volumes) / len(volumes) if volumes else 0

    # Normaliser par la moyenne annuelle
    avg = sum(seasonality.values()) / 12 if seasonality else 1
    if avg > 0:
        for month in seasonality:
            seasonality[month] = round(seasonality[month] / avg, 3)

    return seasonality


def compute_dynamic_cout_revient(
    base_cout_revient,
    product,
    month_name,
    transport_cost_per_tonne,
    ristourne_amount,
    expedition_mode,
    saisonnalite_active=True,
    transport_active=True,
    ristourne_active=True,
    expedition_active=True
):
    """
    Calcule le cout de revient dynamique en appliquant:
    - Saisonnalite: facteur multiplicatif selon le mois
    - Cout de transport: ajoute directement au cout
    - Ristourne: deduite du cout
    - Mode d'expedition: ajustement selon EXW/DDP/Sacs/Vrac

    Returns: cout_revient_ajuste, details_dict
    """
    details = {"base": base_cout_revient, "adjustments": {}}
    cout = base_cout_revient

    # 1. Impact Saisonnalite
    if saisonnalite_active:
        season_factor = SEASONALITY_FACTORS.get(month_name, 1.0)
        # Saisonnalite affecte principalement les couts energetiques (~15% du cout)
        energy_ratio = 0.15
        season_adjustment = (season_factor - 1.0) * energy_ratio
        cout *= (1 + season_adjustment)
        details["adjustments"]["saisonnalite"] = {
            "factor": season_factor,
            "impact": season_adjustment * 100,
            "montant": cout - base_cout_revient
        }

    # 2. Impact Cout de Transport
    if transport_active and transport_cost_per_tonne > 0:
        cout += transport_cost_per_tonne
        details["adjustments"]["transport"] = {
            "cout_transport_tonne": transport_cost_per_tonne,
            "impact": (transport_cost_per_tonne / base_cout_revient) * 100 if base_cout_revient > 0 else 0,
            "montant": transport_cost_per_tonne
        }

    # 3. Impact Ristourne
    if ristourne_active and ristourne_amount > 0:
        cout -= ristourne_amount
        details["adjustments"]["ristourne"] = {
            "montant_ristourne": ristourne_amount,
            "impact": -(ristourne_amount / base_cout_revient) * 100 if base_cout_revient > 0 else 0,
            "montant": -ristourne_amount
        }

    # 4. Impact Mode d'Expedition
    if expedition_active and expedition_mode:
        mode_multipliers = {
            "EXW": 1.0,        # Pas de cout logistique additionnel
            "DDP": 1.08,       # +8% pour livraison payee
            "Sac": 1.05,       # +5% pour conditionnement sac
            "Vrac": 1.02,      # +2% pour vrac
            "Big Bag": 1.04,   # +4% pour big bag
        }
        mult = mode_multipliers.get(expedition_mode, 1.0)
        mode_adjustment = (mult - 1.0) * base_cout_revient
        cout += mode_adjustment
        details["adjustments"]["expedition"] = {
            "mode": expedition_mode,
            "multiplier": mult,
            "impact": (mult - 1.0) * 100,
            "montant": mode_adjustment
        }

    details["final"] = cout
    details["total_adjustment"] = cout - base_cout_revient
    details["total_adjustment_pct"] = ((cout - base_cout_revient) / base_cout_revient * 100) if base_cout_revient > 0 else 0

    return cout, details


def compute_monthly_prix_vente_par_produit(
    year,
    product,
    base_prix_vente,
    transport_cost_per_tonne=0,
    ristourne_amount=0,
    expedition_mode="EXW",
    marge_cible_pct=15.0,
    saisonnalite_active=True,
    transport_active=True,
    ristourne_active=True,
    expedition_active=True
):
    """
    Calcule le prix de vente mensuel par produit avec tous les ajustements.

    Pour chaque mois de l'annee:
    1. Applique le facteur de saisonnalite
    2. Ajoute le cout de transport
    3. Deduit la ristourne
    4. Ajuste selon le mode d'expedition
    5. Ajoute la marge cible

    Returns: dict {month_name: {"prix_vente": X, "cout_revient": Y, "marge": Z, "details": {}}}
    """
    month_names = ["Jan", "Fev", "Mar", "Avr", "Mai", "Juin",
                   "Juil", "Aout", "Sept", "Oct", "Nov", "Dec"]

    # Base = coût variable de production du modèle (inputs sidebar), HORS transport
    # (le transport est ajouté dynamiquement par compute_dynamic_cout_revient)
    kc_ratio = KC_RATIOS.get(product, 0.5)

    pk = normalize_product_key(product)

    _mix = {a: get_val(f"form_{pk}_{a}") for a in ("gypse", "granite", "laitier", "calcaire", "pouzzolane")}

    mat_t = kc_ratio * get_val("clinker_cost") + sum(_mix[a] * get_val(f"{a}_cost") for a in _mix)

    _v1, _v2 = get_val(f"vol_{pk}_site1"), get_val(f"vol_{pk}_site2")

    _vt = _v1 + _v2

    def _w(_a, _b):

        return (_a * _v1 + _b * _v2) / _vt if _vt > 0 else _a

    _ener, _fuel, _adj = {}, {}, {}

    for _s in ("site1", "site2"):

        _ks = f"kwh_per_tonne_{pk}_{_s}"

        _kwh = get_val(_ks) if _ks in VALUE_KEYS else get_val(f"kwh_per_tonne_{pk}")

        _ener[_s] = _kwh * get_val("tarif_kwh")

        _fuel[_s] = sum(get_val(f"fuel_{_f}_dose_{pk}_{_s}") * kc_ratio * get_val(f"fuel_{_f}_price") for _f in ("gasoil", "fuel", "ddo", "cnsl"))

        _adj[_s] = sum(get_val(f"adjuvant_{_a}_dose_{pk}_{_s}") / 1000.0 * get_val(f"adjuvant_{_a}_price") for _a in ("pegasus", "sika", "chryso", "biolatex"))

    sac_t = get_val("sac_cost_per_unit") * get_val("sacs_per_tonne") * min(1.0, get_val(f"sac_exw_pct_{pk}") + get_val(f"sac_ddp_pct_{pk}"))

    base_cout_revient_tonne = (mat_t + _w(_ener["site1"], _ener["site2"]) + _w(_fuel["site1"], _fuel["site2"])

                               + _w(_adj["site1"], _adj["site2"]) + sac_t + get_val("commercial_cost_per_tonne"))

    result = {}
    for i, month_name in enumerate(month_names):
        # Compute dynamic cost
        cout_revient, details = compute_dynamic_cout_revient(
            base_cout_revient=base_cout_revient_tonne,
            product=product,
            month_name=month_name,
            transport_cost_per_tonne=transport_cost_per_tonne,
            ristourne_amount=ristourne_amount,
            expedition_mode=expedition_mode,
            saisonnalite_active=saisonnalite_active,
            transport_active=transport_active,
            ristourne_active=ristourne_active,
            expedition_active=expedition_active
        )

        # Compute selling price with target margin
        prix_vente = cout_revient * (1 + marge_cible_pct / 100)

        # Apply seasonality to selling price too (market adjusts)
        if saisonnalite_active:
            season_factor = SEASONALITY_FACTORS.get(month_name, 1.0)
            prix_vente *= season_factor

        marge = prix_vente - cout_revient
        marge_pct = (marge / cout_revient * 100) if cout_revient > 0 else 0

        result[month_name] = {
            "prix_vente": round(prix_vente, 2),
            "cout_revient": round(cout_revient, 2),
            "marge": round(marge, 2),
            "marge_pct": round(marge_pct, 2),
            "details": details
        }

    return result


