def treasury_daily_flow(enc_data=None, dec_data=None):
    """Construit la série journalière nette de trésorerie à partir des templates
    BD_ENCAISSEMENTS_DAILY / BD_DECAISSEMENTS_DAILY (ou de daily_data.json
    si les clés "encaissements"/"decaissements" y sont renseignées).
    Retourne {date: {"encaisse": float, "decaisse": float, "net": float}}."""
    enc_data = enc_data or BD_ENCAISSEMENTS_DAILY
    dec_data = dec_data or BD_DECAISSEMENTS_DAILY
    dates = sorted(set(enc_data) | set(dec_data))
    flow = {}
    for d in dates:
        enc = sum(site.get("total_jour", 0) for site in (enc_data.get(d) or {}).values())
        dec = sum(site.get("total_jour", 0) for site in (dec_data.get(d) or {}).values())
        flow[d] = {"encaisse": enc, "decaisse": dec, "net": enc - dec}
    return flow


def treasury_data_source():
    """Source des flux de trésorerie : (enc_data, dec_data, is_real).
    Réel = clés "encaissements"/"decaissements" de daily_data.json ;
    sinon fallback sur les templates BD_ENCAISSEMENTS_DAILY / BD_DECAISSEMENTS_DAILY."""
    _dd = globals().get("DAILY_DATA") or {}
    _enc_real, _dec_real = {}, {}
    for _d, _day in _dd.items():
        if not isinstance(_day, dict):
            continue
        if isinstance(_day.get("encaissements"), dict):
            _enc_real[_d] = _day["encaissements"]
        if isinstance(_day.get("decaissements"), dict):
            _dec_real[_d] = _day["decaissements"]
    if _enc_real or _dec_real:
        return _enc_real, _dec_real, True
    return BD_ENCAISSEMENTS_DAILY, BD_DECAISSEMENTS_DAILY, False


def treasury_period_key(date_str, freq):
    """Clé d'agrégation d'une date selon la fréquence : 'D' jour, 'W' semaine ISO,
    'M' mois AAAA-MM, 'Y' année AAAA."""
    if freq == "W":
        _iso = datetime.strptime(date_str, "%Y-%m-%d").isocalendar()
        return f"{_iso[0]}-S{_iso[1]:02d}"
    if freq == "M":
        return date_str[:7]
    if freq == "Y":
        return date_str[:4]
    return date_str


def treasury_flow_records(enc_data=None, dec_data=None, freq="D", filtered_dates=None):
    """Série de trésorerie agrégée : liste de {period, encaisse, decaisse, net}.
    freq : 'D' | 'W' | 'M' | 'Y'. filtered_dates : ensemble de dates à retenir (freq 'D')."""
    flow = treasury_daily_flow(enc_data, dec_data)
    _filt = set(filtered_dates) if filtered_dates else None
    buckets = {}
    for d in sorted(flow.keys()):
        if _filt is not None and d not in _filt:
            continue
        k = treasury_period_key(d, freq)
        b = buckets.setdefault(k, {"period": k, "encaisse": 0.0, "decaisse": 0.0})
        b["encaisse"] += flow[d]["encaisse"]
        b["decaisse"] += flow[d]["decaisse"]
    out = []
    for k in sorted(buckets.keys()):
        b = buckets[k]
        b["net"] = b["encaisse"] - b["decaisse"]
        out.append(b)
    return out


def treasury_strat_records(data, dim_key, freq="D", filtered_dates=None, top_n=6):
    """Agrégation d'une dimension (par_categorie / par_produit / par_canal /
    par_service / par_fournisseur) par période. Retourne (periods, series)
    où series = {dim: [valeurs alignées sur periods]} ; les dimensions hors
    top_n sont regroupées sous "Autres"."""
    _filt = set(filtered_dates) if filtered_dates else None
    totals, buckets = {}, {}
    for d, sites in (data or {}).items():
        if _filt is not None and d not in _filt:
            continue
        k = treasury_period_key(d, freq)
        for _site, vals in (sites or {}).items():
            if not isinstance(vals, dict):
                continue
            for dim, v in (vals.get(dim_key) or {}).items():
                v = v or 0
                totals[dim] = totals.get(dim, 0) + v
                buckets.setdefault(k, {}).setdefault(dim, 0)
                buckets[k][dim] += v
    periods = sorted(buckets.keys())
    if not periods:
        return [], {}
    top_dims = [d for d, _ in sorted(totals.items(), key=lambda kv: kv[1], reverse=True)[:top_n] if totals[d] != 0]
    series = {d: [] for d in top_dims}
    series["Autres"] = []
    for k in periods:
        row = buckets[k]
        others = 0.0
        for d in top_dims:
            series[d].append(row.get(d, 0))
        for dim, v in row.items():
            if dim not in top_dims:
                others += v
        series["Autres"].append(others)
    if all(v == 0 for v in series["Autres"]):
        series.pop("Autres")
    return periods, series


def treasury_totals_for_months(enc_data, dec_data, year, months):
    """Totaux encaissements / décaissements / net pour une liste de mois donnés
    d'une année. Retourne None si aucun flux ne couvre la période."""
    tot_enc = tot_dec = 0.0
    found = False
    flow = treasury_daily_flow(enc_data, dec_data)
    for d, v in flow.items():
        if d[:4] == str(year) and int(d[5:7]) in set(months):
            tot_enc += v["encaisse"]
            tot_dec += v["decaisse"]
            found = True
    if not found:
        return None
    return {"encaisse": tot_enc, "decaisse": tot_dec, "net": tot_enc - tot_dec}





