def _load_weekly_data():
    """Load weekly data from donnees_hebdomadaires.json (PDF-derived + Excel enriched)."""
    _json_path = _os.path.join(_os.path.dirname(_os.path.abspath(__file__)), "donnees_hebdomadaires.json")
    if _os.path.exists(_json_path):
        try:
            with open(_json_path, "r", encoding="utf-8") as f:
                raw = _json.load(f)
            # Transform from {week: {site: data}} to {week: data} for each site
            result = {}
            for week_key, sites in raw.items():
                for site_name, data in sites.items():
                    # Build unique key: use week + site suffix
                    site_suffix = "DEX 1" if "dex_1" in site_name.lower() or site_name == "DEX 1" else "DEX 2"
                    unique_key = f"{week_key}_{site_suffix}"
                    # Ensure site field is set
                    if "site" not in data:
                        data["site"] = f"Site 1 (DEX 1)" if site_suffix == "DEX 1" else f"Site 2 (DEX 2)"
                    result[unique_key] = data
            return result
        except Exception as e:
            print(f"Warning: Could not load donnees_hebdomadaires.json: {e}")
            return {}
    return {}

