# ============================================================
# WEEKLY AGGREGATION FROM DAILY DATA (NEW STRUCTURE)
# ============================================================

def get_week_key(date_str):
    """Get ISO week key from date string."""
    dt = datetime.strptime(date_str.replace("_S2", ""), "%Y-%m-%d")
    return f"{dt.year}-W{dt.isocalendar()[1]:02d}"

def aggregate_daily_to_weekly():
    """Aggregate DAILY_DATA to weekly (new DEX structure)."""
    weekly = defaultdict(lambda: {"dex_1": defaultdict(float), "dex_2": defaultdict(float), "incidents": []})
    for date_str, dex_data in DAILY_DATA.items():
        week_key = get_week_key(date_str)
        for dex_name, data in dex_data.items():
            site_key = dex_name.lower().replace(" ", "_")
            # Expedition totals
            exp = data.get("expedition", {})
            for prod_key, prod_val in exp.items():
                if isinstance(prod_val, dict):
                    for mode, val in prod_val.items():
                        if isinstance(val, (int, float)):
                            weekly[week_key][site_key][f"exp_{prod_key}_{mode}"] += val
                elif isinstance(prod_val, (int, float)):
                    weekly[week_key][site_key][f"exp_{prod_key}"] += prod_val
            # Production totals
            prod = data.get("production", {})
            # Matières premières
            mp = prod.get("matieres_premieres", {})
            for mat_key, mat_val in mp.items():
                if isinstance(mat_val, dict):
                    total_mat = 0
                    for sk, sv in mat_val.items():
                        if isinstance(sv, (int, float)):
                            total_mat += sv
                    weekly[week_key][site_key][f"mp_{mat_key}"] += total_mat
            # Total production
            tp = prod.get("total_production", {})
            if isinstance(tp, (int, float)):
                if tp > 0:
                    weekly[week_key][site_key]["prod_total_total"] += tp
            elif isinstance(tp, dict):
                for sk, sv in tp.items():
                    if isinstance(sv, (int, float)):
                        weekly[week_key][site_key][f"prod_total_{sk}"] += sv
            # CES
            ces = prod.get("ces_mills", {})
            for sk, sv in ces.items():
                if isinstance(sv, (int, float)):
                    weekly[week_key][site_key][f"ces_{sk}"] += sv
            # Fuel
            fuel = prod.get("fuel_mills", {})
            for sk, sv in fuel.items():
                if isinstance(sv, (int, float)):
                    weekly[week_key][site_key][f"fuel_{sk}"] += sv
            # Temps broyage
            tb = prod.get("temps_broyage", {})
            for sk, sv in tb.items():
                if isinstance(sv, (int, float)):
                    weekly[week_key][site_key][f"tps_broyage_{sk}"] += sv
            # Debit
            db = prod.get("debit_broyeur", {})
            for sk, sv in db.items():
                if isinstance(sv, (int, float)):
                    weekly[week_key][site_key][f"debit_{sk}"] += sv
            # Incidents
            weekly[week_key]["incidents"].extend(data.get("faits_marquants", []))
    return dict(weekly)

WEEKLY_DATA_DAILY = aggregate_daily_to_weekly()

def aggregate_daily_to_monthly():
    """Aggregate DAILY_DATA to monthly (new DEX structure)."""
    monthly = defaultdict(lambda: {"dex_1": defaultdict(float), "dex_2": defaultdict(float), "incidents": []})
    for date_str, dex_data in DAILY_DATA.items():
        month_key = date_str.replace("_S2", "")[:7]
        for dex_name, data in dex_data.items():
            site_key = dex_name.lower().replace(" ", "_")
            # Expedition
            exp = data.get("expedition", {})
            for prod_key, prod_val in exp.items():
                if isinstance(prod_val, dict):
                    for mode, val in prod_val.items():
                        if isinstance(val, (int, float)):
                            monthly[month_key][site_key][f"exp_{prod_key}_{mode}"] += val
                elif isinstance(prod_val, (int, float)):
                    monthly[month_key][site_key][f"exp_{prod_key}"] += prod_val
            # Production
            prod = data.get("production", {})
            mp = prod.get("matieres_premieres", {})
            for mat_key, mat_val in mp.items():
                if isinstance(mat_val, dict):
                    total_mat = 0
                    for sk, sv in mat_val.items():
                        if isinstance(sv, (int, float)):
                            total_mat += sv
                    monthly[month_key][site_key][f"mp_{mat_key}"] += total_mat
            tp = prod.get("total_production", {})
            if isinstance(tp, (int, float)):
                if tp > 0:
                    monthly[month_key][site_key]["prod_total_total"] += tp
            elif isinstance(tp, dict):
                for sk, sv in tp.items():
                    if isinstance(sv, (int, float)):
                        monthly[month_key][site_key][f"prod_total_{sk}"] += sv
            ces = prod.get("ces_mills", {})
            for sk, sv in ces.items():
                if isinstance(sv, (int, float)):
                    monthly[month_key][site_key][f"ces_{sk}"] += sv
            fuel = prod.get("fuel_mills", {})
            for sk, sv in fuel.items():
                if isinstance(sv, (int, float)):
                    monthly[month_key][site_key][f"fuel_{sk}"] += sv
            tb = prod.get("temps_broyage", {})
            for sk, sv in tb.items():
                if isinstance(sv, (int, float)):
                    monthly[month_key][site_key][f"tps_broyage_{sk}"] += sv
            db = prod.get("debit_broyeur", {})
            for sk, sv in db.items():
                if isinstance(sv, (int, float)):
                    monthly[month_key][site_key][f"debit_{sk}"] += sv
            monthly[month_key]["incidents"].extend(data.get("faits_marquants", []))
    return dict(monthly)

