def init_session_state():

    # Only run once per session to avoid overwriting widget values on every rerun

    if "_miif_initialized" in st.session_state:

        return



    # Step 1: Load persisted state (if exists) — with performance filtering
    loaded_state = {}

    if os.path.exists(PERSIST_FILE):
        file_size = os.path.getsize(PERSIST_FILE)
        # If file is >10MB, skip loading (too large — will cause slowdown)
        if file_size > 10 * 1024 * 1024:  # 10MB limit
            st.toast(f"ibid_state.json trop volumineux ({file_size/1024/1024:.1f} MB). Etat non charge. Utilisez le bouton 'Nettoyer' dans Parametres.", icon="⚠️")
        else:
            try:
                with open(PERSIST_FILE, "r", encoding="utf-8") as f:
                    loaded_state = json.load(f)
            except Exception:
                pass

    # PERFORMANCE: Filter out large data keys on load
    LARGE_DATA_KEYS = {
        "DAILY_DATA", "daily_data", "WEEKLY_DATA", "weekly_data",
        "BD_BROYEUR_DAILY", "BD_BROYEUR_WEEKLY", "BD_BROYEUR_MONTHLY",
        "BD_CONSO_MATIERES_DAILY", "BD_CONSO_MATIERES_WEEKLY", "BD_CONSO_MATIERES_MONTHLY",
        "BD_EXPEDITION_DAILY", "BD_EXPEDITION_WEEKLY", "BD_EXPEDITION_MONTHLY",
        "HISTORICAL_FINANCIAL_DATA", "SCENARIO_HISTORY", "BUDGET_SCENARIOS",
        "ibid_evolution_records", "ibid_data_records", "ibid_all_records",
        "ibid_silo_stock_records", "_daily_data_json_mtime", "_cache_version",
    }
    loaded_state = {k: v for k, v in loaded_state.items() if k not in LARGE_DATA_KEYS}



    # Step 2: Set base value keys from loaded state or defaults

    for k, v in VALUE_KEYS.items():

        if k in loaded_state:

            st.session_state[k] = _deserialize_value(loaded_state[k])

        elif k not in st.session_state:

            st.session_state[k] = v



    # Step 2b: Detect default value changes and update session_state accordingly

    # If user changed VALUE_KEYS in source code, update session_state for keys that

    # still have the OLD default value (preserving manually modified values)

    old_defaults = st.session_state.get("_value_keys_defaults", {})

    if old_defaults:

        for k, new_v in VALUE_KEYS.items():

            if k in old_defaults:

                old_v = old_defaults[k]

                if old_v != new_v:

                    # Default changed! Update only if user hasn't manually modified

                    current_val = st.session_state.get(k)

                    if current_val == old_v or (isinstance(current_val, float) and isinstance(old_v, float) and abs(current_val - old_v) < 1e-9):

                        st.session_state[k] = new_v

                        # Also update widget input key if it exists

                        input_key = f"{k}_input"

                        if input_key in st.session_state:

                            input_val = st.session_state[input_key]

                            if input_val == old_v or (isinstance(input_val, float) and isinstance(old_v, float) and abs(input_val - old_v) < 1e-9):

                                st.session_state[input_key] = new_v

    # Store current defaults for next run comparison

    st.session_state["_value_keys_defaults"] = {k: v for k, v in VALUE_KEYS.items()}



    # Step 3: Sync widget input keys from loaded/base values

    for k in VALUE_KEYS.keys():

        input_key = f"{k}_input"

        if input_key in loaded_state:

            st.session_state[input_key] = _deserialize_value(loaded_state[input_key])

        elif input_key not in st.session_state:

            st.session_state[input_key] = st.session_state.get(k, VALUE_KEYS.get(k, 0))



    # Step 4: Load any other persisted keys (like scenario_history)

    EXCLUDED_KEYS = {

        "FormSubmitter", "file_uploader", "scenario_uploader", "scenario_history_selector",

        "suggestion_selector", "scenario_selector", "budget_mode_input",

        "kimi_wishlist_input", "save_name", "btn_load_selected_scenario",

        "btn_delete_selected_scenario", "btn_apply_selected_suggestion",

        "btn_reject_selected_suggestion", 
        "btn_apply_market_data", "btn_reset_market_data",

        "btn_close_kimi_modal", "btn_close_info", "export_kimi", "export_info",

        "ibid_logout_btn", "ibid_login_btn", "ibid_unlock_btn", "ibid_lock_btn",

        "ibid_lock_from_active_btn",

    }

    # Keys that should always be overridden from persisted state (lightweight user data)
    _OVERRIDE_KEYS = {"scenario_history", "budget_scenarios", "dismissed_suggestions",
                      "applied_suggestions", "kimi_wishlist_history"}

    for k, v in loaded_state.items():

        if (k not in st.session_state or k in _OVERRIDE_KEYS) and not k.endswith("_input") and k not in EXCLUDED_KEYS and not k.startswith("btn_") and not k.endswith("_btn"):

            st.session_state[k] = _deserialize_value(v)



    
    # Initialize log lists if not present (defensive against corrupted state)
    if "dismissed_suggestions_log" not in st.session_state:
        st.session_state["dismissed_suggestions_log"] = []
    if "applied_suggestions_log" not in st.session_state:
        st.session_state["applied_suggestions_log"] = []
    # Ensure dismissed_suggestions and applied_suggestions are proper sets
    for set_key in ["dismissed_suggestions", "applied_suggestions"]:
        get_clean_set(set_key)  # This cleans and returns the set

# Mark as initialized

    st.session_state["_miif_initialized"] = True



    # Initialize AI search state

    if "ai_search_query" not in st.session_state:

        st.session_state["ai_search_query"] = ""

    if "ai_search_trigger" not in st.session_state:

        st.session_state["ai_search_trigger"] = None

    if "ai_search_result" not in st.session_state:

        st.session_state["ai_search_result"] = {}

    if "ai_search_show_result" not in st.session_state:

        st.session_state["ai_search_show_result"] = False



