def get_val(key):

    """Get the current value - prefer the value key, fallback to input key"""

    return st.session_state.get(key, st.session_state.get(f"{key}_input", VALUE_KEYS.get(key, 0)))



def set_val(key, value):

    """Set a value key safely (never touches widget input keys)"""

    st.session_state[key] = value



def sync_widget_to_value(key):

    """Sync widget input key back to value key after widget creation"""

    input_key = f"{key}_input"

    if input_key in st.session_state:

        st.session_state[key] = st.session_state[input_key]



def get_maintenance_labor_monthly(site):

    """MO maintenance mensuelle (XOF) = Heures Maint. x Cout heure maint.

    NON incluse dans Cout Maint. S1/S2 (qui couvre pieces + prestations externes)."""

    sk = site.lower().replace(" ", "")

    return get_val(f"maintenance_hours_{sk}") * get_val("maintenance_labor_cost_hour")



def get_weighted_kc_ratio():

    """Ratio K/C moyen pondere par les volumes mensuels de base (inputs sidebar)."""

    _num, _den = 0.0, 0.0

    for p in PRODUCTS:

        _v = get_val(f"vol_{normalize_product_key(p)}_site1") + get_val(f"vol_{normalize_product_key(p)}_site2")

        _num += KC_RATIOS[p] * _v

        _den += _v

    return _num / _den if _den > 0 else 0.65



def format_xof(val):

    if abs(val) >= 1e9: return f"{val/1e9:.2f} Mds XOF"

    elif abs(val) >= 1e6: return f"{val/1e6:.1f} M XOF"

    elif abs(val) >= 1e3: return f"{val/1e3:.0f} k XOF"

    else: return f"{val:,.0f} XOF"





