def dg_kpi_box(label, value, delta_text="", delta_class="neu", tooltip_html="", extra_html=""):

    """Boîte KPI au style Tableau de Bord DG : carte kpi-card + libellé / valeur / delta,

    avec infobulle riche optionnelle (icône ℹ) et ligne d'écarts optionnelle.

    Toutes les boîtes de l'app suivent ce style."""

    _delta = f"<div class='kpi-delta {delta_class}'>{delta_text}</div>" if delta_text else ""

    _extra = (f"<div class='kpi-delta neu' style='font-size:0.66rem; margin-top:3px; line-height:1.6;'>"

              f"{extra_html}</div>") if extra_html else ""

    return (f"<div class='kpi-card'>{tooltip_html}<div>"

            f"<div class='kpi-label'>{label}</div>"

            f"<div class='kpi-value'>{value}</div>{_delta}{_extra}</div></div>")



def _variance_values(monthly_vals, year, pp=False):

    """Écarts d'une série mensuelle {AAAA-MM: valeur} pour l'année donnée :
    yoy  = cumul année vs mêmes mois de l'année N-1 ;
    mom  = dernier mois vs mois précédent ;
    myoy = dernier mois vs même mois de l'année N-1.
    pp=True : série déjà en % (ex. marge) → écarts en points."""

    keys = sorted(k for k in monthly_vals if k.startswith(f"{year}-"))

    if not keys:

        return {"yoy": None, "mom": None, "myoy": None}

    # Le mois calendaire en cours est partiel : on compare sur les mois complets

    _now_key = f"{datetime.now().year}-{datetime.now().month:02d}"

    full_keys = [k for k in keys if k != _now_key] or keys

    def _diff(a, b):

        if pp:

            return a - b

        return (a / b - 1) * 100 if b else None

    months_nums = [int(k.split("-")[1]) for k in full_keys]

    cur = sum(monthly_vals[k] for k in full_keys)

    prev_keys = [f"{year-1}-{m:02d}" for m in months_nums]

    prev = sum(monthly_vals[k] for k in prev_keys if k in monthly_vals)

    yoy = _diff(cur, prev) if (all(k in monthly_vals for k in prev_keys) and (prev or pp)) else None

    last_k = full_keys[-1]

    last_v = monthly_vals[last_k]

    lm = int(last_k.split("-")[1])

    pk_m = f"{year}-{lm-1:02d}"

    mom = _diff(last_v, monthly_vals[pk_m]) if pk_m in monthly_vals else None

    pk_y = f"{year-1}-{lm:02d}"

    myoy = _diff(last_v, monthly_vals[pk_y]) if pk_y in monthly_vals else None

    return {"yoy": yoy, "mom": mom, "myoy": myoy}



def _variance_line(monthly_vals, year, pp=False, invert=False):

    """Ligne HTML compacte des écarts pour une boîte KPI (N-1 · M/M-1 · M/N-1).
    invert=True : une hausse est défavorable (ex. kWh/t, consommations) → couleurs inversées."""

    _v = _variance_values(monthly_vals, year, pp=pp)

    parts = []

    for lbl, val in [("N-1", _v["yoy"]), ("M/M-1", _v["mom"]), ("M/N-1", _v["myoy"])]:

        if val is None:

            continue

        arrow = "▲" if val >= 0 else "▼"

        col = "#10b981" if ((val >= 0) != invert) else "#ef4444"

        suffix = " pts" if pp else "%"

        parts.append(f"<span style='color:#5B6770;'>{lbl}</span> <span style='color:{col};'>{arrow}{abs(val):.1f}{suffix}</span>")

    return " · ".join(parts)




def hover_lines_to_html(lines):

    """Convertit des lignes de survol (marqueurs '— Section —') en corps d'infobulle DG."""

    _parts = []

    for _l in lines:

        _l = str(_l)

        if _l.startswith("—") and _l.endswith("—"):

            _parts.append(f"<div class='popover-section-label' style='margin-top:6px;'>{_l.strip('— ')}</div>")

        else:

            _parts.append(f"<div class='popover-inputs'>{_l}</div>")

    return "".join(_parts)



def safe_div(a, b, default=0):

    try: return a / b if b != 0 else default

    except: return default


