# LINEAR PROGRAMMING — Production Allocation Optimizer
# ============================================================

def _compute_unit_profit(product, site):
    """Compute profit per tonne for a product-site combination."""
    pk = normalize_product_key(product)
    kc = KC_RATIOS.get(product, 0.5)
    _mix = {a: get_val(f"form_{pk}_{a}") for a in ("gypse", "granite", "laitier", "calcaire", "pouzzolane")}
    mat_cost = kc * get_val("clinker_cost") + sum(_mix[a] * get_val(f"{a}_cost") for a in _mix)
    kwh_key = f"kwh_per_tonne_{pk}_{site.lower().replace(' ', '_')}"
    kwh = get_val(kwh_key) if kwh_key in VALUE_KEYS else get_val(f"kwh_per_tonne_{pk}")
    energy_cost = kwh * get_val("tarif_kwh")
    fuel_cost = sum(get_val(f"fuel_{f}_dose_{pk}_{site.lower().replace(' ', '_')}") * kc * get_val(f"fuel_{f}_price") for f in ("gasoil", "fuel", "ddo", "cnsl"))
    adj_cost = sum(get_val(f"adjuvant_{a}_dose_{pk}_{site.lower().replace(' ', '_')}") / 1000.0 * get_val(f"adjuvant_{a}_price") for a in ("pegasus", "sika", "chryso", "biolatex"))
    sac_cost = get_val("sac_cost_per_unit") * get_val("sacs_per_tonne") * min(1.0, get_val(f"sac_exw_pct_{pk}") + get_val(f"sac_ddp_pct_{pk}"))
    var_cost = mat_cost + energy_cost + fuel_cost + adj_cost + sac_cost + get_val("commercial_cost_per_tonne")
    price = get_val(f"price_{pk}")
    return price - var_cost


def optimize_production_allocation(objective="max_profit", total_demand=None):
    """Optimize production allocation across sites using LP."""
    try:
        from scipy.optimize import linprog
    except ImportError:
        return None, 0, "scipy non disponible"
    
    variables = [(p, s) for p in PRODUCTS for s in SITES]
    n_vars = len(variables)
    var_index = {v: i for i, v in enumerate(variables)}
    
    c = np.zeros(n_vars)
    for i, (p, s) in enumerate(variables):
        if objective == "max_profit":
            c[i] = -_compute_unit_profit(p, s)
        elif objective == "min_cost":
            # approximate: maximize negative profit
            c[i] = -_compute_unit_profit(p, s) * 0.5 + 1000
        elif objective == "max_volume":
            c[i] = -1.0
        elif objective == "max_ebitda":
            c[i] = -_compute_unit_profit(p, s) * 0.85
        else:
            c[i] = -_compute_unit_profit(p, s)
    
    A_ub, b_ub = [], []
    # Site capacity
    for s in SITES:
        cap = SITE_CAPACITIES.get(s, 1_000_000)
        row = np.zeros(n_vars)
        for p in PRODUCTS:
            if (p, s) in var_index:
                row[var_index[(p, s)]] = 1.0
        A_ub.append(row)
        b_ub.append(cap)
    
    # Product demand equality (as two inequalities)
    if total_demand:
        for p, demand in total_demand.items():
            if p in PRODUCTS and demand > 0:
                row = np.zeros(n_vars)
                for s in SITES:
                    if (p, s) in var_index:
                        row[var_index[(p, s)]] = 1.0
                A_ub.append(row)
                b_ub.append(demand)
                A_ub.append(-row)
                b_ub.append(-demand * 0.98)
    
    bounds = [(0, None) for _ in range(n_vars)]
    result = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub), bounds=bounds, method='highs')
    
    if result.success:
        optimal = {variables[i]: result.x[i] for i in range(n_vars) if result.x[i] > 1}
        obj_val = -result.fun if objective in ("max_profit", "max_volume", "max_ebitda") else result.fun
        return optimal, obj_val, f"Optimal — {obj_val/1e6:.2f} Mds XOF"
    return None, 0, f"Echec: {result.message}"


def apply_lp_optimization(objective="max_profit"):
    """Run LP and update session_state volumes."""
    total_demand = {}
    for p in PRODUCTS:
        pk = normalize_product_key(p)
        total = sum(get_val(f"vol_{pk}_{s.lower().replace(' ', '_')}") for s in SITES)
        if total > 0:
            total_demand[p] = total
    
    optimal, obj_val, status = optimize_production_allocation(objective, total_demand)
    if optimal:
        for (p, s), vol in optimal.items():
            pk = normalize_product_key(p)
            sk = s.lower().replace(' ', '_')
            st.session_state[f"vol_{pk}_{sk}"] = round(vol, 2)
            st.session_state[f"vol_{pk}_{sk}_input"] = round(vol, 2)
    return optimal, obj_val, status



def normalize_product_key(prod_name):

    mapping = {"CPA 52.5": "cpa", "CPJ 42.5": "cpj42", "CPJ 32.5": "cpj32"}

    return mapping.get(prod_name, prod_name.lower().replace(' ', '').replace('.', ''))



def get_monthly_factor(month_idx):

    return list(SEASONALITY_FACTORS.values())[month_idx]




# ============================================================
# CONTRAINTES PHYSIQUES & ALLOCATION LP — v2.6
# ============================================================

def _compute_unit_variable_cost(product, site):
    """Coût variable par tonne pour un (produit, site) donné."""
    pk = normalize_product_key(product)
    kc = KC_RATIOS.get(product, 0.5)

    # Matières premières
    mat = kc * get_val("clinker_cost")
    for add in ("gypse", "granite", "laitier", "calcaire", "pouzzolane"):
        mat += get_val(f"form_{pk}_{add}") * get_val(f"{add}_cost")

    si = site[-1]  # "1" ou "2"

    # Énergie électrique
    kwh_key = f"kwh_per_tonne_{pk}_site{si}"
    kwh = get_val(kwh_key) if kwh_key in VALUE_KEYS else get_val(f"kwh_per_tonne_{pk}")
    ener = kwh * get_val("tarif_kwh")

    # Combustibles
    fuel = 0
    for f in ("gasoil", "fuel", "ddo", "cnsl"):
        dose = get_val(f"fuel_{f}_dose_{pk}_site{si}")
        fuel += dose * kc * get_val(f"fuel_{f}_price")

    # Adjuvants
    adj = 0
    for a in ("pegasus", "sika", "chryso", "biolatex"):
        adj += get_val(f"adjuvant_{a}_dose_{pk}_site{si}") / 1000.0 * get_val(f"adjuvant_{a}_price")

    # Sac
    sac = get_val("sac_cost_per_unit") * get_val("sacs_per_tonne")

    # Transport
    dist = get_val(f"avg_distance_site{si}")
    trans = dist * get_val("transport_cost_per_tkm")

    # Commercial
    comm = get_val("commercial_cost_per_tonne")

    return mat + ener + fuel + adj + sac + trans + comm


def _get_effective_capacity(site, factor=1.0):
    """Capacité effective mensuelle (avec maintenance downtime)."""
    cap = SITE_CAPACITIES.get(site, 1_000_000)
    downtime = get_val(f"maintenance_downtime_pct_site{site[-1]}")
    return cap * (1 - downtime) / 12.0 * factor


def _apply_lp_reallocation(prod_dict, factor=1.0):
    """
    Allocation optimale par programmation linéaire (heuristique gloutonne).

    ORDRE:
    1. Contraintes de mix produit (max % par site) — APPLIQUÉES EN PREMIER
    2. Allocation du reste par coût variable croissant
    3. Vérification capacité par site (hard constraint)

    Retourne: prod_alloue, warnings
    """
    import copy
    prod = copy.deepcopy(prod_dict)
    warnings = []

    # Capacités effectives
    eff_cap = {s: _get_effective_capacity(s, factor) for s in SITES}

    # Volumes cibles par produit
    target_by_product = {p: sum(prod.get((p, s), 0) for s in SITES) for p in PRODUCTS}

    # Coûts variables par (produit, site)
    cv = {}
    for p in PRODUCTS:
        for s in SITES:
            cv[(p, s)] = _compute_unit_variable_cost(p, s)

    # ── ÉTAPE 1: Vérifier capacité globale ──
    total_target = sum(target_by_product.values())
    total_eff_cap = sum(eff_cap.values())

    if total_target > total_eff_cap and total_eff_cap > 0:
        global_scale = total_eff_cap / total_target
        for p in PRODUCTS:
            target_by_product[p] *= global_scale
        warnings.append(
            "⚠️ Capacité globale insuffisante: scaling global ×{:.3f}".format(global_scale)
        )

    # ── ÉTAPE 2: Allocation avec contraintes de mix EN PREMIER ──
    prod_out = {}
    remaining_cap = dict(eff_cap)

    # Contraintes de mix: (produit, site_max, max_pct_key)
    mix_constraints = [
        ("CPA 52.5", "Site 1", "site1_cpa_max_pct"),
        ("CPJ 32.5", "Site 2", "site2_cpj32_max_pct"),
    ]

    for p in PRODUCTS:
        target = target_by_product[p]
        prod_out[(p, "Site 1")] = 0
        prod_out[(p, "Site 2")] = 0

        # Trouver si ce produit a une contrainte de mix
        mix_rule = None
        for mp, msite, mkey in mix_constraints:
            if mp == p:
                mix_rule = (msite, get_val(mkey))
                break

        if mix_rule and mix_rule[1] >= 0:
            max_site, max_pct = mix_rule
            other_site = "Site 2" if max_site == "Site 1" else "Site 1"

            # Allouer le max autorisé sur le site contraint
            max_on_constrained = target * max_pct
            alloc_constrained = min(max_on_constrained, remaining_cap[max_site])
            prod_out[(p, max_site)] = alloc_constrained
            remaining_cap[max_site] -= alloc_constrained
            target -= alloc_constrained

            # Allouer le reste sur l'autre site (si possible)
            if target > 0:
                alloc_other = min(target, remaining_cap[other_site])
                prod_out[(p, other_site)] = alloc_other
                remaining_cap[other_site] -= alloc_other
                target -= alloc_other

            # Si encore du reste (capacité insuffisante sur les deux sites)
            if target > 0:
                # Redistribuer proportionnellement sur les deux sites selon capacité restante
                total_rem = remaining_cap["Site 1"] + remaining_cap["Site 2"]
                if total_rem > 0:
                    for s in SITES:
                        extra = target * (remaining_cap[s] / total_rem)
                        prod_out[(p, s)] += extra
                        remaining_cap[s] -= extra
        else:
            # Pas de contrainte de mix → allocation LP pure par coût croissant
            sites_by_cost = sorted(SITES, key=lambda s: cv[(p, s)])
            for s in sites_by_cost:
                if remaining_cap[s] <= 0:
                    continue
                alloc = min(target, remaining_cap[s])
                prod_out[(p, s)] = alloc
                remaining_cap[s] -= alloc
                target -= alloc
                if target <= 0:
                    break

        if target > 0:
            warnings.append(
                "⚠️ {}: {:.1f} kt non alloués (capacité saturée)".format(p, target/1000)
            )

    # ── ÉTAPE 3: Vérification finale capacité (sécurité) ──
    for s in SITES:
        site_total = sum(prod_out.get((p, s), 0) for p in PRODUCTS)
        if site_total > eff_cap[s] and eff_cap[s] > 0:
            scale = eff_cap[s] / site_total
            for p in PRODUCTS:
                k = (p, s)
                if k in prod_out:
                    prod_out[k] *= scale
            warnings.append(
                "⚠️ {}: scaling final ×{:.3f} (capacité {:.1f} kt dépassée)".format(
                    s, scale, site_total/1000
                )
            )

    return prod_out, warnings

def _apply_physical_constraints(prod_dict, factor=1.0, prefer_lp=True):
    """
    Applique TOUTES les contraintes physiques sur les volumes.

    Contraintes:
    1. Capacité par site (hard)
    2. Mix produit CPA 52.5 (max % Site 1)
    3. Mix produit CPJ 32.5 (max % Site 2)
    4. Capacité globale (hard)

    Si prefer_lp=True: essaie d'abord la réallocation LP.
    Sinon: scaling proportionnel simple.

    Retourne: (prod_constrained, warnings, cap_util)
    """
    import copy
    prod = copy.deepcopy(prod_dict)
    warnings = []

    # Capacités effectives
    eff_cap = {s: _get_effective_capacity(s, factor) for s in SITES}

    # Volumes cibles par produit
    target_by_product = {p: sum(prod.get((p, s), 0) for s in SITES) for p in PRODUCTS}
    total_target = sum(target_by_product.values())
    total_eff_cap = sum(eff_cap.values())

    # ── DÉCISION: LP ou scaling ? ──
    needs_lp = False

    # Vérifier si un site dépasse sa capacité
    for s in SITES:
        site_total = sum(prod.get((p, s), 0) for p in PRODUCTS)
        if site_total > eff_cap[s]:
            needs_lp = True
            break

    # Vérifier si capacité globale insuffisante
    if total_target > total_eff_cap:
        needs_lp = True

    # Vérifier contraintes de mix
    for p, max_site, max_pct_key in [("CPA 52.5", "Site 1", "site1_cpa_max_pct"),
                                        ("CPJ 32.5", "Site 2", "site2_cpj32_max_pct")]:
        total_p = sum(prod.get((p, s), 0) for s in SITES)
        if total_p > 0:
            pct = safe_div(prod.get((p, max_site), 0), total_p, 0)
            if pct > get_val(max_pct_key):
                needs_lp = True
                break

    if prefer_lp and needs_lp:
        # Utiliser l'allocation LP
        prod, warnings = _apply_lp_reallocation(prod, factor)
    else:
        # Scaling proportionnel classique (fallback)
        for s in SITES:
            site_total = sum(prod.get((p, s), 0) for p in PRODUCTS)
            if site_total > eff_cap[s] and eff_cap[s] > 0:
                scale = eff_cap[s] / site_total
                for p in PRODUCTS:
                    k = (p, s)
                    if k in prod:
                        prod[k] *= scale
                warnings.append(
                    "⚠️ {}: scaling proportionnel ×{:.3f} (capacité dépassée)".format(s, scale)
                )

        # Contraintes de mix (post-scaling)
        for p, max_site, max_pct_key, other_site in [
            ("CPA 52.5", "Site 1", "site1_cpa_max_pct", "Site 2"),
            ("CPJ 32.5", "Site 2", "site2_cpj32_max_pct", "Site 1")
        ]:
            total_p = sum(prod.get((p, s), 0) for s in SITES)
            if total_p > 0:
                pct = safe_div(prod.get((p, max_site), 0), total_p, 0)
                max_pct = get_val(max_pct_key)
                if pct > max_pct:
                    target = total_p * max_pct
                    excess = prod.get((p, max_site), 0) - target
                    if excess > 0:
                        prod[(p, max_site)] = target
                        prod[(p, other_site)] = prod.get((p, other_site), 0) + excess
                        # Re-vérifier capacité après redistribution
                        for s2 in SITES:
                            st = sum(prod.get((px, s2), 0) for px in PRODUCTS)
                            if st > eff_cap[s2] and eff_cap[s2] > 0:
                                sc = eff_cap[s2] / st
                                for px in PRODUCTS:
                                    k = (px, s2)
                                    if k in prod:
                                        prod[k] *= sc
                                warnings.append(
                                    "⚠️ {}: saturation après redistribution {}".format(s2, p)
                                )

    # Calcul utilisation post-contrainte (clampé à 100%)
    total_by_site = {s: sum(prod.get((p, s), 0) for p in PRODUCTS) for s in SITES}
    cap_util = {s: min(safe_div(total_by_site[s], eff_cap[s], 0), 1.0) for s in SITES}

    return prod, warnings, cap_util


def calculate_monthly_model(month_idx=None):
    lp_applied = False
    lp_warnings = []

    try:

        factor = get_monthly_factor(month_idx) if month_idx is not None else 1.0



        # Budget mode: if calculated, derive budget from volume target and margin target

        if get_val("budget_mode") == "calculated":

            # Calculate implied budget revenue from volume and price

            implied_revenue = 0

            for p in PRODUCTS:

                for s in SITES:

                    vol_key = f"vol_{normalize_product_key(p)}_site{s[-1]}"

                    price_key = f"price_{normalize_product_key(p)}"

                    implied_revenue += get_val(vol_key) * get_val(price_key)  # Monthly

            set_val("budget_revenue", implied_revenue)

            set_val("budget_volume", sum(get_val(f"vol_{normalize_product_key(p)}_site{s[-1]}") for p in PRODUCTS for s in SITES))

            set_val("budget_ebitda", implied_revenue * get_val("budget_ebitda_margin"))



        # ── LECTURE VOLUMES BRUTS ──
        prod_raw = {}
        for prod_name in PRODUCTS:
            for site in SITES:
                key = f"vol_{normalize_product_key(prod_name)}_site{site[-1]}"
                prod_raw[(prod_name, site)] = get_val(key) * factor

        # ── APPLICATION CONTRAINTES PHYSIQUES (LP PREFERRED) ──
        prod, cap_warnings, cap_util_dict = _apply_physical_constraints(prod_raw, factor, prefer_lp=True)

        total_prod = {p: sum(prod.get((p, s), 0) for s in SITES) for p in PRODUCTS}
        total_by_site = {s: sum(prod.get((p, s), 0) for p in PRODUCTS) for s in SITES}
        grand_total = sum(total_prod.values())

        # Chemical formulation: per-product additive mix (from image: Gypse, Granite, Laitier, Calcaire, Pouzzolane)

        ADDITIVE_MIX = {

            "CPA 52.5": {"gypse": get_val("form_cpa_gypse"), "granite": get_val("form_cpa_granite"), "laitier": get_val("form_cpa_laitier"), "calcaire": get_val("form_cpa_calcaire"), "pouzzolane": get_val("form_cpa_pouzzolane")},

            "CPJ 42.5": {"gypse": get_val("form_cpj42_gypse"), "granite": get_val("form_cpj42_granite"), "laitier": get_val("form_cpj42_laitier"), "calcaire": get_val("form_cpj42_calcaire"), "pouzzolane": get_val("form_cpj42_pouzzolane")},

            "CPJ 32.5": {"gypse": get_val("form_cpj32_gypse"), "granite": get_val("form_cpj32_granite"), "laitier": get_val("form_cpj32_laitier"), "calcaire": get_val("form_cpj32_calcaire"), "pouzzolane": get_val("form_cpj32_pouzzolane")},

        }

        ADDITIVE_COSTS = {

            "gypse": get_val("gypse_cost"),

            "granite": get_val("granite_cost"),

            "laitier": get_val("laitier_cost"),

            "calcaire": get_val("calcaire_cost"),

            "pouzzolane": get_val("pouzzolane_cost"),

        }



        material_cost = {}

        material_cost_detail = {}

        # Chemical formulation per product (dynamique)

        ADDITIVE_MIX = {

            "CPA 52.5": {"gypse": get_val("form_cpa_gypse"), "granite": get_val("form_cpa_granite"), "laitier": get_val("form_cpa_laitier"), "calcaire": get_val("form_cpa_calcaire"), "pouzzolane": get_val("form_cpa_pouzzolane")},

            "CPJ 42.5": {"gypse": get_val("form_cpj42_gypse"), "granite": get_val("form_cpj42_granite"), "laitier": get_val("form_cpj42_laitier"), "calcaire": get_val("form_cpj42_calcaire"), "pouzzolane": get_val("form_cpj42_pouzzolane")},

            "CPJ 32.5": {"gypse": get_val("form_cpj32_gypse"), "granite": get_val("form_cpj32_granite"), "laitier": get_val("form_cpj32_laitier"), "calcaire": get_val("form_cpj32_calcaire"), "pouzzolane": get_val("form_cpj32_pouzzolane")},

        }

        ADDITIVE_COSTS = {

            "gypse": get_val("gypse_cost"),

            "granite": get_val("granite_cost"),

            "laitier": get_val("laitier_cost"),

            "calcaire": get_val("calcaire_cost"),

            "pouzzolane": get_val("pouzzolane_cost"),

        }



        for p in PRODUCTS:

            kc = KC_RATIOS[p]

            reliquat = 1 - kc

            mix = ADDITIVE_MIX[p]

            clinker_cost_per_t = kc * get_val("clinker_cost")

            additive_costs = {}

            total_additive_cost = 0

            for additive, proportion in mix.items():

                # proportion is now % of TOTAL mix (not % of reliquat)

                qty = proportion

                cost = qty * ADDITIVE_COSTS[additive]

                additive_costs[additive] = {"qty": qty, "cost_per_t": cost}

                total_additive_cost += cost

            material_cost[p] = clinker_cost_per_t + total_additive_cost

            material_cost_detail[p] = {

                "clinker": {"qty": kc, "cost_per_t": clinker_cost_per_t},

                "additives": additive_costs,

                "total_additive_cost": total_additive_cost,

                "total": material_cost[p],

                "reliquat": reliquat,

                "reliquat_check": sum(mix.values())

            }



        # CES par produit × site (CPJ 42.5 ventilé S1/S2 via inputs dédiés, repli sur la valeur globale)

        def _kwh_per_tonne(p, s):

            pk = normalize_product_key(p)

            sk = s.lower().replace(" ", "")

            site_key = f"kwh_per_tonne_{pk}_{sk}"

            return get_val(site_key) if site_key in VALUE_KEYS else get_val(f"kwh_per_tonne_{pk}")

        energy_cost_per_ts = {(p, s): _kwh_per_tonne(p, s) * get_val("tarif_kwh") for p in PRODUCTS for s in SITES}

        energy_cost_per_t = {

            p: (safe_div(sum(energy_cost_per_ts[(p, s)] * prod[(p, s)] for s in SITES), total_prod[p], 0)

                if total_prod[p] > 0 else _kwh_per_tonne(p, "Site 1") * get_val("tarif_kwh"))

            for p in PRODUCTS

        }

        # Combustibles (L/t clinker × ratio k/c × prix XOF/L) et adjuvants (g/t ciment × prix XOF/kg) par produit × site

        fuel_cost_per_ts = {}

        adjuvant_cost_per_ts = {}

        for p in PRODUCTS:

            pk = normalize_product_key(p)

            kc = KC_RATIOS[p]

            for s in SITES:

                sk = s.lower().replace(" ", "")

                fuel_cost_per_ts[(p, s)] = sum(get_val(f"fuel_{_f}_dose_{pk}_{sk}") * kc * get_val(f"fuel_{_f}_price") for _f in ("gasoil", "fuel", "ddo", "cnsl"))

                adjuvant_cost_per_ts[(p, s)] = sum(get_val(f"adjuvant_{_a}_dose_{pk}_{sk}") / 1000.0 * get_val(f"adjuvant_{_a}_price") for _a in ("pegasus", "sika", "chryso", "biolatex"))

        sac_cost_per_t = get_val("sac_cost_per_unit") * get_val("sacs_per_tonne")

        # Part ensachée par produit (mix expédition Sac EXW + Sac DDP) : le coût sac ne s'applique qu'aux tonnes en sacs

        sac_share = {p: min(1.0, get_val(f"sac_exw_pct_{normalize_product_key(p)}") + get_val(f"sac_ddp_pct_{normalize_product_key(p)}")) for p in PRODUCTS}

        transport_cost_per_t = {

            "Site 1": get_val("avg_distance_site1") * get_val("transport_cost_per_tkm"),

            "Site 2": get_val("avg_distance_site2") * get_val("transport_cost_per_tkm"),

        }



        def get_effective_price(p, site):

            base = get_val(f"price_{normalize_product_key(p)}")

            pk = normalize_product_key(p)

            vrac_exw = get_val(f"vrac_exw_pct_{pk}")

            vrac_ddp = get_val(f"vrac_ddp_pct_{pk}")

            sac_exw = get_val(f"sac_exw_pct_{pk}")

            sac_ddp = get_val(f"sac_ddp_pct_{pk}")

            # Weighted average price based on expedition mix

            return base + (vrac_exw + vrac_ddp) * get_val("vrac_premium") + (vrac_ddp + sac_ddp) * get_val("ddp_premium")



        revenue = {}

        for p in PRODUCTS:

            for s in SITES:

                revenue[(p, s)] = prod[(p, s)] * get_effective_price(p, s)

        total_revenue = sum(revenue.values())

        revenue_by_product = {p: sum(revenue[(p, s)] for s in SITES) for p in PRODUCTS}



        var_cost = {}

        for p in PRODUCTS:

            for s in SITES:

                mat = material_cost[p]

                ener = energy_cost_per_ts[(p, s)]

                sac = sac_cost_per_t * sac_share[p]

                trans = transport_cost_per_t[s]

                comm = get_val("commercial_cost_per_tonne")

                fuel = fuel_cost_per_ts[(p, s)]

                adj = adjuvant_cost_per_ts[(p, s)]

                var_cost[(p, s)] = prod[(p, s)] * (mat + ener + sac + trans + comm + fuel + adj)

        total_var_cost = sum(var_cost.values())

        var_cost_by_product = {p: sum(var_cost[(p, s)] for s in SITES) for p in PRODUCTS}



        fixed_site1 = get_val("fixed_cost_site1") * get_val("fixed_cost_coverage_rate_site1")

        fixed_site2 = get_val("fixed_cost_site2") * get_val("fixed_cost_coverage_rate_site2")



        # Maintenance costs : Cout Maint. (pieces + prestations, hors MO) + MO maintenance (heures x cout/h)

        maint_labor_site1 = get_maintenance_labor_monthly("Site 1")

        maint_labor_site2 = get_maintenance_labor_monthly("Site 2")

        maint_site1 = get_val("maintenance_cost_site1") + maint_labor_site1

        maint_site2 = get_val("maintenance_cost_site2") + maint_labor_site2

        total_maintenance = maint_site1 + maint_site2



        # Main-d'œuvre de production (coût fixe mensuel par site)

        labor_site1 = get_val("labor_cost_site1")

        labor_site2 = get_val("labor_cost_site2")

        total_labor = labor_site1 + labor_site2



        total_fixed = fixed_site1 + fixed_site2 + get_val("sga_cost") + total_maintenance + total_labor



        gross_margin = total_revenue - total_var_cost

        gross_margin_pct = safe_div(gross_margin, total_revenue, 0)

        ebitda = gross_margin - total_fixed

        ebitda_pct = safe_div(ebitda, total_revenue, 0)

        ebit = ebitda - get_val("amort_monthly")

        ebit_pct = safe_div(ebit, total_revenue, 0)

        ebt = ebit - get_val("interests_monthly")

        tax = max(0, ebt * get_val("tax_rate"))

        net_income = ebt - tax

        net_margin_pct = safe_div(net_income, total_revenue, 0)



        product_margin = {}

        product_contribution = {}

        # Clé de répartition des coûts fixes par produit (sidebar : volumes / CA / manuel)

        _alloc_mode = st.session_state.get("fixed_alloc_mode", "Prorata des volumes (t)")

        _alloc_manual = {"CPA 52.5": get_val("fixed_alloc_pct_cpa"), "CPJ 42.5": get_val("fixed_alloc_pct_cpj42"), "CPJ 32.5": get_val("fixed_alloc_pct_cpj32")}

        _alloc_manual_total = sum(_alloc_manual.values())

        for p in PRODUCTS:

            rev = revenue_by_product[p]

            vc = var_cost_by_product[p]

            product_margin[p] = rev - vc

            if _alloc_mode == "Prorata du CA":

                _share = safe_div(revenue_by_product[p], total_revenue, 0)

            elif _alloc_mode == "Manuel (% par produit)":

                _share = safe_div(_alloc_manual[p], _alloc_manual_total, 0)

            else:  # Prorata des volumes (t)

                _share = safe_div(total_prod[p], grand_total, 0)

            fixed_alloc = total_fixed * _share

            product_contribution[p] = product_margin[p] - fixed_alloc



        avg_price = safe_div(total_revenue, grand_total, 0)

        avg_cost = safe_div(total_var_cost + total_fixed, grand_total, 0)

        avg_var_cost_per_t = safe_div(total_var_cost, grand_total, 0)

        contribution_margin_per_t = avg_price - avg_var_cost_per_t

        break_even_tonnes = safe_div(total_fixed, contribution_margin_per_t, 0) if contribution_margin_per_t > 0 else 0

        break_even_revenue = break_even_tonnes * avg_price



        cogs = total_var_cost + total_fixed * 0.3

        dio = get_val("dio_days")

        dso = get_val("dso_days")

        dpo = get_val("dpo_days")

        ccc = dio + dso - dpo

        stock_value = cogs * (dio / 30)

        receivables = total_revenue * (dso / 30)

        payables = cogs * (dpo / 30)

        wc_requirement = stock_value + receivables - payables



        # Effective capacity accounting for maintenance downtime

        effective_capacity = {

            "Site 1": SITE_CAPACITIES["Site 1"] / 12 * (1 - get_val("maintenance_downtime_pct_site1")),

            "Site 2": SITE_CAPACITIES["Site 2"] / 12 * (1 - get_val("maintenance_downtime_pct_site2"))

        }

        cap_util = cap_util_dict  # Déjà calculé et contraint à ≤100% par _apply_physical_constraints

        overall_cap_util = min(safe_div(grand_total, sum(effective_capacity.values()), 0), 1.0)



        # User-defined capacity utilization targets vs actual

        cap_util_targets = {

            "Site 1": get_val("cap_util_target_site1"),

            "Site 2": get_val("cap_util_target_site2")

        }

        cap_util_actual = {

            "Site 1": get_val("cap_util_actual_site1"),

            "Site 2": get_val("cap_util_actual_site2")

        }



        budget_variance_ebitda = ebitda - get_val("budget_ebitda")

        budget_variance_revenue = total_revenue - get_val("budget_revenue")

        budget_variance_volume = grand_total - get_val("budget_volume")



        site_revenue = {s: sum(revenue[(p, s)] for p in PRODUCTS) for s in SITES}

        site_var_cost = {s: sum(var_cost[(p, s)] for p in PRODUCTS) for s in SITES}

        site_fixed = {"Site 1": fixed_site1, "Site 2": fixed_site2}

        site_ebitda = {

            "Site 1": site_revenue["Site 1"] - site_var_cost["Site 1"] - fixed_site1 - (get_val("sga_cost")/2) - maint_site1 - labor_site1,

            "Site 2": site_revenue["Site 2"] - site_var_cost["Site 2"] - fixed_site2 - (get_val("sga_cost")/2) - maint_site2 - labor_site2

        }



        return {

            "prod": prod, "total_prod": total_prod, "total_by_site": total_by_site,

            "grand_total": grand_total, "revenue": revenue, "total_revenue": total_revenue,

            "revenue_by_product": revenue_by_product, "var_cost": var_cost,

            "total_var_cost": total_var_cost, "var_cost_by_product": var_cost_by_product,

            "total_fixed": total_fixed, "fixed_site1": fixed_site1, "fixed_site2": fixed_site2,

            "maintenance_cost": total_maintenance, "maint_site1": maint_site1, "maint_site2": maint_site2,

            "maint_labor_site1": maint_labor_site1, "maint_labor_site2": maint_labor_site2,

            "gross_margin": gross_margin, "gross_margin_pct": gross_margin_pct,

            "ebitda": ebitda, "ebitda_pct": ebitda_pct, "ebit": ebit, "ebit_pct": ebit_pct,

            "net_income": net_income, "net_margin_pct": net_margin_pct,

            "product_margin": product_margin, "product_contribution": product_contribution,

            "avg_price": avg_price, "avg_cost": avg_cost,

            "break_even_tonnes": break_even_tonnes, "break_even_revenue": break_even_revenue,

            "contribution_margin_per_t": contribution_margin_per_t,

            "dio": dio, "dso": dso, "dpo": dpo, "ccc": ccc,

            "stock_value": stock_value, "receivables": receivables, "payables": payables,

            "wc_requirement": wc_requirement, "cap_util": cap_util, "overall_cap_util": overall_cap_util,

            "cap_util_targets": cap_util_targets, "cap_util_actual": cap_util_actual,

            "effective_capacity": effective_capacity,

            "budget_variance_ebitda": budget_variance_ebitda,

            "budget_variance_revenue": budget_variance_revenue,

            "budget_variance_volume": budget_variance_volume,

            "site_revenue": site_revenue, "site_var_cost": site_var_cost,

            "site_fixed": site_fixed, "site_ebitda": site_ebitda,

            "material_cost": material_cost, "energy_cost_per_t": energy_cost_per_t,

            "energy_cost_per_ts": energy_cost_per_ts, "fuel_cost_per_ts": fuel_cost_per_ts,

            "adjuvant_cost_per_ts": adjuvant_cost_per_ts, "sac_share": sac_share,

            "total_labor": total_labor, "labor_site1": labor_site1, "labor_site2": labor_site2,

            "fixed_alloc_mode": _alloc_mode,

            "cap_warnings": cap_warnings,
            "lp_applied": lp_applied, "lp_warnings": cap_warnings, "tax": tax, "factor": factor,

        }

    except Exception as e:

        st.error(f"Erreur de calcul: {e}")

        return {}



def calculate_annual_data():

    monthly_data = []

    annual_prod = {p: 0 for p in PRODUCTS}

    annual_revenue = {p: 0 for p in PRODUCTS}

    annual_var_cost = {p: 0 for p in PRODUCTS}

    annual_ebitda = 0

    annual_revenue_total = 0

    annual_net_income = 0



    for month_idx in range(12):

        res = calculate_monthly_model(month_idx)

        if res:

            monthly_data.append(res)

            for p in PRODUCTS:

                annual_prod[p] += res["total_prod"].get(p, 0)

                annual_revenue[p] += res["revenue_by_product"].get(p, 0)

                annual_var_cost[p] += res["var_cost_by_product"].get(p, 0)

            annual_ebitda += res.get("ebitda", 0)

            annual_revenue_total += res.get("total_revenue", 0)

            annual_net_income += res.get("net_income", 0)



    return {

        "monthly": monthly_data,

        "annual_prod": annual_prod,

        "annual_revenue": annual_revenue,

        "annual_var_cost": annual_var_cost,

        "annual_ebitda": annual_ebitda,

        "annual_revenue_total": annual_revenue_total,

        "annual_net_income": annual_net_income,

    }



def _compute_model_cascade(annual):

    """Cascade annuelle CA → Résultat Net (M XOF) calculée depuis le modèle."""

    ca = annual["annual_revenue_total"] / 1e6

    cv = sum(m.get("total_var_cost", 0) for m in annual["monthly"]) / 1e6

    mb = ca - cv

    cf = sum(m.get("total_fixed", 0) for m in annual["monthly"]) / 1e6

    eb = annual["annual_ebitda"] / 1e6

    amort = get_val("amort_monthly") * 12 / 1e6

    ebit = eb - amort

    inter = get_val("interests_monthly") * 12 / 1e6

    rai = ebit - inter

    imp = sum(m.get("tax", 0) for m in annual["monthly"]) / 1e6

    rn = annual["annual_net_income"] / 1e6

    labels = ["CA", "Coûts Variables", "Marge Brute", "Coûts Fixes", "EBITDA",
              "Amortissements", "EBIT", "Intérêts", "RAI", "Impôt", "Résultat Net"]

    values = [ca, -cv, mb, -cf, eb, -amort, ebit, -inter, rai, -imp, rn]

    measures = ["relative", "relative", "total", "relative", "total",
                "relative", "total", "relative", "total", "relative", "total"]

    return labels, values, measures



def _make_cascade_fig(labels, values, measures, title, unit="M XOF", dark=True):

    """Figure waterfall générique au style de l'app."""

    fig = go.Figure(go.Waterfall(

        name="Cascade", orientation="v", measure=measures, x=labels, y=values,

        text=[f"{v:,.0f}" for v in values], textposition="outside",

        connector={"line": {"color": "rgb(120, 120, 120)"}},

        decreasing={"marker": {"color": "#ef4444"}},

        increasing={"marker": {"color": "#10b981"}},

        totals={"marker": {"color": "#1E4D8F"}}))

    _layout = dict(title=title, height=480, showlegend=False,
                   yaxis_title=unit, xaxis_tickangle=-30)

    if dark:

        _layout.update(plot_bgcolor="rgba(0,0,0,0)", paper_bgcolor="rgba(0,0,0,0)",
                       font_color="white", title_font_color="white")

    else:

        _layout.update(template="plotly_white")

    fig.update_layout(**_layout)

    return fig



def _compute_intrants_avances(annual):

    """Coûts annuels des intrants avancés du modèle (intégrés au coût variable et aux coûts fixes) :
    combustibles (L/t clinker × prix XOF/L), adjuvants (g/t ciment × prix XOF/kg),
    emballage big bag (XOF/t si 100 % big bag — indicatif, pas de part big bag dans le mix), main-d'œuvre de production."""

    _vols = {}

    for p in PRODUCTS:

        for s in SITES:

            _vols[(p, s)] = sum(m.get("prod", {}).get((p, s), 0) for m in annual["monthly"])

    fuel_rows, fuel_total = [], 0.0

    for lbl, k in [("Gasoil", "gasoil"), ("Fuel", "fuel"), ("DDO", "ddo"), ("CNSL", "cnsl")]:

        price = get_val(f"fuel_{k}_price")

        cost = 0.0

        for (p, s), v in _vols.items():

            if not v:

                continue

            pk = normalize_product_key(p)

            sk = s.lower().replace(" ", "")

            dose = get_val(f"fuel_{k}_dose_{pk}_{sk}")  # L / t clinker

            cost += dose * KC_RATIOS[p] * v * price  # L × XOF/L

        fuel_rows.append({"label": lbl, "prix": price, "unite": "XOF/L", "cout": cost})

        fuel_total += cost

    adj_rows, adj_total = [], 0.0

    for lbl, k in [("Pegasus", "pegasus"), ("SIKA", "sika"), ("Chryso", "chryso"), ("Biolatex", "biolatex")]:

        price = get_val(f"adjuvant_{k}_price")

        cost = 0.0

        for (p, s), v in _vols.items():

            if not v:

                continue

            pk = normalize_product_key(p)

            sk = s.lower().replace(" ", "")

            dose = get_val(f"adjuvant_{k}_dose_{pk}_{sk}")  # g / t ciment

            cost += dose / 1000.0 * v * price  # kg × XOF/kg

        adj_rows.append({"label": lbl, "prix": price, "unite": "XOF/kg", "cout": cost})

        adj_total += cost

    return {

        "fuels": fuel_rows, "fuel_total": fuel_total,

        "adjs": adj_rows, "adj_total": adj_total,

        "bigbag_unit": get_val("bigbag_cost_per_unit") * get_val("bigbags_per_tonne"),  # XOF/t si 100 % big bag

        "labor_annual": (get_val("labor_cost_site1") + get_val("labor_cost_site2")) * 12,

        "alloc_mode": st.session_state.get("fixed_alloc_mode", "Prorata des volumes (t)"),

    }



def generate_suggestions(res):

    suggestions = []

    if not res: return suggestions

    annual = calculate_annual_data()

    # FORCER le recalcul frais des KPIs depuis les inputs actuels (AVEC contraintes physiques LP)
    _fresh_monthly = calculate_monthly_model()
    _fresh_vol_cpa = _fresh_monthly["total_prod"]["CPA 52.5"]
    _fresh_vol_cpj42 = _fresh_monthly["total_prod"]["CPJ 42.5"]
    _fresh_vol_cpj32 = _fresh_monthly["total_prod"]["CPJ 32.5"]
    _fresh_total_volume = _fresh_monthly["grand_total"]
    _fresh_revenue = (_fresh_vol_cpa * get_val("price_cpa") +
                      _fresh_vol_cpj42 * get_val("price_cpj42") +
                      _fresh_vol_cpj32 * get_val("price_cpj32"))

    annual_ebitda = annual['annual_ebitda']

    annual_rev = annual['annual_revenue_total']

    annual_net = annual['annual_net_income']

    total_vol = sum(annual['annual_prod'].values())



    # === FINANCIAL SUGGESTIONS ===



    # Treasury stress detection

    wc_req = sum(m.get('wc_requirement', 0) for m in annual['monthly'])

    ccc = res.get('ccc', 0)

    dso = res.get('dso', 0)

    dpo = res.get('dpo', 0)

    debt_service = get_val('interests_monthly') * 12

    tax_annual = sum(m.get('tax', 0) for m in annual['monthly'])



    if ccc > 45 or dso > 40:

        suggestions.append({

            "id": "sugg_treasury_restructure",

            "title": "💰 Restructuration & Consolidation de la Dette",

            "desc": "<b>Trésorerie tendue détectée</b> : CCC de {:.0f}j, DSO de {:.0f}j. <b>Solution éprouvée</b> : regrouper les emprunts à taux élevés (>12%) en crédit syndiqué structuré. <b>Référence</b> : LafargeHolcim Afrique de l'Ouest a obtenu extension maturité 3→7 ans et baisse TEG de 4-6 pts. <b>Mécanisme</b> : négocier covenant lite avec waiver temporaire sur dette/EBITDA, garantie sur stocks clinker. <b>Pratique BCEAO</b> : banques locales (SGBCI, Ecobank) ouvertes à restructuration si plan de redressement présenté.".format(ccc, dso),

            "impact": "💰 Allègement annuel : {} | Allègement mensuel : {}".format(format_xof(debt_service * 0.35), format_xof(debt_service * 0.35 / 12)),

            "action": {"type": "reduce_dso", "days": 10}

        })



        suggestions.append({

            "id": "sugg_payment_priority",

            "title": "📋 Matrice de Priorisation des Paiements (Cash Waterfall)",

            "desc": "<b>Système hiérarchique validé par Corporate Treasury Forum</b> : <br>• <b>P1 (J-3)</b> : Salaires, CIE électricité (arrêt production)<br>• <b>P2 (J-7)</b> : Fournisseurs clinker stratégiques, transporteur exclusif<br>• <b>P3 (J-15)</b> : Sacs, pièces rechange, services<br>• <b>P4 (J-30)</b> : Créditeurs divers<br><b>Référence</b> : Dangote Cement Nigeria a réduit délais paiement de 45→28 jours avec ce système. <b>Outil</b> : tableau de bord Excel/Power BI avec alertes D-5, D-2, J.",

            "impact": "📉 Réduction DSO cible : {}j | BFR libéré : {}".format(max(15, dso - 10), format_xof(annual_rev * (dso - max(15, dso-10)) / 360)),

            "action": {"type": "reduce_dso", "days": 5}

        })



        suggestions.append({

            "id": "sugg_factoring",

            "title": "🏦 Affacturage / Cession de Créances Distributeurs",

            "desc": "<b>Mécanisme</b> : céder créances clients à banque (SGBCI, Ecobank, NSIA) contre financement immédiat à 85-90% valeur nominale. <b>Marché CI 2026</b> : taux 9-11% annuel, commission 0.3-0.5%. <b>Avantage</b> : transformation immédiate créances→cash sans augmentation dette bilan. <b>Prérequis</b> : contrats distribution formalisés, historique paiement >12 mois. <b>Pratique courante</b> dans BTP ivoirien.",

            "impact": "💰 Liquidité immédiate : {} | Coût annuel : {}".format(format_xof(res.get('receivables', 0) * 0.88), format_xof(res.get('receivables', 0) * 0.88 * 0.10)),

            "action": {"type": "reduce_dso", "days": 8}

        })



        suggestions.append({

            "id": "sugg_dynamic_discount",

            "title": "📊 Dynamic Discounting Fournisseurs Clinker",

            "desc": "<b>Principe</b> : offrir escompte 2-3% aux fournisseurs clinker en échange paiement accéléré (J+7 vs J+45). <b>Référence</b> : HeidelbergCement a négocié rabais 2.5% moyens avec fournisseurs turcs 2023-2024. <b>Win-win</b> : fournisseur améliore trésorerie, SC CI réduit BFR. <b>Impact</b> : avec coût clinker {} et K/C {:.0f}%, économie de {}/t ciment.".format(format_xof(get_val('clinker_cost')), get_weighted_kc_ratio() * 100, format_xof(get_val('clinker_cost') * 0.025 * get_weighted_kc_ratio())),

            "impact": "💰 Economie annuelle : {} | BFR réduit : {}".format(format_xof(total_vol * get_val('clinker_cost') * 0.025 * get_weighted_kc_ratio()), format_xof(res.get('payables', 0) * 0.38)),

            "action": {"type": "reduce_dso", "days": 5}

        })



    # === OPERATIONAL SUGGESTIONS ===



    if res.get("budget_variance_ebitda", 0) < -100_000_000:

        gap = abs(res["budget_variance_ebitda"])

        suggestions.append({

            "id": "sugg_ebitda_price",

            "title": "💹 Augmenter les prix de vente (Segmentation B2B/B2C)",

            "desc": "<b>EBITDA en dessous du budget de {}</b>. Au lieu d'une hausse uniforme, mettre en place <b>pricing dynamique par segment</b> : Tier 1 (Grands Comptes BTP) prix négocié annuel -3-5%, Tier 2 (Grossistes) prix catalogue -2%, Tier 3 (Détaillants) prix catalogue, Tier 4 (Public) plafond officiel. <b>Référence</b> : LafargeHolcim Maroc a gagné 2.3 pts de marge avec cette segmentation.".format(format_xof(gap)),

            "impact": "+{} de CA potentiel | +1.5-2.5 pts marge".format(format_xof(res['total_revenue'] * 0.02)),

            "action": {"type": "price_increase", "value": 0.02}

        })

        suggestions.append({

            "id": "sugg_ebitda_volume",

            "title": "📈 Augmenter les volumes de production",

            "desc": "Augmenter la production de 5% pourrait generer +{} d'EBITDA. <b>Levier</b> : concentrer sur CPJ 32.5 (marge/t plus faible mais volume élevé) et CPA 52.5 (marge/t élevée) selon capacité sites.".format(format_xof(res['contribution_margin_per_t'] * res['grand_total'] * 0.05)),

            "impact": "+{} EBITDA".format(format_xof(res['contribution_margin_per_t'] * res['grand_total'] * 0.05)),

            "action": {"type": "volume_increase", "value": 0.05}

        })



    if res.get("budget_variance_volume", 0) < -5_000:

        suggestions.append({

            "id": "sugg_volume_shift",

            "title": "🔄 Réallouer la production vers Site 2",

            "desc": "Site 2 a une capacité sous-utilisée. Déplacer 3% de la production de Site 1 vers Site 2 pour optimiser les coûts fixes par tonne.",

            "impact": "Optimisation des coûts fixes par tonne",

            "action": {"type": "shift_production", "from": "Site 1", "to": "Site 2", "pct": 0.03}

        })



    if res.get("cap_util", {}).get("Site 1", 0) < 0.6:

        suggestions.append({

            "id": "sugg_cap_site1",

            "title": "⚠️ Sous-utilisation Site 1",

            "desc": "Site 1 utilise seulement {:.0f}% de sa capacité. <b>Actions</b> : négocier contrats cadre BTP saison sèche, développer vente vrac industrielle, ou réduire coûts fixes structurels (personnel intérimaire vs permanent).".format(res['cap_util']['Site 1']*100),

            "impact": "Envisager réduction des coûts fixes ou augmentation volumes",

            "action": {"type": "reduce_fixed", "site": "Site 1", "pct": 0.10}

        })



    cpa_margin = safe_div(res.get("product_margin", {}).get("CPA 52.5", 0), res.get("total_prod", {}).get("CPA 52.5", 1), 0)

    cpj32_margin = safe_div(res.get("product_margin", {}).get("CPJ 32.5", 0), res.get("total_prod", {}).get("CPJ 32.5", 1), 0)

    if cpa_margin > cpj32_margin * 1.5:

        suggestions.append({

            "id": "sugg_mix_cpa",

            "title": "🏆 Privilégier le CPA 52.5",

            "desc": "Marge CPA 52.5 ({}/t) >> CPJ 32.5 ({}/t). <b>Stratégie</b> : orienter force commerciale vers projets infrastructure (barrages, routes, bâtiments publics) qui spécifient CPA 52.5. <b>Référence</b> : projets BNETD et grands chantiers publics CI.".format(format_xof(cpa_margin), format_xof(cpj32_margin)),

            "impact": "Augmenter le mix CPA de 2%",

            "action": {"type": "shift_mix", "from": "CPJ 32.5", "to": "CPA 52.5", "pct": 0.02}

        })



    # === LOGISTICS / DEMURRAGE SUGGESTIONS ===



    clinker_import_annual = total_vol * get_weighted_kc_ratio()  # total_vol est deja annuel ; K/C pondere par les volumes

    if clinker_import_annual > 500_000:  # Significant import volume

        suggestions.append({

            "id": "sugg_demurrage",

            "title": "⚓ Réduction Surestaries Port Abidjan (Demurrage)",

            "desc": "<b>Problème</b> : surestaries au Port d'Abidjan peuvent atteindre 15,000-25,000 USD/jour/navire clinker. <b>Causes CI</b> : congestion (TEM 4.2j vs 2.1j cible), délais douane. <b>Solutions déployées avec succès</b> :<br>• <b>Pre-arrival clearance</b> : dédouanement 72h avant arrivée (-40% délai)<br>• <b>Slot booking</b> : réservation créneau déchargement via API portuaire<br>• <b>Transitaire dédié</b> : accord exclusif DHL Global Forwarding/Kuehne+Nagel<br>• <b>Buffer stock</b> : 21 jours couverture (vs 14) pour absorber retards<br><b>Référence</b> : Cementos Argos a réduit surestaries de 84% via simulation.",

            "impact": "💰 Economie : 180,000-450,000 USD/an | Réduction délai : 1.5-2.5j/navire",

            "action": {"type": "reduce_dso", "days": 3}

        })



        suggestions.append({

            "id": "sugg_coa_contract",

            "title": "🚢 Contrat COA (Contract of Affreightment) vs Spot",

            "desc": "<b>Solution stratégique</b> : remplacer affrètements spot (volatilité, indisponibilité) par <b>COA annuel</b> avec 2-3 armateurs (Grimaldi, Spliethoff). <b>Avantages</b> : prix fixe 12 mois, priorité embarquement, pénalités mutuelles. <b>Pratique</b> : Cemex opère 80% imports clinker via COA Amérique Centrale. <b>Clause</b> : laytime 3j francs, despatch 50% taux surestarie.",

            "impact": "📉 Stabilité prix transport : ±5% vs ±25% spot | Réduction risque surestarie : 60-70%",

            "action": {"type": "reduce_dso", "days": 3}

        })



        suggestions.append({

            "id": "sugg_local_clinker",

            "title": "🏭 Diversification Source Clinker : Mix 70% Import / 30% Local",

            "desc": "<b>Réduction risque logistique</b> : au lieu 100% import (retards navires, change, géopolitique), développer mix avec <b>sources locales</b> : CIMTOGO Lomé (200km), Diamond Cement Ghana (48h transport). <b>Référence</b> : BUA Cement Nigeria a réduit coûts logistiques de 18% en sourçant 40% localement. <b>Investissement</b> : contrat achat ferme 12 mois, stock tampon 15j à PK24.",

            "impact": "💰 Réduction coût logistique : 12-18% | Réduction risque surestarie : 40%",

            "action": {"type": "volume_increase", "value": 0.03}

        })



    # === ENERGY SUGGESTIONS ===



    avg_kwh = safe_div(

        sum(res.get("total_prod", {}).get(p, 0) * {"CPA 52.5": get_val("kwh_per_tonne_cpa"), "CPJ 42.5": get_val("kwh_per_tonne_cpj42"), "CPJ 32.5": get_val("kwh_per_tonne_cpj32")}[p] for p in PRODUCTS),

        res.get("grand_total", 1), 0

    )

    if avg_kwh > 38:

        suggestions.append({

            "id": "sugg_energy_solar",

            "title": "☀️ Parc Solaire Hybride + Stockage (Solar + BESS)",

            "desc": "<b>Solution déployée</b> : Dangote Cement Ibese (Nigeria) a installé 30 MWp solaire + 15 MWh batteries, couvrant 28% consommation. <b>Application SC CI</b> : 8-12 MWp sur toitures/terrains PK24. <b>Modèle</b> : PPA avec opérateur (Africaine d'Energie, CIPREL) sans investissement initial. <b>Tarif</b> : 45-55 XOF/kWh (vs 95 actuel). <b>Subvention</b> : exemption TVA équipements solaires (décret CI 2024).",

            "impact": "⚡ Economie énergie : {} | Réduction carbone : 15,000 tCO2/an".format(format_xof(res.get('grand_total', 0) * 12 * avg_kwh * 40)),

            "action": {"type": "reduce_kwh", "target": 35}

        })



        suggestions.append({

            "id": "sugg_energy_biomasse",

            "title": "🔥 Substitution Biomasse (Coques Palmiste, Coquilles Cacao)",

            "desc": "<b>Pratique éprouvée Afrique</b> : Cimpor Mozambique et Bamburi Cement Kenya substituent 15-30% coke/coal par biomasse locale. <b>Disponibilité CI</b> : 400,000 t/an coques palmiste (SANIA, SIFCA), 150,000 t/an coquilles cacao. <b>Process</b> : broyage + séchage + injection four/chaudière. <b>Avantage</b> : coût 30-40% inférieur fuel lourd, crédits carbone vendables.",

            "impact": "💰 Economie combustible : 25-35% | Revenus crédits carbone : 80,000-150,000 EUR/an",

            "action": {"type": "reduce_kwh", "target": 34}

        })



    # === STRATEGIC SUGGESTIONS ===



    if res.get("ccc", 0) > 50:

        suggestions.append({

            "id": "sugg_wc",

            "title": "📊 Optimiser le fonds de roulement",

            "desc": "CCC de {:.0f} jours est élevé. <b>Actions combinées</b> : réduire DSO (affacturage, relances automatisées), augmenter DPO (négocier J+45→J+60 avec fournisseurs non-stratégiques), optimiser DIO (JIT clinker, réduction stock sacs).".format(res['ccc']),

            "impact": "Libération potentielle de {}".format(format_xof(res['receivables'] * 0.05)),

            "action": {"type": "reduce_dso", "days": 5}

        })



    # Forward integration suggestion (always relevant)

    suggestions.append({

        "id": "sugg_forward_integration",

        "title": "🏗️ Forward Integration : Centrales à Béton + Préfabrication",

        "desc": "<b>Stratégie capture de valeur</b> : au lieu de vendre ciment brut (marge 3-5%), produire béton prêt à l'emploi (marge 12-18%) et éléments préfabriqués (marge 20-30%). <b>Modèle</b> : centrale béton sur chaque site (investissement 800M-1.2Mds XOF), partenariat promoteurs immobiliers (Cogefi, SECOV), contrats cadre grands chantiers. <b>Référence</b> : Cimpor CI a développé 8 centrales, 35% du CA avec 3x la marge ciment.",

        "impact": "💰 Multiplicateur marge : 3-6x | Diversification CA : +40% | Fidélisation client",

        "action": {"type": "price_increase", "value": 0.01}

    })

    return suggestions



def generate_suggestions_enhanced(res, ai_context=None):

    """Generate enhanced suggestions combining model analysis with AI search insights.



    This function extends generate_suggestions() with additional context from:

    - Latest market data (mkt_* variables)

    - AI search history (operational/financial/strategic insights)

    - Current model state vs budget targets



    Parameters:

        res: Current model results from calculate_monthly_model()

        ai_context: Optional dict with AI search insights to incorporate



    Returns:

        List of suggestion dicts with enhanced descriptions

    """

    # Start with base suggestions

    suggestions = generate_suggestions(res)



    if not res:

        return suggestions

    annual = calculate_annual_data()

    annual_ebitda = annual['annual_ebitda']

    annual_rev = annual['annual_revenue_total']

    annual_net = annual['annual_net_income']

    total_vol = sum(annual['annual_prod'].values())



    # === ENHANCED CONTEXT FROM AI SEARCH HISTORY ===

    ai_history = st.session_state.get("ai_search_history", [])

    recent_ai_queries = [h.get("query", "").lower() for h in ai_history[-5:]] if ai_history else []



    # Check if user has recently searched for specific topics

    has_treasury_search = any(w in " ".join(recent_ai_queries) for w in ["tresorerie", "cash", "dette", "financement", "bfr"])

    has_energy_search = any(w in " ".join(recent_ai_queries) for w in ["energie", "solaire", "electricite", "kwh", "biomasse"])

    has_logistics_search = any(w in " ".join(recent_ai_queries) for w in ["surestaries", "demurrage", "port", "navire", "logistique", "clinker import"])

    has_pricing_search = any(w in " ".join(recent_ai_queries) for w in ["prix", "tarif", "plafond", "concurrence", "marché", "strategie"])

    has_maintenance_search = any(w in " ".join(recent_ai_queries) for w in ["maintenance", "panne", "broyeur", "predictive", "fiabilite"])



    # === MARKET DATA CONTEXT ===

    market_surcap = safe_div(get_val('mkt_capacite_totale_ci') - get_val('mkt_consommation_ci'), get_val('mkt_consommation_ci'), 0) * 100

    market_clinker_cost = get_val('mkt_clinker_cout_import')

    current_clinker_cost = get_val('clinker_cost')

    clinker_gap_pct = safe_div(current_clinker_cost - market_clinker_cost, market_clinker_cost, 0) * 100 if market_clinker_cost > 0 else 0



    # === ENHANCED SUGGESTIONS BASED ON AI CONTEXT ===



    # 1. AI-Powered Treasury Enhancement (if treasury was searched)

    if has_treasury_search and (res.get("ccc", 0) > 40 or res.get("dso", 0) > 35):

        suggestions.append({

            "id": "sugg_ai_treasury_enhanced",

            "title": "🤖 AI-Enhanced: Restructuration Dette + Affacturage Combo",

            "desc": f"<b>Analyse AI integree</b> : Votre recherche sur la tresorerie a revele plusieurs solutions complementaires. <b>Combo recommande</b> :<br>• <b>Etape 1</b> : Restructuration dette syndiquee (TEG -4 a -6 pts, maturite 3→7 ans)<br>• <b>Etape 2</b> : Affacturage 85-90% des creances distributeurs (SGBCI/Ecobank, taux 9-11%)<br>• <b>Etape 3</b> : Dynamic discounting 2-3% avec fournisseurs clinker pour paiement J+7<br><b>Contexte marche</b> : Surcapacite {market_surcap:.0f}% exerce pression sur les marges. Liberation de tresorerie critique pour investissements defensifs.<br><b>Donnees actuelles</b> : CCC {res.get('ccc', 0):.0f}j, DSO {res.get('dso', 0):.0f}j, BFR {format_xof(sum(m.get('wc_requirement', 0) for m in annual['monthly']))}.",

            "impact": f"💰 Liberation tresorerie : {format_xof(res.get('receivables', 0) * 0.88)} | Economie dette : {format_xof(get_val('interests_monthly') * 12 * 0.35)} | BFR reduit : {format_xof(res.get('receivables', 0) * 0.05)}",

            "action": {"type": "reduce_dso", "days": 15}

        })



    # 2. AI-Powered Energy Optimization (if energy was searched)

    if has_energy_search:

        avg_kwh = safe_div(

            sum(res.get("total_prod", {}).get(p, 0) * {"CPA 52.5": get_val("kwh_per_tonne_cpa"), "CPJ 42.5": get_val("kwh_per_tonne_cpj42"), "CPJ 32.5": get_val("kwh_per_tonne_cpj32")}[p] for p in PRODUCTS),

            res.get("grand_total", 1), 0

        )

        if avg_kwh > 35:

            suggestions.append({

                "id": "sugg_ai_energy_enhanced",

                "title": "🤖 AI-Enhanced: Parc Solaire + BESS + Biomasse Combo",

                "desc": f"<b>Analyse AI integree</b> : Votre recherche energetique suggere une approche hybride. <b>Combo recommande</b> :<br>• <b>Solaire 8-12 MWp</b> sur toitures/terrains PK24 (PPA avec CIPREL/Africaine d'Energie, 45-55 XOF/kWh vs 95 actuel)<br>• <b>BESS 5-8 MWh</b> pour lissage production et reduction pic tarifaire CIE<br>• <b>Biomasse 15-20%</b> : coques palmiste (SANIA/SIFCA, 400kt/an disponibles) + coquilles cacao<br><b>Contexte marche</b> : Tarif CIE en hausse de {get_val('mkt_tarif_elec_evolution'):.0f}%. Exemption TVA equipements solaires (decret CI 2024).<br><b>Donnees actuelles</b> : Consommation moyenne {avg_kwh:.1f} kWh/t, cout energetique annuel {format_xof(res.get('grand_total', 0) * 12 * avg_kwh * get_val('tarif_kwh'))}.",

                "impact": f"⚡ Economie annuelle : {format_xof(res.get('grand_total', 0) * 12 * avg_kwh * 40)} | Reduction carbone : 15,000 tCO2/an | ROI solaire : 4-5 ans",

                "action": {"type": "reduce_kwh", "target": 32}

            })



    # 3. AI-Powered Logistics Enhancement (if logistics was searched)

    if has_logistics_search:

        clinker_import_annual = total_vol * get_weighted_kc_ratio()

        if clinker_import_annual > 500_000:

            suggestions.append({

                "id": "sugg_ai_logistics_enhanced",

                "title": "🤖 AI-Enhanced: Programme Anti-Surestaries + COA + Diversification",

                "desc": f"<b>Analyse AI integree</b> : Votre recherche logistique revele un risque surestaries majeur. <b>Programme 3 piliers</b> :<br>• <b>Pilier 1 - Pre-arrival clearance</b> : dedouanement 72h avant arrivee navire (-40% delai port)<br>• <b>Pilier 2 - COA annuel</b> : contrat avec 2-3 armateurs (Grimaldi, Spliethoff), prix fixe 12 mois, laytime 3j francs<br>• <b>Pilier 3 - Diversification locale</b> : mix 70% import / 30% local (CIMTOGO Lomé, Diamond Cement Ghana)<br><b>Contexte marche</b> : Clinker importe a {format_xof(market_clinker_cost)}/t. Votre cout actuel : {format_xof(current_clinker_cost)}/t ({clinker_gap_pct:+.0f}% vs marche).<br><b>Donnees actuelles</b> : Volume clinker annuel ~{format_tonnes(clinker_import_annual)}. Surestaries potentielles : 15,000-25,000 USD/jour/navire.",

                "impact": "💰 Economie surestaries : 180,000-450,000 USD/an | Stabilite transport : ±5% vs ±25% spot | Reduction risque logistique : 60-70%",

                "action": {"type": "reduce_dso", "days": 5}

            })



    # 4. AI-Powered Pricing Strategy (if pricing was searched)

    if has_pricing_search:

        cpa_margin = safe_div(res.get("product_margin", {}).get("CPA 52.5", 0), res.get("total_prod", {}).get("CPA 52.5", 1), 0)

        cpj32_margin = safe_div(res.get("product_margin", {}).get("CPJ 32.5", 0), res.get("total_prod", {}).get("CPJ 32.5", 1), 0)

        if cpa_margin > cpj32_margin * 1.3:

            suggestions.append({

                "id": "sugg_ai_pricing_enhanced",

                "title": "🤖 AI-Enhanced: Pricing Dynamique + Forward Integration",

                "desc": f"<b>Analyse AI integree</b> : Votre recherche strategique suggere une capture de valeur maximale. <b>Combo recommande</b> :<br>• <b>Tier 1 (Grands Comptes BTP)</b> : prix negocie annuel, volume >50,000t/an, escompte 3-5%, paiement J+30<br>• <b>Tier 2 (Grossistes)</b> : prix catalogue -2%, volume 10,000-50,000t<br>• <b>Tier 3 (Detaillants)</b> : prix catalogue, paiement comptant<br>• <b>Tier 4 (Projets publics)</b> : prix plafond officiel, appels d'offres<br>• <b>Forward Integration</b> : centrales a beton sur chaque site (investissement 800M-1.2Mds XOF), marge 3-6x vs ciment brut<br><b>Contexte marche</b> : Surcapacite {market_surcap:.0f}%, guerre des prix imminente. Differenciation par service et proximite.<br><b>Donnees actuelles</b> : Marge CPA 52.5 {format_xof(cpa_margin)}/t >> CPJ 32.5 {format_xof(cpj32_margin)}/t. Orientez force commerciale vers projets infrastructure.",

                "impact": f"📈 Amelioration marge : +1.5-2.5 pts | Diversification CA : +40% | Multiplicateur marge beton : 3-6x | Reduction DSO : 5-8 jours",

                "action": {"type": "price_increase", "value": 0.02}

            })



    # 5. AI-Powered Maintenance Enhancement (if maintenance was searched)

    if has_maintenance_search:

        cap_util_s1 = res.get("cap_util", {}).get("Site 1", 0) * 100

        cap_util_s2 = res.get("cap_util", {}).get("Site 2", 0) * 100

        if cap_util_s1 < 70 or cap_util_s2 < 70:

            suggestions.append({

                "id": "sugg_ai_maintenance_enhanced",

                "title": "🤖 AI-Enhanced: Maintenance Predictive IoT + OEE Optimization",

                "desc": f"<b>Analyse AI integree</b> : Votre recherche maintenance suggere une approche predictive. <b>Programme recommande</b> :<br>• <b>Capteurs IoT</b> : 6 capteurs par broyeur (vibration 3 axes, temperature paliers, courant moteur)<br>• <b>Plateforme cloud</b> : Siemens Mindsphere ou SKF @ptitude, alertes seuil vibration >7.1 mm/s RMS (ISO 10816)<br>• <b>Planification predictive</b> : pannes predites 2-4 semaines a l'avance, remplacement planifie vs arret d'urgence<br>• <b>OEE cible</b> : 92% (vs actuel {res.get('overall_cap_util', 0)*100:.1f}%)<br><b>Contexte marche</b> : Sous-utilisation detectee S1 ({cap_util_s1:.1f}%) et S2 ({cap_util_s2:.1f}%). Chaque arret improvu coute 180-250M XOF.<br><b>Donnees actuelles</b> : Heures maintenance S1 {get_val('maintenance_hours_site1')}h/mois, S2 {get_val('maintenance_hours_site2')}h/mois. Arrets S1 {get_val('maintenance_downtime_pct_site1')*100:.0f}%, S2 {get_val('maintenance_downtime_pct_site2')*100:.0f}%.",

                "impact": "🔧 Reduction pannes improvues : 85% | Allongement duree vie broyeurs : +30% | OEE cible : 92% | Cout capteurs : 25-40M XOF/an",

                "action": {"type": "reduce_fixed", "site": "Site 1", "pct": 0.05}

            })



    # 6. Market Data Alert - Clinker cost vs market

    if abs(clinker_gap_pct) > 10:

        suggestions.append({

            "id": "sugg_market_clinker_alert",

            "title": f"🌐 Alerte Marche: Cout Clinker {'Supérieur' if clinker_gap_pct > 0 else 'Inférieur'} au Marché",

            "desc": f"<b>Analyse marche integree</b> : Votre cout clinker ({format_xof(current_clinker_cost)}/t) est {abs(clinker_gap_pct):.0f}% {'au-dessus' if clinker_gap_pct > 0 else 'en-dessous'} du cout marche estime ({format_xof(market_clinker_cost)}/t).<br><b>Causes possibles</b> : {'Cours change defavorable, surestaries port, ou mauvaise negociation fournisseur.' if clinker_gap_pct > 0 else 'Avantage competitif temporaire ou sous-estimation couts caches.'}<br><b>Actions recommandees</b> :<br>• Renegocier contrats fournisseurs (reference : prix marche + marge transport 5-8%)<br>•{' Optimiser logistique portuaire (pre-arrival clearance, slot booking)' if clinker_gap_pct > 0 else ' Verifier qualite clinker et couts qualite (rejet, retour, stockage)'}<br>• Considerer diversification sources locales (CIMTOGO, Diamond Cement)",

            "impact": f"💰 Potentiel economie : {format_xof(total_vol * get_weighted_kc_ratio() * abs(current_clinker_cost - market_clinker_cost))}/an | {'Reduction surestaries' if clinker_gap_pct > 0 else 'Verification qualite'}",

            "action": {"type": "price_increase", "value": 0.01}

        })



    # 7. Market Data Alert - Surcapacity pressure

    if market_surcap > 100:

        suggestions.append({

            "id": "sugg_market_surcap_alert",

            "title": "🌐 Alerte Marche: Surcapacite Critique (>100%)",

            "desc": f"<b>Analyse marche integree</b> : La surcapacite du marche ivoirien est de <b>{market_surcap:.0f}%</b> (capacite {get_val('mkt_capacite_totale_ci')/1e6:.1f} Mt vs consommation {get_val('mkt_consommation_ci')/1e6:.1f} Mt).<br><b>Impact</b> : Guerre des prix imminente, compression marges pour tous les acteurs. Nouveaux entrants (Empire Ciment 1.5 Mt, Dangote expansion) aggravent la situation.<br><b>Strategies defensives</b> :<br>• <b>Differenciation</b> : centrales a beton, prefabrication (marge 3-6x)<br>• <b>Cout leadership</b> : optimisation energetique, maintenance predictive, negociation fournisseurs<br>• <b>Niche BTP</b> : CPA 52.5 pour grands chantiers publics (barrages, routes, batiments)<br>• <b>Export regional</b> : Burkina, Mali, Niger (marges superieures 15-25%)",

            "impact": "📈 Diversification revenus : +40% CA | Reduction risque prix : -30% | Marge cible beton : 12-18% vs 3-5% ciment",

            "action": {"type": "volume_increase", "value": 0.03}

        })



    # 8. Budget Variance Alert - Enhanced with AI context

    budget_ebitda_gap = res.get("budget_variance_ebitda", 0)

    if budget_ebitda_gap < -500_000_000:

        suggestions.append({

            "id": "sugg_ai_budget_emergency",

            "title": "🚨 AI-Enhanced: Plan d'Urgence Rentabilite (EBITDA < -500M vs Budget)",

            "desc": f"<b>Analyse AI integree</b> : Votre EBITDA est en dessous du budget de {format_xof(abs(budget_ebitda_gap))}. <b>Plan d'urgence 90 jours</b> :<br>• <b>J-30</b> : Renegociation immédiate prix clinker (-5% cible), dynamic discounting fournisseurs<br>• <b>J-60</b> : Lancement affacturage creances, restructuration dette (TEG -4 pts)<br>• <b>J-90</b> : Installation capteurs IoT maintenance, PPA solaire 5 MWp (phase 1)<br><b>Contexte marche</b> : Surcapacite {market_surcap:.0f}%, necessite actions rapides avant guerre des prix.<br><b>Donnees actuelles</b> : Marge EBITDA {res.get('ebitda_pct', 0)*100:.1f}% vs budget {get_val('budget_ebitda_margin')*100:.1f}%. CA {format_xof(res.get('total_revenue', 0))} vs budget {format_xof(get_val('budget_revenue'))}.",

            "impact": f"💰 Potentiel recuperation : {format_xof(abs(budget_ebitda_gap) * 0.6)} sur 90j | Liberation tresorerie : {format_xof(res.get('receivables', 0) * 0.88)} | Economie energie : {format_xof(res.get('grand_total', 0) * 12 * 35 * 40)}",

            "action": {"type": "price_increase", "value": 0.03}

        })



    # Deduplicate by ID (keep first occurrence)

    seen_ids = set()

    unique_suggestions = []

    for s in suggestions:

        if s["id"] not in seen_ids:

            seen_ids.add(s["id"])

            unique_suggestions.append(s)



    return unique_suggestions



def preview_suggestion_changes(sugg_id, suggestions):

    '''Generate a preview of what would change if suggestion is applied.'''

    for s in suggestions:

        if s["id"] == sugg_id:

            action = s["action"]

            changes = []



            if action["type"] == "price_increase":

                for p in PRODUCTS:

                    key = f"price_{normalize_product_key(p)}"

                    old_val = get_val(key)

                    new_val = int(old_val * (1 + action["value"]))

                    changes.append({"param": f"Prix {p}", "old": old_val, "new": new_val, "unit": "XOF/t"})



            elif action["type"] == "volume_increase":

                for p in PRODUCTS:

                    for site in SITES:

                        key = f"vol_{normalize_product_key(p)}_site{site[-1]}"

                        old_val = get_val(key)

                        new_val = int(old_val * (1 + action["value"]))

                        changes.append({"param": f"Vol {p} {site}", "old": old_val, "new": new_val, "unit": "t/mois"})



            elif action["type"] == "reduce_dso":

                old_val = get_val("dso_days")

                new_val = max(15, old_val - action["days"])

                changes.append({"param": "DSO (jours)", "old": old_val, "new": new_val, "unit": "jours"})



            elif action["type"] == "reduce_fixed":

                site_key = f"fixed_cost_{action['site'].lower().replace(' ', '')}"

                old_val = get_val(site_key)

                new_val = int(old_val * (1 - action["pct"]))

                changes.append({"param": f"Couts fixes {action['site']}", "old": old_val, "new": new_val, "unit": "XOF/mois"})



            elif action["type"] == "shift_mix":

                from_key = f"vol_{normalize_product_key(action['from'])}_site1"

                to_key = f"vol_{normalize_product_key(action['to'])}_site1"

                old_from = get_val(from_key)

                old_to = get_val(to_key)

                shift_amount = int(old_from * action["pct"])

                changes.append({"param": f"Vol {action['from']} S1", "old": old_from, "new": old_from - shift_amount, "unit": "t/mois"})

                changes.append({"param": f"Vol {action['to']} S1", "old": old_to, "new": old_to + shift_amount, "unit": "t/mois"})



            elif action["type"] == "reduce_kwh":

                target = action.get("target", 35)

                old_cpa = get_val("kwh_per_tonne_cpa")

                old_cpj42 = get_val("kwh_per_tonne_cpj42")

                old_cpj32 = get_val("kwh_per_tonne_cpj32")

                new_cpj42 = max(target - 4, 20)

                new_cpj32 = max(target - 7, 15)

                changes.append({"param": "kWh/t CPA", "old": old_cpa, "new": target, "unit": "kWh/t"})

                changes.append({"param": "kWh/t CPJ42", "old": old_cpj42, "new": new_cpj42, "unit": "kWh/t"})

                changes.append({"param": "kWh/t CPJ32", "old": old_cpj32, "new": new_cpj32, "unit": "kWh/t"})



            return changes, s

    return None, None



def apply_suggestion(sugg_id, suggestions):

    '''Apply a suggestion after confirmation.'''

    for s in suggestions:

        if s["id"] == sugg_id:

            action = s["action"]

            if action["type"] == "price_increase":

                for p in PRODUCTS:

                    key = f"price_{normalize_product_key(p)}"

                    set_val(key, int(get_val(key) * (1 + action["value"])))

            elif action["type"] == "volume_increase":

                for p in PRODUCTS:

                    for site in SITES:

                        key = f"vol_{normalize_product_key(p)}_site{site[-1]}"

                        set_val(key, int(get_val(key) * (1 + action["value"])))

            elif action["type"] == "reduce_dso":

                set_val("dso_days", max(15, get_val("dso_days") - action["days"]))

            elif action["type"] == "reduce_fixed":

                site_key = f"fixed_cost_{action['site'].lower().replace(' ', '')}"

                set_val(site_key, int(get_val(site_key) * (1 - action["pct"])))

            elif action["type"] == "shift_mix":

                from_key = f"vol_{normalize_product_key(action['from'])}_site1"

                to_key = f"vol_{normalize_product_key(action['to'])}_site1"

                shift_amount = int(get_val(from_key) * action["pct"])

                set_val(from_key, get_val(from_key) - shift_amount)

                set_val(to_key, get_val(to_key) + shift_amount)

            elif action["type"] == "reduce_kwh":

                target = action.get("target", 35)

                set_val("kwh_per_tonne_cpa", target)

                set_val("kwh_per_tonne_cpj42", max(target - 4, 20))

                set_val("kwh_per_tonne_cpj42_site1", max(target - 4, 20))

                set_val("kwh_per_tonne_cpj42_site2", max(target - 4, 20))

                set_val("kwh_per_tonne_cpj32", max(target - 7, 15))

            safe_set_add("applied_suggestions", sugg_id)

            st.toast(f"Suggestion appliquee: {s['title']}", icon="✅")

            return True

    return False













def save_scenario(name, description=""):

    scenario = {

        "name": name,

        "description": description,

        "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),

        "params": {k: get_val(k) for k in VALUE_KEYS.keys() if not k.startswith("_") and k not in ["scenario_history", "dismissed_suggestions", "applied_suggestions", "show_infographic", "kimi_wishlist_history", "kimi_show_modal", "kimi_last_scenario"]}

    }

    st.session_state["scenario_history"].append(scenario)
    # Keep only last 3 entries to prevent state bloat
    if len(st.session_state["scenario_history"]) > 3:
        st.session_state["scenario_history"] = st.session_state["scenario_history"][-3:]

    save_session_state()  # Persist to disk



    # Create a launchable scenario file

    _create_scenario_launcher(scenario)



    st.toast(f"Scenario '{name}' sauvegarde", icon="💾")



def _create_scenario_launcher(scenario):

    """Create a standalone .py file that launches the app with this scenario pre-loaded."""

    module_dir = os.path.dirname(os.path.abspath(__file__))

    safe_name = scenario["name"].replace(" ", "_").replace("/", "_").replace("\\", "_")

    ts = scenario['timestamp'].replace(':', '-').replace(' ', '_')

    launcher_path = os.path.join(module_dir, f"scenario_{safe_name}_{ts}.py")



    scenario_json = json.dumps(scenario, indent=2, ensure_ascii=False)

    launcher_basename = os.path.basename(launcher_path)



    # Build launcher code line by line to avoid quote issues

    lines_out = []

    lines_out.append("# -*- coding: utf-8 -*-")

    lines_out.append('"""')

    lines_out.append(f"Launcher auto-généré pour le scénario: {scenario['name']}")

    lines_out.append(f"Généré le: {scenario['timestamp']}")

    lines_out.append(f"Description: {scenario['description']}")

    lines_out.append("")

    lines_out.append("Usage:")

    lines_out.append(f'    streamlit run "{launcher_basename}"')

    lines_out.append('"""')

    lines_out.append("import os")

    lines_out.append("import json")

    lines_out.append("")

    lines_out.append("LAUNCHER_DIR = os.path.dirname(os.path.abspath(__file__))")

    lines_out.append('MAIN_APP = os.path.join(LAUNCHER_DIR, "ibid_app.py")')

    lines_out.append("STATE_FILE = os.path.join(LAUNCHER_DIR, 'ibid_state.json')")

    lines_out.append("")

    lines_out.append(f"SCENARIO_DATA = {scenario_json}")

    lines_out.append("")

    lines_out.append("existing_state = {}")

    lines_out.append("if os.path.exists(STATE_FILE):")

    lines_out.append("    try:")

    lines_out.append("        with open(STATE_FILE, 'r', encoding='utf-8') as f:")

    lines_out.append("            existing_state = json.load(f)")

    lines_out.append("    except:")

    lines_out.append("        pass")

    lines_out.append("")

    lines_out.append("for k, v in SCENARIO_DATA['params'].items():")

    lines_out.append("    existing_state[k] = v")

    lines_out.append("existing_state['active_scenario'] = SCENARIO_DATA['name']")

    lines_out.append("")

    lines_out.append("with open(STATE_FILE, 'w', encoding='utf-8') as f:")

    lines_out.append("    json.dump(existing_state, f, ensure_ascii=False, indent=2, default=str)")

    lines_out.append("")

    lines_out.append("print('Scenario charge: ' + SCENARIO_DATA['name'])")

    lines_out.append("print('App: ' + MAIN_APP)")

    lines_out.append("")

    lines_out.append("os.system('python -m streamlit run "' + MAIN_APP + '"')")



    launcher_code = "\n".join(lines_out)



    with open(launcher_path, "w", encoding="utf-8") as f:

        f.write(launcher_code)



    st.toast(f"Fichier launcher cree: {os.path.basename(launcher_path)}", icon="📄")

    return launcher_path



def load_scenario(idx):

    """Load a scenario by index. Caller must call st.rerun() after."""

    if 0 <= idx < len(st.session_state["scenario_history"]):

        scenario = st.session_state["scenario_history"][idx]

        pending = {}

        for k, v in scenario["params"].items():

            if k in VALUE_KEYS:

                set_val(k, v)

                # Queue widget input key update for next run

                # This ensures widgets display the new values

                pending[k] = v

        # Store pending updates to be applied before widgets render

        if pending:

            st.session_state["_pending_widget_updates"] = pending

        st.session_state["active_scenario"] = scenario["name"]

        st.toast(f"Scenario '{scenario['name']}' charge", icon="📂")

        return True

    return False







def upload_scenario(uploaded_file):

    """Load a scenario from an uploaded JSON or Python launcher file and add it to history."""

    try:

        file_name = uploaded_file.name

        file_ext = file_name.split('.')[-1].lower() if '.' in file_name else ''



        if file_ext == 'py':

            # Parse Python launcher file - extract SCENARIO_DATA dict

            py_content = uploaded_file.read().decode('utf-8')



            # Find SCENARIO_DATA assignment using brace counting (handles nested dicts)

            start_marker = "SCENARIO_DATA = "

            start_idx = py_content.find(start_marker)

            if start_idx == -1:

                st.error("Fichier .py invalide: SCENARIO_DATA non trouve")

                return False



            # Find the opening brace

            brace_start = py_content.find("{", start_idx)

            if brace_start == -1:

                st.error("Fichier .py invalide: SCENARIO_DATA non trouve")

                return False



            # Count braces to find the matching closing brace (handles nested structures)

            brace_count = 0

            in_string = False

            string_char = None

            i = brace_start



            while i < len(py_content):

                char = py_content[i]



                # Handle string literals (both single and double quotes)

                if char in ('"', "'") and (i == 0 or py_content[i-1] != '\\'):

                    if not in_string:

                        in_string = True

                        string_char = char

                    elif char == string_char:

                        in_string = False

                        string_char = None



                # Only count braces outside of strings

                if not in_string:

                    if char == '{':

                        brace_count += 1

                    elif char == '}':

                        brace_count -= 1

                        if brace_count == 0:

                            # Found the matching closing brace

                            break

                i += 1

            else:

                st.error("Fichier .py invalide: SCENARIO_DATA mal forme (accolades non equilibrees)")

                return False



            data_str = py_content[brace_start:i+1]



            # Extract the dict using json.loads (data is JSON from json.dumps in launcher)

            import json

            try:

                scenario_data = json.loads(data_str)

            except (json.JSONDecodeError, ValueError) as e:

                st.error(f"Fichier .py invalide: impossible de parser SCENARIO_DATA — {e}")

                return False



            # Extract name from file or SCENARIO_DATA

            scen_name = scenario_data.get("name", file_name.replace('.py', '').replace('scenario_', '').replace('_', ' '))

            scen_desc = scenario_data.get("description", "Importe depuis launcher Python")

            scen_ts = scenario_data.get("timestamp", datetime.now().strftime("%Y-%m-%d %H:%M:%S"))

            scen_params = scenario_data.get("params", {})



        elif file_ext == 'json':

            # Parse JSON file directly

            scenario_data = json.load(uploaded_file)

            scen_name = scenario_data.get("name", "Scenario Importe")

            scen_desc = scenario_data.get("description", "Importe depuis JSON")

            scen_ts = scenario_data.get("timestamp", datetime.now().strftime("%Y-%m-%d %H:%M:%S"))

            scen_params = scenario_data.get("params", {})

        else:

            st.error(f"Format non supporte: .{file_ext}. Utilisez .json ou .py")

            return False



        # Validate required fields

        if not scen_params:

            st.error("Fichier invalide: aucun parametre trouve")

            return False



        # Build scenario object

        scenario = {

            "name": scen_name,

            "description": scen_desc,

            "timestamp": scen_ts,

            "params": scen_params

        }



        # Validate params keys

        valid_params = {k: v for k, v in scenario["params"].items() if k in VALUE_KEYS}

        invalid_params = {k: v for k, v in scenario["params"].items() if k not in VALUE_KEYS}



        if invalid_params:

            st.warning(f"Parametres ignores (inconnus): {', '.join(list(invalid_params.keys())[:5])}")



        if not valid_params:

            st.error("Aucun parametre valide trouve dans le fichier")

            return False



        scenario["params"] = valid_params



        # Check for duplicate name

        existing_names = [s["name"] for s in st.session_state.get("scenario_history", [])]

        base_name = scenario["name"]

        if base_name in existing_names:

            scenario["name"] = f"{base_name} (importe {datetime.now().strftime('%H%M%S')})"



        # Add to history

        st.session_state["scenario_history"].append(scenario)

        save_session_state()



        st.toast(f"Scenario '{scenario['name']}' importe avec succes ({file_ext.upper()})", icon="📤")

        return True



    except json.JSONDecodeError as e:

        st.error(f"Fichier JSON invalide: {e}")

        return False

    except Exception as e:

        st.error(f"Erreur lors de l'import: {e}")

        return False



def set_as_defaults():

    """Save current values as defaults and log the previous defaults for download."""

    # First, capture the current defaults before overwriting

    previous_defaults = {}

    if os.path.exists(PERSIST_FILE):

        try:

            with open(PERSIST_FILE, "r", encoding="utf-8") as f:

                previous_defaults = json.load(f)

        except Exception:

            pass



    # Build a log entry with timestamp and the previous default values

    log_entry = {

        "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),

        "previous_defaults": previous_defaults,

        "note": "Snapshot des valeurs par défaut précédentes avant réinitialisation"

    }



    # Append to defaults history log

    if "defaults_history_log" not in st.session_state:

        st.session_state["defaults_history_log"] = []

    st.session_state["defaults_history_log"].append(log_entry)



    # Also save to a dedicated JSON file for persistence across sessions

    defaults_log_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "ibid_defaults_history.json")

    try:

        existing_log = []

        if os.path.exists(defaults_log_file):

            with open(defaults_log_file, "r", encoding="utf-8") as f:

                existing_log = json.load(f)

        existing_log.append(log_entry)

        with open(defaults_log_file, "w", encoding="utf-8") as f:

            json.dump(existing_log, f, ensure_ascii=False, indent=2, default=str)

    except Exception as e:

        st.toast(f"Erreur sauvegarde log defauts: {e}", icon="⚠️")



    # Now save current values as the new defaults
    # Explicitly save VALUE_KEYS to ensure they persist
    defaults_state = {}
    for k in VALUE_KEYS.keys():
        # Save base value
        if k in st.session_state:
            try:
                defaults_state[k] = _serialize_value(st.session_state[k])
            except (TypeError, ValueError):
                pass
        # Save widget input value
        input_key = f"{k}_input"
        if input_key in st.session_state:
            try:
                defaults_state[input_key] = _serialize_value(st.session_state[input_key])
            except (TypeError, ValueError):
                pass
    
    # Also save other non-excluded session state keys
    EXCLUDED_SAVE = {
        "FormSubmitter", "file_uploader", "scenario_uploader", "scenario_history_selector",
        "suggestion_selector", "scenario_selector", "budget_mode_input",
        "kimi_wishlist_input", "save_name",
        "ibid_logout_btn", "ibid_login_btn", "ibid_unlock_btn", "ibid_lock_btn",
        "ibid_lock_from_active_btn", "btn_close_kimi_modal", "btn_close_info",
        "export_kimi", "export_info",
    }
    LARGE_SKIP = {"DAILY_DATA", "daily_data", "WEEKLY_DATA", "weekly_data",
                  "BD_BROYEUR_DAILY", "BD_BROYEUR_WEEKLY", "BD_BROYEUR_MONTHLY",
                  "BD_CONSO_MATIERES_DAILY", "BD_CONSO_MATIERES_WEEKLY", "BD_CONSO_MATIERES_MONTHLY",
                  "BD_EXPEDITION_DAILY", "BD_EXPEDITION_WEEKLY", "BD_EXPEDITION_MONTHLY",
                  "HISTORICAL_FINANCIAL_DATA", "SCENARIO_HISTORY", "BUDGET_SCENARIOS",
                  "ibid_evolution_records", "ibid_data_records", "ibid_all_records",
                  "ibid_silo_stock_records", "_daily_data_json_mtime", "_cache_version",
                  "previous_defaults", "defaults_history_log"}
    for k, v in st.session_state.items():
        if k in defaults_state or k in EXCLUDED_SAVE or k.startswith("_") or k.startswith("btn_") or k.endswith("_btn") or k in LARGE_SKIP:
            continue
        try:
            serialized = _serialize_value(v)
            size_est = len(json.dumps(serialized)) if serialized is not None else 0
            if size_est < 100_000:
                defaults_state[k] = serialized
        except (TypeError, ValueError):
            pass
    
    # Write to PERSIST_FILE
    try:
        with open(PERSIST_FILE, "w", encoding="utf-8") as f:
            json.dump(defaults_state, f, ensure_ascii=False, indent=2, default=str)
        st.toast("Valeurs actuelles definies comme defauts et sauvegardees", icon="✅")
    except Exception as e:
        st.toast(f"Erreur sauvegarde defauts: {e}", icon="⚠️")
        # Fallback: try to use save_session_state
        save_session_state()



