def parse_kimi_wishlist(text):

    """Parse user wishlist text into parameter updates. Returns (updates_dict, explanation)"""

    text_lower = text.lower()

    updates = {}

    explanations = []



    # Price targets

    if any(w in text_lower for w in ["prix", "price", "augmenter", "baisser", "hausse", "reduire prix"]):

        if "cpa" in text_lower or "52" in text_lower:

            if any(w in text_lower for w in ["augment", "hausse", "+", "plus", "elever"]):

                pct = 0.10

                for word in text_lower.split():

                    if "%" in word:

                        try: pct = float(word.replace("%", "").replace("+", "")) / 100

                        except: pass

                updates["price_cpa"] = int(get_val("price_cpa") * (1 + pct))

                explanations.append(f"Prix CPA 52.5 augmente de {pct*100:.0f}% -> {updates['price_cpa']:,.0f} XOF/t")

            elif any(w in text_lower for w in ["baiss", "reduire", "-", "moins", "diminuer"]):

                pct = 0.10

                for word in text_lower.split():

                    if "%" in word:

                        try: pct = float(word.replace("%", "").replace("-", "")) / 100

                        except: pass

                updates["price_cpa"] = int(get_val("price_cpa") * (1 - pct))

                explanations.append(f"Prix CPA 52.5 baisse de {pct*100:.0f}% -> {updates['price_cpa']:,.0f} XOF/t")



        if "cpj 42" in text_lower or "cpj42" in text_lower:

            if any(w in text_lower for w in ["augment", "hausse", "+", "plus"]):

                pct = 0.10

                for word in text_lower.split():

                    if "%" in word:

                        try: pct = float(word.replace("%", "").replace("+", "")) / 100

                        except: pass

                updates["price_cpj42"] = int(get_val("price_cpj42") * (1 + pct))

                explanations.append(f"Prix CPJ 42.5 augmente de {pct*100:.0f}% -> {updates['price_cpj42']:,.0f} XOF/t")

            elif any(w in text_lower for w in ["baiss", "reduire", "-", "moins"]):

                pct = 0.10

                for word in text_lower.split():

                    if "%" in word:

                        try: pct = float(word.replace("%", "").replace("-", "")) / 100

                        except: pass

                updates["price_cpj42"] = int(get_val("price_cpj42") * (1 - pct))

                explanations.append(f"Prix CPJ 42.5 baisse de {pct*100:.0f}% -> {updates['price_cpj42']:,.0f} XOF/t")



        if "cpj 32" in text_lower or "cpj32" in text_lower:

            if any(w in text_lower for w in ["augment", "hausse", "+", "plus"]):

                pct = 0.10

                for word in text_lower.split():

                    if "%" in word:

                        try: pct = float(word.replace("%", "").replace("+", "")) / 100

                        except: pass

                updates["price_cpj32"] = int(get_val("price_cpj32") * (1 + pct))

                explanations.append(f"Prix CPJ 32.5 augmente de {pct*100:.0f}% -> {updates['price_cpj32']:,.0f} XOF/t")

            elif any(w in text_lower for w in ["baiss", "reduire", "-", "moins"]):

                pct = 0.10

                for word in text_lower.split():

                    if "%" in word:

                        try: pct = float(word.replace("%", "").replace("-", "")) / 100

                        except: pass

                updates["price_cpj32"] = int(get_val("price_cpj32") * (1 - pct))

                explanations.append(f"Prix CPJ 32.5 baisse de {pct*100:.0f}% -> {updates['price_cpj32']:,.0f} XOF/t")



    # Volume targets

    if any(w in text_lower for w in ["volume", "tonne", "production", "produire"]):

        if any(w in text_lower for w in ["augment", "hausse", "+", "plus", "elever"]):

            pct = 0.10

            for word in text_lower.split():

                if "%" in word:

                    try: pct = float(word.replace("%", "").replace("+", "")) / 100

                    except: pass

            for p in PRODUCTS:

                for s in SITES:

                    key = f"vol_{normalize_product_key(p)}_site{s[-1]}"

                    updates[key] = int(get_val(key) * (1 + pct))

            explanations.append(f"Volumes augmentes de {pct*100:.0f}% sur tous les produits et sites")

        elif any(w in text_lower for w in ["baiss", "reduire", "-", "moins", "diminuer"]):

            pct = 0.10

            for word in text_lower.split():

                if "%" in word:

                    try: pct = float(word.replace("%", "").replace("-", "")) / 100

                    except: pass

            for p in PRODUCTS:

                for s in SITES:

                    key = f"vol_{normalize_product_key(p)}_site{s[-1]}"

                    updates[key] = int(get_val(key) * (1 - pct))

            explanations.append(f"Volumes baisses de {pct*100:.0f}% sur tous les produits et sites")



    # Clinker cost

    if "clinker" in text_lower:

        if any(w in text_lower for w in ["augment", "hausse", "+", "plus"]):

            pct = 0.15

            for word in text_lower.split():

                if "%" in word:

                    try: pct = float(word.replace("%", "").replace("+", "")) / 100

                    except: pass

            updates["clinker_cost"] = int(get_val("clinker_cost") * (1 + pct))

            explanations.append(f"Cout clinker augmente de {pct*100:.0f}% -> {updates['clinker_cost']:,.0f} XOF/t")

        elif any(w in text_lower for w in ["baiss", "reduire", "-", "moins", "diminuer"]):

            pct = 0.10

            for word in text_lower.split():

                if "%" in word:

                    try: pct = float(word.replace("%", "").replace("-", "")) / 100

                    except: pass

            updates["clinker_cost"] = int(get_val("clinker_cost") * (1 - pct))

            explanations.append(f"Cout clinker baisse de {pct*100:.0f}% -> {updates['clinker_cost']:,.0f} XOF/t")



    # Energy

    if any(w in text_lower for w in ["energie", "electricite", "kwh", "consommation"]):

        if any(w in text_lower for w in ["reduire", "baiss", "economie", "optimiser", "diminuer"]):

            target = 35

            for word in text_lower.split():

                if word.isdigit() and int(word) < 100:

                    target = int(word)

            updates["kwh_per_tonne_cpa"] = target

            updates["kwh_per_tonne_cpj42"] = target - 4

            updates["kwh_per_tonne_cpj42_site1"] = target - 4

            updates["kwh_per_tonne_cpj42_site2"] = target - 4

            updates["kwh_per_tonne_cpj32"] = target - 7

            explanations.append(f"Consommation energetique optimisee -> CPA:{target}, CPJ42:{target-4}, CPJ32:{target-7} kWh/t")



    # Working capital

    if any(w in text_lower for w in ["fonds de roulement", "bfr", "ccc", "working capital"]):

        if any(w in text_lower for w in ["reduire", "optimiser", "diminuer"]):

            updates["dso_days"] = max(15, get_val("dso_days") - 5)

            updates["dpo_days"] = min(60, get_val("dpo_days") + 5)

            explanations.append(f"BFR optimise: DSO {get_val('dso_days')}->{updates['dso_days']}j, DPO {get_val('dpo_days')}->{updates['dpo_days']}j")



    # Fixed costs

    if any(w in text_lower for w in ["cout fixe", "fixe", "structure"]):

        if any(w in text_lower for w in ["reduire", "baiss", "diminuer", "couper"]):

            pct = 0.10

            for word in text_lower.split():

                if "%" in word:

                    try: pct = float(word.replace("%", "").replace("-", "")) / 100

                    except: pass

            updates["fixed_cost_site1"] = int(get_val("fixed_cost_site1") * (1 - pct))

            updates["fixed_cost_site2"] = int(get_val("fixed_cost_site2") * (1 - pct))

            explanations.append(f"Couts fixes reduits de {pct*100:.0f}%")



    # Mix product

    if "mix" in text_lower and "cpa" in text_lower:

        if any(w in text_lower for w in ["privileg", "augment", "plus", "favoriser"]):

            updates["vol_cpa_site1"] = int(get_val("vol_cpa_site1") * 1.2)

            updates["vol_cpa_site2"] = int(get_val("vol_cpa_site2") * 1.2)

            updates["vol_cpj32_site1"] = int(get_val("vol_cpj32_site1") * 0.9)

            updates["vol_cpj32_site2"] = int(get_val("vol_cpj32_site2") * 0.9)

            explanations.append("Mix produit optimise vers CPA 52.5 (+20% CPA, -10% CPJ32)")



    # EBITDA target

    if "ebitda" in text_lower:

        if any(w in text_lower for w in ["target", "objectif", "atteindre", "fixer", "vouloir"]):

            target_val = None

            for word in text_lower.split():

                if "m" in word.lower() or "milliard" in word.lower():

                    try:

                        num = float(word.lower().replace("m", "").replace("ds", "").replace("illiard", "").replace("xof", ""))

                        target_val = num * 1e9

                        break

                    except: pass

            if target_val:

                updates["budget_ebitda"] = target_val

                explanations.append(f"Objectif EBITDA fixe a {format_xof(target_val)}")



    if not updates:

        explanations.append("Aucun parametre reconnu. Essayez: 'augmenter prix CPA 10%', 'reduire cout clinker 15%', 'optimiser BFR'")



    return updates, explanations



def apply_kimi_scenario(updates, explanations):

    """Apply parsed wishlist updates and store history. Caller must call st.rerun() after."""

    pending = {}

    for k, v in updates.items():

        set_val(k, v)

        pending[k] = v

    if pending:

        st.session_state["_pending_widget_updates"] = pending



    scenario_record = {

        "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),

        "updates": updates,

        "explanations": explanations,

    }

    st.session_state["kimi_wishlist_history"].append(scenario_record)

    st.session_state["kimi_last_scenario"] = scenario_record

    st.session_state["kimi_show_modal"] = True

    st.toast("Scenario Kimi AI genere et applique!", icon="🤖")





def load_historical_baseline_2025():

    """Load 2025 actuals as baseline scenario. Returns dict of updates."""

    hist = HISTORICAL_DATA_2025

    total_prod = hist["production_total_t"]

    total_monthly = total_prod / 12



    # Map product mix to model products

    # CPA 52.5 gets CPA 52.5 + CPA 42.5 + CHF = 20+15+5 = 40%

    cpa_share = (hist["mix_cpa525_pct"] + hist["mix_cpa425_pct"] + hist["mix_chf_pct"]) / 100

    cpj42_share = hist["mix_cpj425_pct"] / 100

    cpj32_share = hist["mix_cpj325_pct"] / 100



    # Split between 2 sites (based on mill data: A+B ~600K, C ~600K)

    site1_share = (hist["production_broyeur_a_t"] + hist["production_broyeur_b_t"]) / total_prod

    site2_share = hist["production_broyeur_c_t"] / total_prod



    updates = {

        "vol_cpa_site1": int(total_monthly * cpa_share * site1_share),

        "vol_cpa_site2": int(total_monthly * cpa_share * site2_share),

        "vol_cpj42_site1": int(total_monthly * cpj42_share * site1_share),

        "vol_cpj42_site2": int(total_monthly * cpj42_share * site2_share),

        "vol_cpj32_site1": int(total_monthly * cpj32_share * site1_share),

        "vol_cpj32_site2": int(total_monthly * cpj32_share * site2_share),

        "budget_volume": hist["production_budget_t"] / 12,

        "kwh_per_tonne_cpa": hist["ces_kwh_per_tonne"],

        "kwh_per_tonne_cpj42": hist["ces_kwh_per_tonne"] - 3,

        "kwh_per_tonne_cpj42_site1": hist["ces_kwh_per_tonne"] - 3,

        "kwh_per_tonne_cpj42_site2": hist["ces_kwh_per_tonne"] - 3,

        "kwh_per_tonne_cpj32": hist["ces_kwh_per_tonne"] - 6,

    }

    return updates



def get_historical_monthly_data():

    """Return historical monthly production and expedition data for charts."""

    hist = HISTORICAL_DATA_2025

    months = MONTHS



    prod_data = []

    exp_data = []

    for m in months:

        if m in hist["production_monthly"]:

            p = hist["production_monthly"][m]

            prod_data.append({"Mois": m, "Realise": p["realise"], "Budget": p["budget"]})

        if m in hist["expedition_monthly"]:

            e = hist["expedition_monthly"][m]

            exp_data.append({"Mois": m, "Realise": e["realise"], "Budget": e["budget"]})



    return pd.DataFrame(prod_data), pd.DataFrame(exp_data)









