def generate_qa_answer(question):

    """Generate an answer to a user question based on current model data and analysis.

    Returns dict with answer text, target tab index, and target element ID for navigation."""

    import re

    q_lower = question.lower().strip()



    # Get current data for analysis

    res = calculate_monthly_model()

    annual = calculate_annual_data()



    answers = []

    # Navigation metadata: which tab and element to focus on

    nav_tab = None

    nav_element = None

    nav_highlight = None



    # Pattern 1: Cost/revient questions -> Tab 3 (Cost)

    if any(w in q_lower for w in ["cout", "revient", "coût", "augmente", "augmentent", "hausse", "élevé", "eleve", "cher"]):

        nav_tab = 3  # Cout de Revient tab



        # Check if asking about summer/été

        if any(w in q_lower for w in ["été", "ete", "juin", "juillet", "aout", "août", "summer", "ete"]):

            nav_element = "cost-seasonality-chart"

            nav_highlight = "cost-summer-analysis"



            # Analyze summer months (June=5, July=6, August=7)

            summer_months = [5, 6, 7]  # Juin, Juillet, Aout

            summer_factors = [get_monthly_factor(m) for m in summer_months]

            avg_summer_factor = sum(summer_factors) / len(summer_factors)



            # Calculate cost impact

            base_month_costs = []

            summer_month_costs = []

            for m in range(12):

                res_m = calculate_monthly_model(m)

                avg_cost_t = safe_div(res_m.get("total_var_cost", 0) + res_m.get("total_fixed", 0), res_m.get("grand_total", 1), 0)

                if m in summer_months:

                    summer_month_costs.append(avg_cost_t)

                else:

                    base_month_costs.append(avg_cost_t)



            avg_base = sum(base_month_costs) / len(base_month_costs) if base_month_costs else 0

            avg_summer = sum(summer_month_costs) / len(summer_month_costs) if summer_month_costs else 0

            diff_pct = safe_div(avg_summer - avg_base, avg_base, 0) * 100



            answers.append(

                f"<b>Les coûts de revient augmentent en été</b> pour 3 raisons principales:<br><br>"

                f"1️⃣ <b>Saisonnalité basse</b> : Juin-Août ont un facteur saisonnier de {avg_summer_factor:.2f}x "

                f"(vs ~1.0x en moyenne). Les volumes chutent de {((1-avg_summer_factor)*100):.0f}%, "

                f"mais les <b>coûts fixes</b> (personnel, amortissements, SGA) restent constants. "

                f"Résultat : le coût fixe par tonne augmente.<br><br>"

                f"2️⃣ <b>Coût énergétique</b> : La consommation électrique reste élevée ({get_val('kwh_per_tonne_cpa')} kWh/t pour CPA) "

                f"même avec des volumes réduits. Le tarif électrique ({get_val('tarif_kwh')} XOF/kWh) pèse plus lourd par tonne produite.<br><br>"

                f"3️⃣ <b>Maintenance estivale</b> : Les arrêts planifiés augmentent en saison basse "

                f"({get_val('maintenance_downtime_pct_site1')*100:.0f}% arrêt S1, {get_val('maintenance_downtime_pct_site2')*100:.0f}% S2), "

                f"réduisant la capacité effective sans réduire les coûts fixes.<br><br>"

                f"📊 <b>Impact chiffré</b> : Coût moyen hors été = {format_xof(avg_base)}/t | "

                f"Coût été = {format_xof(avg_summer)}/t | <b>Écart : {diff_pct:+.1f}%</b><br><br>"

                f"🎯 <i>Navigation automatique vers l'onglet '⚙️ Cout de Revient' > graphique d'évolution mensuelle</i>"

            )



        # Check if asking about specific product

        if any(w in q_lower for w in ["cpa", "52.5"]):

            nav_element = "cost-product-cpa"

            nav_highlight = "cost-structure-cpa"

            kc = KC_RATIOS["CPA 52.5"]

            clinker_cost = kc * get_val("clinker_cost")

            energy = get_val("kwh_per_tonne_cpa") * get_val("tarif_kwh")

            sac = get_val("sac_cost_per_unit") * get_val("sacs_per_tonne")

            answers.append(

                f"<b>CPA 52.5</b> : Le coût de revient est élevé car c'est le produit le plus concentré en clinker "

                f"(<b>K/C = {kc*100:.0f}%</b>).<br>"

                f"• Clinker : {format_xof(clinker_cost)}/t ({kc*100:.0f}% du coût matière)<br>"

                f"• Énergie : {format_xof(energy)}/t ({get_val('kwh_per_tonne_cpa')} kWh/t)<br>"

                f"• Ensachage : {format_xof(sac)}/t<br>"

                f"• <b>Prix de vente</b> : {format_xof(get_val('price_cpa'))}/t | "

                f"Marge estimée : {format_xof(get_val('price_cpa') - clinker_cost - energy - sac)}/t<br><br>"

                f"🎯 <i>Navigation automatique vers l'onglet '⚙️ Cout de Revient' > structure CPA 52.5</i>"

            )



        if any(w in q_lower for w in ["cpj 32", "cpj32", "32.5"]):

            nav_element = "cost-product-cpj32"

            nav_highlight = "cost-structure-cpj32"

            kc = KC_RATIOS["CPJ 32.5"]

            clinker_cost = kc * get_val("clinker_cost")

            energy = get_val("kwh_per_tonne_cpj32") * get_val("tarif_kwh")

            answers.append(

                f"<b>CPJ 32.5</b> : C'est le produit le moins cher à produire grâce à son faible K/C ratio "

                f"(<b>{kc*100:.0f}%</b> vs 80% pour CPA).<br>"

                f"• Clinker : {format_xof(clinker_cost)}/t (économie de {format_xof((0.80-kc)*get_val('clinker_cost'))}/t vs CPA)<br>"

                f"• Énergie : {format_xof(energy)}/t ({get_val('kwh_per_tonne_cpj32')} kWh/t)<br>"

                f"• <b>Prix de vente</b> : {format_xof(get_val('price_cpj32'))}/t | "

                f"Marge plus faible en valeur absolue mais compétitive sur le marché.<br><br>"

                f"🎯 <i>Navigation automatique vers l'onglet '⚙️ Cout de Revient' > structure CPJ 32.5</i>"

            )



        if not answers:

            nav_element = "cost-structure-chart"

            nav_highlight = "cost-summary-table"

            # Generic cost answer

            material_costs = {p: res.get("material_cost", {}).get(p, 0) for p in PRODUCTS}

            energy_costs = {p: res.get("energy_cost_per_t", {}).get(p, 0) for p in PRODUCTS}

            answers.append(

                f"<b>Structure des coûts actuels</b> (par tonne) :<br>"

                + "<br>".join([

                    f"• <b>{p}</b> : Matières {format_xof(material_costs.get(p, 0))} | "

                    f"Énergie {format_xof(energy_costs.get(p, 0))} | "

                    f"Prix vente {format_xof(get_val(f'price_{normalize_product_key(p)}'))}"

                    for p in PRODUCTS

                ]) + f"<br><br>Les coûts fixes mensuels s'élèvent à {format_xof(res.get('total_fixed', 0))}, "

                f"soit {format_xof(safe_div(res.get('total_fixed', 0), res.get('grand_total', 1), 0))}/t à volume actuel.<br><br>"

                f"🎯 <i>Navigation automatique vers l'onglet '⚙️ Cout de Revient'</i>"

            )



    # Pattern 2: Profitability / rentability questions -> Tab 0 (DG Dashboard)

    if any(w in q_lower for w in ["rentable", "rentabilité", "rentabilite", "marge", "profit", "perte", "meilleur", "pire"]):

        nav_tab = 0  # DG Dashboard

        nav_element = "dg-product-margin-table"

        nav_highlight = "kpi-marge-ebitda"



        margins = {}

        for p in PRODUCTS:

            rev = sum(m.get("revenue_by_product", {}).get(p, 0) for m in annual["monthly"])

            vc = sum(m.get("var_cost_by_product", {}).get(p, 0) for m in annual["monthly"])

            vol = sum(m.get("total_prod", {}).get(p, 0) for m in annual["monthly"])

            margins[p] = {

                "total_margin": rev - vc,

                "margin_per_t": safe_div(rev - vc, vol, 0),

                "volume": vol,

                "revenue": rev

            }



        best = max(margins.items(), key=lambda x: x[1]["margin_per_t"])

        worst = min(margins.items(), key=lambda x: x[1]["margin_per_t"])



        answers.append(

            f"<b>Analyse de rentabilité par produit</b> (sur 12 mois) :<br><br>"

            + "<br>".join([

                f"• <b>{p}</b> : Marge {format_xof(m['total_margin'])} total | "

                f"{format_xof(m['margin_per_t'])}/t | Volume {format_tonnes(m['volume'])}"

                for p, m in margins.items()

            ]) + f"<br><br>🏆 <b>Produit le plus rentable</b> : {best[0]} avec {format_xof(best[1]['margin_per_t'])}/t<br>"

            f"📉 <b>Moins rentable</b> : {worst[0]} avec {format_xof(worst[1]['margin_per_t'])}/t<br><br>"

            f"Le <b>{best[0]}</b> est plus rentable car son prix de vente élevé "

            f"({format_xof(get_val(f'price_{normalize_product_key(best[0])}'))}/t) compense son K/C ratio plus élevé.<br><br>"

            f"🎯 <i>Navigation automatique vers l'onglet '📊 Tableau de Bord DG' > table des marges par produit</i>"

        )



    # Pattern 3: Seasonality / saisonnalité questions -> Tab 2 (Production)

    if any(w in q_lower for w in ["saison", "saisonnalité", "saisonnalite", "mois", "pluie", "seche", "sèche", "cycle"]):

        nav_tab = 2  # Production Mensuelle

        nav_element = "prod-seasonality-chart"

        nav_highlight = "prod-seasonality-curve"



        high_months = [m for m, f in SEASONALITY_FACTORS.items() if f >= 1.05]

        low_months = [m for m, f in SEASONALITY_FACTORS.items() if f < 0.95]



        answers.append(

            f"<b>Saisonnalité du marché cimentier ivoirien</b> :<br><br>"

            f"📈 <b>Haute saison</b> (facteur > 1.05) : {', '.join(high_months)}<br>"

            f"   → Activité BTP intense, travaux routiers/infrastructures<br>"

            f"   → Volumes supérieurs de {((max(SEASONALITY_FACTORS.values())-1)*100):.0f}% au pic<br><br>"

            f"📉 <b>Basse saison</b> (facteur < 0.95) : {', '.join(low_months)}<br>"

            f"   → Saison des pluies, ralentissement chantiers<br>"

            f"   → Volumes réduits jusqu'à {((1-min(SEASONALITY_FACTORS.values()))*100):.0f}% en dessous de la moyenne<br><br>"

            f"💡 <b>Impact financier</b> : La basse saison dégrade la rentabilité car les coûts fixes "

            f"sont amortis sur moins de tonnes. Le CA mensuel varie de "

            f"{format_xof(get_val('budget_revenue') * min(SEASONALITY_FACTORS.values()))} à "

            f"{format_xof(get_val('budget_revenue') * max(SEASONALITY_FACTORS.values()))} selon le mois.<br><br>"

            f"🎯 <i>Navigation automatique vers l'onglet '🏭 Production Mensuelle' > courbe de saisonnalité</i>"

        )



    # Pattern 4: Volume / production questions -> Tab 2 (Production)

    if any(w in q_lower for w in ["volume", "production", "tonne", "quantité", "capacité", "capacite", "utilisation"]):

        nav_tab = 2  # Production Mensuelle

        nav_element = "prod-capacity-utilization"

        nav_highlight = "prod-capacity-gauge"



        cap_util = res.get("cap_util", {})

        targets = res.get("cap_util_targets", {})



        answers.append(

            f"<b>Utilisation des capacités actuelle</b> :<br><br>"

            f"• <b>Site 1</b> : {cap_util.get('Site 1', 0)*100:.1f}% utilisé "

            f"(cible : {targets.get('Site 1', 0)*100:.0f}%)<br>"

            f"• <b>Site 2</b> : {cap_util.get('Site 2', 0)*100:.1f}% utilisé "

            f"(cible : {targets.get('Site 2', 0)*100:.0f}%)<br>"

            f"• <b>Global</b> : {res.get('overall_cap_util', 0)*100:.1f}%<br><br>"

            f"📊 <b>Volumes mensuels actuels</b> :<br>"

            + "<br>".join([

                f"• {p} : S1={format_tonnes(get_val(f'vol_{normalize_product_key(p)}_site1'))} | "

                f"S2={format_tonnes(get_val(f'vol_{normalize_product_key(p)}_site2'))}"

                for p in PRODUCTS

            ]) + f"<br><br>Capacité nominale totale : {format_tonnes(sum(SITE_CAPACITIES.values()))}/an<br>"

            f"Capacité effective (après maintenance) : "

            f"{format_tonnes(sum(SITE_CAPACITIES[s] * (1 - get_val(f'maintenance_downtime_pct_{s.lower().replace(" ", "")}')) for s in SITES))}/an<br><br>"

            f"🎯 <i>Navigation automatique vers l'onglet '🏭 Production Mensuelle' > indicateurs d'utilisation capacité</i>"

        )



    # Pattern 5: Market / marché questions -> Tab 1 (Database)

    if any(w in q_lower for w in ["marché", "marche", "concurrent", "concurrence", "prix", "plafond", "dangote", "lafarge"]):

        nav_tab = 1  # Donnees Marche

        nav_element = "db-market-kpis"

        nav_highlight = "db-competitors-table"



        surcap = safe_div(get_val("mkt_capacite_totale_ci") - get_val("mkt_consommation_ci"), get_val("mkt_consommation_ci"), 0) * 100

        scci_share = safe_div(sum(SITE_CAPACITIES.values()), get_val("mkt_capacite_totale_ci"), 0) * 100



        answers.append(

            f"<b>Contexte marché cimentier Côte d'Ivoire 2026</b> :<br><br>"

            f"🏭 <b>Capacité totale</b> : {get_val('mkt_capacite_totale_ci')/1e6:.1f} Mt/an pour "

            f"{get_val('mkt_nb_cimentiers')} cimentiers et {get_val('mkt_nb_usines')} usines<br>"

            f"📉 <b>Consommation</b> : {get_val('mkt_consommation_ci')/1e6:.0f} Mt/an<br>"

            f"⚠️ <b>Surcapacité</b> : {surcap:.0f}% (pression à la baisse sur les prix)<br><br>"

            f"💰 <b>Prix plafonds officiels</b> (Arrêté 26/12/2024) :<br>"

            f"• CPJ 42.5 : {format_xof(get_val('mkt_prix_plafond_cpj42'))}/t<br>"

            f"• CPJ 32.5 : {format_xof(get_val('mkt_prix_plafond_cpj32'))}/t<br>"

            f"• CPA 52.5 : {format_xof(get_val('mkt_prix_plafond_cpa52'))}/t (estimé)<br><br>"

            f"🎯 <b>Part de marché SC CI</b> : {scci_share:.1f}%<br>"

            f"Principaux concurrents : LafargeHolcim (~17%), Dangote (~17%), CIM Ivoire (~17%)<br><br>"

            f"🎯 <i>Navigation automatique vers l'onglet '🗄️ Donnees Marche' > KPIs du marché</i>"

        )



    # Pattern 6: EBITDA / financial performance -> Tab 4 (Financial)

    if any(w in q_lower for w in ["ebitda", "résultat", "resultat", "bénéfice", "benefice", "perte", "financier", "ca"]):

        nav_tab = 4  # Analyse Financiere

        nav_element = "fin-waterfall-chart"

        nav_highlight = "fin-annual-summary"



        annual_ebitda = sum(m.get("ebitda", 0) for m in annual["monthly"])

        annual_rev = sum(m.get("total_revenue", 0) for m in annual["monthly"])

        annual_net = sum(m.get("net_income", 0) for m in annual["monthly"])

        budget_var = annual_ebitda - get_val("budget_ebitda") * 12



        answers.append(

            f"<b>Performance financière annuelle</b> (12 mois) :<br><br>"

            f"💰 <b>CA</b> : {format_xof(annual_rev)}<br>"

            f"📊 <b>EBITDA</b> : {format_xof(annual_ebitda)} "

            f"({safe_div(annual_ebitda, annual_rev, 0)*100:.1f}% de marge)<br>"

            f"💵 <b>Résultat net</b> : {format_xof(annual_net)}<br><br>"

            f"🎯 <b>vs Budget</b> : {format_xof(budget_var)} "

            f"({'✅ Supérieur' if budget_var > 0 else '⚠️ Inférieur'} au budget)<br><br>"

            f"📈 <b>Point mort</b> : {format_tonnes(sum(m.get('break_even_tonnes', 0) for m in annual['monthly']))}/an<br>"

            f"📉 <b>BFR requis</b> : {format_xof(sum(m.get('wc_requirement', 0) for m in annual['monthly']))}<br><br>"

            f"🎯 <i>Navigation automatique vers l'onglet '💳 Analyse Financiere' > cascade du résultat net</i>"

        )



    # Pattern 7: Break-even / point mort -> Tab 5 (Optimization)

    if any(w in q_lower for w in ["point mort", "seuil", "rentabilité", "break even", "break-even"]):

        nav_tab = 5  # Optimisation

        nav_element = "opt-break-even-chart"

        nav_highlight = "opt-break-even-kpis"



        be_tonnes = sum(m.get("break_even_tonnes", 0) for m in annual["monthly"])

        be_rev = sum(m.get("break_even_revenue", 0) for m in annual["monthly"])

        total_vol = sum(m.get("grand_total", 0) for m in annual["monthly"])

        securite = safe_div(total_vol - be_tonnes, total_vol, 0) * 100



        answers.append(

            f"<b>Analyse du point mort</b> :<br><br>"

            f"📍 <b>Point mort annuel</b> : {format_tonnes(be_tonnes)}<br>"

            f"   (soit {format_xof(be_rev)} de CA)<br><br>"

            f"🏭 <b>Production actuelle</b> : {format_tonnes(total_vol)}<br>"

            f"🛡️ <b>Marge de sécurité</b> : {securite:.1f}%<br><br>"

            f"💡 <b>Interprétation</b> : La production peut baisser de {securite:.1f}% "

            f"avant de devenir déficitaire. "

            f"{'✅ Bonne résilience' if securite > 20 else '⚠️ Marge faible - risque si volumes baissent'}.<br><br>"

            f"🎯 <i>Navigation automatique vers l'onglet '🔧 Optimisation' > analyse du point mort</i>"

        )



    # Default / fallback answer -> Tab 0 (DG Dashboard)

    if not answers:

        nav_tab = 0  # DG Dashboard by default

        nav_element = "dg-kpi-cards"

        nav_highlight = "kpi-ca-annuel"



        answers.append(

            f"<b>Analyse des données actuelles</b> :<br><br>"

            f"📊 <b>Production mensuelle</b> : {format_tonnes(res.get('grand_total', 0))}<br>"

            f"💰 <b>CA mensuel</b> : {format_xof(res.get('total_revenue', 0))}<br>"

            f"📈 <b>EBITDA mensuel</b> : {format_xof(res.get('ebitda', 0))} "

            f"({res.get('ebitda_pct', 0)*100:.1f}%)<br>"

            f"🏭 <b>Utilisation capacité</b> : {res.get('overall_cap_util', 0)*100:.1f}%<br><br>"

            f"💡 Essayez des questions plus spécifiques comme :<br>"

            f"• 'Pourquoi les coûts augmentent en été?'<br>"

            f"• 'Quel est le produit le plus rentable?'<br>"

            f"• 'Analyse du point mort'<br>"

            f"• 'Contexte du marché ivoirien'<br><br>"

            f"🎯 <i>Navigation automatique vers l'onglet '📊 Tableau de Bord DG'</i>"

        )



    # Store in history with navigation metadata

    if "qa_history" not in st.session_state:

        st.session_state["qa_history"] = []

    st.session_state["qa_history"].append({

        "question": question,

        "answer": "<br><br>".join(answers),

        "timestamp": datetime.now().strftime("%H:%M:%S"),

        "nav_tab": nav_tab,

        "nav_element": nav_element,

        "nav_highlight": nav_highlight

    })



    return {

        "answer": "<br><br>".join(answers),

        "nav_tab": nav_tab,

        "nav_element": nav_element,

        "nav_highlight": nav_highlight

    }





