def _load_quality_data():
    """Charge les données qualité depuis quality_data.json."""
    try:
        json_path = _os.path.join(_os.path.dirname(_os.path.abspath(__file__)), "quality_data.json")
        with open(json_path, 'r') as f:
            return json.load(f)
    except Exception as e:
        return []

def _compute_control_limits(values):
    """Calcule moyenne, UCL et LCL pour cartes de contrôle (±3σ)."""
    arr = np.array(values)
    mean = np.mean(arr)
    std = np.std(arr, ddof=1) if len(arr) > 1 else 0
    ucl = mean + 3 * std
    lcl = mean - 3 * std
    return mean, ucl, lcl, std

