def _parse_faits_marquants(daily_data):
    """Parse faits marquants to extract stop reasons and durations."""
    import re

    # Patterns for grouping similar reasons
    REASON_PATTERNS = {
        "Arrêt — Vibration / Ferraille / Corps étrangers": [
            "vibration", "ferraille", "corps étrangers", "boulets", "présence de ferr"
        ],
        "Arrêt — Tension CIE / Électrique": [
            "tension cie", "coupure cie", "variation de tension", "disjonction", "défaut electrical", "défaut profibus", "effacement cie"
        ],
        "Arrêt — Silos pleins / Niveau / Affluence": [
            "silos pleins", "niveau des silos", "bon niveau des silos", "moins d'affluence", "manque de camions"
        ],
        "Arrêt — Maintenance / Réparation / Entretien": [
            "réparation", "remplacement", "entretien", "maintenance", "réfection", "inspection", "rechargement de la table"
        ],
        "Arrêt — Optimisation / Consommation": [
            "optimisation", "effacement", "moins d'affluence des camions"
        ],
        "Arrêt — Manque matière / Stock / Eau": [
            "stock", "manque de", "insuffisants", "épuisé", "tank à eau vide", "pompe"
        ],
        "Réception / Livraison / Navire": [
            "réception de", "livraison", "navire", "venant de"
        ],
        "Problème équipement / Chargeuse": [
            "dégradation", "chargeuse", "godet", "immobilisée"
        ],
        "Données erronées / Système": [
            "données erronées", "relevées incorrectes", "en observation", "système de mesure"
        ],
        "Travaux / Réfection infrastructure": [
            "travaux de", "plateforme", "réfection", "bande"
        ],
    }

    events = []  # List of {reason, duration_hours, raw_text, date, dex, source}

    for date_str, dex_data in daily_data.items():
        for dex_name, data in dex_data.items():
            # 1. Parse faits marquants from PDFs
            faits = data.get("faits_marquants", [])
            for fait in faits:
                fait_lower = fait.lower()

                # Extract duration from patterns like "19h00-23h15" or "06h00-23h20"
                duration = 0
                time_patterns = re.findall(r'(\d{1,2})h(\d{2})?-(\d{1,2})h(\d{2})?', fait)
                for match in time_patterns:
                    h1 = int(match[0])
                    m1 = int(match[1]) if match[1] else 0
                    h2 = int(match[2])
                    m2 = int(match[3]) if match[3] else 0

                    # Handle overnight (e.g., 23h15 to 06h00)
                    start_min = h1 * 60 + m1
                    end_min = h2 * 60 + m2
                    if end_min < start_min:
                        end_min += 24 * 60
                    duration += (end_min - start_min) / 60

                # Categorize reason
                reason = "Autre"
                for cat_name, keywords in REASON_PATTERNS.items():
                    if any(kw in fait_lower for kw in keywords):
                        reason = cat_name
                        break

                events.append({
                    "date": date_str, "dex": dex_name,
                    "reason": reason, "duration_hours": duration,
                    "raw_text": fait, "source": "pdf"
                })

            # 2. Parse suivi de production comments from WhatsApp data
            suivi_comments = data.get("suivi_comments", [])
            if not suivi_comments:
                # Also check expedition for WhatsApp comments
                exp = data.get("expedition", {})
                if isinstance(exp, dict):
                    for key in ["whatsapp_comment", "suivi_comment", "commentaire"]:
                        if key in exp and exp[key]:
                            cmt = str(exp[key])
                            if cmt and cmt.lower() not in ["none", "nan", "", "n/a"]:
                                suivi_comments.append(cmt)
            for comment in suivi_comments:
                cmt_lower = comment.lower()
                reason = "Suivi — Commentaire"
                for cat_name, keywords in REASON_PATTERNS.items():
                    if any(kw in cmt_lower for kw in keywords):
                        reason = f"Suivi — {cat_name}"
                        break
                if any(kw in cmt_lower for kw in ["arrêt", "arret", "stop", "panne"]):
                    if reason == "Suivi — Commentaire":
                        reason = "Suivi — Arrêt / Panne"
                events.append({
                    "date": date_str, "dex": dex_name,
                    "reason": reason, "duration_hours": 0,
                    "raw_text": comment, "source": "suivi"
                })

    return events



    # ═══════════════════════════════════════════════════════════
    # PDF SOURCE LINK — Click on any chart point to see source PDF
    # ═══════════════════════════════════════════════════════════
    st.markdown("<div style='height:16px;'></div>", unsafe_allow_html=True)
    st.html("<div class='section-title-light'>📄 Source PDF des Données Journalières</div>")

    # Collect all selections
    all_events = [
        event_prod_d1, event_prod_d2, event_prod_tot,
        event_exp_prod, event_exp_tot,
        event_stock_prod, event_stock_tot,
        event_ces_tot, event_ces_prod,
        event_deb_prod, event_deb_tot,
        event_fuel_prod, event_fuel_tot,
        event_kc
    ]

    selected_date = None
    for ev in all_events:
        if ev and ev.selection and ev.selection.points:
            pt = ev.selection.points[0]
            sel_date = str(pt.get("x", ""))
            if sel_date and sel_date in daily_data:
                selected_date = sel_date
                break

    if selected_date:
        st.success(f"📅 Date sélectionnée: **{selected_date}**")
        for site in daily_data[selected_date]:
            pdf_name = daily_data[selected_date][site].get("source_pdf", "")
            if pdf_name:
                st.info(f"🏭 **{site}** — Source PDF: `{pdf_name}`")
            else:
                st.warning(f"🏭 **{site}** — Aucun PDF source enregistré")
    else:
        st.info("💡 Cliquez sur un point de données dans les graphiques ci-dessus pour voir le PDF source.")

    # Fallback: manual date selector
    with st.expander("🔍 Sélection manuelle de date et PDF", expanded=False):
        all_dates = sorted(daily_data.keys())
        if all_dates:
            sel_date_manual = st.selectbox("Date", all_dates, key="pdf_manual_date")
            if sel_date_manual in daily_data:
                for site in daily_data[sel_date_manual]:
                    pdf_name = daily_data[sel_date_manual][site].get("source_pdf", "")
                    if pdf_name:
                        st.write(f"🏭 **{site}**: `{pdf_name}`")
                    else:
                        st.write(f"🏭 **{site}**: Aucun PDF source")

def _render_pareto_charts(daily_data):
    """Render 4 Pareto charts (2x2 grid): DEX1/2 x Duration/Count."""
    events = _parse_faits_marquants(daily_data)

    if not events:
        st.info("Aucun fait marquant à analyser.")
        return

    n_days = len(daily_data)
    st.html(f"<div class='section-title-light'>📊 Pareto des Arrêts — {n_days} jours de données détaillées</div>")

    TOP_N = 8
    df_events = pd.DataFrame(events)

    def _truncate_label(text, max_len=55):
        return text[:max_len-3] + "..." if len(text) > max_len else text

    def _build_pareto(df, value_col, title, bar_color, xaxis_title, key_suffix):
        """Build a horizontal Pareto chart with text inside/outside bars."""
        if df.empty:
            return None

        grouped = df.groupby("reason")[value_col].sum().reset_index()
        grouped = grouped.sort_values(value_col, ascending=True)
        grouped.columns = ["Raison", "Valeur"]

        if len(grouped) > TOP_N:
            top = grouped.tail(TOP_N).copy()
            autre_val = grouped.head(len(grouped) - TOP_N)["Valeur"].sum()
            autre_reasons = grouped.head(len(grouped) - TOP_N)["Raison"].tolist()[:10]
            autre_hover = "<br>".join([f"  • {r}" for r in autre_reasons])
            top = pd.concat([
                pd.DataFrame([{"Raison": "Autre", "Valeur": autre_val, "_hover": autre_hover}]),
                top
            ], ignore_index=True)
            grouped = top
        else:
            grouped["_hover"] = ""

        grouped["Cumul_%"] = grouped["Valeur"].cumsum() / grouped["Valeur"].sum() * 100

        fig = go.Figure()

        bar_colors = []
        hover_texts = []
        text_positions = []
        text_colors = []
        text_labels = []

        max_val = grouped["Valeur"].max()
        threshold = max_val * 0.25  # 25% of max for inside text

        for _, row in grouped.iterrows():
            if row["Raison"] == "Autre" and row.get("_hover"):
                bar_colors.append("#5B6770")
                hover_texts.append(f"<b>Autre</b><br>{xaxis_title}: {row['Valeur']:.1f}<br><br>Regroupe:<br>{row['_hover']}")
            else:
                bar_colors.append(bar_color)
                hover_texts.append(f"<b>{row['Raison']}</b><br>{xaxis_title}: {row['Valeur']:.1f}<br>Cumul: {row['Cumul_%']:.1f}%")

            # Decide text position: inside if bar is long enough
            if row["Valeur"] >= threshold:
                text_positions.append("inside")
                text_colors.append("white")
            else:
                text_positions.append("outside")
                text_colors.append("#E6E9ED")

        display_labels = [_truncate_label(r) for r in grouped["Raison"]]

        if value_col == "duration_hours":
            val_texts = [f"{v:.1f} h" for v in grouped["Valeur"]]
        else:
            val_texts = [f"{int(v)}" for v in grouped["Valeur"]]

        # Text: reason + value + cumul%
        texts = [f"{lbl}<br>{val}<br>({cum:.0f}%)" for lbl, val, cum in zip(display_labels, val_texts, grouped["Cumul_%"])]

        fig.add_trace(go.Bar(
            y=grouped["Raison"],
            x=grouped["Valeur"],
            name=xaxis_title,
            marker_color=bar_colors,
            text=texts,
            textposition=text_positions,
            insidetextanchor="middle",
            textfont=dict(color=text_colors, size=13),
            hovertext=hover_texts,
            hoverinfo="text",
            orientation="h"
        ))

        fig.update_layout(
            title=dict(text=title, font_size=18, font_color="#FFFFFF", x=0.5),
            template="plotly_dark",
            height=750,
            showlegend=False,
            margin=dict(l=20, r=180, t=60, b=40),
            yaxis=dict(
                showticklabels=False,
                showgrid=False,
                zeroline=False,
                autorange="reversed",
                title=""
            ),
            xaxis=dict(
                title=dict(text=xaxis_title, font_color="#E6E9ED", font_size=12),
                tickfont=dict(size=13, color="#5B6770"),
                gridcolor="rgba(91,103,112,0.2)"
            ),
            paper_bgcolor="rgba(0,0,0,0)",
            plot_bgcolor="rgba(11,31,58,0.4)",
            font=dict(color="#E6E9ED")
        )

        return fig

    def _build_count_pareto(df, title, bar_color, xaxis_title, key_suffix):
        """Build a horizontal Pareto chart for event counts."""
        if df.empty:
            return None

        cnt_df = df.groupby("reason").size().reset_index(name="count")
        cnt_df = cnt_df.sort_values("count", ascending=True)
        cnt_df.columns = ["Raison", "Valeur"]

        if len(cnt_df) > TOP_N:
            top = cnt_df.tail(TOP_N).copy()
            autre_val = cnt_df.head(len(cnt_df) - TOP_N)["Valeur"].sum()
            autre_reasons = cnt_df.head(len(cnt_df) - TOP_N)["Raison"].tolist()[:10]
            autre_hover = "<br>".join([f"  • {r}" for r in autre_reasons])
            top = pd.concat([
                pd.DataFrame([{"Raison": "Autre", "Valeur": autre_val, "_hover": autre_hover}]),
                top
            ], ignore_index=True)
            cnt_df = top
        else:
            cnt_df["_hover"] = ""

        cnt_df["Cumul_%"] = cnt_df["Valeur"].cumsum() / cnt_df["Valeur"].sum() * 100

        fig = go.Figure()

        bar_colors = []
        hover_texts = []
        text_positions = []
        text_colors = []

        max_val = cnt_df["Valeur"].max()
        threshold = max_val * 0.25

        for _, row in cnt_df.iterrows():
            if row["Raison"] == "Autre" and row.get("_hover"):
                bar_colors.append("#5B6770")
                hover_texts.append(f"<b>Autre</b><br>Nombre: {int(row['Valeur'])}<br><br>Regroupe:<br>{row['_hover']}")
            else:
                bar_colors.append(bar_color)
                hover_texts.append(f"<b>{row['Raison']}</b><br>Nombre: {int(row['Valeur'])}<br>Cumul: {row['Cumul_%']:.1f}%")

            if row["Valeur"] >= threshold:
                text_positions.append("inside")
                text_colors.append("white")
            else:
                text_positions.append("outside")
                text_colors.append("#E6E9ED")

        display_labels = [_truncate_label(r) for r in cnt_df["Raison"]]
        val_texts = [f"{int(v)}" for v in cnt_df["Valeur"]]
        texts = [f"{lbl}<br>{val}<br>({cum:.0f}%)" for lbl, val, cum in zip(display_labels, val_texts, cnt_df["Cumul_%"])]

        fig.add_trace(go.Bar(
            y=cnt_df["Raison"],
            x=cnt_df["Valeur"],
            name="Nombre",
            marker_color=bar_colors,
            text=texts,
            textposition=text_positions,
            insidetextanchor="middle",
            textfont=dict(color=text_colors, size=13),
            hovertext=hover_texts,
            hoverinfo="text",
            orientation="h"
        ))

        fig.update_layout(
            title=dict(text=title, font_size=18, font_color="#FFFFFF", x=0.5),
            template="plotly_dark",
            height=750,
            showlegend=False,
            margin=dict(l=20, r=180, t=60, b=40),
            yaxis=dict(
                showticklabels=False,
                showgrid=False,
                zeroline=False,
                autorange="reversed",
                title=""
            ),
            xaxis=dict(
                title=dict(text="Nombre d'événements", font_color="#E6E9ED", font_size=12),
                tickfont=dict(size=13, color="#5B6770"),
                gridcolor="rgba(91,103,112,0.2)"
            ),
            paper_bgcolor="rgba(0,0,0,0)",
            plot_bgcolor="rgba(11,31,58,0.4)",
            font=dict(color="#E6E9ED")
        )

        return fig

    # Split by DEX
    dex1_events = df_events[df_events["dex"] == "DEX 1"]
    dex2_events = df_events[df_events["dex"] == "DEX 2"]

    with st.expander("📊 Voir les graphiques détaillés", expanded=False):
        # Row 1: DEX 1 — side by side (Durée + Count)
        st.markdown("<div style='color:#F58220; font-weight:700; font-size:1.1rem; margin:16px 0 8px; border-bottom:2px solid #F58220; padding-bottom:4px;'>🏭 DEX 1</div>", unsafe_allow_html=True)
        c1, c2 = st.columns([1, 1])
        with c1:
            fig_d1_dur = _build_pareto(dex1_events, "duration_hours", 
                "DEX 1 — Durée (h)", "#1E4D8F", "Durée (h)", "dex1_dur")
            if fig_d1_dur:
                st.plotly_chart(fig_d1_dur, use_container_width=True, key="chart_pareto_dex1_dur", config={"displayModeBar": True})
            else:
                st.info("Aucun arrêt DEX 1 avec durée.")
        with c2:
            fig_d1_cnt = _build_count_pareto(dex1_events, 
                "DEX 1 — Nombre d'événements", "#10b981", "Nombre", "dex1_cnt")
            if fig_d1_cnt:
                st.plotly_chart(fig_d1_cnt, use_container_width=True, key="chart_pareto_dex1_cnt", config={"displayModeBar": True})
            else:
                st.info("Aucun événement DEX 1.")

        # Row 2: DEX 2 — side by side (Durée + Count)
        st.markdown("<div style='color:#F58220; font-weight:700; font-size:1.1rem; margin:24px 0 8px; border-bottom:2px solid #F58220; padding-bottom:4px;'>🏭 DEX 2</div>", unsafe_allow_html=True)
        c3, c4 = st.columns([1, 1])
        with c3:
            fig_d2_dur = _build_pareto(dex2_events, "duration_hours", 
                "DEX 2 — Durée (h)", "#1E4D8F", "Durée (h)", "dex2_dur")
            if fig_d2_dur:
                st.plotly_chart(fig_d2_dur, use_container_width=True, key="chart_pareto_dex2_dur", config={"displayModeBar": True})
            else:
                st.info("Aucun arrêt DEX 2 avec durée.")
        with c4:
            fig_d2_cnt = _build_count_pareto(dex2_events, 
                "DEX 2 — Nombre d'événements", "#10b981", "Nombre", "dex2_cnt")
            if fig_d2_cnt:
                st.plotly_chart(fig_d2_cnt, use_container_width=True, key="chart_pareto_dex2_cnt", config={"displayModeBar": True})
            else:
                st.info("Aucun événement DEX 2.")

        # Summary table
        with st.expander("📋 Détail des événements regroupés", expanded=False):
            summary = df_events.groupby("reason").agg(
                Nombre=("reason", "count"),
                Duree_Totale_h=("duration_hours", "sum"),
                Duree_Moyenne_h=("duration_hours", "mean")
            ).reset_index()
            summary = summary.sort_values("Nombre", ascending=False)
            st.dataframe(summary, use_container_width=True, hide_index=True)

