# PRODUCT & METRIC FILTERING CONFIG
# ============================================================
# Products excluded from production data per site
# NOTE: Use _get_excluded_production(dex_name, date_str) for date-aware exclusion
_EXCLUDED_PRODUCTION = {
    "DEX 1": {"CPA 42.5", "CPA 52.5", "CHF"},
    # DEX 2 : jamais de production CPA 42.5 (TDB mensuel : réel = 0 sur 55 mois, 2022-01 → 2026-07) — le Site 2 l'expédie uniquement depuis les stocks
    "DEX 2": {"MC 12.5", "CPA 42.5"},
}

def _get_excluded_production(dex_name, date_str=None):
    """Get excluded products for a site, with date-aware logic.
    
    DEX 1 produced CPA 52.5 in March 2026 but not after.
    """
    base = set(_EXCLUDED_PRODUCTION.get(dex_name, set()))
    # DEX 1: allow CPA 52.5 before April 2026
    if dex_name == "DEX 1" and date_str and date_str < "2026-04-01":
        base.discard("CPA 52.5")
    return base
# Products excluded from quality data per site
_EXCLUDED_QUALITY = {
    "DEX 1": {"CPA 42.5", "CHF"},
    "DEX 2": {"MC 12.5", "CHF"},
}
# Metric validation ranges (min, max)
_METRIC_RANGES = {
    "CES": (10, 80),         # kWh/t — >80 highly unlikely, requires revalidation
    "Fuel": (0, 15),         # L/t
    "Debit": (15, 160),      # t/h — cap at 160 (physical limit per site)
    "KC": (40, 100),         # % — <40 impossible if production exists
    "SO3": (1, 5),           # %
    "Refus": (0, 30),        # %
    "Blaine": (2000, 6000),  # cm²/g
}
# Max temps de broyage per broyeur per day (hours)
_MAX_TEMPS_BROYAGE = 24
# Fake product keys that should NEVER appear in product-level graphs
_FAKE_PRODUCT_KEYS = {"TOTAL MATIERES", "Mills", "Mill_1", "Mill_2", "total", "_total", "Mix", "mix", "A", "B", "_by_broyeur", "CPA 42.5"}


def _is_metric_valid(metric_name, value):
    """Check if a metric value is within valid range."""
    if value is None:
        return False
    if not isinstance(value, (int, float)):
        return False
    if metric_name not in _METRIC_RANGES:
        return True  # No range defined = accept all
    min_val, max_val = _METRIC_RANGES[metric_name]
    return min_val <= value <= max_val



def _is_fake_product_key(key):
    """Check if a product key is fake, including suffix/prefix patterns like CPJ 32.5_total."""
    if not isinstance(key, str):
        return False
    key_lower = key.lower()
    # Exact matches
    exact_fakes = {"total matieres", "mills", "mill_1", "mill_2", "total", "_total", "mix", "a", "b", "_by_broyeur", "cpa 42.5"}
    if key_lower in exact_fakes:
        return True
    # Suffix patterns
    if key_lower.endswith("_total") or key_lower.endswith(" total"):
        return True
    return False


def _filter_invalid_expedition(exp_data, dex_name=None):
    """Remove invalid expedition entries. Also removes CHF from DEX 2."""
    filtered = {}
    for prod_key, prod_vals in exp_data.items():
        if prod_key == "total_jour":
            filtered[prod_key] = prod_vals
            continue
        if not isinstance(prod_vals, dict):
            continue
        if prod_key == "CHF" and dex_name == "DEX 2":
            continue
        if prod_key == "CHF":
            total = sum(v for v in prod_vals.values() if isinstance(v, (int, float)))
            if total > 200:
                continue
        filtered[prod_key] = prod_vals
    return filtered


def _extract_evolution_data(daily_data_json):
    """Extract time-series data for evolution charts — WITH FILTERING & VALIDATION."""
    import copy
    daily_data = copy.deepcopy(daily_data_json)
    records = []

    PRODUCT_MAP = {
        "mc_12_5": "CPJ 32.5", "cpj_42_5": "CPJ 42.5", "cpa_42_5": "CPA 42.5",
        "cpa_52_5": "CPA 52.5", "cpj_32_5": "CPJ 32.5", "chf": "CHF",
        "total": "Total", "mix": "Mix",
    }

    QUALITY_PRODUCT_MAP = {
        "CPJ 42.5 N": "CPJ 42.5 (Site 2)", "CPJ 42.5 R": "CPJ 42.5 (Site 1)",
        "CPJ 32.5": "CPJ 32.5 (Site 1)", "CPA 52.5 N": "CPA 52.5 (Site 2)",
    }

    def _map_product(key, is_quality=False):
        if is_quality:
            return QUALITY_PRODUCT_MAP.get(key, key)
        return PRODUCT_MAP.get(key, key)

    def _parse_silo_name(silo_key):
        parts = silo_key.split('_')
        if len(parts) >= 3 and parts[0] == 'silo':
            silo_num = parts[1]
            product_key = '_'.join(parts[2:])
            return f"Silo {silo_num}", PRODUCT_MAP.get(product_key, product_key)
        return silo_key, "Inconnu"

    def _map_expedition_product(key):
        mapping = {
            "CPJ 32.5": "CPJ 32.5", "CPJ 42.5": "CPJ 42.5",
            "CPA 42.5": "CPA 42.5", "CPA 52.5": "CPA 52.5", "CHF": "CHF",
        }
        return mapping.get(key, key)

    def _reassign_chf(records, date_str, dex_name, metric_name):
        """Reassign CHF values to CPJ 42.5 for a given metric/date/dex."""
        chf_vals = [r for r in records if r.get("date") == date_str and r.get("dex") == dex_name
                    and r.get("metric") == metric_name and r.get("product") == "CHF"]
        for r in chf_vals:
            records.append({
                "date": date_str, "dex": dex_name, "metric": metric_name,
                "product": "CPJ 42.5", "value": r["value"]
            })

    for date_str, dex_data in daily_data.items():
        for dex_name, data in dex_data.items():
            prod = data.get("production", {})
            exp = data.get("expedition", {})
            stocks = data.get("stocks", {})

            # Get excluded products for this site
            excluded_prod = _get_excluded_production(dex_name, date_str)
            excluded_qual = _EXCLUDED_QUALITY.get(dex_name, set())

            # --- CES ---
            ces = prod.get("ces_mills", {})
            # Priority for CES_Site: 0) pre-computed, 1) Excel "Total", 2) total_matieres, 3) weighted average
            has_ces_total = False
            
            # 0. Pre-computed value (most reliable - validated offline)
            computed = data.get("computed", {})
            if "CES_Site" in computed:
                records.append({"date": date_str, "dex": dex_name, "metric": "CES_Site", "product": "Total", "value": computed["CES_Site"]})
                has_ces_total = True
            
            # 1. Excel "Total" product
            if not has_ces_total and "Total" in ces:
                v = ces["Total"]
                ces_total_val = v.get("Mills") or v.get("realise") if isinstance(v, dict) else (v if isinstance(v, (int, float)) else None)
                if isinstance(ces_total_val, (int, float)) and _is_metric_valid("CES", ces_total_val):
                    records.append({"date": date_str, "dex": dex_name, "metric": "CES_Site", "product": "Total", "value": round(ces_total_val, 2)})
                    has_ces_total = True
            
            # 2. total_matieres from PDF (CES mill de total matiere)
            if not has_ces_total:
                total_matieres = prod.get("total_matieres", {})
                if isinstance(total_matieres, dict):
                    tm_ces = total_matieres.get("ces")
                    if isinstance(tm_ces, (int, float)) and tm_ces is not None and _is_metric_valid("CES", tm_ces):
                        records.append({"date": date_str, "dex": dex_name, "metric": "CES_Site", "product": "Total", "value": round(tm_ces, 2)})
                        has_ces_total = True
            
            # Per-product CES records (for par produit graph) — skip "Total"
            for k, v in ces.items():
                if k in excluded_prod or _is_fake_product_key(k) or k == "Total":
                    continue
                if isinstance(v, dict):
                    a_val = v.get("A")
                    b_val = v.get("B")
                    mills_val = v.get("Mills")
                    # NOTE: ne plus recombiner A+B ici — "Mills" dans le JSON est déjà le débit/CES combiné correct
                    # (production / heures-broyeur cumulées). La somme A+B doublait le débit quand les 2 broyeurs tournaient.
                    if isinstance(mills_val, (int, float)) and mills_val is not None and _is_metric_valid("CES", mills_val):
                        records.append({"date": date_str, "dex": dex_name, "metric": "CES", "product": _map_product(k), "value": round(mills_val, 2)})
                    if dex_name == "DEX 1":
                        for broy_key, broy_val in v.items():
                            if broy_key in ("A", "B") and isinstance(broy_val, (int, float)) and broy_val is not None and _is_metric_valid("CES", broy_val):
                                records.append({"date": date_str, "dex": dex_name, "metric": "CES_Broyeur", "product": _map_product(k), "broyeur": broy_key, "value": broy_val})
                elif isinstance(v, (int, float)) and v is not None and _is_metric_valid("CES", v):
                    records.append({"date": date_str, "dex": dex_name, "metric": "CES", "product": _map_product(k), "value": v})
            _reassign_chf(records, date_str, dex_name, "CES")

            # --- CES_Site fallback: if total_matieres had no CES, try Excel "Total" ---
            if not has_ces_total and "CES_Site" not in [r.get("metric") for r in records if r.get("date") == date_str and r.get("dex") == dex_name]:
                if "Total" in ces:
                    v = ces["Total"]
                    ces_total_val = v.get("Mills") if isinstance(v, dict) else (v if isinstance(v, (int, float)) else None)
                    if isinstance(ces_total_val, (int, float)) and _is_metric_valid("CES", ces_total_val):
                        records.append({"date": date_str, "dex": dex_name, "metric": "CES_Site", "product": "Total", "value": round(ces_total_val, 2)})
                        has_ces_total = True
            # --- CES_Site last resort: weighted average of per-product CES ---
            if not has_ces_total and "CES_Site" not in [r.get("metric") for r in records if r.get("date") == date_str and r.get("dex") == dex_name]:
                weighted_sum = 0.0
                prod_weighted = 0.0
                tp = prod.get("total_production", {})
                if isinstance(tp, dict):
                    for pk, pv in tp.items():
                        if pk in ("total", "_total", "mix") or pk in excluded_prod or _is_fake_product_key(pk):
                            continue
                        if isinstance(pv, (int, float)) and pv > 0:
                            pk_ces = ces.get(pk, {}).get("Mills") if isinstance(ces.get(pk), dict) else ces.get(pk)
                            if isinstance(pk_ces, (int, float)) and pk_ces is not None and _is_metric_valid("CES", pk_ces):
                                weighted_sum += pk_ces * pv
                                prod_weighted += pv
                elif isinstance(tp, (int, float)) and tp > 0:
                    # Simple total, use total CES if available
                    ces_total = ces.get("Mills") if isinstance(ces, dict) else ces
                    if isinstance(ces_total, (int, float)) and ces_total is not None and _is_metric_valid("CES", ces_total):
                        weighted_sum = ces_total * tp
                        prod_weighted = tp
                if prod_weighted > 0:
                    wa = weighted_sum / prod_weighted
                    if _is_metric_valid("CES", wa):
                        records.append({"date": date_str, "dex": dex_name, "metric": "CES_Site", "product": "Total", "value": round(wa, 2)})

            # --- Debit ---
            debit = prod.get("debit_broyeur", {})
            # Priority for Debit_Site: 0) pre-computed, 1) Excel "Total", 2) total_matieres, 3) A+B / max
            has_debit_total = False
            
            # 0. Pre-computed value (most reliable - validated offline)
            if "Debit_Site" in computed:
                records.append({"date": date_str, "dex": dex_name, "metric": "Debit_Site", "product": "Total", "value": computed["Debit_Site"]})
                has_debit_total = True
            
            # 1. Excel "Total" product
            if not has_debit_total and "Total" in debit:
                v = debit["Total"]
                debit_total_val = v.get("Mills") or v.get("realise") if isinstance(v, dict) else (v if isinstance(v, (int, float)) else None)
                if isinstance(debit_total_val, (int, float)) and _is_metric_valid("Debit", debit_total_val):
                    records.append({"date": date_str, "dex": dex_name, "metric": "Debit_Site", "product": "Total", "value": round(debit_total_val, 2)})
                    has_debit_total = True
            
            # 2. total_matieres from PDF (Debit mill de total matiere)
            if not has_debit_total:
                total_matieres = prod.get("total_matieres", {})
                if isinstance(total_matieres, dict):
                    tm_debit = total_matieres.get("debit")
                    if isinstance(tm_debit, (int, float)) and tm_debit is not None and _is_metric_valid("Debit", tm_debit):
                        records.append({"date": date_str, "dex": dex_name, "metric": "Debit_Site", "product": "Total", "value": round(tm_debit, 2)})
                        has_debit_total = True
            
            # Per-product Debit records (for par produit graph) — skip "Total"
            for k, v in debit.items():
                if k in excluded_prod or _is_fake_product_key(k) or k == "Total":
                    continue
                if isinstance(v, dict):
                    a_val = v.get("A")
                    b_val = v.get("B")
                    mills_val = v.get("Mills")
                    # NOTE: ne plus recombiner A+B ici — "Mills" dans le JSON est déjà le débit/CES combiné correct
                    # (production / heures-broyeur cumulées). La somme A+B doublait le débit quand les 2 broyeurs tournaient.
                    if isinstance(mills_val, (int, float)) and mills_val is not None and _is_metric_valid("Debit", mills_val):
                        records.append({"date": date_str, "dex": dex_name, "metric": "Debit", "product": _map_product(k), "value": round(mills_val, 2)})
                    if dex_name == "DEX 1":
                        for broy_key, broy_val in v.items():
                            if broy_key in ("A", "B") and isinstance(broy_val, (int, float)) and broy_val is not None and _is_metric_valid("Debit", broy_val):
                                records.append({"date": date_str, "dex": dex_name, "metric": "Debit_Broyeur", "product": _map_product(k), "broyeur": broy_key, "value": broy_val})
                elif isinstance(v, (int, float)) and v is not None and _is_metric_valid("Debit", v):
                    records.append({"date": date_str, "dex": dex_name, "metric": "Debit", "product": _map_product(k), "value": v})
            _reassign_chf(records, date_str, dex_name, "Debit")

            # --- Debit_Site fallback: if total_matieres had no debit, try Excel "Total" ---
            if not has_debit_total and "Debit_Site" not in [r.get("metric") for r in records if r.get("date") == date_str and r.get("dex") == dex_name]:
                if "Total" in debit:
                    v = debit["Total"]
                    debit_total_val = v.get("Mills") if isinstance(v, dict) else (v if isinstance(v, (int, float)) else None)
                    if isinstance(debit_total_val, (int, float)) and _is_metric_valid("Debit", debit_total_val):
                        records.append({"date": date_str, "dex": dex_name, "metric": "Debit_Site", "product": "Total", "value": round(debit_total_val, 2)})
                        has_debit_total = True
            # --- Debit_Site last resort: compute from per-product A/B ---
            # DEX 1: A+B from broyeurs (NOT sum across products)
            # DEX 2: max per-product Mills (single broyeur)
            if not has_debit_total and "Debit_Site" not in [r.get("metric") for r in records if r.get("date") == date_str and r.get("dex") == dex_name]:
                if dex_name == "DEX 1":
                    a_vals = []
                    b_vals = []
                    for pk, pv in debit.items():
                        if pk in excluded_prod or _is_fake_product_key(pk):
                            continue
                        if isinstance(pv, dict):
                            a = pv.get("A")
                            b = pv.get("B")
                            if isinstance(a, (int, float)) and a > 0:
                                a_vals.append(a)
                            if isinstance(b, (int, float)) and b > 0:
                                b_vals.append(b)
                    a_site = max(a_vals) if a_vals else 0
                    b_site = max(b_vals) if b_vals else 0
                    total_debit = a_site + b_site
                    if total_debit > 0:
                        records.append({"date": date_str, "dex": dex_name, "metric": "Debit_Site", "product": "Total", "value": round(total_debit, 2)})
                else:
                    per_product_debits = []
                    for pk, pv in debit.items():
                        if pk in excluded_prod or _is_fake_product_key(pk):
                            continue
                        if isinstance(pv, dict):
                            pk_debit = pv.get("Mills", 0)
                            if isinstance(pk_debit, (int, float)) and pk_debit > 0:
                                per_product_debits.append(pk_debit)
                        elif isinstance(pv, (int, float)) and pv > 0:
                            per_product_debits.append(pv)
                    if per_product_debits:
                        total_debit = max(per_product_debits)
                        records.append({"date": date_str, "dex": dex_name, "metric": "Debit_Site", "product": "Total", "value": round(total_debit, 2)})

            # --- Fuel ---
            fuel = prod.get("fuel_mills", {})
            # Capture "Total" as Fuel_Site if available
            if "Total" in fuel:
                v = fuel["Total"]
                fv = v.get("Mills") if isinstance(v, dict) else (v if isinstance(v, (int, float)) else None)
                if isinstance(fv, (int, float)) and _is_metric_valid("Fuel", fv):
                    records.append({"date": date_str, "dex": dex_name, "metric": "Fuel_Site", "product": "Total", "value": round(fv, 3)})
            # Per-product Fuel records (for par produit graph) — skip "Total"
            for k, v in fuel.items():
                if k in excluded_prod or _is_fake_product_key(k) or k == "Total":
                    continue
                if isinstance(v, dict):
                    mills_val = v.get("Mills")
                    if isinstance(mills_val, (int, float)) and mills_val is not None and _is_metric_valid("Fuel", mills_val):
                        records.append({"date": date_str, "dex": dex_name, "metric": "Fuel", "product": _map_product(k), "value": mills_val})
                    # DEX 1: extract A/B broyeur breakdown
                    if dex_name == "DEX 1":
                        for broy_key, broy_val in v.items():
                            if broy_key in ("A", "B") and isinstance(broy_val, (int, float)) and broy_val is not None and _is_metric_valid("Fuel", broy_val):
                                if broy_val == 0:
                                    ces_dict = prod.get("ces_mills", {}).get(k, {})
                                    debit_dict = prod.get("debit_broyeur", {}).get(k, {})
                                    has_ces = isinstance(ces_dict, dict) and ces_dict.get(broy_key, 0) > 0
                                    has_debit = isinstance(debit_dict, dict) and debit_dict.get(broy_key, 0) > 0
                                    if not has_ces and not has_debit:
                                        continue
                                records.append({"date": date_str, "dex": dex_name, "metric": "Fuel_Broyeur", "product": _map_product(k), "broyeur": broy_key, "value": broy_val})
                    # DEX 2: extract Mills broyeur value
                    elif dex_name == "DEX 2" and k in ("CPJ 42.5", "CPA 52.5"):
                        mills_val = v.get("Mills")
                        if isinstance(mills_val, (int, float)) and mills_val is not None and _is_metric_valid("Fuel", mills_val):
                            records.append({"date": date_str, "dex": dex_name, "metric": "Fuel_Broyeur", "product": _map_product(k), "broyeur": "Mills", "value": mills_val})
                elif isinstance(v, (int, float)) and v is not None and _is_metric_valid("Fuel", v):
                    records.append({"date": date_str, "dex": dex_name, "metric": "Fuel", "product": _map_product(k), "value": v})
            _reassign_chf(records, date_str, dex_name, "Fuel")

            # --- Fuel_Site (total) — production-weighted average ---
            weighted_sum = 0.0
            prod_weighted = 0.0
            tp = prod.get("total_production", {})
            if isinstance(tp, dict):
                for pk, pv in tp.items():
                    if pk in ("total", "_total", "mix") or pk in excluded_prod or _is_fake_product_key(pk):
                        continue
                    if isinstance(pv, (int, float)) and pv > 0:
                        pk_fuel = fuel.get(pk, {}).get("Mills") if isinstance(fuel.get(pk), dict) else fuel.get(pk)
                        if isinstance(pk_fuel, (int, float)) and pk_fuel is not None and _is_metric_valid("Fuel", pk_fuel):
                            weighted_sum += pk_fuel * pv
                            prod_weighted += pv
            elif isinstance(tp, (int, float)) and tp > 0:
                # Simple total, use total Fuel if available
                fuel_total = fuel.get("Mills") if isinstance(fuel, dict) else fuel
                if isinstance(fuel_total, (int, float)) and fuel_total is not None and _is_metric_valid("Fuel", fuel_total):
                    weighted_sum = fuel_total * tp
                    prod_weighted = tp
            if prod_weighted > 0:
                wa = weighted_sum / prod_weighted
                if _is_metric_valid("Fuel", wa):
                    records.append({"date": date_str, "dex": dex_name, "metric": "Fuel", "product": "Total", "value": round(wa, 3)})

            # --- Production ---
            total_prod = prod.get("total_production", {})
            total_added = False
            if isinstance(total_prod, dict):
                for k, v in total_prod.items():
                    if k in excluded_prod:
                        continue
                    # Skip TOTAL MATIERES - use individual product values instead
                    if k == "TOTAL MATIERES":
                        continue
                    # Handle per-broyeur dicts: extract Mills or sum A+B
                    v_scalar = None
                    if isinstance(v, dict):
                        v_mills = v.get("Mills")
                        if isinstance(v_mills, (int, float)) and v_mills > 0:
                            v_scalar = v_mills
                        else:
                            # Sum A+B for production (additive across broyeurs)
                            v_scalar = sum(vv for kk, vv in v.items() if kk in ("A", "B") and isinstance(vv, (int, float)) and vv > 0)
                            if v_scalar == 0:
                                v_scalar = None
                    elif isinstance(v, (int, float)):
                        v_scalar = v
                    
                    if v_scalar is not None and v_scalar > 0:
                        if k.lower() in ("total", "_total", "mix"):
                            records.append({"date": date_str, "dex": dex_name, "metric": "Production", "product": "Total", "value": v_scalar})
                            total_added = True
                            continue
                        records.append({"date": date_str, "dex": dex_name, "metric": "Production", "product": _map_product(k), "value": v_scalar})
                        # DEX 1: also extract per-broyeur production for scatter/detail views
                        if dex_name == "DEX 1" and isinstance(v, dict):
                            for broy_key, broy_val in v.items():
                                if broy_key in ("A", "B") and isinstance(broy_val, (int, float)) and broy_val > 0:
                                    records.append({"date": date_str, "dex": dex_name, "metric": "Production_Broyeur", "product": _map_product(k), "broyeur": broy_key, "value": broy_val})
            elif isinstance(total_prod, (int, float)) and total_prod > 0:
                # Simple total production value (from PDFs/KPIs)
                records.append({"date": date_str, "dex": dex_name, "metric": "Production", "product": "Total", "value": total_prod})
                total_added = True
            # If only TOTAL MATIERES was present (no real products), try to infer from temps_broyage or expedition
            def _get_scalar(val):
                if isinstance(val, dict):
                    v_mills = val.get("Mills")
                    if isinstance(v_mills, (int, float)) and v_mills > 0:
                        return v_mills
                    return sum(vv for kk, vv in val.items() if kk in ("A", "B") and isinstance(vv, (int, float)) and vv > 0)
                return val if isinstance(val, (int, float)) else 0
            
            # Only process TOTAL MATIERES / individual sum if total_prod is a dict
            if isinstance(total_prod, dict):
                has_real_products = any(kk not in ("total", "_total", "mix", "TOTAL MATIERES") and kk not in excluded_prod 
                                        and _get_scalar(vv) > 0 for kk, vv in total_prod.items())
                if not has_real_products and "TOTAL MATIERES" in total_prod:
                    total_val = total_prod["TOTAL MATIERES"]
                    if isinstance(total_val, (int, float)) and total_val > 0:
                        # Try to infer product from temps_broyage (which product was running?)
                        tps = prod.get("temps_broyage", {})
                        active_prods = [pk for pk, pv in tps.items() if isinstance(pv, dict) and pv.get("Mills", 0) > 0 
                                        and pk not in excluded_prod and pk != "TOTAL MATIERES"]
                        if active_prods:
                            for ap in active_prods:
                                records.append({"date": date_str, "dex": dex_name, "metric": "Production", "product": _map_product(ap), "value": total_val})
                        else:
                            # Fallback: use expedition to infer product
                            exp_prod = [pk for pk, pv in exp.items() if isinstance(pv, dict) and sum(vvv for vvv in pv.values() if isinstance(vvv, (int, float))) > 0
                                        and pk not in ("total_jour", "total_sacs", "total_vracs", "total_big_bag")]
                            if exp_prod:
                                for ep in exp_prod:
                                    records.append({"date": date_str, "dex": dex_name, "metric": "Production", "product": _map_expedition_product(ep), "value": total_val})
                            else:
                                # Last resort: record as "Total Matières" for visibility
                                records.append({"date": date_str, "dex": dex_name, "metric": "Production", "product": "Total Matières", "value": total_val})
                if not total_added and total_prod:
                    individual_sum = 0
                    for kk, vv in total_prod.items():
                        if kk.lower() not in ("total", "_total", "mix") and kk not in excluded_prod and kk != "TOTAL MATIERES":
                            sv = _get_scalar(vv)
                            if sv > 0:
                                individual_sum += sv
                    if individual_sum > 0:
                        records.append({"date": date_str, "dex": dex_name, "metric": "Production", "product": "Total", "value": individual_sum})
            _reassign_chf(records, date_str, dex_name, "Production")

            # --- Temps de Broyage (validated: max 24h) ---
            tps_broy = prod.get("temps_broyage", {})
            for prod_key, val in tps_broy.items():
                if prod_key in ("total", "_total", "mix"):
                    continue
                if _is_fake_product_key(prod_key):
                    continue
                if prod_key in excluded_prod:
                    continue
                if isinstance(val, dict):
                    mills_val = val.get("Mills")
                    if isinstance(mills_val, (int, float)) and mills_val is not None and 0 < mills_val <= _MAX_TEMPS_BROYAGE:
                        records.append({"date": date_str, "dex": dex_name, "metric": "TempsBroyage", "product": _map_product(prod_key), "value": mills_val})
                    # DEX 1: extract A/B broyeur breakdown
                    if dex_name == "DEX 1":
                        for broy_key, broy_val in val.items():
                            if broy_key in ("A", "B") and isinstance(broy_val, (int, float)) and broy_val is not None and 0 < broy_val <= _MAX_TEMPS_BROYAGE:
                                records.append({"date": date_str, "dex": dex_name, "metric": "TempsBroyage_Broyeur", "product": _map_product(prod_key), "broyeur": broy_key, "value": broy_val})
                    # DEX 2: extract Mills broyeur value (single mill)
                    elif dex_name == "DEX 2" and prod_key in ("CPJ 42.5", "CPA 52.5"):
                        mills_val = val.get("Mills")
                        if isinstance(mills_val, (int, float)) and mills_val is not None and 0 < mills_val <= _MAX_TEMPS_BROYAGE:
                            records.append({"date": date_str, "dex": dex_name, "metric": "TempsBroyage_Broyeur", "product": _map_product(prod_key), "broyeur": "Mills", "value": mills_val})
                elif isinstance(val, (int, float)) and val is not None and 0 < val <= _MAX_TEMPS_BROYAGE:
                    records.append({"date": date_str, "dex": dex_name, "metric": "TempsBroyage", "product": _map_product(prod_key), "value": val})

            # NOTE: DEX 2 combined temps > 24h indicates a parsing issue
            # Do NOT scale — flag for investigation instead

            # --- Matières Premières (consommées par produit) ---
            mp = prod.get("matieres_premieres", {})
            # Detect and fix inverted MP data (product->material instead of material->product)
            _MP_MATERIALS = {"clinker", "gypse", "granite", "pouzzolane", "laitier", "argile", "calcaire"}
            _MP_PRODUCTS = {"CPJ 32.5", "CPJ 42.5", "CPA 42.5", "CPA 52.5", "CHF"}
            is_inverted = False
            for top_key, sub_dict in mp.items():
                if isinstance(sub_dict, dict):
                    for sub_key in sub_dict:
                        if sub_key in _MP_MATERIALS:
                            is_inverted = True
                            break
                if is_inverted:
                    break
            if is_inverted:
                # Transpose: product->material becomes material->product
                fixed_mp = {}
                for product, materials in mp.items():
                    if product in ("total", "TOTAL MATIERES"):
                        fixed_mp[product] = materials
                        continue
                    if isinstance(materials, dict):
                        for material, val in materials.items():
                            if material not in fixed_mp:
                                fixed_mp[material] = {}
                            fixed_mp[material][product] = val
                mp = fixed_mp
            for materiau, prod_vals in mp.items():
                if isinstance(prod_vals, dict):
                    for prod_key, val in prod_vals.items():
                        # Skip total keys ("Mills"/"Total"/"1") — they are aggregates, not products
                        if prod_key in ("Mills", "Total", "TOTAL", "1"):
                            continue
                        if isinstance(val, (int, float)) and val is not None and val > 0:
                            records.append({"date": date_str, "dex": dex_name, "metric": "MatieresPremieres", "product": _map_product(prod_key), "materiau": materiau, "value": val})

            # --- Expedition (filtered) ---
            exp = _filter_invalid_expedition(exp, dex_name)
            total_exp = exp.get("total_jour")
            if isinstance(total_exp, (int, float)) and total_exp is not None and total_exp > 0:
                records.append({"date": date_str, "dex": dex_name, "metric": "Expedition", "product": "Total", "value": total_exp})
            for prod_key, prod_vals in exp.items():
                if prod_key == "total_jour":
                    continue
                if isinstance(prod_vals, dict):
                    prod_name = _map_expedition_product(prod_key)
                    has_total_field = ("_total" in prod_vals and isinstance(prod_vals["_total"], (int, float)) and prod_vals["_total"] > 0) or \
                                      ("total" in prod_vals and isinstance(prod_vals["total"], (int, float)) and prod_vals["total"] > 0)
                    if has_total_field:
                        # Has _total: only use _total for the product total (no individual modes)
                        total_val = prod_vals.get("_total") or prod_vals.get("total")
                        # Do NOT register mode="total"; just record the product value
                        # The mode is None so it won't show in mode-based visualizations
                        records.append({"date": date_str, "dex": dex_name, "metric": "Expedition", "product": prod_name, "value": total_val})
                    else:
                        # No total field: register individual modes with proper names
                        MODE_MAP = {"_sacs": "Sacs", "sacs": "Sacs", "_vracs": "Vrac", "vracs": "Vrac", "_big_bag": "Big Bag", "big_bag": "Big Bag"}
                        for mode, val in prod_vals.items():
                            if isinstance(val, (int, float)) and val is not None and val > 0:
                                mode_name = MODE_MAP.get(mode, mode)
                                records.append({"date": date_str, "dex": dex_name, "metric": "Expedition", "product": prod_name, "mode": mode_name, "value": val})

            # --- Stocks ---
            for silo_key, val in stocks.items():
                if silo_key == "total_disponible":
                    if isinstance(val, (int, float)) and val is not None:
                        records.append({"date": date_str, "dex": dex_name, "metric": "Stock", "product": "Total", "silo": "Total", "value": val})
                    continue
                silo_name, prod_name = _parse_silo_name(silo_key)
                if isinstance(val, (int, float)) and val is not None:
                    records.append({"date": date_str, "dex": dex_name, "metric": "Stock", "product": prod_name, "silo": silo_name, "value": val})

            # --- Cibles & Autonomie (from Excel cibles field) ---
            cibles = data.get("cibles", {})
            if cibles:
                # Stock ciment cibles
                stock_ciment_cible = cibles.get("stock_ciment", {})
                for prod_key, val in stock_ciment_cible.items():
                    if isinstance(val, (int, float)) and val is not None and val > 0:
                        records.append({"date": date_str, "dex": dex_name, "metric": "CibleStockCiment", "product": prod_key, "value": val})
                # Autonomie (in cibles.reception_* as days)
                for mat_key, val in cibles.items():
                    if mat_key.startswith("reception_") and isinstance(val, dict):
                        for prod_key, v in val.items():
                            if isinstance(v, (int, float)) and v is not None and v > 0 and v < 100:  # autonomie is in days (< 100)
                                records.append({"date": date_str, "dex": dex_name, "metric": "AutonomieJours", "materiau": mat_key.replace("reception_", ""), "product": prod_key, "value": v})

            # --- Adjuvants (totals) ---
            additives = data.get("additives", {})
            for adj_key, adj_val in additives.items():
                if isinstance(adj_val, dict):
                    # Per-product totals: { "CPJ 32.5": 1197, "CPJ 42.5": 900 }
                    for prod_name_a, prod_val in adj_val.items():
                        if isinstance(prod_val, (int, float)) and prod_val is not None and prod_val > 0:
                            records.append({"date": date_str, "dex": dex_name, "metric": "Adjuvant", "product": prod_name_a, "adj_type": adj_key.replace("adj_", "").upper(), "value": prod_val})
                elif isinstance(adj_val, (int, float)) and adj_val is not None and adj_val > 0:
                    records.append({"date": date_str, "dex": dex_name, "metric": "Adjuvant", "product": adj_key.replace("adj_", "").upper(), "value": adj_val})

            # --- Adjuvants per broyeur (DEX 1) ---
            # Structure: { "CPJ 32.5": { "adj_sika": {"A": 603, "B": 594} } }
            additives_broyeur = data.get("additives_broyeur", {})
            for prod_name_a, adj_types in additives_broyeur.items():
                for adj_key, broyeur_vals in adj_types.items():
                    if not isinstance(broyeur_vals, dict):
                        continue
                    for broy_key, broy_val in broyeur_vals.items():
                        if broy_key in ("A", "B") and isinstance(broy_val, (int, float)) and broy_val is not None and broy_val >= 0:
                            records.append({"date": date_str, "dex": dex_name, "metric": "Adjuvant_Broyeur", "product": prod_name_a, "adj_type": adj_key.replace("adj_", "").upper(), "broyeur": broy_key, "value": broy_val})

            # --- Stock MP (from Excel) ---
            stock_mp = data.get("stock_mp", {})
            for mat_name, val in stock_mp.items():
                if isinstance(val, dict):
                    # Nested structure: {"clinker": {"recu": ..., "stock": ..., "autonomie": ...}}
                    stock_val = val.get("stock")
                    if isinstance(stock_val, (int, float)) and stock_val is not None:
                        records.append({"date": date_str, "dex": dex_name, "metric": "StockMP", "materiau": mat_name, "value": abs(stock_val)})
                    # Also add autonomie from nested structure
                    auto_val = val.get("autonomie")
                    if isinstance(auto_val, (int, float)) and auto_val is not None:
                        records.append({"date": date_str, "dex": dex_name, "metric": "AutonomieMP", "materiau": mat_name, "value": auto_val})
                    # Also add reception from nested structure
                    rec_val = val.get("recu")
                    if isinstance(rec_val, (int, float)) and rec_val is not None and rec_val > 0:
                        records.append({"date": date_str, "dex": dex_name, "metric": "RecuMP", "materiau": mat_name, "value": rec_val})
                elif isinstance(val, (int, float)) and val is not None:
                    records.append({"date": date_str, "dex": dex_name, "metric": "StockMP", "materiau": mat_name, "value": abs(val)})

            # --- Recu MP (daily reception from Excel) ---
            receptions = data.get("receptions", {})
            for rec_key, rec_val in receptions.items():
                if isinstance(rec_val, (int, float)) and rec_val is not None and rec_val > 0:
                    records.append({"date": date_str, "dex": dex_name, "metric": "RecuMP", "materiau": rec_key, "value": rec_val})

            # --- Autonomie MP (from Excel) ---
            autonomie_mp = data.get("autonomie_mp", {})
            for mat_name, val in autonomie_mp.items():
                if isinstance(val, (int, float)) and val is not None:
                    records.append({"date": date_str, "dex": dex_name, "metric": "AutonomieMP", "materiau": mat_name, "value": val})

            # --- Consommation Matières Premières (aggregated per material) ---
            mp_conso = prod.get("matieres_premieres", {})
            if is_inverted:
                mp_conso = fixed_mp
            for materiau, prod_vals in mp_conso.items():
                if materiau in ("total", "TOTAL MATIERES"):
                    continue
                if isinstance(prod_vals, dict):
                    # Sum per-product/broyeur detail keys only; total keys
                    # ("Mills"/"Total"/"1") duplicate the details and would double-count.
                    # Fall back to total keys when no details are present.
                    _MP_TOTAL_KEYS = ("Mills", "Total", "TOTAL", "1")
                    detail_conso = sum(v for k, v in prod_vals.items() if k not in _MP_TOTAL_KEYS and isinstance(v, (int, float)) and v > 0)
                    totalkey_conso = sum(v for k, v in prod_vals.items() if k in _MP_TOTAL_KEYS and isinstance(v, (int, float)) and v > 0)
                    total_conso = detail_conso if detail_conso > 0 else totalkey_conso
                    if total_conso > 0:
                        records.append({"date": date_str, "dex": dex_name, "metric": "ConsoMP", "materiau": materiau, "value": total_conso})

            # --- Quality (filtered) ---
            qual = data.get("quality", {})
            for broy_key, broy_val in qual.items():
                if isinstance(broy_val, dict):
                    for prod_key, prod_qual in broy_val.items():
                        # Skip excluded quality products
                        base_prod = prod_key.split(" (")[0] if " (" in prod_key else prod_key
                        if base_prod in excluded_qual:
                            continue
                        if isinstance(prod_qual, dict):
                            mapped_prod = _map_product(prod_key, is_quality=True)
                            if "Site" not in mapped_prod:
                                site_label = "Site 1" if "DEX 1" in dex_name else "Site 2"
                                mapped_prod = f"{mapped_prod} ({site_label})"

                            # K/C
                            kc = prod_qual.get("k_c")
                            if kc and isinstance(kc, str):
                                try:
                                    kc_val = float(kc.replace("%", "").replace(",", "."))
                                    if kc_val > 0 and _is_metric_valid("KC", kc_val):
                                        records.append({"date": date_str, "dex": dex_name, "metric": "KC", "product": mapped_prod, "broyeur": broy_key, "value": kc_val})
                                except:
                                    pass
                            # SO3
                            so3 = prod_qual.get("so3")
                            if isinstance(so3, (int, float)) and so3 is not None and _is_metric_valid("SO3", so3):
                                records.append({"date": date_str, "dex": dex_name, "metric": "SO3", "product": mapped_prod, "broyeur": broy_key, "value": so3})
                            # Refus 45u
                            refus = prod_qual.get("refus_45u")
                            if isinstance(refus, (int, float)) and refus is not None and _is_metric_valid("Refus", refus):
                                records.append({"date": date_str, "dex": dex_name, "metric": "Refus", "product": mapped_prod, "broyeur": broy_key, "value": refus})
                            # Blaine
                            blaine = prod_qual.get("blaine")
                            if isinstance(blaine, (int, float)) and blaine is not None and _is_metric_valid("Blaine", blaine):
                                records.append({"date": date_str, "dex": dex_name, "metric": "Blaine", "product": mapped_prod, "broyeur": broy_key, "value": blaine})

            # Note: CES_Site and Debit_Site are extracted earlier in the loop
            # with priority: 1) Excel "Total", 2) total_matieres, 3) computed fallback
            # The site_totals field from Excel is NOT used (values are incorrect for DEX 1)
            # site_totals doubles DEX 1 values (A+B instead of (A+B)/2 for CES)
            # Kept for reference but NOT added to records
            # site_totals = data.get("site_totals", {})
            # for metric_short, total_val in site_totals.items(): ...

    return pd.DataFrame(records)


def _render_evolution_charts(daily_data):
    """Render evolution charts split into separate sections."""
    df = _extract_evolution_data(dict(daily_data))

    if df.empty:
        st.info("Aucune donnée d\'évolution disponible.")
        return

    df["date"] = pd.to_datetime(df["date"].str.replace("_S2", ""), errors="coerce")
    df = df.dropna(subset=["date"])

    def _split_cpj42(df_sub):
        """Split shared products (CPJ 42.5, CPA 52.5) by site to avoid overlapping lines."""
        df_sub = df_sub.copy()
        shared_products = [r"CPJ\s*42\.5", r"CPA\s*52\.5"]
        for prod_pat in shared_products:
            mask = (
                df_sub["product"].str.contains(prod_pat, case=False, na=False, regex=True) &
                ~df_sub["product"].str.contains("Site|DEX", case=False, na=False)
            )
            df_sub.loc[mask, "product"] = df_sub.loc[mask, "product"] + " (" + df_sub.loc[mask, "dex"] + ")"
        return df_sub

    def _render_stacked_bar_broyeur(df_broyeur, metric_name, unit, color_a="#1E4D8F", color_b="#F58220"):
        """Render 2 grouped bar charts (1 per broyeur) showing products for DEX 1.
        Broyeur A and B each get their own graph with products grouped (NOT stacked).
        Products are side-by-side since a broyeur can't run >24h total."""
        if df_broyeur.empty:
            return
        df_b = df_broyeur[df_broyeur["dex"] == "DEX 1"].copy()
        if df_b.empty:
            return
        # One graph per broyeur (A and B), products grouped within each
        broyeurs = ["A", "B"]
        prods = ["CPJ 32.5", "CPJ 42.5"]  # DEX 1 does NOT produce CPA 52.5
        prod_colors = {"CPJ 32.5": "#1E4D8F", "CPJ 42.5": "#F58220"}
        cols = st.columns(2)
        for i, broy in enumerate(broyeurs):
            df_broy = df_b[df_b["broyeur"] == broy].copy()
            with cols[i]:
                if df_broy.empty:
                    st.info(f"Aucune donnée Broyeur {broy} pour la période sélectionnée.")
                    continue
                fig = go.Figure()
                for prod in prods:
                    df_p = df_broy[df_broy["product"] == prod].copy()
                    if not df_p.empty:
                        fig.add_trace(go.Bar(x=df_p["date"], y=df_p["value"], name=prod, marker_color=prod_colors.get(prod, "#5B6770")))
                fig.update_layout(barmode="group", title=f"{metric_name} — Broyeur {broy}", yaxis_title=unit, xaxis_title="Date", template="plotly_white", height=350, legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"), yaxis=dict(range=[0, 24]))
                st.plotly_chart(fig, use_container_width=True, key=f"chart_{metric_name.lower().replace(' ', '_').replace('/', '_')}_broyeur_{broy}_group", config={"displayModeBar": True})

    def _render_scatter_broyeur(df_broyeur, metric_name, unit, color_a="#1E4D8F", color_b="#F58220", include_site2=False):
        """Render 3 scatter plots (1 per product) showing A vs B (and site 2) broyeur values."""
        if df_broyeur.empty:
            return
        prods_config = [
            ("CPJ 32.5", ["A", "B"], False),
            ("CPJ 42.5", ["A", "B"], True),
        ]
        cols = st.columns(2)
        for i, (prod, broyeurs, has_site2) in enumerate(prods_config):
            df_p = df_broyeur[df_broyeur["product"] == prod].copy()
            if df_p.empty:
                continue
            with cols[i]:
                fig = go.Figure()
                colors = {"A": color_a, "B": color_b, "Site 2": "#10b981"}
                for broy in broyeurs:
                    df_b = df_p[(df_p["broyeur"] == broy) & (df_p["dex"] == "DEX 1")]
                    if not df_b.empty:
                        fig.add_trace(go.Scatter(x=df_b["date"], y=df_b["value"], mode="markers", name=f"Broyeur {broy}", marker=dict(color=colors.get(broy, "#1E4D8F"), size=8)))
                if has_site2 and include_site2:
                    df_s2 = df_p[(df_p["dex"] == "DEX 2")]
                    if not df_s2.empty:
                        fig.add_trace(go.Scatter(x=df_s2["date"], y=df_s2["value"], mode="markers", name="Site 2", marker=dict(color=colors["Site 2"], size=8, symbol="diamond")))
                fig.update_layout(title=f"{metric_name} — {prod}", yaxis_title=unit, xaxis_title="Date", template="plotly_white", height=300, legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
                st.plotly_chart(fig, use_container_width=True, key=f"chart_{metric_name.lower().replace(' ', '_').replace('/', '_')}_{prod.replace(' ', '_').replace('.', '_')}_scat", config={"displayModeBar": True})

    # ============================================================
    # --- PRODUCTION ---
    # ============================================================
    st.html("<div class=\'section-title-light\'>🏭 Production (t)</div>")
    with st.expander("📊 Voir les graphiques détaillés", expanded=False):
        prod_df = df[df["metric"] == "Production"].copy()
        if not prod_df.empty:
            # Exclude invalid/aggregate products per site
            EXCLUDED_D1 = {"Total", "Mix", "CHF", "TOTAL MATIERES", "Mills", "Mill_1", "Mill_2", "CPA 42.5", "_by_broyeur"}
            EXCLUDED_D2 = {"Total", "Mix", "CHF", "TOTAL MATIERES", "Mills", "Mill_1", "Mill_2", "CPA 42.5", "CPJ 32.5", "_by_broyeur"}
            prod_dex1 = prod_df[(~prod_df["product"].isin(EXCLUDED_D1)) & (prod_df["dex"] == "DEX 1")].copy()
            prod_dex2 = prod_df[(~prod_df["product"].isin(EXCLUDED_D2)) & (prod_df["dex"] == "DEX 2")].copy()
            c1, c2 = st.columns(2)
            with c1:
                if not prod_dex1.empty:
                    prod_dex1 = _split_cpj42(prod_dex1)
                    fig = px.bar(prod_dex1, x="date", y="value", color="product", title="Production par Produit — DEX 1", labels={"value": "Production (t)", "date": "Date", "product": "Produit"}, template="plotly_white", height=350)
                    fig.update_layout(legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
                    st.plotly_chart(fig, use_container_width=True, key="chart_prod_dex1_bar", config={"displayModeBar": True})
            with c2:
                if not prod_dex2.empty:
                    prod_dex2 = _split_cpj42(prod_dex2)
                    fig = px.bar(prod_dex2, x="date", y="value", color="product", title="Production par Produit — DEX 2", labels={"value": "Production (t)", "date": "Date", "product": "Produit"}, template="plotly_white", height=350)
                    fig.update_layout(legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
                    st.plotly_chart(fig, use_container_width=True, key="chart_prod_dex2_bar", config={"displayModeBar": True})

            prod_total = prod_df[prod_df["product"].isin(["Total", "Mix"])].copy()
            if not prod_total.empty:
                # Compute MTD/YTD delta: (production - commandes) for dates where BOTH exist
                # Only count dates from March 10 onwards where commandes data is available
                cmd_mtd_sum = 0
                prod_mtd_sum = 0
                cmd_ytd_sum = 0
                prod_ytd_sum = 0
                first_cmd_date = "2026-03-10"
                current_month = None
                _FAKE_PROD = {"total", "_total", "mix", "TOTAL MATIERES", "_by_broyeur", "CPA 42.5", "A", "B", "Mills"}
                
                for date_str in sorted(daily_data.keys()):
                    if date_str < first_cmd_date:
                        continue
                    dt = pd.to_datetime(date_str.replace("_S2", ""))
                    month_key = f"{dt.year}-{dt.month:02d}"
                    if current_month is None:
                        current_month = month_key
                    
                    # Check if this date has commandes data
                    has_cmd = False
                    cmd_val = 0
                    for entry in daily_data[date_str].values():
                        cibles = entry.get("cibles", {})
                        if cibles and "commandes_journalieres_t" in cibles:
                            v = cibles["commandes_journalieres_t"]
                            if isinstance(v, (int, float)) and v > 0:
                                has_cmd = True
                                cmd_val = v
                                break
                    
                    if not has_cmd:
                        continue  # Skip dates without commandes
                    
                    # Sum commandes
                    cmd_ytd_sum += cmd_val
                    if month_key == current_month:
                        cmd_mtd_sum += cmd_val
                    
                    # Sum production for this date (handle per-broyeur dicts)
                    date_prod = 0
                    for entry in daily_data[date_str].values():
                        tp = entry.get("production", {}).get("total_production", {})
                        if isinstance(tp, (int, float)):
                            if tp > 0:
                                date_prod += tp
                        elif isinstance(tp, dict):
                            for pk, pv in tp.items():
                                if pk in _FAKE_PROD:
                                    continue
                                if isinstance(pv, dict):
                                    # Prefer Mills (pre-computed total), else sum A+B
                                    if "Mills" in pv and isinstance(pv["Mills"], (int, float)) and pv["Mills"] > 0:
                                        date_prod += pv["Mills"]
                                    elif "total" in pv and isinstance(pv["total"], (int, float)) and pv["total"] > 0:
                                        date_prod += pv["total"]
                                    else:
                                        for bk in ["A", "B"]:
                                            bv = pv.get(bk)
                                            if isinstance(bv, (int, float)) and bv > 0:
                                                date_prod += bv
                                elif isinstance(pv, (int, float)) and pv > 0:
                                    date_prod += pv
                    prod_ytd_sum += date_prod
                    if month_key == current_month:
                        prod_mtd_sum += date_prod
                
                deltas = []
                if cmd_mtd_sum > 0:
                    mtd_delta_t = prod_mtd_sum - cmd_mtd_sum
                    mtd_pct = (mtd_delta_t / cmd_mtd_sum) * 100
                    deltas.append(f"MTD: {mtd_delta_t:+.0f}t ({mtd_pct:+.0f}%)")
                elif current_month and current_month >= "2026-03":
                    deltas.append(f"MTD: 0t (0%)")
                if cmd_ytd_sum > 0:
                    ytd_delta_t = prod_ytd_sum - cmd_ytd_sum
                    ytd_pct = (ytd_delta_t / cmd_ytd_sum) * 100
                    deltas.append(f"YTD: {ytd_delta_t:+.0f}t ({ytd_pct:+.0f}%)")
                elif current_month and current_month >= "2026-03":
                    deltas.append(f"YTD: 0t (0%)")
                
                title = "Production Totale par Site"
                if deltas:
                    title += f" | {' | '.join(deltas)}"
                
                fig = px.bar(prod_total, x="date", y="value", color="dex", title=title, labels={"value": "Production (t)", "date": "Date", "dex": "Site"}, template="plotly_white", height=350)
                fig.update_layout(barmode="stack", legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
                
                # Add cibles (commandes) as target line
                cibles_data = []
                for date_str, dex_data in daily_data.items():
                    for entry in dex_data.values():
                        cibles = entry.get("cibles", {})
                        if cibles and "commandes_journalieres_t" in cibles:
                            cibles_data.append({
                                "date": pd.to_datetime(date_str.replace("_S2", "")),
                                "cible": cibles["commandes_journalieres_t"]
                            })
                            break
                if cibles_data:
                    cibles_df = pd.DataFrame(cibles_data).dropna()
                    if not cibles_df.empty:
                        cibles_df = cibles_df.sort_values("date")
                        fig.add_trace(go.Scatter(
                            x=cibles_df["date"], y=cibles_df["cible"],
                            mode="lines+markers", name="Cible (Commandes)",
                            line=dict(color="#FF4444", width=2, dash="dash"),
                            marker=dict(color="#FF4444", size=6, symbol="diamond")
                        ))
                
                st.plotly_chart(fig, use_container_width=True, key="chart_prod_tot_bar", config={"displayModeBar": True})

        # --- Matières Premières (consommées par produit) — STACKED BAR ---
        mp_df = df[df["metric"] == "MatieresPremieres"].copy()
        if not mp_df.empty:
            mp_df = mp_df[~mp_df["product"].isin(["TOTAL MATIERES", "Mills", "Mill_1", "Mill_2", "total", "Total"])].copy()
            if not mp_df.empty:
                st.markdown("<div style='color: #5B6770; font-weight: 600; font-size: 0.85rem; margin-top: 10px;'>🪨 Matières Premières Consommées (t)</div>", unsafe_allow_html=True)
                c1, c2 = st.columns(2)
                with c1:
                    mp_d1 = mp_df[mp_df["dex"] == "DEX 1"].copy()
                    if not mp_d1.empty:
                        mp_d1_agg = mp_d1.groupby(["date", "materiau"], as_index=False)["value"].sum()
                        fig = px.bar(mp_d1_agg, x="date", y="value", color="materiau",
                            title="Matières Premières Consommées — DEX 1",
                            labels={"value": "Quantité (t)", "date": "Date", "materiau": "Matière"},
                            template="plotly_white", height=400)
                        fig.update_layout(barmode="stack", legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
                        st.plotly_chart(fig, use_container_width=True, key="chart_mp_dex1_bar", config={"displayModeBar": True})
                with c2:
                    mp_d2 = mp_df[mp_df["dex"] == "DEX 2"].copy()
                    if not mp_d2.empty:
                        mp_d2_agg = mp_d2.groupby(["date", "materiau"], as_index=False)["value"].sum()
                        fig = px.bar(mp_d2_agg, x="date", y="value", color="materiau",
                            title="Matières Premières Consommées — DEX 2",
                            labels={"value": "Quantité (t)", "date": "Date", "materiau": "Matière"},
                            template="plotly_white", height=400)
                        fig.update_layout(barmode="stack", legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
                        st.plotly_chart(fig, use_container_width=True, key="chart_mp_dex2_bar", config={"displayModeBar": True})

        # --- Adjuvants par Produit (L / tonne de ciment) ---
        # Build adjuvant cibles lookup from Excel
        adj_cibles_lookup = {}
        adj_cibles_raw = {}
        for date_str, dex_data in daily_data.items():
            for dex_name, entry in dex_data.items():
                cibles = entry.get("cibles", {})
                prod = entry.get("production", {}).get("total_production", {})
                for adj_key in ["adj_sika", "adj_chryso", "adj_biolatex"]:
                    if adj_key not in cibles:
                        continue
                    adj_cible = cibles[adj_key]
                    if not isinstance(adj_cible, dict):
                        continue
                    for prod_name_c, cible_qty in adj_cible.items():
                        if not isinstance(cible_qty, (int, float)) or cible_qty <= 0:
                            continue
                        # Handle both dict and float total_production
                        if isinstance(prod, dict):
                            prod_qty = prod.get(prod_name_c, 0)
                        else:
                            prod_qty = prod if prod_name_c.lower() in ("total", "mix") else 0
                        if isinstance(prod_qty, (int, float)) and prod_qty > 0:
                            cible_l_per_t = cible_qty / prod_qty
                            if 0.1 <= cible_l_per_t <= 2.0:
                                key = (dex_name, prod_name_c)
                                if key not in adj_cibles_raw:
                                    adj_cibles_raw[key] = []
                                adj_cibles_raw[key].append(cible_l_per_t)
        for (dex_name, prod_name_c), vals in adj_cibles_raw.items():
            if vals:
                adj_cibles_lookup[(dex_name, prod_name_c)] = sum(vals) / len(vals)

        # Use ACTUAL per-broyeur adjuvant data from Excel (Adjuvant_Broyeur metric)
        adj_broyeur_df = df[df["metric"] == "Adjuvant_Broyeur"].copy()
        if not adj_broyeur_df.empty:
            st.markdown("<div style='color: #5B6770; font-weight: 600; font-size: 0.85rem; margin-top: 10px;'>🧪 Adjuvants par Produit et Broyeur (L / t)</div>", unsafe_allow_html=True)
            # Compute L/tonne using ACTUAL per-broyeur production from Excel
            adj_broyeur_l_per_t = []
            for _, brow in adj_broyeur_df.iterrows():
                date_f = brow["date"]
                dex_f = brow["dex"]
                prod_f = brow["product"]
                broy_f = brow.get("broyeur", "")
                adj_type = brow.get("adj_type", "")
                val = brow["value"]
                # Get actual per-broyeur production from daily_data
                prod_qty = None
                date_str_f = date_f.strftime("%Y-%m-%d") if hasattr(date_f, 'strftime') else str(date_f)
                if date_str_f in daily_data and dex_f in daily_data[date_str_f]:
                    tp = daily_data[date_str_f][dex_f].get("production", {}).get("total_production", {})
                    if isinstance(tp, dict):
                        prod_val = tp.get(prod_f)
                    elif isinstance(tp, (int, float)) and tp > 0:
                        prod_val = tp
                    else:
                        prod_val = None
                    if isinstance(prod_val, dict) and broy_f in prod_val:
                        # Actual per-broyeur production: {A: 1507, B: 1484}
                        prod_qty = prod_val[broy_f]
                    elif isinstance(prod_val, (int, float)) and prod_val > 0:
                        # Scalar production (from PDF): use FULL production
                        # The adjuvant qty is for this broyeur; production is total for the product
                        # Never use production / 2 - use total production as-is
                        prod_qty = prod_val
                if prod_qty and prod_qty > 0:
                    l_per_t = val / prod_qty
                    if 0 < l_per_t <= 2.0:
                        adj_broyeur_l_per_t.append({
                            "date": date_f, "dex": dex_f, "product": prod_f,
                            "broyeur": broy_f, "adj_type": adj_type,
                            "value": round(l_per_t, 4)
                        })
            if adj_broyeur_l_per_t:
                adj_b_df = pd.DataFrame(adj_broyeur_l_per_t)
                # Render CPJ 32.5 and CPJ 42.5 DEX 1 with ACTUAL broyeur data
                for prod_name in ["CPJ 32.5", "CPJ 42.5"]:
                    df_prod = adj_b_df[(adj_b_df["product"] == prod_name) & (adj_b_df["dex"] == "DEX 1")].copy()
                    if df_prod.empty or len(df_prod) <= 1:
                        continue
                    # Sum all adjuvant types per broyeur
                    df_broyeur = df_prod.groupby(["date", "broyeur"], as_index=False)["value"].sum()
                    if df_broyeur.empty or len(df_broyeur) <= 1:
                        continue
                    fig = px.line(df_broyeur, x="date", y="value", color="broyeur",
                                  title=f"{prod_name} — DEX 1 Adjuvant par Broyeur (L / tonne)",
                                  labels={"value": "L / tonne", "date": "Date", "broyeur": "Broyeur"},
                                  template="plotly_white", height=280,
                                  color_discrete_map={"A": "#1E4D8F", "B": "#F58220"})
                    fig.update_traces(mode="lines+markers")
                    # Add Excel cible
                    cible_key = ("DEX 1", prod_name)
                    if cible_key in adj_cibles_lookup:
                        avg_cible = adj_cibles_lookup[cible_key]
                        fig.add_hline(y=avg_cible, line_dash="dash", line_color="#10b981",
                                      annotation_text=f"Cible Excel: {avg_cible:.2f} L/t", annotation_position="top right")
                    fig.update_layout(xaxis=dict(tickformat="%d %b"), margin=dict(t=40),
                                      legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1))
                    st.plotly_chart(fig, use_container_width=True, key=f"chart_adj_broyeur_{prod_name.replace(' ','_').replace('.','_')}_d1", config={"displayModeBar": True})

        # Fallback: use total adjuvant data for DEX 2 and other products
        adj_df = df[df["metric"] == "Adjuvant"].copy()
        if not adj_df.empty:
            st.markdown("<div style='color: #5B6770; font-weight: 600; font-size: 0.85rem; margin-top: 10px;'>🧪 Adjuvants par Produit (L / t)</div>", unsafe_allow_html=True)
            adj_site = adj_df.groupby(["date", "dex"], as_index=False)["value"].sum().rename(columns={"value": "adj_total"})
            prod_for_adj = df[df["metric"] == "Production"].copy()
            prod_for_adj = prod_for_adj[~prod_for_adj["product"].isin(["Total", "Mix", "CHF", "TOTAL MATIERES", "Mills"])].copy()
            if not prod_for_adj.empty:
                adj_per_prod = []
                for _, arow in adj_site.iterrows():
                    date_f = arow["date"]
                    dex_f = arow["dex"]
                    adj_total = arow["adj_total"]
                    prods = prod_for_adj[(prod_for_adj["date"] == date_f) & (prod_for_adj["dex"] == dex_f)]
                    prod_total = prods["value"].sum()
                    if prod_total > 0:
                        for _, prow in prods.iterrows():
                            share = prow["value"] / prod_total
                            l_per_tonne = round(adj_total * share / prow["value"], 4) if prow["value"] > 0 else 0
                            if 0 < l_per_tonne <= 2.0:
                                adj_per_prod.append({"date": date_f, "dex": dex_f, "product": prow["product"], "value": l_per_tonne})
                if adj_per_prod:
                    adj_all_df = pd.DataFrame(adj_per_prod)
                    adj_all_df = adj_all_df[~adj_all_df["product"].isin({"CPA 42.5", "_BY_BROYEUR", "TOTAL MATIERES"})].copy()
                    # DEX 2 lines
                    for prod_name in ["CPJ 32.5", "CPJ 42.5"]:
                        df_d2 = adj_all_df[(adj_all_df["product"] == prod_name) & (adj_all_df["dex"] == "DEX 2")].copy()
                        if not df_d2.empty and len(df_d2) > 1:
                            fig = px.line(df_d2, x="date", y="value",
                                          title=f"{prod_name} — DEX 2 (L / tonne)",
                                          labels={"value": "L / tonne", "date": "Date"},
                                          template="plotly_white", height=280)
                            fig.update_traces(mode="lines+markers", line=dict(color="#10b981"))
                            cible_key = ("DEX 2", prod_name)
                            if cible_key in adj_cibles_lookup:
                                avg_cible = adj_cibles_lookup[cible_key]
                                fig.add_hline(y=avg_cible, line_dash="dash", line_color="#FF4444",
                                              annotation_text=f"Cible Excel: {avg_cible:.2f} L/t", annotation_position="top right")
                            fig.update_layout(xaxis=dict(tickformat="%d %b"), margin=dict(t=40))
                            st.plotly_chart(fig, use_container_width=True, key=f"chart_adj_d2_{prod_name.replace(' ','_').replace('.','_')}", config={"displayModeBar": True})
                    # Other products combined DEX (exclude _total variants)
                    adj_other = adj_all_df[~adj_all_df["product"].isin(["CPJ 32.5", "CPJ 42.5"])].copy()
                    adj_other = adj_other[~adj_other["product"].str.contains("_total|_total$", case=False, na=False)].copy()
                    for prod_name in sorted(adj_other["product"].unique()):
                        df_p = adj_other[adj_other["product"] == prod_name].copy()
                        if not df_p.empty and len(df_p) > 1:
                            fig = px.line(df_p, x="date", y="value", color="dex",
                                          title=f"{prod_name} — Adjuvant (L / tonne)",
                                          labels={"value": "L / tonne", "date": "Date", "dex": "Site"},
                                          template="plotly_white", height=280)
                            fig.update_traces(mode="lines+markers")
                            for dex_n in ["DEX 1", "DEX 2"]:
                                cible_key = (dex_n, prod_name)
                                if cible_key in adj_cibles_lookup:
                                    avg_cible = adj_cibles_lookup[cible_key]
                                    color = "#1E4D8F" if dex_n == "DEX 1" else "#F58220"
                                    fig.add_hline(y=avg_cible, line_dash="dash", line_color=color,
                                                  annotation_text=f"Cible {dex_n}: {avg_cible:.2f} L/t", annotation_position="top right")
                            fig.update_layout(legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1, font=dict(size=10)), xaxis=dict(tickformat="%d %b"), margin=dict(t=40))
                            st.plotly_chart(fig, use_container_width=True, key=f"chart_adjprod_{prod_name.replace(' ','_').replace('.','_')}_line", config={"displayModeBar": True})

        # --- Temps de Broyage (Mills) ---
        tps_df = df[df["metric"] == "TempsBroyage"].copy()
        if not tps_df.empty:
            tps_by_prod = tps_df[~tps_df["product"].isin(["Total", "Mix", "CHF", "TOTAL MATIERES", "Mills", "Mill_1", "Mill_2"])].copy()
            if not tps_by_prod.empty:
                c1, c2 = st.columns(2)
                with c1:
                    tps_d1 = tps_by_prod[tps_by_prod["dex"] == "DEX 1"]
                    if not tps_d1.empty:
                        fig = px.bar(tps_d1, x="date", y="value", color="product", title="Temps de Broyage par Produit — DEX 1", labels={"value": "Temps (h)", "date": "Date", "product": "Produit"}, template="plotly_white", height=350)
                        fig.update_layout(legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"), yaxis=dict(range=[0, 24]))
                        st.plotly_chart(fig, use_container_width=True, key="chart_tps_dex1_bar", config={"displayModeBar": True})
                with c2:
                    tps_d2 = tps_by_prod[tps_by_prod["dex"] == "DEX 2"]
                    if not tps_d2.empty:
                        fig = px.bar(tps_d2, x="date", y="value", color="product", barmode="group", title="Temps de Broyage par Produit — DEX 2", labels={"value": "Temps (h)", "date": "Date", "product": "Produit"}, template="plotly_white", height=350)
                        fig.update_layout(legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"), yaxis=dict(range=[0, 24]))
                        st.plotly_chart(fig, use_container_width=True, key="chart_tps_dex2_bar", config={"displayModeBar": True})

            # --- Temps de Broyage Total par Site (total_matieres) ---
            tps_total = tps_df[tps_df["product"].isin(["Total", "Mix"])].copy()
            if not tps_total.empty:
                fig = px.bar(tps_total, x="date", y="value", color="dex", title="Temps de Broyage Total par Site (Total Matières)", labels={"value": "Temps (h)", "date": "Date", "dex": "Site"}, template="plotly_white", height=300)
                fig.update_layout(barmode="stack", legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
                st.plotly_chart(fig, use_container_width=True, key="chart_tps_tot_bar", config={"displayModeBar": True})

    # ============================================================
    # --- EXPEDITION ---
    # ============================================================
    st.html("<div class=\'section-title-light\'>🚛 Expédition (t)</div>")
    with st.expander("📊 Voir les graphiques détaillés", expanded=False):
        exp_df = df[df["metric"] == "Expedition"].copy()
        if not exp_df.empty:
            exp_by_prod = exp_df[~exp_df["product"].isin(["Total"])].copy()
            if not exp_by_prod.empty and "mode" in exp_by_prod.columns:
                exp_pivot = exp_by_prod.groupby(["date", "dex", "product"])["value"].sum().reset_index()
                fig = px.bar(exp_pivot, x="date", y="value", color="product", facet_col="dex", title="Expédition par Produit & Site — Stacked Bar", labels={"value": "Expédition (t)", "date": "Date", "product": "Produit", "dex": "Site"}, template="plotly_white", height=400)
                fig.update_layout(barmode="stack", legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
                st.plotly_chart(fig, use_container_width=True, key="chart_exp_prod_bar", config={"displayModeBar": True})

            exp_total = exp_df[exp_df["product"].isin(["Total"])].copy()
            if not exp_total.empty:
                fig = px.bar(exp_total, x="date", y="value", color="dex", title="Expédition Totale par Site — Stacked Bar", labels={"value": "Expédition (t)", "date": "Date", "dex": "Site"}, template="plotly_white", height=350)
                fig.update_layout(barmode="stack", legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
                
                # Add cibles (commandes) as target line + compute MTD/YTD delta
                # Delta = (expedition - commandes) for dates where BOTH exist, from March 10
                cibles_data = []
                cmd_mtd_sum = 0
                exp_mtd_sum = 0
                cmd_ytd_sum = 0
                exp_ytd_sum = 0
                first_cmd_date = "2026-03-10"
                current_month = None
                for date_str in sorted(daily_data.keys()):
                    if date_str < first_cmd_date:
                        continue
                    dt = pd.to_datetime(date_str.replace("_S2", ""))
                    month_key = f"{dt.year}-{dt.month:02d}"
                    if current_month is None:
                        current_month = month_key
                    
                    # Check if this date has commandes data
                    has_cmd = False
                    cmd_val = 0
                    for entry in daily_data[date_str].values():
                        cibles = entry.get("cibles", {})
                        if cibles and "commandes_journalieres_t" in cibles:
                            v = cibles["commandes_journalieres_t"]
                            if isinstance(v, (int, float)) and v > 0:
                                has_cmd = True
                                cmd_val = v
                                cibles_data.append({"date": dt, "cible": cmd_val})
                                break
                    
                    if not has_cmd:
                        continue  # Skip dates without commandes
                    
                    # Sum commandes
                    cmd_ytd_sum += cmd_val
                    if month_key == current_month:
                        cmd_mtd_sum += cmd_val
                    
                    # Sum expedition for this date
                    date_exp = 0
                    for entry in daily_data[date_str].values():
                        exp = entry.get("expedition", {})
                        if isinstance(exp, dict):
                            tj = exp.get("total_jour", 0)
                            if isinstance(tj, (int, float)) and tj > 0:
                                date_exp += tj
                            # Also check whatsapp
                            wt = exp.get("whatsapp_total", 0)
                            if isinstance(wt, (int, float)) and wt > 0 and date_exp == 0:
                                date_exp = wt
                    exp_ytd_sum += date_exp
                    if month_key == current_month:
                        exp_mtd_sum += date_exp
                
                # MTD/YTD delta annotation: show tonnes and %
                deltas = []
                if cmd_mtd_sum > 0:
                    mtd_delta_t = exp_mtd_sum - cmd_mtd_sum
                    mtd_pct = (mtd_delta_t / cmd_mtd_sum) * 100
                    deltas.append(f"MTD: {mtd_delta_t:+.0f}t ({mtd_pct:+.0f}%)")
                elif current_month and current_month >= "2026-03":
                    deltas.append(f"MTD: 0t (0%)")
                if cmd_ytd_sum > 0:
                    ytd_delta_t = exp_ytd_sum - cmd_ytd_sum
                    ytd_pct = (ytd_delta_t / cmd_ytd_sum) * 100
                    deltas.append(f"YTD: {ytd_delta_t:+.0f}t ({ytd_pct:+.0f}%)")
                elif current_month and current_month >= "2026-03":
                    deltas.append(f"YTD: 0t (0%)")
                
                if cibles_data:
                    cibles_df = pd.DataFrame(cibles_data).dropna()
                    if not cibles_df.empty:
                        cibles_df = cibles_df.sort_values("date")
                        fig.add_trace(go.Scatter(
                            x=cibles_df["date"], y=cibles_df["cible"],
                            mode="lines+markers", name="Cible (Commandes)",
                            line=dict(color="#FF4444", width=2, dash="dash"),
                            marker=dict(color="#FF4444", size=6, symbol="diamond")
                        ))
                        title_extra = " — avec Cible (Commandes)"
                        if deltas:
                            title_extra += f" | {' | '.join(deltas)}"
                        fig.update_layout(title=f"Expédition Totale par Site{title_extra}")
                
                st.plotly_chart(fig, use_container_width=True, key="chart_exp_tot_bar", config={"displayModeBar": True})

            exp_by_mode = exp_df[~exp_df["product"].isin(["Total"])].copy()
            if not exp_by_mode.empty and "mode" in exp_by_mode.columns:
                mode_agg = exp_by_mode.groupby(["date", "dex", "mode"])["value"].sum().reset_index()
                if not mode_agg.empty:
                    fig_mode = px.bar(mode_agg, x="date", y="value", color="mode", facet_col="dex", title="Expédition par Mode (Sacs / Vrac / Big Bag) — Stacked Bar", labels={"value": "Expédition (t)", "date": "Date", "mode": "Mode", "dex": "Site"}, template="plotly_white", height=400)
                    fig_mode.update_layout(barmode="stack", legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
                    st.plotly_chart(fig_mode, use_container_width=True, key="chart_exp_mode_bar", config={"displayModeBar": True})

    # ============================================================
    # --- FLUX MATIERES PREMIERES ---
    # ============================================================
    st.html("<div class=\'section-title-light\'>📦 Flux Matières Premières (t)</div>")
    with st.expander("📊 Voir les graphiques détaillés", expanded=False):
        stock_df = df[df["metric"] == "StockMP"].copy()
        recu_df = df[df["metric"] == "RecuMP"].copy()
        conso_df = df[df["metric"] == "ConsoMP"].copy()
        auto_df = df[df["metric"] == "AutonomieMP"].copy()

        # --- Graphiques Flux MP (style Flux de Trésorerie) ---
        # Barres : Reçu (+) et Stock (+) empilés, Consommation (-) en dessous de zéro
        # Ligne : Autonomie (jours) sur axe secondaire
        FLUX_MP_MATERIALS = ["clinker", "gypse", "granite"]
        for site_name in ["DEX 1", "DEX 2"]:
            site_charts_rendered = False
            for materiau in FLUX_MP_MATERIALS:
                def _mp_subset(dfm):
                    if dfm.empty or "materiau" not in dfm.columns:
                        return pd.DataFrame()
                    return dfm[(dfm["materiau"].astype(str).str.lower() == materiau) & (dfm["dex"] == site_name)].copy()

                stock_m = _mp_subset(stock_df)
                recu_m = _mp_subset(recu_df)
                conso_m = _mp_subset(conso_df)
                auto_m = _mp_subset(auto_df)

                if stock_m.empty and recu_m.empty and conso_m.empty and auto_m.empty:
                    continue

                # Normaliser les dates (retirer suffixe éventuel "_S2")
                for _dfm in (stock_m, recu_m, conso_m, auto_m):
                    if not _dfm.empty:
                        _dfm["date"] = _dfm["date"].astype(str).str.replace("_S2", "", regex=False)

                # Agréger par date : somme pour les flux (reçu/consommation),
                # dernière valeur pour les niveaux (stock/autonomie)
                stock_s = stock_m.groupby("date")["value"].last() if not stock_m.empty else pd.Series(dtype=float)
                recu_s = recu_m.groupby("date")["value"].sum() if not recu_m.empty else pd.Series(dtype=float)
                conso_s = conso_m.groupby("date")["value"].sum() if not conso_m.empty else pd.Series(dtype=float)
                auto_s = auto_m.groupby("date")["value"].last() if not auto_m.empty else pd.Series(dtype=float)

                all_dates = sorted(set(stock_s.index) | set(recu_s.index) | set(conso_s.index) | set(auto_s.index))
                if not all_dates:
                    continue

                stock_vals = [float(stock_s.get(d, 0)) for d in all_dates]
                recu_vals = [float(recu_s.get(d, 0)) for d in all_dates]
                conso_vals = [-float(conso_s.get(d, 0)) for d in all_dates]  # négatif
                auto_vals = [float(auto_s[d]) if d in auto_s.index else None for d in all_dates]

                fig_mp = go.Figure()
                # Barres positives : Reçu (+) puis Stock (+)
                fig_mp.add_trace(go.Bar(
                    name="Reçu (t)", x=all_dates, y=recu_vals,
                    marker_color="#10b981", marker_line_width=0,
                ))
                fig_mp.add_trace(go.Bar(
                    name="Stock (t)", x=all_dates, y=stock_vals,
                    marker_color="#3b82f6", marker_line_width=0,
                ))
                # Barre négative : Consommation (-)
                fig_mp.add_trace(go.Bar(
                    name="Consommation (t)", x=all_dates, y=conso_vals,
                    marker_color="#ef4444", marker_line_width=0,
                ))
                # Ligne Autonomie sur axe secondaire
                fig_mp.add_trace(go.Scatter(
                    name="Autonomie (j)", x=all_dates, y=auto_vals,
                    mode="lines+markers",
                    line=dict(color="#F58220", width=3),
                    marker=dict(size=7, color="#F58220"),
                    yaxis="y2", connectgaps=False,
                ))

                fig_mp.update_layout(
                    barmode="relative",
                    title=f"Flux {materiau.capitalize()} — {site_name} (t)",
                    height=420,
                    yaxis=dict(
                        title="Tonnes",
                        zeroline=True, zerolinecolor="#5B6770", zerolinewidth=1,
                        gridcolor="rgba(91,103,112,0.15)",
                    ),
                    yaxis2=dict(
                        title="Autonomie (j)",
                        overlaying="y", side="right", showgrid=False,
                    ),
                    xaxis=dict(title="Date", gridcolor="rgba(91,103,112,0.15)"),
                    legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="center", x=0.5, font=dict(size=11)),
                    plot_bgcolor="#0B1F3A", paper_bgcolor="#0B1F3A",
                    font=dict(color="#E6E9ED"),
                    hovermode="x unified",
                )
                st.plotly_chart(fig_mp, use_container_width=True, key=f"chart_flux_mp_{site_name.replace(' ', '')}_{materiau}", config={"displayModeBar": True})
                site_charts_rendered = True
            if not site_charts_rendered:
                st.info(f"Aucun graphique flux MP (clinker/gypse/granite) disponible pour {site_name}.")

    # ============================================================
    # --- CES + Débit vs CES ---
    # ============================================================
    st.html("<div class=\'section-title-light\'>⚡ CES (kWh/t) & Débit vs CES</div>")
    with st.expander("📊 Voir les graphiques détaillés", expanded=False):
        ces_df = df[df["metric"] == "CES"].copy()
        if not ces_df.empty:
            # CES par Broyeur et Site: DEX 1 split into Broyeur A/B (scatter), DEX 2 single line
            ces_site_df = df[df["metric"] == "CES_Site"].copy()
            ces_broyeur_df = df[df["metric"] == "CES_Broyeur"].copy()
            if not ces_site_df.empty or not ces_broyeur_df.empty:
                plot_rows = []
                # DEX 2: use CES_Site (single broyeur)
                for _, row in ces_site_df.iterrows():
                    if row["dex"] == "DEX 2":
                        plot_rows.append({"date": row["date"], "series": "DEX 2", "value": row["value"]})
                # DEX 1: use CES_Broyeur (per broyeur only — no DEX 1 aggregate)
                for _, row in ces_broyeur_df.iterrows():
                    if row["dex"] == "DEX 1":
                        plot_rows.append({"date": row["date"], "series": f"DEX 1 - Broyeur {row['broyeur']}", "value": row["value"]})
                if plot_rows:
                    plot_df = pd.DataFrame(plot_rows)
                    fig = px.scatter(plot_df, x="date", y="value", color="series", title="CES par Broyeur et Site", labels={"value": "CES (kWh/t)", "date": "Date", "series": "Série"}, template="plotly_white", height=350)
                    fig.update_traces(marker=dict(size=7, opacity=0.85))
                    fig.update_layout(legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
                    event_ces_tot = st.plotly_chart(fig, use_container_width=True, key="chart_ces_tot_line", config={"displayModeBar": True})
            else:
                # Fallback: compute validated CES_Site from per-product weighted average
                _FAKE_PROD = {"Total", "Mix", "CHF", "TOTAL MATIERES", "Mills", "Mill_1", "Mill_2", "_by_broyeur", "CPA 42.5", "A", "B"}
                ces_site_rows = []
                for date_str, dex_data in daily_data.items():
                    for dex_name, entry in dex_data.items():
                        prod = entry.get("production", {})
                        ces = prod.get("ces_mills", {})
                        tp = prod.get("total_production", {})
                        weighted_sum = 0.0
                        prod_weighted = 0.0
                        if isinstance(tp, dict):
                            for pk, pv in tp.items():
                                if pk in _FAKE_PROD:
                                    continue
                                if isinstance(pv, dict):
                                    pv = pv.get("Mills", 0) or 0
                                if isinstance(pv, (int, float)) and pv > 0:
                                    pk_ces = ces.get(pk, {}).get("Mills") if isinstance(ces.get(pk), dict) else None
                                    if isinstance(pk_ces, (int, float)) and pk_ces is not None and 10 <= pk_ces <= 90:
                                        weighted_sum += pk_ces * pv
                                        prod_weighted += pv
                        elif isinstance(tp, (int, float)) and tp > 0:
                            # Simple total, use total CES if available
                            ces_total = ces.get("Mills") if isinstance(ces, dict) else ces
                            if isinstance(ces_total, (int, float)) and ces_total is not None and 10 <= ces_total <= 90:
                                weighted_sum = ces_total * tp
                                prod_weighted = tp
                        if prod_weighted > 0:
                            wa = weighted_sum / prod_weighted
                            if 10 <= wa <= 90:
                                ces_site_rows.append({"date": pd.to_datetime(date_str.replace("_S2", "")), "dex": dex_name, "value": round(wa, 2)})
                if ces_site_rows:
                    ces_site_df = pd.DataFrame(ces_site_rows)
                    if not ces_site_df.empty:
                        fig = px.line(ces_site_df, x="date", y="value", color="dex", title="CES Totale par Site", labels={"value": "CES (kWh/t)", "date": "Date", "dex": "Site"}, template="plotly_white", height=350)
                        fig.update_traces(line=dict(width=3), marker=dict(size=6))
                        fig.update_layout(legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
                        event_ces_tot = st.plotly_chart(fig, use_container_width=True, key="chart_ces_tot_line", config={"displayModeBar": True})

            ces_prod = ces_df[~ces_df["product"].isin(["Total", "Mix", "CHF", "TOTAL MATIERES", "Mills", "Mill_1", "Mill_2", "_by_broyeur", "CPA 42.5", "A", "B"])].copy()
            if not ces_prod.empty:
                ces_prod = _split_cpj42(ces_prod)
                # Split into 2 side-by-side graphs for DEX 1 and DEX 2
                c1, c2 = st.columns(2)
                with c1:
                    ces_d1 = ces_prod[ces_prod["dex"] == "DEX 1"]
                    if not ces_d1.empty:
                        fig = px.scatter(ces_d1, x="date", y="value", color="product", title="CES par Produit — DEX 1", labels={"value": "CES (kWh/t)", "date": "Date", "product": "Produit"}, template="plotly_white", height=400)
                        fig.update_traces(marker=dict(size=7, opacity=0.85))
                        fig.update_layout(legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
                        st.plotly_chart(fig, use_container_width=True, key="chart_ces_prod_d1_scatter", config={"displayModeBar": True})
                with c2:
                    ces_d2 = ces_prod[ces_prod["dex"] == "DEX 2"]
                    if not ces_d2.empty:
                        fig = px.scatter(ces_d2, x="date", y="value", color="product", title="CES par Produit — DEX 2", labels={"value": "CES (kWh/t)", "date": "Date", "product": "Produit"}, template="plotly_white", height=400)
                        fig.update_traces(marker=dict(size=7, opacity=0.85))
                        fig.update_layout(legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
                        st.plotly_chart(fig, use_container_width=True, key="chart_ces_prod_d2_scatter", config={"displayModeBar": True})

        # --- 3 Scatter Plots: CES par Broyeur ---
        ces_broyeur = df[df["metric"] == "CES_Broyeur"].copy()
        if not ces_broyeur.empty:
            st.markdown("<div style=\'font-size: 0.85rem; color: #5B6770; margin-top: 10px;\'><b>CES par Broyeur (scatter)</b></div>", unsafe_allow_html=True)
            _render_scatter_broyeur(ces_broyeur, "CES", "CES (kWh/t)", color_a="#1E4D8F", color_b="#F58220", include_site2=True)

        # --- Débit vs CES (Scatter) ---
        debit_df = df[df["metric"] == "Debit"].copy()
        if not ces_df.empty and not debit_df.empty:
            ces_m = ces_df[~ces_df["product"].isin(["Total", "Mix", "CHF", "TOTAL MATIERES", "Mills", "Mill_1", "Mill_2"])].copy()
            deb_m = debit_df[~debit_df["product"].isin(["Total", "Mix", "CHF", "TOTAL MATIERES", "Mills", "Mill_1", "Mill_2", "_by_broyeur", "CPA 42.5", "A", "B"])].copy()
            ces_m = _split_cpj42(ces_m)
            deb_m = _split_cpj42(deb_m)
            merged = pd.merge(ces_m[["date", "dex", "product", "value"]], deb_m[["date", "dex", "product", "value"]], on=["date", "dex", "product"], suffixes=("_ces", "_debit"))
            if not merged.empty:
                c1, c2 = st.columns(2)
                with c1:
                    dex1_data = merged[merged["dex"] == "DEX 1"]
                    if not dex1_data.empty:
                        fig = px.scatter(dex1_data, x="value_debit", y="value_ces", color="product", title="Débit vs CES — DEX 1", labels={"value_debit": "Débit (t/h)", "value_ces": "CES (kWh/t)", "product": "Produit"}, template="plotly_white", height=350)
                        fig.update_layout(legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1))
                        st.plotly_chart(fig, use_container_width=True, key="chart_scatter_dex1", config={"displayModeBar": True})
                with c2:
                    dex2_data = merged[merged["dex"] == "DEX 2"]
                    if not dex2_data.empty:
                        fig = px.scatter(dex2_data, x="value_debit", y="value_ces", color="product", title="Débit vs CES — DEX 2", labels={"value_debit": "Débit (t/h)", "value_ces": "CES (kWh/t)", "product": "Produit"}, template="plotly_white", height=350)
                        fig.update_layout(legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1))
                        st.plotly_chart(fig, use_container_width=True, key="chart_scatter_dex2", config={"displayModeBar": True})

    # ============================================================
    # --- DEBIT ---
    # ============================================================
    st.html("<div class=\'section-title-light\'>🏭 Débit Broyeur (t/h)</div>")
    with st.expander("📊 Voir les graphiques détaillés", expanded=False):
        if not debit_df.empty:
            deb_prod = debit_df[~debit_df["product"].isin(["Total", "Mix", "CHF", "TOTAL MATIERES", "Mills", "Mill_1", "Mill_2", "_by_broyeur", "CPA 42.5", "A", "B"])].copy()
            if not deb_prod.empty:
                deb_prod = _split_cpj42(deb_prod)
                # Split into 2 side-by-side graphs for DEX 1 and DEX 2
                c1, c2 = st.columns(2)
                with c1:
                    deb_d1 = deb_prod[deb_prod["dex"] == "DEX 1"]
                    if not deb_d1.empty:
                        fig = px.scatter(deb_d1, x="date", y="value", color="product", title="Débit par Produit — DEX 1", labels={"value": "Débit (t/h)", "date": "Date", "product": "Produit"}, template="plotly_white", height=400)
                        fig.update_traces(marker=dict(size=7, opacity=0.85))
                        fig.update_layout(legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
                        st.plotly_chart(fig, use_container_width=True, key="chart_deb_prod_d1_scatter", config={"displayModeBar": True})
                with c2:
                    deb_d2 = deb_prod[deb_prod["dex"] == "DEX 2"]
                    if not deb_d2.empty:
                        fig = px.scatter(deb_d2, x="date", y="value", color="product", title="Débit par Produit — DEX 2", labels={"value": "Débit (t/h)", "date": "Date", "product": "Produit"}, template="plotly_white", height=400)
                        fig.update_traces(marker=dict(size=7, opacity=0.85))
                        fig.update_layout(legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
                        st.plotly_chart(fig, use_container_width=True, key="chart_deb_prod_d2_scatter", config={"displayModeBar": True})

            # Débit par Broyeur et Site: DEX 1 split into Broyeur A/B (scatter), DEX 2 single line
            deb_site_df = df[df["metric"] == "Debit_Site"].copy()
            deb_broyeur_df = df[df["metric"] == "Debit_Broyeur"].copy()
            if not deb_site_df.empty or not deb_broyeur_df.empty:
                plot_rows = []
                # DEX 2: use Debit_Site (single broyeur)
                for _, row in deb_site_df.iterrows():
                    if row["dex"] == "DEX 2":
                        plot_rows.append({"date": row["date"], "series": "DEX 2", "value": row["value"]})
                # DEX 1: use Debit_Broyeur (per broyeur only — no DEX 1 aggregate)
                for _, row in deb_broyeur_df.iterrows():
                    if row["dex"] == "DEX 1":
                        plot_rows.append({"date": row["date"], "series": f"DEX 1 - Broyeur {row['broyeur']}", "value": row["value"]})
                if plot_rows:
                    plot_df = pd.DataFrame(plot_rows)
                    fig = px.scatter(plot_df, x="date", y="value", color="series", title="Débit par Broyeur et Site", labels={"value": "Débit (t/h)", "date": "Date", "series": "Série"}, template="plotly_white", height=350)
                    fig.update_traces(marker=dict(size=7, opacity=0.85))
                    fig.update_layout(legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
                    event_deb_tot = st.plotly_chart(fig, use_container_width=True, key="chart_deb_tot_line", config={"displayModeBar": True})
            else:
                deb_total = debit_df[debit_df["product"].isin(["Total", "Mix"])].copy()
                if not deb_total.empty:
                    fig = px.scatter(deb_total, x="date", y="value", color="dex", title="Débit par Broyeur et Site", labels={"value": "Débit (t/h)", "date": "Date", "dex": "Site"}, template="plotly_white", height=350)
                    fig.update_traces(marker=dict(size=7, opacity=0.85))
                    fig.update_layout(legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
                    event_deb_tot = st.plotly_chart(fig, use_container_width=True, key="chart_deb_tot_line", config={"displayModeBar": True})

        # --- 3 Scatter Plots: Débit par Broyeur DEX 1 ---
        deb_broyeur = df[df["metric"] == "Debit_Broyeur"].copy()
        if not deb_broyeur.empty:
            st.markdown("<div style=\'font-size: 0.85rem; color: #5B6770; margin-top: 10px;\'><b>Débit par Broyeur — DEX 1 (scatter)</b></div>", unsafe_allow_html=True)
            _render_scatter_broyeur(deb_broyeur, "Débit", "Débit (t/h)", color_a="#10b981", color_b="#F58220", include_site2=False)

        # --- Débit par Broyeur DEX 2 (scatter) ---
        deb_dex2_broyeur = df[(df["metric"] == "Debit_Broyeur") & (df["dex"] == "DEX 2")].copy()
        if not deb_dex2_broyeur.empty:
            st.markdown("<div style='font-size: 0.85rem; color: #5B6770; margin-top: 10px;'><b>Débit par Broyeur — DEX 2 (scatter)</b></div>", unsafe_allow_html=True)
            fig = go.Figure()
            colors = {"CPJ 42.5": "#1E4D8F", "CPA 52.5": "#F58220"}
            for prod in ["CPJ 42.5", "CPA 52.5"]:
                df_p = deb_dex2_broyeur[deb_dex2_broyeur["product"] == prod].copy()
                if not df_p.empty:
                    fig.add_trace(go.Scatter(x=df_p["date"], y=df_p["value"], mode="markers", name=prod, marker=dict(color=colors.get(prod, "#5B6770"), size=8)))
            fig.update_layout(title="Débit par Broyeur — DEX 2", yaxis_title="Débit (t/h)", xaxis_title="Date", template="plotly_white", height=350, legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
            st.plotly_chart(fig, use_container_width=True, key="chart_debit_dex2_broyeur_scatter", config={"displayModeBar": True})

        # --- Temps de Broyage par Broyeur (stacked bar) DEX 1 ---
        tps_broyeur = df[df["metric"] == "TempsBroyage_Broyeur"].copy()
        if not tps_broyeur.empty:
            st.markdown("<div style=\'font-size: 0.85rem; color: #5B6770; margin-top: 10px;\'><b>Temps de Broyage par Broyeur — DEX 1 (grouped bar)</b></div>", unsafe_allow_html=True)
            _render_stacked_bar_broyeur(tps_broyeur, "Temps de Broyage", "Temps (h)", color_a="#8B5CF6", color_b="#F59E0B")

        # --- Temps de Broyage DEX 2: CPJ 42.5 + CPA 52.5 combined stacked ---
        tps_dex2 = df[(df["metric"] == "TempsBroyage") & (df["dex"] == "DEX 2")].copy()
        if not tps_dex2.empty:
            mill_prods = ["CPJ 42.5", "CPA 52.5"]
            has_data = any(p in tps_dex2["product"].values for p in mill_prods)
            if has_data:
                st.markdown("<div style='font-size: 0.85rem; color: #5B6770; margin-top: 10px;'><b>Temps de Broyage — DEX 2 (CPJ 42.5 + CPA 52.5)</b></div>", unsafe_allow_html=True)
                fig = go.Figure()
                colors = {"CPJ 42.5": "#1E4D8F", "CPA 52.5": "#F58220"}
                for prod in mill_prods:
                    df_p = tps_dex2[tps_dex2["product"] == prod].copy()
                    if not df_p.empty:
                        fig.add_trace(go.Bar(x=df_p["date"], y=df_p["value"], name=prod, marker_color=colors.get(prod, "#5B6770")))
                fig.update_layout(barmode="group", title="Temps de Broyage — DEX 2", yaxis_title="Temps (h)", xaxis_title="Date", template="plotly_white", height=350, legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"), yaxis=dict(range=[0, 24]))
                st.plotly_chart(fig, use_container_width=True, key="chart_tps_dex2_combined_stack", config={"displayModeBar": True})

    # ============================================================
    # --- K/C ---
    # ============================================================
    st.html("<div class=\'section-title-light\'>🔥 K/C Ratio (%)</div>")
    with st.expander("📊 Voir les graphiques détaillés", expanded=False):
        kc_df = df[df["metric"] == "KC"].copy()
        if not kc_df.empty:
            kc_df_chart = kc_df.copy()
            shared_kc = [r"CPJ\s*42\.5", r"CPA\s*52\.5"]
            for pat in shared_kc:
                mask = (
                    kc_df_chart["product"].str.contains(pat, case=False, na=False, regex=True) &
                    ~kc_df_chart["product"].str.contains("Site|DEX", case=False, na=False)
                )
                kc_df_chart.loc[mask, "product"] = kc_df_chart.loc[mask, "product"] + " (" + kc_df_chart.loc[mask, "dex"] + ")"
            fig = px.line(kc_df_chart, x="date", y="value", color="product", title="K/C par Produit & Site (CPA 52.5 DEX 1 & DEX 2 inclus)", labels={"value": "K/C (%)", "date": "Date", "product": "Produit"}, template="plotly_white", height=450)
            fig.update_traces(line=dict(width=2.5), marker=dict(size=6))
            fig.update_layout(legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"), yaxis=dict(title="K/C (%)", range=[0, 100]))
            event_kc = st.plotly_chart(fig, use_container_width=True, key="chart_kc_line", config={"displayModeBar": True})

    # ============================================================
    # --- FUEL ---
    # ============================================================
    st.html("<div class=\'section-title-light\'>⛽ Consommation Combustible (L/t)</div>")
    with st.expander("📊 Voir les graphiques détaillés", expanded=False):
        fuel_df = df[df["metric"] == "Fuel"].copy()
        if not fuel_df.empty:
            fuel_prod = fuel_df[~fuel_df["product"].isin(["Total", "Mix", "CHF", "TOTAL MATIERES", "Mills", "Mill_1", "Mill_2", "_by_broyeur", "CPA 42.5", "A", "B"])].copy()
            if not fuel_prod.empty:
                fuel_prod = _split_cpj42(fuel_prod)
                fig = px.scatter(fuel_prod, x="date", y="value", color="product", title="Fuel par Produit (CPJ 42.5 séparé DEX 1 / DEX 2)", labels={"value": "Fuel (L/t)", "date": "Date", "product": "Produit"}, template="plotly_white", height=400)
                fig.update_traces(marker=dict(size=7, opacity=0.85))
                fig.update_layout(legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
                event_fuel_prod = st.plotly_chart(fig, use_container_width=True, key="chart_fuel_prod_scatter", config={"displayModeBar": True})

            # Fuel par Broyeur et Site: DEX 1 split into Broyeur A/B (scatter), DEX 2 single line
            fuel_site_df = df[df["metric"] == "Fuel_Site"].copy()
            fuel_broyeur_df = df[df["metric"] == "Fuel_Broyeur"].copy()
            if not fuel_site_df.empty or not fuel_broyeur_df.empty:
                plot_rows = []
                # DEX 2: use Fuel_Site (single broyeur)
                for _, row in fuel_site_df.iterrows():
                    if row["dex"] == "DEX 2":
                        plot_rows.append({"date": row["date"], "series": "DEX 2", "value": row["value"]})
                # DEX 1: use Fuel_Broyeur (per broyeur only — no DEX 1 aggregate)
                for _, row in fuel_broyeur_df.iterrows():
                    if row["dex"] == "DEX 1":
                        plot_rows.append({"date": row["date"], "series": f"DEX 1 - Broyeur {row['broyeur']}", "value": row["value"]})
                if plot_rows:
                    plot_df = pd.DataFrame(plot_rows)
                    fig = px.scatter(plot_df, x="date", y="value", color="series", title="Fuel par Broyeur et Site", labels={"value": "Fuel (L/t)", "date": "Date", "series": "Série"}, template="plotly_white", height=350)
                    fig.update_traces(marker=dict(size=7, opacity=0.85))
                    fig.update_layout(legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
                    event_fuel_tot = st.plotly_chart(fig, use_container_width=True, key="chart_fuel_tot_scatter", config={"displayModeBar": True})
            else:
                fuel_total = fuel_df[fuel_df["product"].isin(["Total", "Mix"])].copy()
                if not fuel_total.empty:
                    fig = px.scatter(fuel_total, x="date", y="value", color="dex", title="Fuel par Broyeur et Site", labels={"value": "Fuel (L/t)", "date": "Date", "dex": "Site"}, template="plotly_white", height=350)
                    fig.update_traces(marker=dict(size=7, opacity=0.85))
                    fig.update_layout(legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
                    event_fuel_tot = st.plotly_chart(fig, use_container_width=True, key="chart_fuel_tot_scatter", config={"displayModeBar": True})

        # --- 3 Scatter Plots: Fuel par Broyeur DEX 1 ---
        fuel_broyeur = df[df["metric"] == "Fuel_Broyeur"].copy()
        if not fuel_broyeur.empty:
            st.markdown("<div style=\'font-size: 0.85rem; color: #5B6770; margin-top: 10px;\'><b>Fuel par Broyeur — DEX 1 (scatter)</b></div>", unsafe_allow_html=True)
            _render_scatter_broyeur(fuel_broyeur, "Fuel", "Fuel (L/t)", color_a="#EF4444", color_b="#3B82F6", include_site2=False)

        # --- Scatter Plot: Fuel par Broyeur DEX 2 (CPJ 42.5 + CPA 52.5 combined) ---
        fuel_dex2_broyeur = df[(df["metric"] == "Fuel_Broyeur") & (df["dex"] == "DEX 2")].copy()
        if not fuel_dex2_broyeur.empty:
            st.markdown("<div style='font-size: 0.85rem; color: #5B6770; margin-top: 10px;'><b>Fuel par Broyeur — DEX 2 (scatter)</b></div>", unsafe_allow_html=True)
            fig = go.Figure()
            colors = {"CPJ 42.5": "#1E4D8F", "CPA 52.5": "#F58220"}
            for prod in ["CPJ 42.5", "CPA 52.5"]:
                df_p = fuel_dex2_broyeur[fuel_dex2_broyeur["product"] == prod].copy()
                if not df_p.empty:
                    fig.add_trace(go.Scatter(x=df_p["date"], y=df_p["value"], mode="markers", name=prod, marker=dict(color=colors.get(prod, "#5B6770"), size=8)))
            fig.update_layout(title="Fuel par Broyeur — DEX 2", yaxis_title="Fuel (L/t)", xaxis_title="Date", template="plotly_white", height=350, legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1), xaxis=dict(tickformat="%d %b"))
            st.plotly_chart(fig, use_container_width=True, key="chart_fuel_dex2_broyeur_scatter", config={"displayModeBar": True})

    # ============================================================
    # --- ANALYSE AVANCÉE ---
    # ============================================================
    try:
        _render_analytics_charts(df)
    except Exception as e:
        st.error(f"Erreur Analytics: {e}")


def _render_analytics_charts(df):
    """Render advanced analytical visualizations."""
    st.html("<div class='section-title-light'>📈 Analyse Avancée</div>")
    with st.expander("📊 Voir les graphiques détaillés", expanded=False):
        # --- 1. Heatmap: Production par Jour de Semaine ---
        prod_df_an = df[df["metric"] == "Production"].copy()
        if not prod_df_an.empty:
            prod_indiv = prod_df_an[~prod_df_an["product"].isin(["Total", "Mix"])].copy()
            if not prod_indiv.empty:
                prod_indiv["jour_semaine"] = prod_indiv["date"].dt.day_name()
                prod_indiv["mois"] = prod_indiv["date"].dt.strftime("%Y-%m")
                day_map = {"Monday": "Lundi", "Tuesday": "Mardi", "Wednesday": "Mercredi",
                           "Thursday": "Jeudi", "Friday": "Vendredi", "Saturday": "Samedi", "Sunday": "Dimanche"}
                prod_indiv["jour_semaine"] = prod_indiv["jour_semaine"].map(day_map)
                day_order = ["Lundi", "Mardi", "Mercredi", "Jeudi", "Vendredi", "Samedi", "Dimanche"]
                heat_pivot = prod_indiv.groupby(["mois", "jour_semaine"])["value"].sum().unstack(fill_value=0)
                heat_pivot = heat_pivot.reindex(columns=day_order, fill_value=0)
                fig_hm = go.Figure(data=go.Heatmap(
                    z=heat_pivot.values, x=heat_pivot.columns, y=heat_pivot.index,
                    colorscale="YlOrRd", hovertemplate="%{y} %{x}<br>Production: %{z:.0f} t<extra></extra>"
                ))
                fig_hm.update_layout(
                    title="Production par Jour de Semaine et Mois (t)", template="plotly_white", height=350,
                    xaxis_title="Jour", yaxis_title="Mois"
                )
                st.plotly_chart(fig_hm, use_container_width=True, key="chart_heatmap_prod", config={"displayModeBar": True})

        # --- 2. Box Plot: Distribution par Produit ---
        if not prod_df_an.empty:
            prod_box = prod_df_an[~prod_df_an["product"].isin(["Total", "Mix", "TOTAL MATIERES"])].copy()
            if not prod_box.empty:
                fig_box = px.box(prod_box, x="product", y="value", color="dex",
                    title="Distribution de la Production par Produit et Site",
                    labels={"value": "Production (t)", "product": "Produit", "dex": "Site"},
                    template="plotly_white", height=400)
                fig_box.update_layout(legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1))
                st.plotly_chart(fig_box, use_container_width=True, key="chart_box_prod", config={"displayModeBar": True})

        # --- 3. Moving Average Trends ---
        prod_total_ma = prod_df_an[prod_df_an["product"].isin(["Total", "Mix"])].copy()
        if not prod_total_ma.empty:
            prod_total_ma = prod_total_ma.sort_values("date")
            ma7 = prod_total_ma.groupby("dex")["value"].rolling(window=7, min_periods=1).mean().reset_index(level=0, drop=True)
            ma30 = prod_total_ma.groupby("dex")["value"].rolling(window=30, min_periods=1).mean().reset_index(level=0, drop=True)
            prod_total_ma["MA7"] = ma7.values
            prod_total_ma["MA30"] = ma30.values
            fig_ma = go.Figure()
            for dex in prod_total_ma["dex"].unique():
                sub = prod_total_ma[prod_total_ma["dex"] == dex]
                fig_ma.add_trace(go.Scatter(x=sub["date"], y=sub["value"], mode="markers", name=f"{dex} (brut)", marker=dict(size=4, opacity=0.4)))
                fig_ma.add_trace(go.Scatter(x=sub["date"], y=sub["MA7"], mode="lines", name=f"{dex} MA7", line=dict(width=2)))
                fig_ma.add_trace(go.Scatter(x=sub["date"], y=sub["MA30"], mode="lines", name=f"{dex} MA30", line=dict(width=2, dash="dash")))
            fig_ma.update_layout(
                title="Production Totale — Moyennes Mobiles (7j et 30j)", template="plotly_white", height=400,
                xaxis_title="Date", yaxis_title="Production (t)",
                legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1),
                xaxis=dict(tickformat="%d %b")
            )
            st.plotly_chart(fig_ma, use_container_width=True, key="chart_ma_prod", config={"displayModeBar": True})

        # --- 4. Efficiency: CES vs Production Volume ---
        ces_eff = df[df["metric"] == "CES"].copy()
        prod_eff = df[df["metric"] == "Production"].copy()
        if not ces_eff.empty and not prod_eff.empty:
            ces_m_eff = ces_eff[~ces_eff["product"].isin(["Total", "Mix", "CHF"])].copy()
            prod_m_eff = prod_eff[~prod_eff["product"].isin(["Total", "Mix"])].copy()
            if not ces_m_eff.empty and not prod_m_eff.empty:
                merged_eff = pd.merge(ces_m_eff[["date", "dex", "product", "value"]], 
                                      prod_m_eff[["date", "dex", "product", "value"]],
                                      on=["date", "dex", "product"], suffixes=("_ces", "_prod"))
                if not merged_eff.empty:
                    fig_eff = px.scatter(merged_eff, x="value_prod", y="value_ces", color="product", facet_col="dex",
                        title="Efficacité: CES vs Volume de Production",
                        labels={"value_prod": "Production (t)", "value_ces": "CES (kWh/t)", "product": "Produit"},
                        template="plotly_white", height=400)
                    fig_eff.update_layout(legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1))
                    st.plotly_chart(fig_eff, use_container_width=True, key="chart_efficiency", config={"displayModeBar": True})


def _render_quality_charts(daily_data):
    """Render control charts for SO3, Refus 45µ, Blaine per product."""
    df = _extract_evolution_data(dict(daily_data))

    if df.empty:
        return

    df["date"] = pd.to_datetime(df["date"].str.replace("_S2", ""), errors="coerce")
    df = df.dropna(subset=["date"])

    st.html("<div class='section-title-light'>🧪 Cartes de Contrôle — SO3, Refus 45µ, Blaine</div>")
    with st.expander("📊 Voir les graphiques détaillés", expanded=False):

        for metric, label, color in [("SO3", "SO3 (%)", "#10b981"), ("Refus", "Refus 45µ (%)", "#ef4444"), ("Blaine", "Blaine (cm²/g)", "#3b82f6")]:
            sub = df[df["metric"] == metric].copy()
            if sub.empty:
                continue

            products = sub["product"].unique()
            if len(products) == 0:
                continue

            st.markdown(f"<div style='color:#1E4D8F; font-weight:700; font-size:0.95rem; margin:16px 0 8px;'>{label}</div>", unsafe_allow_html=True)

            cols = st.columns(2)
            for i, product in enumerate(products):
                prod_df = sub[sub["product"] == product].sort_values("date")
                if len(prod_df) < 2:
                    continue

                values = prod_df["value"].values
                mean = np.mean(values)
                std = np.std(values, ddof=1) if len(values) > 1 else 0
                ucl = mean + 3 * std
                lcl = mean - 3 * std

                with cols[i % 2]:
                    fig = go.Figure()

                    fig.add_trace(go.Scatter(
                        x=prod_df["date"], y=prod_df["value"],
                        mode="lines+markers",
                        name=product,
                        line=dict(color=color, width=2),
                        marker=dict(size=6)
                    ))

                    fig.add_hline(y=mean, line_dash="dash", line_color="#F58220", 
                                 annotation_text=f"μ={mean:.2f}", annotation_position="right")
                    fig.add_hline(y=ucl, line_dash="dot", line_color="#ef4444",
                                 annotation_text=f"UCL={ucl:.2f}", annotation_position="right")
                    fig.add_hline(y=lcl, line_dash="dot", line_color="#ef4444",
                                 annotation_text=f"LCL={lcl:.2f}", annotation_position="right")
                    fig.add_hrect(y0=lcl, y1=ucl, line_width=0, fillcolor="rgba(16,185,129,0.05)")

                    fig.update_layout(
                        title=dict(text=product, font_size=13),
                        template="plotly_white",
                        height=280,
                        showlegend=False,
                        margin=dict(l=40, r=40, t=40, b=30),
                        xaxis=dict(tickformat="%d %b", title=""),
                        yaxis=dict(title=label)
                    )

                    key_safe = f"chart_ctrl_{metric.lower()}_{product}".replace(' ', '_').replace('/', '_').replace('(', '_').replace(')', '_').replace('-', '_')
                    st.plotly_chart(fig, use_container_width=True, key=key_safe, config={"displayModeBar": True})

_REAL_PROD_SET = {'CPJ 32.5', 'CPJ 42.5', 'CPA 52.5', 'CPA 42.5', 'CHF'}


def _ventilate_production_records(prod_by_period, exp_by_period, x_label):
    """Transforme {periode: {produit: tonnes}} en records pour graphique empilé.

    Gère le total 'MIX'/'Total' (production non ventilée par produit) :
    - Période avec produits réels + total : n'affiche que le reliquat non ventilé
      (total - somme des produits) s'il est positif, sinon supprime le total en double.
    - Période avec uniquement un total : ventile selon le mix des expéditions de la
      période (sinon selon le mix produit moyen de la période filtrée).
    Retourne (records, ventilated_periods).
    """
    global_totals = defaultdict(float)
    for prods in prod_by_period.values():
        for pk, v in prods.items():
            if pk in _REAL_PROD_SET and isinstance(v, (int, float)) and v > 0:
                global_totals[pk] += v
    global_sum = sum(global_totals.values())
    global_mix = {pk: v / global_sum for pk, v in global_totals.items()} if global_sum > 0 else {}

    records = []
    ventilated = []
    for period, prods in prod_by_period.items():
        real = {pk: v for pk, v in prods.items()
                if pk in _REAL_PROD_SET and isinstance(v, (int, float)) and v > 0}
        mix_total = prods.get('MIX', 0) or prods.get('Total', 0) or 0
        for pk, v in real.items():
            records.append({x_label: period, 'Produit': pk, 'Production (t)': round(v, 1)})
        if isinstance(mix_total, (int, float)) and mix_total > 0:
            real_sum = sum(real.values())
            remainder = mix_total - real_sum
            if real_sum == 0:
                # Aucun détail produit : ventilation estimée du total
                ref = {pk: v for pk, v in exp_by_period.get(period, {}).items()
                       if pk in _REAL_PROD_SET and isinstance(v, (int, float)) and v > 0}
                ref = ref or global_mix
                if ref:
                    ref_sum = sum(ref.values())
                    for pk, v in ref.items():
                        records.append({x_label: period, 'Produit': pk,
                                        'Production (t)': round(mix_total * v / ref_sum, 1)})
                    ventilated.append(period)
                else:
                    records.append({x_label: period, 'Produit': 'Non ventilé',
                                    'Production (t)': round(mix_total, 1)})
            elif remainder > 1:
                # Détail produit partiel : afficher uniquement le reliquat non ventilé
                records.append({x_label: period, 'Produit': 'Non ventilé',
                                'Production (t)': round(remainder, 1)})
            # sinon : le total MIX duplique la somme des produits -> ignoré
    return records, ventilated


def _render_aggregated_charts(agg_data, x_label, key_prefix):
    """Render aggregated daily charts for weekly/monthly tabs.
    
    agg_data: {period_key: {dex: {production: {}, expedition: {}, temps_broyage: {}, ces: {}, matieres: {}}}}
    """
    if not agg_data:
        st.info("Aucune donnée agrégée disponible.")
        return
    
    _PROD_COLORS = {'CPJ 32.5': '#10b981', 'CPJ 42.5': '#F58220', 'CPA 52.5': '#1E4D8F', 'CPA 42.5': '#8b5cf6', 'CHF': '#ef4444'}
    
    # Determine y-axis max for temps de broyage based on aggregation level
    if x_label == "Semaine":
        tps_y_max = 168  # 24h * 7 days
    elif x_label == "Mois":
        tps_y_max = 720  # 24h * 30 days
    else:
        tps_y_max = 24
    
    # Helper to sort period keys chronologically
    def _sort_key(period):
        try:
            if x_label == "Semaine":
                # Format: 2026-W32
                year, week = period.split('-W')
                return (int(year), int(week))
            elif x_label == "Mois":
                # Format: 2026-08
                year, month = period.split('-')
                return (int(year), int(month))
            else:
                return period
        except:
            return (0, 0)
    
    sorted_periods = sorted(agg_data.items(), key=lambda x: _sort_key(x[0]))
    
    # Row 1: Production par produit
    _PROD_EXCLUDE_AGG = {'Total', 'total', '_total', 'mix', 'TOTAL MATIERES'}
    _REAL_PRODS_AGG = {'CPJ 32.5', 'CPJ 42.5', 'CPA 52.5', 'CPA 42.5', 'CHF'}
    g1, g2 = st.columns(2)
    with g1:
        prod_by_period_d1 = {}
        exp_by_period_d1 = {}
        for period, dexs in sorted_periods:
            prods = {pk: val for pk, val in dexs.get('DEX 1', {}).get('production', {}).items()
                     if pk not in _PROD_EXCLUDE_AGG and val and isinstance(val, (int, float)) and val > 0}
            if prods:
                prod_by_period_d1[period] = prods
            exp_d1 = dexs.get('DEX 1', {}).get('expedition', {})
            if exp_d1:
                exp_by_period_d1[period] = exp_d1
        prod_records, ventilated_d1 = _ventilate_production_records(prod_by_period_d1, exp_by_period_d1, x_label)
        if prod_records:
            df = pd.DataFrame(prod_records)
            # Ensure chronological order on x-axis
            period_order = [p for p, _ in sorted_periods]
            _PROD_COLORS_AGG = {'CPJ 32.5': '#10b981', 'CPJ 42.5': '#F58220', 'CPA 52.5': '#1E4D8F', 'CPA 42.5': '#8b5cf6', 'CHF': '#ef4444', 'Non ventilé': '#5B6770'}
            fig = px.bar(df, x=x_label, y='Production (t)', color='Produit',
                        color_discrete_map=_PROD_COLORS_AGG, template='plotly_white', height=350,
                        title="Production par Produit — DEX 1",
                        category_orders={x_label: period_order})
            fig.update_layout(barmode='stack', margin=dict(l=20,r=20,t=40,b=20))
            st.plotly_chart(fig, use_container_width=True, key=f"{key_prefix}_prod_d1", config={"displayModeBar": True})
            if ventilated_d1:
                st.caption(f"ℹ️ DEX 1 — répartition produit estimée (mix expéditions/période) pour : {', '.join(ventilated_d1[:5])}{'…' if len(ventilated_d1) > 5 else ''}")
        else:
            st.info("Aucune donnée de production DEX 1.")
    
    with g2:
        prod_by_period_d2 = {}
        exp_by_period_d2 = {}
        for period, dexs in sorted_periods:
            prods = {pk: val for pk, val in dexs.get('DEX 2', {}).get('production', {}).items()
                     if pk not in _PROD_EXCLUDE_AGG and val and isinstance(val, (int, float)) and val > 0}
            if prods:
                prod_by_period_d2[period] = prods
            exp_d2 = dexs.get('DEX 2', {}).get('expedition', {})
            if exp_d2:
                exp_by_period_d2[period] = exp_d2
        prod_records, ventilated_d2 = _ventilate_production_records(prod_by_period_d2, exp_by_period_d2, x_label)
        if prod_records:
            df = pd.DataFrame(prod_records)
            period_order = [p for p, _ in sorted_periods]
            _PROD_COLORS_AGG = {'CPJ 32.5': '#10b981', 'CPJ 42.5': '#F58220', 'CPA 52.5': '#1E4D8F', 'CPA 42.5': '#8b5cf6', 'CHF': '#ef4444', 'Non ventilé': '#5B6770'}
            fig = px.bar(df, x=x_label, y='Production (t)', color='Produit',
                        color_discrete_map=_PROD_COLORS_AGG, template='plotly_white', height=350,
                        title="Production par Produit — DEX 2",
                        category_orders={x_label: period_order})
            fig.update_layout(barmode='stack', margin=dict(l=20,r=20,t=40,b=20))
            st.plotly_chart(fig, use_container_width=True, key=f"{key_prefix}_prod_d2", config={"displayModeBar": True})
            if ventilated_d2:
                st.caption(f"ℹ️ DEX 2 — répartition produit estimée (mix expéditions/période) pour : {', '.join(ventilated_d2[:5])}{'…' if len(ventilated_d2) > 5 else ''}")
        else:
            st.info("Aucune donnée de production DEX 2.")
    
    # Row 2: Expedition par produit (filtered: no whatsapp_total/mtd)
    _EXP_EXCLUDE = {'whatsapp_total', 'whatsapp_mtd', 'total_jour', 'total_sacs', 'total_vracs', 'total_big_bag', '_source', '_combined_total'}
    g3, g4 = st.columns(2)
    with g3:
        exp_records = []
        for period, dexs in sorted_periods:
            for pk, val in dexs.get('DEX 1', {}).get('expedition', {}).items():
                if pk in _EXP_EXCLUDE:
                    continue
                if val and val > 0:
                    exp_records.append({x_label: period, 'Produit': pk, 'Expédition (t)': round(val, 1)})
        if exp_records:
            df = pd.DataFrame(exp_records)
            period_order = [p for p, _ in sorted_periods]
            fig = px.bar(df, x=x_label, y='Expédition (t)', color='Produit',
                        color_discrete_map=_PROD_COLORS, template='plotly_white', height=350,
                        title="Expédition par Produit — DEX 1",
                        category_orders={x_label: period_order})
            fig.update_layout(barmode='stack', margin=dict(l=20,r=20,t=40,b=20))
            st.plotly_chart(fig, use_container_width=True, key=f"{key_prefix}_exp_d1", config={"displayModeBar": True})
        else:
            st.info("Aucune donnée d'expédition DEX 1.")
    
    with g4:
        exp_records = []
        for period, dexs in sorted_periods:
            for pk, val in dexs.get('DEX 2', {}).get('expedition', {}).items():
                if pk in _EXP_EXCLUDE:
                    continue
                if val and val > 0:
                    exp_records.append({x_label: period, 'Produit': pk, 'Expédition (t)': round(val, 1)})
        if exp_records:
            df = pd.DataFrame(exp_records)
            period_order = [p for p, _ in sorted_periods]
            fig = px.bar(df, x=x_label, y='Expédition (t)', color='Produit',
                        color_discrete_map=_PROD_COLORS, template='plotly_white', height=350,
                        title="Expédition par Produit — DEX 2",
                        category_orders={x_label: period_order})
            fig.update_layout(barmode='stack', margin=dict(l=20,r=20,t=40,b=20))
            st.plotly_chart(fig, use_container_width=True, key=f"{key_prefix}_exp_d2", config={"displayModeBar": True})
        else:
            st.info("Aucune donnée d'expédition DEX 2.")
    
    # Row 3: Temps de broyage
    g5, g6 = st.columns(2)
    with g5:
        tps_records = []
        for period, dexs in sorted_periods:
            for pk, val in dexs.get('DEX 1', {}).get('temps_broyage', {}).items():
                if val and val > 0:
                    tps_records.append({x_label: period, 'Produit': pk, 'Temps (h)': round(val, 1)})
        if tps_records:
            df = pd.DataFrame(tps_records)
            period_order = [p for p, _ in sorted_periods]
            fig = px.bar(df, x=x_label, y='Temps (h)', color='Produit',
                        color_discrete_map=_PROD_COLORS, template='plotly_white', height=350,
                        title="Temps de Broyage — DEX 1",
                        category_orders={x_label: period_order})
            fig.update_layout(barmode='group', margin=dict(l=20,r=20,t=40,b=20), yaxis=dict(range=[0, tps_y_max]))
            st.plotly_chart(fig, use_container_width=True, key=f"{key_prefix}_tps_d1", config={"displayModeBar": True})
        else:
            st.info("Aucune donnée de temps de broyage DEX 1.")
    
    with g6:
        tps_records = []
        for period, dexs in sorted_periods:
            for pk, val in dexs.get('DEX 2', {}).get('temps_broyage', {}).items():
                if val and val > 0:
                    tps_records.append({x_label: period, 'Produit': pk, 'Temps (h)': round(val, 1)})
        if tps_records:
            df = pd.DataFrame(tps_records)
            period_order = [p for p, _ in sorted_periods]
            fig = px.bar(df, x=x_label, y='Temps (h)', color='Produit',
                        color_discrete_map=_PROD_COLORS, template='plotly_white', height=350,
                        title="Temps de Broyage — DEX 2",
                        category_orders={x_label: period_order})
            fig.update_layout(barmode='group', margin=dict(l=20,r=20,t=40,b=20), yaxis=dict(range=[0, tps_y_max]))
            st.plotly_chart(fig, use_container_width=True, key=f"{key_prefix}_tps_d2", config={"displayModeBar": True})
        else:
            st.info("Aucune donnée de temps de broyage DEX 2.")
    
    # Row 4: CES — scatter plot
    ces_records = []
    for period, dexs in sorted_periods:
        for dex_name in ['DEX 1', 'DEX 2']:
            for pk, val in dexs.get(dex_name, {}).get('ces', {}).items():
                if val and 5 < val < 150:
                    ces_records.append({x_label: period, 'Site': dex_name, 'Produit': pk, 'CES (kWh/t)': round(val, 1)})
    if ces_records:
        df = pd.DataFrame(ces_records)
        period_order = [p for p, _ in sorted_periods]
        fig = px.scatter(df, x=x_label, y='CES (kWh/t)', color='Produit', symbol='Site',
                     color_discrete_map=_PROD_COLORS, template='plotly_white', height=350,
                     title="CES par Produit et Site",
                     category_orders={x_label: period_order})
        fig.update_traces(marker=dict(size=10, opacity=0.8, line=dict(width=1, color='white')))
        fig.update_layout(margin=dict(l=20,r=20,t=40,b=20))
        st.plotly_chart(fig, use_container_width=True, key=f"{key_prefix}_ces", config={"displayModeBar": True})
    
    # Row 5: Matières premières
    mp_records = []
    for period, dexs in sorted_periods:
        for dex_name in ['DEX 1', 'DEX 2']:
            for mat, val in dexs.get(dex_name, {}).get('matieres', {}).items():
                if val and val > 0:
                    mp_records.append({x_label: period, 'Site': dex_name, 'Matière': mat, 'Quantité (t)': round(val, 1)})
    if mp_records:
        df = pd.DataFrame(mp_records)
        period_order = [p for p, _ in sorted_periods]
        fig = px.bar(df, x=x_label, y='Quantité (t)', color='Matière', facet_col='Site',
                    template='plotly_white', height=400,
                    title="Matières Premières Consommées par Site",
                    category_orders={x_label: period_order})
        fig.update_layout(barmode='stack', margin=dict(l=20,r=20,t=40,b=20))
        st.plotly_chart(fig, use_container_width=True, key=f"{key_prefix}_mp", config={"displayModeBar": True})


def _render_weekly_filtered(site, product, broyeur, timeframe, year, daily_data):
    """Vue hebdomadaire avec filtres et sélecteur de plage de dates."""
    st.html("<div class='section-title-light'>📊 Données Hebdomadaires — Filtres Actifs</div>")
    
    # ── FILTRE PLAGE DE DATES ──
    all_dates = sorted(daily_data.keys())
    if all_dates:
        min_date = pd.to_datetime(all_dates[0]).date()
        max_date = pd.to_datetime(all_dates[-1]).date()
        col_d1, col_d2 = st.columns(2)
        with col_d1:
            start_date = st.date_input("Date début", value=min_date, min_value=min_date, max_value=max_date, key="weekly_start_date")
        with col_d2:
            end_date = st.date_input("Date fin", value=max_date, min_value=min_date, max_value=max_date, key="weekly_end_date")
        date_filter_active = True
    else:
        start_date, end_date = None, None
        date_filter_active = False
    
    # Filtre site + produit + broyeur sur WEEKLY_DATA
    filtered_weekly = {}
    for k, v in WEEKLY_DATA.items():
        if site != "Tous":
            data_site = v.get('site', '').lower()
            if site.lower() not in data_site and data_site not in site.lower():
                continue
        # Filtre produit
        if product != "Tous":
            pf = product.lower().replace(" ", "_").replace(".", "_")
            has_prod = False
            for section in ['Prod humide', 'Prod. Sèche', 'Tps de prod. (H)', 'Débit (T/h)', 'CES (KWh/t)', 'CS Gasoil+DDO (L/t)', 'Facteur de débit (%)', '% K/C Sec', '% K/C Humide']:
                if section in v:
                    for pk in v[section].keys():
                        if pf in pk.lower().replace(" ", "_").replace(".", "_"):
                            has_prod = True
                            break
                if has_prod:
                    break
            if not has_prod:
                continue
        # Filtre broyeur
        if broyeur != "Tous":
            bf = broyeur.lower()
            has_broy = False
            for bk in v.keys():
                if bf in bk.lower():
                    has_broy = True
                    break
            if not has_broy:
                pass
        # Filtre année implicite via les clés (2026-Wxx)
        if str(year) not in k:
            continue
        filtered_weekly[k] = v
    
    # Sort by week number for chronological ordering
    filtered_weekly = dict(sorted(filtered_weekly.items(), key=lambda x: x[0]))
    
    if not filtered_weekly:
        st.warning("Aucune donnée hebdomadaire ne correspond aux filtres.")
        return
    
    st.success(f"{len(filtered_weekly)} semaines de données")

    # KPIs synthèse hebdomadaire - sum across real products
    _REAL_PROD_KEYS_W = {'CPJ 32.5', 'CPJ 42.5', 'CPA 52.5', 'CPA 42.5', 'CHF'}
    total_prod_weekly = 0
    for v in filtered_weekly.values():
        week_prod = 0
        for pk in _REAL_PROD_KEYS_W:
            week_prod += (v.get('Prod. Sèche', {}).get(pk, 0) or v.get('Prod humide', {}).get(pk, 0))
        # MIX/Total = production totale de la semaine : le total prévaut s'il
        # dépasse la somme des produits (détail partiel), sinon il la duplique
        mix_total_w = (v.get('Prod. Sèche', {}).get('MIX', 0) or v.get('Prod humide', {}).get('MIX', 0)
                       or v.get('Prod. Sèche', {}).get('Total', 0) or v.get('Prod humide', {}).get('Total', 0))
        if isinstance(mix_total_w, (int, float)) and mix_total_w > week_prod:
            week_prod = mix_total_w
        total_prod_weekly += week_prod
    total_exp_weekly = sum(v.get('TOTAL (T)', {}).get('TOTAL', 0) for v in filtered_weekly.values())
    total_incidents_weekly = sum(len(v.get('faits_marquants', [])) for v in filtered_weekly.values())

    k1, k2, k3, k4 = st.columns(4)
    with k1:
        st.html(dg_kpi_box("Semaines", f'{len(filtered_weekly)}'))
    with k2:
        st.html(dg_kpi_box("Production", f'{total_prod_weekly:,.0f} t'))
    with k3:
        st.html(dg_kpi_box("Expédition", f'{total_exp_weekly:,.0f} t'))
    with k4:
        st.html(dg_kpi_box("Faits Marquants", f'{total_incidents_weekly}'))

    # ── GRAPHIQUES HEBDOMADAIRES ──
    st.markdown("<div style='margin-top:24px;'></div>", unsafe_allow_html=True)
    g1, g2 = st.columns(2)
    with g1:
        prod_by_week = {}
        exp_by_week = {}
        for wk, wdata in filtered_weekly.items():
            prods = {}
            for prod_key in ['CPJ 42.5', 'CPJ 32.5', 'CPA 52.5', 'CPA 42.5', 'CHF', 'MIX']:
                # Try traditional structure first
                val = wdata.get('Prod. Sèche', {}).get(prod_key, 0) or wdata.get('Prod humide', {}).get(prod_key, 0)
                # Fallback to new production structure
                if not val:
                    prod_data = wdata.get('production', {})
                    if prod_key in prod_data:
                        val = prod_data[prod_key]
                    elif prod_key == 'CPJ 42.5' and 'total_production' in prod_data:
                        # For PDF data where total_production is a simple value
                        # Check if product-specific data exists in production dict
                        val = prod_data.get(prod_key, 0)
                # MIX = total hebdomadaire : essayer aussi les alias 'Total' / 'total_production'
                if prod_key == 'MIX' and not val:
                    val = (wdata.get('Prod. Sèche', {}).get('Total', 0) or wdata.get('Prod humide', {}).get('Total', 0))
                    if not val:
                        _tp = wdata.get('production', {}).get('total_production', 0)
                        val = _tp if isinstance(_tp, (int, float)) else 0
                if val and isinstance(val, (int, float)) and val > 0:
                    prods[prod_key] = val
            if prods:
                prod_by_week[wk] = prods
            _exp_tot = wdata.get('TOTAL (T)', {})
            if _exp_tot:
                exp_by_week[wk] = _exp_tot
        # Ventilation du total 'MIX' : reliquat si détail partiel, répartition
        # estimée (mix expéditions/période) si aucun détail produit
        prod_weeks, ventilated_weeks = _ventilate_production_records(prod_by_week, exp_by_week, 'Semaine')
        if prod_weeks:
            df_prod = pd.DataFrame(prod_weeks)
            # Robust chronological sorting with DEX order
            df_prod['_sort_year'] = df_prod['Semaine'].str.extract(r'(\d+)-W').astype(int)
            df_prod['_sort_week'] = df_prod['Semaine'].str.extract(r'W(\d+)').astype(int)
            df_prod['_sort_dex'] = df_prod['Semaine'].str.extract(r'DEX\s*(\d+)').fillna(0).astype(int)
            df_prod = df_prod.sort_values(['_sort_year', '_sort_week', '_sort_dex']).drop(columns=['_sort_year', '_sort_week', '_sort_dex'])
            # Ensure consistent x-axis category order
            week_order = df_prod['Semaine'].unique().tolist()
            _PROD_COLORS_W = {'CPJ 42.5':'#F58220','CPJ 32.5':'#10b981','CPA 52.5':'#1E4D8F','CPA 42.5':'#8b5cf6','CHF':'#ef4444','Non ventilé':'#5B6770'}
            fig_prod = px.bar(df_prod, x='Semaine', y='Production (t)', color='Produit', 
                              color_discrete_map=_PROD_COLORS_W,
                              template='plotly_white', height=350,
                              category_orders={'Semaine': week_order})
            fig_prod.update_layout(margin=dict(l=20,r=20,t=40,b=20))
            st.plotly_chart(fig_prod, use_container_width=True, key="weekly_prod_chart", config={"displayModeBar": True})
            if ventilated_weeks:
                st.caption(f"ℹ️ Répartition produit estimée (mix expéditions/période) pour : {', '.join(ventilated_weeks[:5])}{'…' if len(ventilated_weeks) > 5 else ''}")
        else:
            st.info("Aucune donnée de production par produit pour les graphiques.")
    with g2:
        ces_weeks = []
        for wk, wdata in filtered_weekly.items():
            # Try traditional structure first
            if 'CES (KWh/t)' in wdata:
                for prod_key, val in wdata['CES (KWh/t)'].items():
                    if prod_key not in ('MIX', 'CHF') and isinstance(val, (int, float)) and val > 0 and val <= 80:
                        ces_weeks.append({'Semaine': wk, 'Produit': prod_key, 'CES (kWh/t)': val})
            # Fallback to new production structure
            elif 'production' in wdata and 'ces_mills' in wdata['production']:
                for prod_key, val in wdata['production']['ces_mills'].items():
                    if prod_key not in ('MIX', 'CHF', 'Total') and isinstance(val, (int, float)) and val > 0 and val <= 80:
                        ces_weeks.append({'Semaine': wk, 'Produit': prod_key, 'CES (kWh/t)': val})
        if ces_weeks:
            df_ces = pd.DataFrame(ces_weeks)
            df_ces = _filter_outliers_df(df_ces, 'CES (kWh/t)', 'ces')
            df_ces['_sort_year'] = df_ces['Semaine'].str.extract(r'(\d+)-W').astype(int)
            df_ces['_sort_week'] = df_ces['Semaine'].str.extract(r'W(\d+)').astype(int)
            df_ces['_sort_dex'] = df_ces['Semaine'].str.extract(r'DEX\s*(\d+)').fillna(0).astype(int)
            df_ces = df_ces.sort_values(['_sort_year', '_sort_week', '_sort_dex']).drop(columns=['_sort_year', '_sort_week', '_sort_dex'])
            week_order_ces = df_ces['Semaine'].unique().tolist()
            fig_ces = px.scatter(df_ces, x='Semaine', y='CES (kWh/t)', color='Produit',
                              color_discrete_map={'CPA 52.5':'#1E4D8F','CPJ 42.5':'#F58220','CPJ 32.5':'#10b981'},
                              template='plotly_white', height=350,
                              category_orders={'Semaine': week_order_ces})
            fig_ces.update_traces(marker=dict(size=10, opacity=0.8, line=dict(width=1, color='white')))
            fig_ces.update_layout(margin=dict(l=20,r=20,t=40,b=20))
            st.plotly_chart(fig_ces, use_container_width=True, key="weekly_ces_chart", config={"displayModeBar": True})
        else:
            st.info("Aucune donnée CES pour les graphiques.")

    # K/C ratio par semaine
    kc_weeks = []
    for wk, wdata in filtered_weekly.items():
        # Try traditional structure first
        for section in ['% K/C Sec', '% K/C Humide']:
            if section in wdata:
                for prod_key, val in wdata[section].items():
                    if prod_key not in ('MIX', 'CHF') and isinstance(val, (int, float)):
                        kc_val = val*100 if val < 1 else val
                        if kc_val >= 40:
                            kc_weeks.append({'Semaine': wk, 'Produit': prod_key, 'K/C Sec (%)': kc_val})
        # Fallback to new production structure
        if 'production' in wdata:
            # Check if quality data exists in production
            quality = wdata['production'].get('quality', {})
            for prod_key, qdata in quality.items():
                if isinstance(qdata, dict) and 'kc_sec' in qdata:
                    val = qdata['kc_sec']
                    if isinstance(val, (int, float)):
                        kc_val = val*100 if val < 1 else val
                        if kc_val >= 40:
                            kc_weeks.append({'Semaine': wk, 'Produit': prod_key, 'K/C Sec (%)': kc_val})
    if kc_weeks:
        df_kc = pd.DataFrame(kc_weeks)
        df_kc['_sort_year'] = df_kc['Semaine'].str.extract(r'(\d+)-W').astype(int)
        df_kc['_sort_week'] = df_kc['Semaine'].str.extract(r'W(\d+)').astype(int)
        df_kc['_sort_dex'] = df_kc['Semaine'].str.extract(r'DEX\s*(\d+)').fillna(0).astype(int)
        df_kc = df_kc.sort_values(['_sort_year', '_sort_week', '_sort_dex']).drop(columns=['_sort_year', '_sort_week', '_sort_dex'])
        week_order_kc = df_kc['Semaine'].unique().tolist()
        fig_kc = px.scatter(df_kc, x='Semaine', y='K/C Sec (%)', color='Produit',
                         color_discrete_map={'CPA 52.5':'#1E4D8F','CPJ 42.5':'#F58220','CPJ 32.5':'#10b981'},
                         template='plotly_white', height=350,
                         category_orders={'Semaine': week_order_kc})
        fig_kc.update_traces(marker=dict(size=10, opacity=0.8, line=dict(width=1, color='white')))
        fig_kc.update_layout(margin=dict(l=20,r=20,t=40,b=20))
        st.plotly_chart(fig_kc, use_container_width=True, key="weekly_kc_chart", config={"displayModeBar": True})
    else:
        st.info("Aucune donnée K/C pour les graphiques.")

    # ── GRAPHIQUES JOURNALIERS AGRÉGÉS PAR SEMAINE ──
    st.markdown("<div style='margin-top:24px;'></div>", unsafe_allow_html=True)
    st.html("<div class='section-title-light' style='font-size:0.9rem;'>📊 Données Journalières Agrégées par Semaine</div>")
    
    # Aggregate daily_data by ISO week
    _REAL_PROD = {'CPJ 32.5', 'CPJ 42.5', 'CPA 52.5', 'CPA 42.5', 'CHF'}
    week_agg = {}
    for date_str in sorted(daily_data.keys()):
        if year and str(year) not in date_str:
            continue
        if date_filter_active:
            try:
                d = pd.to_datetime(date_str).date()
                if d < start_date or d > end_date:
                    continue
            except:
                continue
        try:
            dt = pd.to_datetime(date_str)
            week_key = f"{dt.year}-W{dt.isocalendar().week:02d}"
        except:
            continue
        if week_key not in week_agg:
            week_agg[week_key] = {}
        
        for dex_name in ['DEX 1', 'DEX 2']:
            if dex_name not in week_agg[week_key]:
                week_agg[week_key][dex_name] = {
                    'production': {}, 'expedition': {}, 'temps_broyage': {},
                    'debit': {}, 'ces': {}, 'matieres': {}
                }
            site_data = daily_data[date_str].get(dex_name, {})
            prod = site_data.get('production', {})
            
            # Production
            tp = prod.get('total_production', {})
            if isinstance(tp, (int, float)):
                # Simple total production value (from PDFs)
                if tp > 0:
                    # Try to get per-product data from production dict
                    for pk, pv in prod.items():
                        if pk in ('total', '_total', 'mix', 'TOTAL MATIERES') or pk not in _REAL_PROD:
                            continue
                        if isinstance(pv, (int, float)) and pv > 0:
                            week_agg[week_key][dex_name]['production'][pk] = week_agg[week_key][dex_name]['production'].get(pk, 0) + pv
                    # If no per-product data, store under a generic key
                    if not week_agg[week_key][dex_name]['production']:
                        week_agg[week_key][dex_name]['production']['Total'] = tp
            elif isinstance(tp, dict):
                for pk, pv in tp.items():
                    if pk in ('total', '_total', 'mix', 'TOTAL MATIERES') or pk not in _REAL_PROD:
                        continue
                    if isinstance(pv, dict):
                        v = pv.get('Mills') or sum(vv for kk, vv in pv.items() if kk in ('A', 'B') and isinstance(vv, (int, float)) and vv > 0)
                    elif isinstance(pv, (int, float)):
                        v = pv
                    else:
                        v = 0
                    if v and v > 0:
                        week_agg[week_key][dex_name]['production'][pk] = week_agg[week_key][dex_name]['production'].get(pk, 0) + v
            
            # Expedition
            exp = site_data.get('expedition', {})
            for pk, pv in exp.items():
                if pk in ('total_jour', 'total_sacs', 'total_vracs', 'total_big_bag', '_source', '_combined_total'):
                    continue
                if isinstance(pv, dict):
                    v = sum(vv for vv in pv.values() if isinstance(vv, (int, float)) and vv > 0)
                elif isinstance(pv, (int, float)):
                    v = pv
                else:
                    v = 0
                if v and v > 0:
                    week_agg[week_key][dex_name]['expedition'][pk] = week_agg[week_key][dex_name]['expedition'].get(pk, 0) + v
            
            # Temps de broyage (Mills only, max 24h per day)
            tb = prod.get('temps_broyage', {})
            for pk, pv in tb.items():
                if pk in ('total', '_total', 'mix', 'TOTAL MATIERES'):
                    continue
                if isinstance(pv, dict):
                    v = pv.get('Mills') or sum(vv for kk, vv in pv.items() if kk in ('A', 'B') and isinstance(vv, (int, float)) and vv > 0)
                elif isinstance(pv, (int, float)):
                    v = pv
                else:
                    v = 0
                if v and 0 < v <= 24:
                    week_agg[week_key][dex_name]['temps_broyage'][pk] = week_agg[week_key][dex_name]['temps_broyage'].get(pk, 0) + v
            
            # CES (average weighted by production)
            ces = prod.get('ces_mills', {})
            for pk, pv in ces.items():
                if pk in ('total', '_total', 'mix', 'TOTAL MATIERES') or pk not in _REAL_PROD:
                    continue
                if isinstance(pv, dict):
                    v = pv.get('Mills') or sum(vv for kk, vv in pv.items() if kk in ('A', 'B') and isinstance(vv, (int, float)) and vv > 0)
                elif isinstance(pv, (int, float)):
                    v = pv
                else:
                    v = 0
                if v and 5 < v < 150:
                    prod_v = week_agg[week_key][dex_name]['production'].get(pk, 0)
                    if prod_v > 0:
                        prev = week_agg[week_key][dex_name]['ces'].get(pk, {})
                        week_agg[week_key][dex_name]['ces'][pk] = {
                            'weighted_sum': prev.get('weighted_sum', 0) + v * prod_v,
                            'total_prod': prev.get('total_prod', 0) + prod_v
                        }
            
            # Matières premières
            mp = prod.get('matieres_premieres', {})
            for mat, vals in mp.items():
                if isinstance(vals, dict):
                    v = sum(vv for kk, vv in vals.items() if kk in ('Mills', 'Total', '1') and isinstance(vv, (int, float)) and vv > 0)
                elif isinstance(vals, (int, float)):
                    v = vals
                else:
                    v = 0
                if v and v > 0:
                    week_agg[week_key][dex_name]['matieres'][mat] = week_agg[week_key][dex_name]['matieres'].get(mat, 0) + v
    
    # Convert CES weighted averages
    for wk in week_agg:
        for dex in week_agg[wk]:
            for pk in list(week_agg[wk][dex]['ces'].keys()):
                d = week_agg[wk][dex]['ces'][pk]
                if isinstance(d, dict) and d.get('total_prod', 0) > 0:
                    week_agg[wk][dex]['ces'][pk] = d['weighted_sum'] / d['total_prod']
                else:
                    del week_agg[wk][dex]['ces'][pk]
    
    # Render aggregated charts
    _render_aggregated_charts(week_agg, "Semaine", "weekly_agg")

    # Affichage des données hebdomadaires regroupées dans un expander central
    with st.expander("📋 Voir les données hebdomadaires détaillées", expanded=False):
        for week_key in sorted(filtered_weekly.keys()):
            week_data = filtered_weekly[week_key]
            with st.expander(f"📅 {week_key} — {week_data.get('site', 'N/A')} — {week_data.get('date_range', '')}", expanded=False):
                # Prod humide / sèche
                prod_h = week_data.get('Prod humide', {})
                prod_s = week_data.get('Prod. Sèche', {})
                
                c1, c2 = st.columns(2)
                with c1:
                    st.markdown("**Production Humide**")
                    for prod, val in prod_h.items():
                        st.write(f"- {prod}: {val:,.2f} t")
                with c2:
                    st.markdown("**Production Sèche**")
                    for prod, val in prod_s.items():
                        st.write(f"- {prod}: {val:,.2f} t")
                
                # CES / Débit
                if 'CES (KWh/t)' in week_data:
                    st.markdown("**Consommation Énergétique**")
                    for prod, val in week_data['CES (KWh/t)'].items():
                        st.write(f"- {prod}: {val:.2f} kWh/t")
                
                # Matières premières
                if 'Clinker' in week_data:
                    st.markdown("**Matières Premières**")
                    clinker = week_data['Clinker']
                    if isinstance(clinker, dict):
                        clinker_total = sum(v for k, v in clinker.items() if k in _REAL_PROD_KEYS_W and isinstance(v, (int, float)))
                        st.write(f"- Clinker: {clinker_total:,.2f} t")
                
                # Expédition
                total_t = week_data.get('TOTAL (T)', {}).get('TOTAL', 0)
                if total_t:
                    st.metric("Total Expédition", f"{total_t:,.0f} t")
                
                # Cibles & Écarts (from Excel)
                cibles = week_data.get('cibles', {})
                ecarts = week_data.get('ecarts', {})
                if cibles or ecarts:
                    st.markdown("**🎯 Cibles & Écarts (Excel)**")
                    cc1, cc2 = st.columns(2)
                    with cc1:
                        if cibles:
                            st.markdown("*Cibles hebdo*")
                            for cat, vals in cibles.items():
                                if isinstance(vals, dict):
                                    # Only show first 2 product values
                                    items = list(vals.items())[:2]
                                    st.write(f"  {cat}: {', '.join(f'{k}={v:.2f}' for k,v in items)}")
                                else:
                                    st.write(f"  {cat}: {vals:.3f}" if isinstance(vals, (int, float)) else f"  {cat}: {vals}")
                    with cc2:
                        if ecarts:
                            st.markdown("*Écarts hebdo*")
                            for cat, vals in ecarts.items():
                                if isinstance(vals, dict):
                                    items = list(vals.items())[:2]
                                    st.write(f"  {cat}: {', '.join(f'{k}={v:+.3f}' for k,v in items)}")
                                else:
                                    st.write(f"  {cat}: {vals:+.3f}" if isinstance(vals, (int, float)) else f"  {cat}: {vals}")



    # --- FLUX DE TRÉSORERIE (encaissements / décaissements hebdomadaires) ---
    try:
        _render_treasury_flow_section(freq="W", expanded=False)
    except Exception as e:
        st.error(f"Erreur Trésorerie hebdo: {e}")

def _render_monthly_filtered(site, product, broyeur, timeframe, year, daily_data):
    """Vue mensuelle avec filtres et sélecteur de plage de dates."""
    st.html("<div class='section-title-light'>📈 Données Mensuelles — Filtres Actifs</div>")
    
    # ── FILTRE PLAGE DE DATES ──
    all_dates = sorted(daily_data.keys())
    if all_dates:
        min_date = pd.to_datetime(all_dates[0]).date()
        max_date = pd.to_datetime(all_dates[-1]).date()
        col_d1, col_d2 = st.columns(2)
        with col_d1:
            start_date = st.date_input("Date début", value=min_date, min_value=min_date, max_value=max_date, key="monthly_start_date")
        with col_d2:
            end_date = st.date_input("Date fin", value=max_date, min_value=min_date, max_value=max_date, key="monthly_end_date")
        date_filter_active = True
    else:
        start_date, end_date = None, None
        date_filter_active = False
    
    # Données mensuelles filtrées par année
    months = []
    for m in range(1, 13):
        key = f"{year}-{m:02d}"
        
        # Données broyeur
        broyeur_data = BD_BROYEUR_MONTHLY.get(key, {})
        # Données conso matières
        conso_data = BD_CONSO_MATIERES_MONTHLY.get(key, {})
        # Données expédition
        exp_data = BD_EXPEDITION_MONTHLY.get(key, {})
        # Données financières
        fin_data = HISTORICAL_FINANCIAL_DATA.get(key, {})
        
        if broyeur_data or exp_data or fin_data:
            months.append({
                "mois": MONTHS[m-1],
                "key": key,
                "production": broyeur_data.get("production_t", 0),
                "ces": broyeur_data.get("ces_kwh_t", 0),
                "expedition": exp_data.get("expedition_t", 0),
                "casse": exp_data.get("casse_pct", 0),
                "ca_reel": fin_data.get("ca_reel", 0) / 1e9,
                "ca_budget": fin_data.get("ca_budget", 0) / 1e9,
                "ebitda_reel": fin_data.get("ebitda_reel", 0) / 1e9,
                "ebitda_budget": fin_data.get("ebitda_budget", 0) / 1e9,
            })
    
    if not months:
        st.warning(f"Aucune donnée mensuelle pour {year}.")
        return
    
    df = pd.DataFrame(months)
    
    # KPIs
    k1, k2, k3, k4 = st.columns(4)
    with k1:
        st.html(dg_kpi_box("Production Totale", f'{df["production"].sum():,.0f} t'))
    with k2:
        st.html(dg_kpi_box("Expédition Totale", f'{df["expedition"].sum():,.0f} t'))
    with k3:
        st.html(dg_kpi_box("CA Réel", f'{df["ca_reel"].sum():,.2f} Mds'))
    with k4:
        st.html(dg_kpi_box("EBITDA Réel", f'{df["ebitda_reel"].sum():,.2f} Mds'))
    
    # Graphiques
    fig1 = make_subplots(rows=2, cols=2, subplot_titles=("Production vs Expédition", "CA Réel vs Budget", "EBITDA Réel vs Budget", "Taux de Casse"))
    fig1.add_trace(go.Bar(name="Production", x=df["mois"], y=df["production"], marker_color="#1E4D8F"), row=1, col=1)
    fig1.add_trace(go.Bar(name="Expédition", x=df["mois"], y=df["expedition"], marker_color="#F58220"), row=1, col=1)
    fig1.add_trace(go.Scatter(name="CA Réel", x=df["mois"], y=df["ca_reel"], line=dict(color="#1E4D8F")), row=1, col=2)
    fig1.add_trace(go.Scatter(name="CA Budget", x=df["mois"], y=df["ca_budget"], line=dict(color="#5B6770", dash="dash")), row=1, col=2)
    fig1.add_trace(go.Scatter(name="EBITDA Réel", x=df["mois"], y=df["ebitda_reel"], line=dict(color="#F58220")), row=2, col=1)
    fig1.add_trace(go.Scatter(name="EBITDA Budget", x=df["mois"], y=df["ebitda_budget"], line=dict(color="#10b981", dash="dash")), row=2, col=1)
    fig1.add_trace(go.Bar(name="Taux Casse %", x=df["mois"], y=df["casse"], marker_color="#ef4444"), row=2, col=2)
    fig1.update_layout(height=700, template="plotly_white", showlegend=True)
    st.plotly_chart(fig1, use_container_width=True, key="chart_fig1_19", config={"displayModeBar": True})
    
    # ── GRAPHIQUES JOURNALIERS AGRÉGÉS PAR MOIS ──
    st.markdown("<div style='margin-top:24px;'></div>", unsafe_allow_html=True)
    st.html("<div class='section-title-light' style='font-size:0.9rem;'>📊 Données Journalières Agrégées par Mois</div>")
    
    # Aggregate daily_data by month
    month_agg = {}
    _REAL_PROD = {'CPJ 32.5', 'CPJ 42.5', 'CPA 52.5', 'CPA 42.5', 'CHF'}
    
    for date_str in sorted(daily_data.keys()):
        month_key = date_str[:7]  # YYYY-MM
        if year and str(year) not in month_key:
            continue
        if date_filter_active:
            try:
                d = pd.to_datetime(date_str).date()
                if d < start_date or d > end_date:
                    continue
            except:
                continue
        if month_key not in month_agg:
            month_agg[month_key] = {}
        
        for dex_name in ['DEX 1', 'DEX 2']:
            if dex_name not in month_agg[month_key]:
                month_agg[month_key][dex_name] = {
                    'production': {}, 'expedition': {}, 'temps_broyage': {},
                    'debit': {}, 'ces': {}, 'matieres': {}
                }
            site_data = daily_data[date_str].get(dex_name, {})
            prod = site_data.get('production', {})
            
            # Production
            tp = prod.get('total_production', {})
            if isinstance(tp, (int, float)):
                # Simple total production value (from PDFs)
                if tp > 0:
                    # Try to get per-product data from production dict
                    for pk, pv in prod.items():
                        if pk in ('total', '_total', 'mix', 'TOTAL MATIERES') or pk not in _REAL_PROD:
                            continue
                        if isinstance(pv, (int, float)) and pv > 0:
                            month_agg[month_key][dex_name]['production'][pk] = month_agg[month_key][dex_name]['production'].get(pk, 0) + pv
                    # If no per-product data, store under a generic key
                    if not month_agg[month_key][dex_name]['production']:
                        month_agg[month_key][dex_name]['production']['Total'] = tp
            elif isinstance(tp, dict):
                for pk, pv in tp.items():
                    if pk in ('total', '_total', 'mix', 'TOTAL MATIERES') or pk not in _REAL_PROD:
                        continue
                    if isinstance(pv, dict):
                        v = pv.get('Mills') or sum(vv for kk, vv in pv.items() if kk in ('A', 'B') and isinstance(vv, (int, float)) and vv > 0)
                    elif isinstance(pv, (int, float)):
                        v = pv
                    else:
                        v = 0
                    if v and v > 0:
                        month_agg[month_key][dex_name]['production'][pk] = month_agg[month_key][dex_name]['production'].get(pk, 0) + v
            
            # Expedition
            exp = site_data.get('expedition', {})
            for pk, pv in exp.items():
                if pk in ('total_jour', 'total_sacs', 'total_vracs', 'total_big_bag', '_source', '_combined_total'):
                    continue
                if isinstance(pv, dict):
                    v = sum(vv for vv in pv.values() if isinstance(vv, (int, float)) and vv > 0)
                elif isinstance(pv, (int, float)):
                    v = pv
                else:
                    v = 0
                if v and v > 0:
                    month_agg[month_key][dex_name]['expedition'][pk] = month_agg[month_key][dex_name]['expedition'].get(pk, 0) + v
            
            # Temps de broyage
            tb = prod.get('temps_broyage', {})
            for pk, pv in tb.items():
                if pk in ('total', '_total', 'mix', 'TOTAL MATIERES'):
                    continue
                if isinstance(pv, dict):
                    v = pv.get('Mills') or sum(vv for kk, vv in pv.items() if kk in ('A', 'B') and isinstance(vv, (int, float)) and vv > 0)
                elif isinstance(pv, (int, float)):
                    v = pv
                else:
                    v = 0
                if v and 0 < v <= 24:
                    month_agg[month_key][dex_name]['temps_broyage'][pk] = month_agg[month_key][dex_name]['temps_broyage'].get(pk, 0) + v
            
            # CES
            ces = prod.get('ces_mills', {})
            for pk, pv in ces.items():
                if pk in ('total', '_total', 'mix', 'TOTAL MATIERES') or pk not in _REAL_PROD:
                    continue
                if isinstance(pv, dict):
                    v = pv.get('Mills') or sum(vv for kk, vv in pv.items() if kk in ('A', 'B') and isinstance(vv, (int, float)) and vv > 0)
                elif isinstance(pv, (int, float)):
                    v = pv
                else:
                    v = 0
                if v and 5 < v < 150:
                    prod_v = month_agg[month_key][dex_name]['production'].get(pk, 0)
                    if prod_v > 0:
                        prev = month_agg[month_key][dex_name]['ces'].get(pk, {})
                        month_agg[month_key][dex_name]['ces'][pk] = {
                            'weighted_sum': prev.get('weighted_sum', 0) + v * prod_v,
                            'total_prod': prev.get('total_prod', 0) + prod_v
                        }
            
            # Matières premières
            mp = prod.get('matieres_premieres', {})
            for mat, vals in mp.items():
                if isinstance(vals, dict):
                    v = sum(vv for kk, vv in vals.items() if kk in ('Mills', 'Total', '1') and isinstance(vv, (int, float)) and vv > 0)
                elif isinstance(vals, (int, float)):
                    v = vals
                else:
                    v = 0
                if v and v > 0:
                    month_agg[month_key][dex_name]['matieres'][mat] = month_agg[month_key][dex_name]['matieres'].get(mat, 0) + v
    
    # Convert CES weighted averages
    for mk in month_agg:
        for dex in month_agg[mk]:
            for pk in list(month_agg[mk][dex]['ces'].keys()):
                d = month_agg[mk][dex]['ces'][pk]
                if isinstance(d, dict) and d.get('total_prod', 0) > 0:
                    month_agg[mk][dex]['ces'][pk] = d['weighted_sum'] / d['total_prod']
                else:
                    del month_agg[mk][dex]['ces'][pk]
    
    _render_aggregated_charts(month_agg, "Mois", "monthly_agg")
    
    # Tableau détaillé
    st.dataframe(df, use_container_width=True, hide_index=True)



    # --- FLUX DE TRÉSORERIE (encaissements / décaissements mensuels) ---
    try:
        _render_treasury_flow_section(freq="M", expanded=False)
    except Exception as e:
        st.error(f"Erreur Trésorerie mensuelle: {e}")

def _render_annual_filtered(site, product, broyeur, timeframe, year):
    """Vue annuelle avec filtres."""
    st.html("<div class='section-title-light'>📉 Données Annuelles — Filtres Actifs</div>")
    
    years = sorted(HISTORICAL_ANNUAL_SUMMARY.keys())
    data = []
    for y in years:
        d = HISTORICAL_ANNUAL_SUMMARY[y]
        data.append({
            "Année": y,
            "CA Réel": d.get("ca_reel", 0),
            "CA Budget": d.get("ca_budget", 0),
            "EBITDA Réel": d.get("ebitda_reel", 0),
            "EBITDA Budget": d.get("ebitda_budget", 0),
            "Marge EBITDA": d.get("marge_ebitda", 0) * 100,
            "TRO CA": d.get("tro_ca", 0) * 100,
        })
    
    df = pd.DataFrame(data)
    
    # Graphique d'évolution annuelle
    fig = make_subplots(specs=[[{"secondary_y": True}]])
    fig.add_trace(go.Bar(name="CA Réel", x=df["Année"], y=df["CA Réel"], marker_color="#1E4D8F"), secondary_y=False)
    fig.add_trace(go.Bar(name="CA Budget", x=df["Année"], y=df["CA Budget"], marker_color="#5B6770"), secondary_y=False)
    fig.add_trace(go.Scatter(name="EBITDA Réel", x=df["Année"], y=df["EBITDA Réel"], line=dict(color="#F58220", width=3)), secondary_y=True)
    fig.add_trace(go.Scatter(name="EBITDA Budget", x=df["Année"], y=df["EBITDA Budget"], line=dict(color="#10b981", width=3, dash="dash")), secondary_y=True)
    fig.update_layout(title="Évolution Annuelle CA & EBITDA", barmode="group", template="plotly_white", height=500)
    fig.update_yaxes(title_text="CA / Budget (Mds XOF)", secondary_y=False)
    fig.update_yaxes(title_text="EBITDA (Mds XOF)", secondary_y=True)
    st.plotly_chart(fig, use_container_width=True, key="chart_fig_20", config={"displayModeBar": True})
    
    # Tableau
    st.dataframe(df, use_container_width=True, hide_index=True)
    
    # Données de production annuelle agrégées
    prod_by_year = {}
    for key, d in BD_BROYEUR_MONTHLY.items():
        y = int(key.split("-")[0])
        if y not in prod_by_year:
            prod_by_year[y] = 0
        prod_by_year[y] += d.get("production_t", 0)
    
    if prod_by_year:
        st.markdown("**Production Totale par Année**")
        prod_df = pd.DataFrame([{"Année": y, "Production (t)": v} for y, v in sorted(prod_by_year.items())])
        fig2 = px.bar(prod_df, x="Année", y="Production (t)", color_discrete_sequence=["#1E4D8F"])
        fig2.update_layout(template="plotly_white", height=350)
        st.plotly_chart(fig2, use_container_width=True, key="chart_fig2_21", config={"displayModeBar": True})


