    fig8.add_trace(go.Scatter(x=months, y=vol_monthly, name="Volume", mode="lines+markers", line=dict(color="#8b5cf6", width=2.5, dash="dot"), marker=dict(size=7, symbol="circle", color="#8b5cf6", line=dict(color="white", width=1))), secondary_y=True)

