    fig8.update_yaxes(title_text="<b>Volume (kt)</b>", title_font=dict(color="#8b5cf6", size=12), tickfont=dict(color="#8b5cf6", size=10), gridcolor="rgba(139,92,246,0.15)", secondary_y=True)
