    # Chart 11: Structure des Coûts Détaillée (Pareto)
    cost_items_raw = ['Clinker', 'Energie', 'Combustibles', 'Adjuvants', 'Ensachage', 'Transport', 'Commercial', 'Fixes Site 1', 'Fixes Site 2', 'SGA', 'Maintenance', "Main-d'œuvre"]
    _annual_vol_ps = {(p, s): sum(m.get("prod", {}).get((p, s), 0) for m in annual["monthly"]) for p in PRODUCTS for s in SITES}
    _sac_share_map = res.get("sac_share", {p: 1.0 for p in PRODUCTS})
    cost_values_raw = [
        sum(annual["annual_prod"].get(p, 0) * (res.get("material_cost", {}).get(p, 0) if not isinstance(res.get("material_cost", {}).get(p, {}), dict) else res.get("material_cost", {}).get(p, {}).get("total", 0)) for p in PRODUCTS) / 1e9,
        sum(annual["annual_prod"].get(p, 0) * res.get("energy_cost_per_t", {}).get(p, 0) for p in PRODUCTS) / 1e9,
        sum(_annual_vol_ps[(p, s)] * res.get("fuel_cost_per_ts", {}).get((p, s), 0) for p in PRODUCTS for s in SITES) / 1e9,
        sum(_annual_vol_ps[(p, s)] * res.get("adjuvant_cost_per_ts", {}).get((p, s), 0) for p in PRODUCTS for s in SITES) / 1e9,
        sum(annual["annual_prod"].get(p, 0) * get_val("sac_cost_per_unit") * get_val("sacs_per_tonne") * _sac_share_map.get(p, 1.0) for p in PRODUCTS) / 1e9,
        sum(annual["annual_prod"].get(p, 0) * get_val("avg_distance_site1") * get_val("transport_cost_per_tkm") for p in PRODUCTS) / 1e9 / 2 +
        sum(annual["annual_prod"].get(p, 0) * get_val("avg_distance_site2") * get_val("transport_cost_per_tkm") for p in PRODUCTS) / 1e9 / 2,
        sum(annual["annual_prod"].get(p, 0) * get_val("commercial_cost_per_tonne") for p in PRODUCTS) / 1e9,
        res.get("fixed_site1", 0) * 12 / 1e9,
        res.get("fixed_site2", 0) * 12 / 1e9,
        get_val("sga_cost") * 12 / 1e9,
        (get_val("maintenance_cost_site1") + get_val("maintenance_cost_site2") + get_maintenance_labor_monthly("Site 1") + get_maintenance_labor_monthly("Site 2")) * 12 / 1e9,
        (get_val("labor_cost_site1") + get_val("labor_cost_site2")) * 12 / 1e9,
    ]
    
    # Sort for Pareto
    cost_data_sorted = sorted(zip(cost_items_raw, cost_values_raw), key=lambda x: x[1], reverse=True)
    cost_items_det = [x[0] for x in cost_data_sorted]
    cost_values_det = [x[1] for x in cost_data_sorted]
    _total_costs = float(sum(cost_values_det)) or 1.0
    cumulative_pct = [float(v) / _total_costs * 100.0 for v in np.cumsum(cost_values_det)]

    fig11 = make_subplots(specs=[[{"secondary_y": True}]])
