    vrac_vals = [HISTORICAL_SALES_ANNUAL.get(y, {}).get("vrac", 0) / 1e3 for y in sales_years]
    total_vals = [HISTORICAL_SALES_ANNUAL.get(y, {}).get("total_tonnes", 0) / 1e3 for y in sales_years]

    fig3 = go.Figure()
