        model_marge = annual["annual_ebitda"] / annual["annual_revenue_total"] * 100 if annual["annual_revenue_total"] > 0 else 0

        hist_ca = hist_2024.get("ca_reel", 0)
        hist_ebitda = hist_2024.get("ebitda_reel", 0)
        hist_vol = HISTORICAL_SALES_ANNUAL.get(2024, {}).get("total_tonnes", 0) / 1e3
