st.html("<div class='ai-search-title'>🔍 I-BiD® AI Search — Solutions Sectorielles pour la Cimenterie</div>")

st.html("<div class='ai-search-subtitle'>Posez une question sur vos défis opérationnels, financiers, stratégiques ou logistiques. L'IA propose des solutions éprouvées dans l'industrie cimentière.</div>")



ai_col1, ai_col2, ai_col3 = st.columns([3, 1.5, 1.5])

with ai_col1:

    ai_query = st.text_input(

        "",

        value=st.session_state.get("ai_search_query", ""),

        key="ai_search_input",

        placeholder="Ex: Comment soulager ma trésorerie ? Réduire les surestaries au port ? Optimiser l'énergie ? Stratégie prix vs Dangote ?",

        label_visibility="collapsed"

    )

with ai_col2:

    if st.button("🔍 Rechercher", type="primary", use_container_width=True, key="btn_ai_search"):

        if ai_query.strip():

            st.session_state["ai_search_trigger"] = ai_query

            st.session_state["ai_search_query"] = ai_query

            st.rerun()

        else:

            st.warning("Veuillez saisir une question")

with ai_col3:

    def _reset_ai_search():

        # Keep ai_search_history intact - only reset current input/display

        st.session_state["ai_search_query"] = ""

        st.session_state["ai_search_input"] = ""

        st.session_state["ai_search_trigger"] = None

        st.session_state["ai_search_result"] = {}

        st.session_state["ai_search_show_result"] = False

        st.session_state["qa_nav_tab"] = None

        st.session_state["qa_nav_element"] = None

        st.session_state["qa_nav_highlight"] = None

        st.session_state["_needs_rerun"] = True

    st.button("🗑️ Reset", use_container_width=True, key="btn_ai_search_reset", on_click=_reset_ai_search)

    if st.session_state.pop("_needs_rerun", False):

        st.rerun()



st.html('</div>')



# Handle AI Search Trigger

if st.session_state.get("ai_search_trigger"):

    query = st.session_state["ai_search_trigger"]

    st.session_state["ai_search_trigger"] = None  # Clear trigger



    result = generate_ai_search_answer(query)

    st.session_state["ai_search_result"] = result

    st.session_state["ai_search_show_result"] = True



    # Set navigation if applicable

    if result.get("nav_tab") is not None:

        st.session_state["qa_nav_tab"] = result["nav_tab"]

        st.session_state["qa_nav_element"] = result.get("nav_element")

        st.session_state["qa_nav_highlight"] = None



# Display AI Search Results

if st.session_state.get("ai_search_show_result", False):

    result = st.session_state.get("ai_search_result", {})

    solutions = result.get("solutions", [])



    if solutions:

        st.html(f"<div style='color:#F58220; font-size:0.9rem; font-weight:600; margin:16px 0 12px 0;'>🤖 {len(solutions)} solution(s) trouvée(s) pour : '<i>{result.get('query', '')}</i>'</div>")



        for sol in solutions:

            st.html(f"""

            <div class='ai-solution-card'>

                <span class='ai-search-badge {sol['badge']}'>{sol['badge_text']}</span>

                <div class='ai-solution-title'>{sol['title']}</div>

                <div class='ai-solution-desc'>{sol['desc']}</div>

                <div class='ai-solution-source'>📚 {sol['source']}</div>

                <div class='ai-solution-impact'>{sol['impact']}</div>

            </div>

            """)



# AI Search History - ALWAYS displayed independently of current results

if st.session_state.get("ai_search_history") and len(st.session_state["ai_search_history"]) > 0:

    with st.expander("📜 Historique Recherches AI", expanded=False):

        for i, item in enumerate(reversed(st.session_state["ai_search_history"][-10:])):

            idx = len(st.session_state["ai_search_history"]) - 1 - i

            with st.container():

                st.html(f"<div class='history-item-box'>"

                            f"<div class='history-item-question'><b style='color:#1E4D8F;'>{item['timestamp']}</b> — {item['query']}</div>"

                            f"<div class='history-item-answer'>{item['solutions_count']} solution(s) trouvée(s)</div>"

                            f"</div>")

                cols = st.columns([4, 1])

                with cols[1]:

                    def _restore_ai(idx=idx):

                        hist_item = st.session_state["ai_search_history"][idx]

                        st.session_state["ai_search_query"] = hist_item["query"]

                        st.session_state["ai_search_show_result"] = True

                        if "full_result" in hist_item:

                            st.session_state["ai_search_result"] = hist_item["full_result"]

                        else:

                            st.session_state["ai_search_trigger"] = hist_item["query"]

                        if hist_item.get("nav_tab") is not None:

                            st.session_state["qa_nav_tab"] = hist_item["nav_tab"]

                            st.session_state["qa_nav_element"] = hist_item.get("nav_element")

                    st.button("📂 Voir", key=f"btn_restore_ai_{idx}", use_container_width=True, on_click=_restore_ai)

