if st.session_state.get("show_infographic", False):

    with st.container():

        st.html("<div class='infographic-section'>")

        c1, c2, c3 = st.columns([0.7, 0.15, 0.15])

        with c1:

            _info_scen = st.session_state.get("active_scenario", "Base")

            _info_opt_map = {"max_profit": "Max Profit", "min_cost": "Min Coût", "max_volume": "Max Volume", "max_ebitda": "Max EBITDA"}

            _info_opt = _info_opt_map.get(st.session_state.get("lp_objective", "max_profit"), "Max Profit")

            st.html(f"<h3>📊 Business Model (Budget Planification Tool) : Synthèse Analytique des Résultats — Scénario {_info_scen}, Optimisation {_info_opt}</h3>")

            _info_obj_txt = (

                f"🎯 Objectifs Budget — CA: {get_val('budget_revenue')/1e9:.2f} Mds/mois | "

                f"Volume: {get_val('budget_volume')/1e3:.0f} kt/mois | "

                f"EBITDA: {get_val('budget_ebitda')/1e9:.2f} Mds/mois | "

                f"Marge: {get_val('budget_ebitda_margin')*100:.1f}% | "

                f"RN cible: {get_val('budget_net_income')/1e9:.2f} Mds/mois"

            )

            st.html(f"<p style='color:#5B6770; font-size:0.85rem;'>{_info_obj_txt}</p>")

        # Sélecteur de granularité (dans le flux principal, pas dans generate_html_report)
