def get_historical_month(year, month):

    """Get historical financial data for a specific month."""

    key = f"{year}-{month:02d}"

    return HISTORICAL_FINANCIAL_DATA.get(key, None)



def get_historical_annual_summary(year):

    """Get annual summary for a specific year."""

    return HISTORICAL_ANNUAL_SUMMARY.get(year, None)



def get_historical_seasonal_factor(month):

    """Get seasonal factor from actual historical data (1-12)."""

    return HISTORICAL_SEASONAL_FACTORS.get(month, 1.0)



def compute_historical_variance_current():

    """Compare current model results with latest historical actuals (2025-2026)."""

    # Get latest 12 months of historical data

    latest_months = []

    for year in [2025, 2026]:

        for month in range(1, 13):

            key = f"{year}-{month:02d}"

            if key in HISTORICAL_FINANCIAL_DATA:

                data = HISTORICAL_FINANCIAL_DATA[key]

                if data["ca_reel"] > 0:  # Only include months with actual data

                    latest_months.append({

                        "year": year, "month": month, **data

                    })



    if not latest_months:

        return None



    # Compute averages

    avg_ca = sum(m["ca_reel"] for m in latest_months) / len(latest_months)

    avg_ebitda = sum(m["ebitda_reel"] for m in latest_months) / len(latest_months)

    avg_margin = avg_ebitda / avg_ca if avg_ca > 0 else 0



    # Get current model results

    res = calculate_monthly_model()

    annual = calculate_annual_data()

    current_ca = annual["annual_revenue_total"] / 12

    current_ebitda = annual["annual_ebitda"] / 12

    current_margin = current_ebitda / current_ca if current_ca > 0 else 0



    return {

        "historical_avg_ca": avg_ca,

        "historical_avg_ebitda": avg_ebitda,

        "historical_avg_margin": avg_margin,

        "current_ca": current_ca,

        "current_ebitda": current_ebitda,

        "current_margin": current_margin,

        "variance_ca": (current_ca - avg_ca) / avg_ca if avg_ca > 0 else 0,

        "variance_ebitda": (current_ebitda - avg_ebitda) / avg_ebitda if avg_ebitda > 0 else 0,

        "variance_margin": (current_margin - avg_margin) * 100,

        "latest_months_count": len(latest_months),

        "period": f"{latest_months[0]['year']}-{latest_months[0]['month']:02d} à {latest_months[-1]['year']}-{latest_months[-1]['month']:02d}"

    }



def compute_historical_trend():

    """Compute trend analysis from historical data."""

    years = sorted(HISTORICAL_ANNUAL_SUMMARY.keys())

    trend = []

    for year in years:

        data = HISTORICAL_ANNUAL_SUMMARY[year]

        trend.append({

            "year": year,

            "ca": data["ca_reel"],

            "ebitda": data["ebitda_reel"],

            "marge": data["marge_ebitda"] * 100,

            "tro": data["tro_ca"] * 100,

        })

    return trend



def get_historical_yoy_growth():

    """Compute year-over-year growth rates."""

    years = sorted(HISTORICAL_ANNUAL_SUMMARY.keys())

    growth = []

    for i in range(1, len(years)):

        prev = HISTORICAL_ANNUAL_SUMMARY[years[i-1]]

        curr = HISTORICAL_ANNUAL_SUMMARY[years[i]]

        growth.append({

            "year": years[i],

            "ca_growth": (curr["ca_reel"] - prev["ca_reel"]) / prev["ca_reel"] * 100 if prev["ca_reel"] > 0 else 0,

            "ebitda_growth": (curr["ebitda_reel"] - prev["ebitda_reel"]) / abs(prev["ebitda_reel"]) * 100 if prev["ebitda_reel"] != 0 else 0,

            "marge_change": (curr["marge_ebitda"] - prev["marge_ebitda"]) * 100,

        })

    return growth







