# ── Périodes intermédiaires du rapport comparatif (trimestre / semestre) ──
REPORT_PERIOD_MONTHS = {
    "semester": {1: [1, 2, 3, 4, 5, 6], 2: [7, 8, 9, 10, 11, 12]},
    "quarter": {1: [1, 2, 3], 2: [4, 5, 6], 3: [7, 8, 9], 4: [10, 11, 12]},
}


def report_period_months(tf_type, month=None):
    """Mois de la période pour un type de rapport (année / semestre / trimestre / mois)."""
    if tf_type == "year":
        return list(range(1, 13))
    if tf_type in ("semester", "quarter"):
        return REPORT_PERIOD_MONTHS[tf_type].get(month, [])
    if month:
        return [month]
    return []


def prepare_historical_data(tf_type, year, month=None, sites=None, products=None):
    """Prépare et agrège les données historiques pour la période sélectionnée.

    Args:
        tf_type: "year" ou "month"
        year: année sélectionnée
        month: mois (optionnel, si tf_type="month")
        sites: liste de sites filtrés (optionnel) ex: ["Site 1", "Site 2"]
        products: liste de produits filtrés (optionnel) ex: ["CPJ 32.5", "CPJ 42.5"]

    Returns a dict with keys: ca_reel, ca_budget, ebitda_reel, ebitda_budget,
    production_t, expedition_t, volume_details, monthly_data, has_data
    """
    result = {
        "ca_reel": 0, "ca_budget": 0, "ebitda_reel": 0, "ebitda_budget": 0,
        "production_t": 0, "expedition_t": 0, "volume_details": {},
        "monthly_data": [], "has_data": False
    }

    if tf_type == "year":
        # Agréger sur l'année
        for m in range(1, 13):
            key = f"{year}-{m:02d}"
            if key in HISTORICAL_FINANCIAL_DATA:
                data = HISTORICAL_FINANCIAL_DATA[key]
                result["ca_reel"] += data.get("ca_reel", 0)
                result["ca_budget"] += data.get("ca_budget", 0)
                result["ebitda_reel"] += data.get("ebitda_reel", 0)
                result["ebitda_budget"] += data.get("ebitda_budget", 0)
                result["monthly_data"].append({
                    "month": m, "month_name": MONTHS[m-1],
                    "ca_reel": data.get("ca_reel", 0),
                    "ca_budget": data.get("ca_budget", 0),
                    "ebitda_reel": data.get("ebitda_reel", 0),
                    "ebitda_budget": data.get("ebitda_budget", 0),
                    "marge_reel": safe_div(data.get("ebitda_reel", 0), data.get("ca_reel", 0), 0),
                    "marge_budget": safe_div(data.get("ebitda_budget", 0), data.get("ca_budget", 0), 0)
                })
                result["has_data"] = True

        # Production data from HISTORICAL_DATA_2025 (only for 2025)
        if year == 2025:
            result["production_t"] = HISTORICAL_DATA_2025.get("production_total_t", 0)
            result["expedition_t"] = HISTORICAL_DATA_2025.get("expedition_total_t", 0)
            result["kc_ratio"] = HISTORICAL_DATA_2025.get("kc_ratio_pct", 69)
            result["ces_kwh"] = HISTORICAL_DATA_2025.get("ces_kwh_per_tonne", 34.42)
        elif year == 2024:
            result["production_t"] = HISTORICAL_DATA_2025.get("production_total_2024_t", 0)
            result["expedition_t"] = HISTORICAL_DATA_2025.get("expedition_total_2024_t", 0)
            result["kc_ratio"] = HISTORICAL_DATA_2025.get("kc_ratio_2024_pct", 71)
            result["ces_kwh"] = HISTORICAL_DATA_2025.get("ces_kwh_per_tonne_2024", 35.43)
        elif year in HISTORICAL_ANNUAL_SUMMARY:
            # Use annual summary if available
            ann = HISTORICAL_ANNUAL_SUMMARY[year]
            # Convert from Mds to actual values
            result["ca_reel"] = ann.get("ca_reel", 0) * 1e9
            result["ca_budget"] = ann.get("ca_budget", 0) * 1e9
            result["ebitda_reel"] = ann.get("ebitda_reel", 0) * 1e9
            result["ebitda_budget"] = ann.get("ebitda_budget", 0) * 1e9

        # Production/expédition mensuelles depuis les bases broyeur/expédition
        # (toutes années : 2022 → année en cours). Sert de repli quand les
        # agrégats annuels ne sont pas disponibles et alimente les graphiques.
        bd_prod_monthly = {}
        bd_exp_monthly = {}
        total_prod_bd = 0.0
        total_exp_bd = 0.0
        total_kwh_bd = 0.0
        total_clinker_bd = 0.0
        total_mat_bd = 0.0
        for m in range(1, 13):
            bd_key = f"{year}-{m:02d}"
            if bd_key in BD_BROYEUR_MONTHLY:
                d = BD_BROYEUR_MONTHLY[bd_key]
                p = d.get("production_t", 0) or 0
                total_prod_bd += p
                total_kwh_bd += d.get("kwh", 0) or 0
                bd_prod_monthly[MONTHS[m-1]] = {"realise": p, "budget": d.get("objectif_t", 0) or 0}
            if bd_key in BD_EXPEDITION_MONTHLY:
                d = BD_EXPEDITION_MONTHLY[bd_key]
                e = d.get("expedition_t", 0) or 0
                total_exp_bd += e
                bd_exp_monthly[MONTHS[m-1]] = {"realise": e, "budget": d.get("bud_expedition_t", 0) or 0}
            if bd_key in BD_CONSO_MATIERES_MONTHLY:
                d = BD_CONSO_MATIERES_MONTHLY[bd_key]
                total_clinker_bd += d.get("Clinker", 0) or 0
                total_mat_bd += d.get("_total_t", 0) or 0
        if total_prod_bd > 0 and result["production_t"] == 0:
            result["production_t"] = total_prod_bd
        if total_exp_bd > 0 and result["expedition_t"] == 0:
            result["expedition_t"] = total_exp_bd
        if bd_prod_monthly:
            result["production_monthly"] = bd_prod_monthly
        if bd_exp_monthly:
            result["expedition_monthly"] = bd_exp_monthly
        if total_prod_bd > 0 and total_kwh_bd > 0 and "ces_kwh" not in result:
            result["ces_kwh"] = total_kwh_bd / total_prod_bd
        if total_mat_bd > 0 and "kc_ratio" not in result:
            result["kc_ratio"] = total_clinker_bd / total_mat_bd * 100

    elif tf_type in ("semester", "quarter"):
        # Agréger les données financières sur les mois du semestre / trimestre
        period_months = report_period_months(tf_type, month)
        for m in period_months:
            key = f"{year}-{m:02d}"
            if key in HISTORICAL_FINANCIAL_DATA:
                data = HISTORICAL_FINANCIAL_DATA[key]
                result["ca_reel"] += data.get("ca_reel", 0)
                result["ca_budget"] += data.get("ca_budget", 0)
                result["ebitda_reel"] += data.get("ebitda_reel", 0)
                result["ebitda_budget"] += data.get("ebitda_budget", 0)
                result["monthly_data"].append({
                    "month": m, "month_name": MONTHS[m-1],
                    "ca_reel": data.get("ca_reel", 0),
                    "ca_budget": data.get("ca_budget", 0),
                    "ebitda_reel": data.get("ebitda_reel", 0),
                    "ebitda_budget": data.get("ebitda_budget", 0),
                    "marge_reel": safe_div(data.get("ebitda_reel", 0), data.get("ca_reel", 0), 0),
                    "marge_budget": safe_div(data.get("ebitda_budget", 0), data.get("ca_budget", 0), 0)
                })
                result["has_data"] = True

        # Production / expédition / conso sur les mois de la période (bases mensuelles)
        bd_prod_monthly = {}
        bd_exp_monthly = {}
        total_prod_bd = total_exp_bd = total_kwh_bd = total_clinker_bd = total_mat_bd = 0.0
        for m in period_months:
            bd_key = f"{year}-{m:02d}"
            if bd_key in BD_BROYEUR_MONTHLY:
                d = BD_BROYEUR_MONTHLY[bd_key]
                p = d.get("production_t", 0) or 0
                total_prod_bd += p
                total_kwh_bd += d.get("kwh", 0) or 0
                bd_prod_monthly[MONTHS[m-1]] = {"realise": p, "budget": d.get("objectif_t", 0) or 0}
            if bd_key in BD_EXPEDITION_MONTHLY:
                d = BD_EXPEDITION_MONTHLY[bd_key]
                e = d.get("expedition_t", 0) or 0
                total_exp_bd += e
                bd_exp_monthly[MONTHS[m-1]] = {"realise": e, "budget": d.get("bud_expedition_t", 0) or 0}
            if bd_key in BD_CONSO_MATIERES_MONTHLY:
                d = BD_CONSO_MATIERES_MONTHLY[bd_key]
                total_clinker_bd += d.get("Clinker", 0) or 0
                total_mat_bd += d.get("_total_t", 0) or 0
        if total_prod_bd > 0:
            result["production_t"] = total_prod_bd
            result["production_budget_t"] = sum(v.get("budget", 0) for v in bd_prod_monthly.values())
        if total_exp_bd > 0:
            result["expedition_t"] = total_exp_bd
            result["expedition_budget_t"] = sum(v.get("budget", 0) for v in bd_exp_monthly.values())
        if bd_prod_monthly:
            result["production_monthly"] = bd_prod_monthly
        if bd_exp_monthly:
            result["expedition_monthly"] = bd_exp_monthly
        if total_prod_bd > 0 and total_kwh_bd > 0:
            result["ces_kwh"] = total_kwh_bd / total_prod_bd
        if total_mat_bd > 0:
            result["kc_ratio"] = total_clinker_bd / total_mat_bd * 100

    else:  # month
        key = f"{year}-{month:02d}"
        if key in HISTORICAL_FINANCIAL_DATA:
            data = HISTORICAL_FINANCIAL_DATA[key]
            result["ca_reel"] = data.get("ca_reel", 0)
            result["ca_budget"] = data.get("ca_budget", 0)
            result["ebitda_reel"] = data.get("ebitda_reel", 0)
            result["ebitda_budget"] = data.get("ebitda_budget", 0)
            result["monthly_data"].append({
                "month": month, "month_name": MONTHS[month-1],
                "ca_reel": data.get("ca_reel", 0),
                "ca_budget": data.get("ca_budget", 0),
                "ebitda_reel": data.get("ebitda_reel", 0),
                "ebitda_budget": data.get("ebitda_budget", 0),
                "marge_reel": safe_div(data.get("ebitda_reel", 0), data.get("ca_reel", 0), 0),
                "marge_budget": safe_div(data.get("ebitda_budget", 0), data.get("ca_budget", 0), 0)
            })
            result["has_data"] = True

        # Production/expédition mensuelles (toutes années, bases broyeur/expédition)
        if key in BD_BROYEUR_MONTHLY:
            d = BD_BROYEUR_MONTHLY[key]
            result["production_t"] = d.get("production_t", 0) or 0
            result["production_budget_t"] = d.get("objectif_t", 0) or 0
            if d.get("production_t", 0) > 0 and d.get("kwh", 0) > 0:
                result["ces_kwh"] = d["kwh"] / d["production_t"]
        if key in BD_EXPEDITION_MONTHLY:
            d = BD_EXPEDITION_MONTHLY[key]
            result["expedition_t"] = d.get("expedition_t", 0) or 0
            result["expedition_budget_t"] = d.get("bud_expedition_t", 0) or 0
        if key in BD_CONSO_MATIERES_MONTHLY:
            d = BD_CONSO_MATIERES_MONTHLY[key]
            if d.get("_total_t", 0) > 0:
                result["kc_ratio"] = d.get("Clinker", 0) / d["_total_t"] * 100

    # Marges agrégées de la période (utilisées par le rapport comparatif)
    result["marge_reel"] = safe_div(result["ebitda_reel"], result["ca_reel"], 0)
    result["marge_budget"] = safe_div(result["ebitda_budget"], result["ca_budget"], 0)

    # Apply product filters if specified (filter sales volume data)
    if products and products != ["Tous"]:
        product_cols_map = {
            "CPJ 32.5": "cpj32", "CPJ 42.5": "cpj42", "CPA 42.5": "cpa42",
            "CPA 52.5": "cpa52", "MC 12.5": "mc12", "CHF": "chf"
        }
        # Filtered data is tracked in volume_details
        result["volume_details"] = {
            "filtered_products": products,
            "product_cols": [product_cols_map.get(p, p) for p in products if p in product_cols_map]
        }

    # Apply site filters if specified (track for downstream use)
    if sites and sites != ["Tous"]:
        result["filtered_sites"] = sites

    return result


def is_partial_year_period(tf_type, year, month=None):
    """Vérifie si la période sélectionnée est une année partielle (année en cours)."""
    if tf_type != "year":
        return False

    current_year = datetime.now().year
    if year != current_year:
        return False

    # Count how many months have historical data for this year
    months_with_data = 0
    for key in HISTORICAL_FINANCIAL_DATA.keys():
        if key.startswith(f"{year}-"):
            months_with_data += 1

    # If less than 12 months, it's a partial year
    return months_with_data < 12


def compute_annual_projection(hist, model, year, month=None):
    """Calcule la projection annuelle à partir des données partielles.

    Extrapole les données historiques partielles sur 12 mois.
    """
    if not hist or not hist.get("has_data", False):
        return None

    # Count months with data
    months_count = len(hist.get("monthly_data", []))
    if months_count == 0:
        return None

    # Extrapolation factor
    factor = 12.0 / months_count

    projection = {
        "ca_reel": hist.get("ca_reel", 0) * factor,
        "ca_budget": hist.get("ca_budget", 0) * factor,
        "ebitda_reel": hist.get("ebitda_reel", 0) * factor,
        "ebitda_budget": hist.get("ebitda_budget", 0) * factor,
        "production_t": hist.get("production_t", 0) * factor,
        "expedition_t": hist.get("expedition_t", 0) * factor,
        "months_count": months_count,
        "factor": factor,
        "marge_ebitda_reel": safe_div(hist.get("ebitda_reel", 0) * factor, hist.get("ca_reel", 0) * factor, 0),
        "marge_ebitda_budget": safe_div(hist.get("ebitda_budget", 0) * factor, hist.get("ca_budget", 0) * factor, 0),
    }

    return projection


def generate_corrective_actions(comparison):
    """Génère les actions correctives basées sur la comparaison historique vs modèle."""
    actions = []

    if not comparison:
        return actions

    ca_gap = comparison.get("ca_gap_pct", 0)
    ebitda_gap = comparison.get("ebitda_gap_pct", 0)
    volume_gap = comparison.get("volume_gap_pct", 0)

    if ca_gap < -10:
        actions.append({
            "priority": "HIGH",
            "category": "Revenus",
            "action": "Analyser la sous-performance du CA : vérifier les prix de vente, le mix produit, et la part de marché",
            "impact": "Potentiel de récupération : " + format_xof(abs(comparison.get("ca_gap", 0)))
        })

    if ebitda_gap < -15:
        actions.append({
            "priority": "HIGH", 
            "category": "Rentabilité",
            "action": "Urgence rentabilité : revoir la structure des coûts fixes, négocier le clinker, optimiser l'énergie",
            "impact": "Potentiel de récupération : " + format_xof(abs(comparison.get("ebitda_gap", 0)))
        })
    elif ebitda_gap < -5:
        actions.append({
            "priority": "MEDIUM",
            "category": "Rentabilité", 
            "action": "Optimiser la marge EBITDA : revoir les coûts variables (clinker, énergie, transport)",
            "impact": "Potentiel de récupération : " + format_xof(abs(comparison.get("ebitda_gap", 0)))
        })

    if volume_gap < -10:
        actions.append({
            "priority": "MEDIUM",
            "category": "Volumes",
            "action": "Augmenter les volumes : analyser la demande marché, ajuster la production, optimiser la force commerciale",
            "impact": "Potentiel de volume : " + format_tonnes(abs(comparison.get("volume_gap", 0)))
        })

    if ca_gap > 5 and ebitda_gap > 5:
        actions.append({
            "priority": "LOW",
            "category": "Performance",
            "action": "Performance supérieure aux attentes : capitaliser sur les leviers de succès, sécuriser les gains",
            "impact": "Maintenir la tendance positive"
        })

    if not actions:
        actions.append({
            "priority": "INFO",
            "category": "Général",
            "action": "La performance est alignée avec les attentes. Continuer le suivi régulier.",
            "impact": "Aucune action corrective nécessaire"
        })

    return actions


def generate_historical_comparison_report_tab(timeframe_type, selected_year, selected_month=None, include_projection=True, detail_view="mensuel"):

    """Génère le rapport comparatif historique avec projections."""



    # Préparer les données

    hist = prepare_historical_data(timeframe_type, selected_year, selected_month)



    # Récupérer les données du modèle pour la même période

    model_data = get_model_data_for_period(timeframe_type, selected_year, selected_month)



    # Calculer la projection si année partielle (toujours actif par défaut)

    projection = None

    if is_partial_year_period(timeframe_type, selected_year, selected_month):

        try:

            projection = compute_annual_projection(hist, model_data, selected_year, selected_month, timeframe_type)

        except Exception as e:

            st.warning(f"Erreur lors du calcul de la projection: {e}")

            projection = None



    # Calculer la comparaison

    comparison = compute_historical_model_comparison(hist, model_data)



    # Générer les actions correctives

    actions = generate_corrective_actions(comparison)



    # Générer le rapport HTML

    current_year = datetime.now().year

    current_month = datetime.now().month

    return build_historical_report_html(timeframe_type, selected_year, selected_month, hist, model_data, comparison, projection, current_year, current_month, detail_view)


def get_historical_data_for_period(tf_type, year, month):

    """Récupère les données historiques pour la période sélectionnée."""

    

    result = {

        "ca_reel": 0, "ca_budget": 0, "ebitda_reel": 0, "ebitda_budget": 0,

        "production_t": 0, "expedition_t": 0, "volume_details": {},

        "monthly_data": [], "has_data": False

    }

    

    if tf_type == "year":

        # Agréger sur l'année

        for m in range(1, 13):

            key = f"{year}-{m:02d}"

            if key in HISTORICAL_FINANCIAL_DATA:

                data = HISTORICAL_FINANCIAL_DATA[key]

                result["ca_reel"] += data["ca_reel"]

                result["ca_budget"] += data["ca_budget"]

                result["ebitda_reel"] += data["ebitda_reel"]

                result["ebitda_budget"] += data["ebitda_budget"]

                result["monthly_data"].append({

                    "month": m, "month_name": MONTHS[m-1],

                    **data,

                    "marge_reel": data["ebitda_reel"] / data["ca_reel"] if data["ca_reel"] != 0 else 0,

                    "marge_budget": data["ebitda_budget"] / data["ca_budget"] if data["ca_budget"] != 0 else 0

                })

                result["has_data"] = True

        

        # Données production/expédition 2025

        if year == 2025:

            result["production_t"] = HISTORICAL_DATA_2025.get("production_total_t", 0)

            result["expedition_t"] = HISTORICAL_DATA_2025.get("expedition_total_t", 0)

            result["kc_ratio"] = HISTORICAL_DATA_2025.get("kc_ratio_pct", 69)

            result["ces_kwh"] = HISTORICAL_DATA_2025.get("ces_kwh_per_tonne", 34.42)

            result["production_monthly"] = HISTORICAL_DATA_2025.get("production_monthly", {})

            result["expedition_monthly"] = HISTORICAL_DATA_2025.get("expedition_monthly", {})

            

        elif year == 2024:

            result["production_t"] = HISTORICAL_DATA_2025.get("production_total_2024_t", 0)

            result["expedition_t"] = HISTORICAL_DATA_2025.get("expedition_total_2024_t", 0)

            result["kc_ratio"] = HISTORICAL_DATA_2025.get("kc_ratio_2024_pct", 71)

            result["ces_kwh"] = HISTORICAL_DATA_2025.get("ces_kwh_per_tonne_2024", 35.43)

            

    else:  # month

        key = f"{year}-{month:02d}"

        if key in HISTORICAL_FINANCIAL_DATA:

            data = HISTORICAL_FINANCIAL_DATA[key]

            result["ca_reel"] = data["ca_reel"]

            result["ca_budget"] = data["ca_budget"]

            result["ebitda_reel"] = data["ebitda_reel"]

            result["ebitda_budget"] = data["ebitda_budget"]

            result["monthly_data"] = [{

                "month": month, "month_name": MONTHS[month-1],

                **data,

                "marge_reel": data["ebitda_reel"] / data["ca_reel"] if data["ca_reel"] != 0 else 0,

                "marge_budget": data["ebitda_budget"] / data["ca_budget"] if data["ca_budget"] != 0 else 0

            }]

            result["has_data"] = True

            

            # Données mensuelles production 2025

            if year == 2025:

                month_name = MONTHS[month-1]

                if month_name in HISTORICAL_DATA_2025.get("production_monthly", {}):

                    pm = HISTORICAL_DATA_2025["production_monthly"][month_name]

                    result["production_t"] = pm.get("realise", 0)

                    result["production_budget_t"] = pm.get("budget", 0)

                if month_name in HISTORICAL_DATA_2025.get("expedition_monthly", {}):

                    em = HISTORICAL_DATA_2025["expedition_monthly"][month_name]

                    result["expedition_t"] = em.get("realise", 0)

                    result["expedition_budget_t"] = em.get("budget", 0)

    

    # Calcul des marges agrégées

    if result["ca_reel"] != 0:

        result["marge_reel"] = result["ebitda_reel"] / result["ca_reel"]

    else:

        result["marge_reel"] = 0

        

    if result["ca_budget"] != 0:

        result["marge_budget"] = result["ebitda_budget"] / result["ca_budget"]

    else:

        result["marge_budget"] = 0

    

    result["ecart_ca"] = result["ca_reel"] - result["ca_budget"]

    result["ecart_ebitda"] = result["ebitda_reel"] - result["ebitda_budget"]

    result["ecart_marge"] = result["marge_reel"] - result["marge_budget"]

    

    # Compute production and expedition from monthly data for all years
    if tf_type == "year":
        total_prod = 0
        total_exp = 0
        for month in range(1, 13):
            month_key = f"{year}-{month:02d}"
            if month_key in BD_BROYEUR_MONTHLY:
                for dex_name, dex_data in BD_BROYEUR_MONTHLY[month_key].items():
                    if isinstance(dex_data, dict):
                        for prod, val in dex_data.items():
                            if prod not in ("TOTAL MATIERES", "Mills", "Mill_1", "Mill_2", "total", "_total", "Mix", "mix", "A", "B", "_by_broyeur"):
                                if isinstance(val, (int, float)) and val > 0:
                                    total_prod += val
            if month_key in BD_EXPEDITION_MONTHLY:
                for exp_type, exp_data in BD_EXPEDITION_MONTHLY[month_key].items():
                    if isinstance(exp_data, dict):
                        for prod, val in exp_data.items():
                            if prod not in ("total_jour", "total_sacs", "total_vracs", "total_big_bag", "_source", "_combined_total"):
                                if isinstance(val, (int, float)) and val > 0:
                                    total_exp += val
        if total_prod > 0:
            result["production_t"] = total_prod
        if total_exp > 0:
            result["expedition_t"] = total_exp

    

    # Données annuelles summary si disponible

    if year in HISTORICAL_ANNUAL_SUMMARY:

        result["annual_summary"] = HISTORICAL_ANNUAL_SUMMARY[year]

    

    return result





def get_model_data_for_period(tf_type, year, month):
    """Récupère les données du modèle pour la période correspondante.

    CRITICAL: When comparing to historical data, the model data MUST use
    the SAME timeframe. If historical only has Jan-Apr 2026, the model
    should only return Jan-Apr data, not the full 12-month projection.
    """

    # Determine which months have historical data for this year
    months_with_hist = set()
    for key in HISTORICAL_FINANCIAL_DATA.keys():
        if key.startswith(f"{year}-"):
            m = int(key.split("-")[1])
            months_with_hist.add(m)

    # Calculate model data
    annual = calculate_annual_data()
    res = calculate_monthly_model()

    result = {
        "ca": 0, "ebitda": 0, "net_income": 0,
        "production_t": 0, "volume_by_product": {},
        "marge_ebitda": 0, "marge_net": 0,
        "monthly_data": [], "has_data": True
    }

    if tf_type == "year":
        # For year mode: ONLY sum model data for months that have historical data
        # This ensures apples-to-apples comparison
        if months_with_hist:
            valid_months = sorted(months_with_hist)

            for m_idx in valid_months:
                m_idx_0based = m_idx - 1
                if 0 <= m_idx_0based < len(annual["monthly"]):
                    m_data = annual["monthly"][m_idx_0based]
                    result["ca"] += m_data.get("total_revenue", 0)
                    result["ebitda"] += m_data.get("ebitda", 0)
                    result["net_income"] += m_data.get("net_income", 0)
                    result["production_t"] += m_data.get("grand_total", 0)

                    # Accumulate volume by product
                    for p, vol in m_data.get("total_prod", {}).items():
                        result["volume_by_product"][p] = result["volume_by_product"].get(p, 0) + vol

                    result["monthly_data"].append({
                        "month": m_idx,
                        "month_name": MONTHS[m_idx_0based],
                        "ca": m_data.get("total_revenue", 0),
                        "ebitda": m_data.get("ebitda", 0),
                        "net_income": m_data.get("net_income", 0),
                        "production": m_data.get("grand_total", 0),
                        "marge_ebitda": m_data.get("ebitda_pct", 0),
                        "marge_net": m_data.get("net_margin_pct", 0)
                    })

            result["marge_ebitda"] = safe_div(result["ebitda"], result["ca"], 0)
            result["marge_net"] = safe_div(result["net_income"], result["ca"], 0)
        else:
            # No historical data for this year - return full annual model as fallback
            result["ca"] = annual["annual_revenue_total"]
            result["ebitda"] = annual["annual_ebitda"]
            result["net_income"] = annual["annual_net_income"]
            result["production_t"] = sum(annual["annual_prod"].values())
            result["volume_by_product"] = annual["annual_prod"]
            result["marge_ebitda"] = safe_div(annual["annual_ebitda"], annual["annual_revenue_total"], 0)
            result["marge_net"] = safe_div(annual["annual_net_income"], annual["annual_revenue_total"], 0)

            for m_idx, m_data in enumerate(annual["monthly"]):
                result["monthly_data"].append({
                    "month": m_idx + 1,
                    "month_name": MONTHS[m_idx],
                    "ca": m_data.get("total_revenue", 0),
                    "ebitda": m_data.get("ebitda", 0),
                    "net_income": m_data.get("net_income", 0),
                    "production": m_data.get("grand_total", 0),
                    "marge_ebitda": m_data.get("ebitda_pct", 0),
                    "marge_net": m_data.get("net_margin_pct", 0)
                })

    elif tf_type in ("semester", "quarter"):
        # Semestre / trimestre : somme du modèle sur les mois de la période
        period_months = report_period_months(tf_type, month)
        # Comparaison à périmètre constant : restreindre aux mois ayant des données historiques
        valid_months = [m for m in period_months if m in months_with_hist] or period_months
        for m_idx in valid_months:
            m_idx_0based = m_idx - 1
            if 0 <= m_idx_0based < len(annual["monthly"]):
                m_data = annual["monthly"][m_idx_0based]
                result["ca"] += m_data.get("total_revenue", 0)
                result["ebitda"] += m_data.get("ebitda", 0)
                result["net_income"] += m_data.get("net_income", 0)
                result["production_t"] += m_data.get("grand_total", 0)
                for p, vol in m_data.get("total_prod", {}).items():
                    result["volume_by_product"][p] = result["volume_by_product"].get(p, 0) + vol
                result["monthly_data"].append({
                    "month": m_idx,
                    "month_name": MONTHS[m_idx_0based],
                    "ca": m_data.get("total_revenue", 0),
                    "ebitda": m_data.get("ebitda", 0),
                    "net_income": m_data.get("net_income", 0),
                    "production": m_data.get("grand_total", 0),
                    "marge_ebitda": m_data.get("ebitda_pct", 0),
                    "marge_net": m_data.get("net_margin_pct", 0)
                })
        result["marge_ebitda"] = safe_div(result["ebitda"], result["ca"], 0)
        result["marge_net"] = safe_div(result["net_income"], result["ca"], 0)

    else:  # month
        # Mois spécifique du modèle
        m_idx = month - 1
        if 0 <= m_idx < 12:
            m_data = annual["monthly"][m_idx] if m_idx < len(annual["monthly"]) else calculate_monthly_model(m_idx)
            result["ca"] = m_data.get("total_revenue", 0)
            result["ebitda"] = m_data.get("ebitda", 0)
            result["net_income"] = m_data.get("net_income", 0)
            result["production_t"] = m_data.get("grand_total", 0)
            result["volume_by_product"] = m_data.get("total_prod", {})
            result["marge_ebitda"] = m_data.get("ebitda_pct", 0)
            result["marge_net"] = m_data.get("net_margin_pct", 0)
            result["monthly_data"] = [{
                "month": month,
                "month_name": MONTHS[month-1],
                "ca": result["ca"],
                "ebitda": result["ebitda"],
                "net_income": result["net_income"],
                "production": result["production_t"],
                "marge_ebitda": result["marge_ebitda"],
                "marge_net": result["marge_net"]
            }]

    return result





def compute_historical_model_comparison(hist, model):

    """Calcule les écarts entre données historiques, budget et modèle.
    
    Performance logic:
    - Historique > Budget → Performance SUPÉRIEURE (better than budget)
    - Historique > Modèle → Performance SUPÉRIEURE (better than model)
    - Budget > Modèle → Objectifs AMBITIEUX
    - Budget < Modèle → Objectifs CONSERVATEURS
    """

    # Calculate Marge EBITDA = EBITDA / CA (if not already provided)
    hist_marge = hist.get("marge_reel", 0)
    if hist_marge == 0 and hist.get("ca_reel", 0) > 0:
        hist_marge = safe_div(hist["ebitda_reel"], hist["ca_reel"], 0)
    # Persist computed margin back into hist dict for HTML builder access
    hist["marge_reel"] = hist_marge
    
    model_marge = model.get("marge_ebitda", 0)
    if model_marge == 0 and model.get("ca", 0) > 0:
        model_marge = safe_div(model["ebitda"], model["ca"], 0)
    # Persist computed margin back into model dict
    model["marge_ebitda"] = model_marge
    
    # Budget values
    hist_budget_ca = hist.get("ca_budget", 0)
    hist_budget_ebitda = hist.get("ebitda_budget", 0)
    hist_budget_marge = hist.get("marge_budget", 0)
    if hist_budget_marge == 0 and hist_budget_ca > 0:
        hist_budget_marge = safe_div(hist_budget_ebitda, hist_budget_ca, 0)

    comparison = {

        "ca": {

            "hist": hist["ca_reel"],
            "budget": hist_budget_ca,
            "model": model["ca"],
            "ecart_model_abs": model["ca"] - hist["ca_reel"],
            "ecart_model_pct": safe_div(model["ca"] - hist["ca_reel"], hist["ca_reel"], 0) * 100 if hist["ca_reel"] != 0 else 0,
            "ecart_budget_pct": safe_div(hist["ca_reel"] - hist_budget_ca, hist_budget_ca, 0) * 100 if hist_budget_ca > 0 else 0,
            "ecart_pct": safe_div(model["ca"] - hist["ca_reel"], hist["ca_reel"], 0) * 100 if hist["ca_reel"] != 0 else 0,

        },

        "ebitda": {

            "hist": hist["ebitda_reel"],
            "budget": hist_budget_ebitda,
            "model": model["ebitda"],
            "ecart_model_abs": model["ebitda"] - hist["ebitda_reel"],
            "ecart_model_pct": safe_div(model["ebitda"] - hist["ebitda_reel"], hist["ebitda_reel"], 0) * 100 if hist["ebitda_reel"] != 0 else 0,
            "ecart_budget_pct": safe_div(hist["ebitda_reel"] - hist_budget_ebitda, hist_budget_ebitda, 0) * 100 if hist_budget_ebitda > 0 else 0,
            "ecart_pct": safe_div(model["ebitda"] - hist["ebitda_reel"], hist["ebitda_reel"], 0) * 100 if hist["ebitda_reel"] != 0 else 0,

        },

        "marge_ebitda": {

            "hist": hist_marge * 100,
            "budget": hist_budget_marge * 100,
            "model": model_marge * 100,
            "ecart_abs": (model_marge - hist_marge) * 100,
            "ecart_model_abs": (model_marge - hist_marge) * 100,
            "ecart_budget_abs": (hist_marge - hist_budget_marge) * 100,
            "ecart_pct": 0

        },

        "production": {

            "hist": hist.get("production_t", 0),
            "model": model.get("production_t", 0),
            "ecart_abs": model.get("production_t", 0) - hist.get("production_t", 0),
            "ecart_pct": safe_div(model.get("production_t", 0) - hist.get("production_t", 0), hist.get("production_t", 1), 0) * 100

        },

        "performance_status": "NEUTRE",
        "objective_status": "NEUTRE",
        "gap_analysis": []

    }

    

    # Déterminer le statut de performance (Historique vs Budget ET Historique vs Modèle)
    ebitda_vs_budget = comparison["ebitda"]["ecart_budget_pct"]  # Positive = hist > budget = better
    ebitda_vs_model = -comparison["ebitda"]["ecart_model_pct"]  # Positive = hist > model = better
    
    if ebitda_vs_budget > 5 and ebitda_vs_model > 5:
        comparison["performance_status"] = "SUPÉRIEUR"
    elif ebitda_vs_budget < -5 and ebitda_vs_model < -5:
        comparison["performance_status"] = "INFÉRIEUR"
    elif ebitda_vs_budget > 5:
        comparison["performance_status"] = "SUP. vs BUDGET"
    elif ebitda_vs_model > 5:
        comparison["performance_status"] = "SUP. vs MODÈLE"
    elif ebitda_vs_budget < -5:
        comparison["performance_status"] = "INF. vs BUDGET"
    elif ebitda_vs_model < -5:
        comparison["performance_status"] = "INF. vs MODÈLE"
    else:
        comparison["performance_status"] = "CONFORME"
    
    # Déterminer le statut des objectifs (Budget vs Modèle)
    budget_vs_model_ca = safe_div(hist_budget_ca - model["ca"], model["ca"], 0) * 100 if model["ca"] > 0 else 0
    if budget_vs_model_ca > 10:
        comparison["objective_status"] = "AMBITIEUX"
    elif budget_vs_model_ca < -10:
        comparison["objective_status"] = "CONSERVATEURS"
    else:
        comparison["objective_status"] = "ALIGNÉS"

    

    # Analyse des écarts significatifs

    if abs(comparison["ca"]["ecart_budget_pct"]) > 10:

        comparison["gap_analysis"].append({

            "type": "CA",

            "severity": "HIGH" if abs(comparison["ca"]["ecart_budget_pct"]) > 20 else "MEDIUM",

            "message": f"CA {comparison['ca']['ecart_budget_pct']:+.1f}% vs budget : {'surperformance' if comparison['ca']['ecart_budget_pct'] > 0 else 'sous-performance'}"

        })

    

    if abs(comparison["ebitda"]["ecart_budget_pct"]) > 15:

        comparison["gap_analysis"].append({

            "type": "EBITDA",

            "severity": "HIGH" if abs(comparison["ebitda"]["ecart_budget_pct"]) > 30 else "MEDIUM",

            "message": f"EBITDA {comparison['ebitda']['ecart_budget_pct']:+.1f}% vs budget : {'rentabilité supérieure' if comparison['ebitda']['ecart_budget_pct'] > 0 else 'alerte rentabilité'}"

        })

    

    if abs(comparison["marge_ebitda"]["ecart_budget_abs"]) > 2:

        comparison["gap_analysis"].append({

            "type": "MARGE",

            "severity": "HIGH" if abs(comparison["marge_ebitda"]["ecart_budget_abs"]) > 5 else "MEDIUM",

            "message": f"Marge EBITDA {comparison['marge_ebitda']['ecart_budget_abs']:+.1f} pts vs budget"

        })

    

    return comparison





def is_partial_year_period(timeframe_type, selected_year, selected_month=None):

    """Détermine si la période sélectionnée est une année partielle (en cours).



    Retourne True si l'année sélectionnée a des données historiques partielles

    (moins de 12 mois), ce qui nécessite une projection pour les mois restants.

    """



    if timeframe_type == "month":

        return False

    if timeframe_type in ("semester", "quarter"):

        # Partiel si un ou plusieurs mois de la période n'ont pas encore de données réelles

        period_months = report_period_months(timeframe_type, selected_month)

        months_with_data = {int(k.split("-")[1]) for k in HISTORICAL_FINANCIAL_DATA.keys() if k.startswith(f"{selected_year}-")}

        return any(m not in months_with_data for m in period_months)



    # Compter les mois avec données historiques réelles

    months_with_data = sum(1 for k in HISTORICAL_FINANCIAL_DATA.keys() if k.startswith(f"{selected_year}-"))



    # C'est une année partielle si nous avons des données mais moins de 12 mois

    # Cela inclut l'année en cours ET les années récentes avec données incomplètes

    return 0 < months_with_data < 12


def compute_annual_projection(hist, model, year, month, tf_type="year"):

    """Calcule la projection annuelle basée sur la période partielle.



    Utilise le nombre réel de mois avec données historiques pour déterminer

    la période réalisée et projeter les mois restants avec ajustement saisonnier.

    Pour un semestre / trimestre : annualisation de la période (ajustement saisonnier).

    """


    # Cas semestre / trimestre : annualisation de la période avec ajustement saisonnier

    if tf_type in ("semester", "quarter"):

        period_months = report_period_months(tf_type, month)

        period_len = len(period_months)

        if period_len == 0 or not hist or not hist.get("has_data", False):

            return None

        avg_monthly_ca = hist.get("ca_reel", 0) / period_len

        avg_monthly_ebitda = hist.get("ebitda_reel", 0) / period_len

        seasonal_factors = HISTORICAL_SEASONAL_FACTORS

        projected_ca = 0

        projected_ebitda = 0

        for m in range(1, 13):

            if m in period_months:

                continue

            factor = seasonal_factors.get(m, 1.0)

            projected_ca += avg_monthly_ca * factor

            projected_ebitda += avg_monthly_ebitda * factor

        total_projected_ca = hist.get("ca_reel", 0) + projected_ca

        total_projected_ebitda = hist.get("ebitda_reel", 0) + projected_ebitda

        hist_annual = HISTORICAL_ANNUAL_SUMMARY.get(year, {})

        hist_ca = hist_annual.get("ca_reel", 0) * 1e9

        hist_ebitda = hist_annual.get("ebitda_reel", 0) * 1e9

        return {

            "months_elapsed": period_len,

            "months_remaining": 12 - period_len,

            "avg_monthly_ca": avg_monthly_ca,

            "avg_monthly_ebitda": avg_monthly_ebitda,

            "projected_ca_remaining": projected_ca,

            "projected_ebitda_remaining": projected_ebitda,

            "total_projected_ca": total_projected_ca,

            "total_projected_ebitda": total_projected_ebitda,

            "vs_historical_ca": safe_div(total_projected_ca - hist_ca, hist_ca, 0) * 100 if hist_ca > 0 else 0,

            "vs_historical_ebitda": safe_div(total_projected_ebitda - hist_ebitda, hist_ebitda, 0) * 100 if hist_ebitda > 0 else 0,

            "seasonal_adjustment": True,

            "confidence": "MOYENNE" if period_len >= 3 else "FAIBLE"

        }



    # Compter les mois avec données historiques réelles pour l'année sélectionnée

    months_with_data = sum(1 for k in HISTORICAL_FINANCIAL_DATA.keys() if k.startswith(f"{year}-"))



    # Utiliser le nombre réel de mois avec données comme mois écoulés

    # Cela garantit que la projection est basée sur les données disponibles

    months_elapsed = months_with_data if months_with_data > 0 else datetime.now().month



    # Données mensuelles moyennes du modèle (basées sur les mois réalisés)

    avg_monthly_ca = model["ca"] / max(months_elapsed, 1)

    avg_monthly_ebitda = model["ebitda"] / max(months_elapsed, 1)



    # Projection pour les mois restants

    months_remaining = 12 - months_elapsed



    # Application du facteur saisonnier historique

    seasonal_factors = HISTORICAL_SEASONAL_FACTORS



    projected_ca = 0

    projected_ebitda = 0

    for m in range(months_elapsed + 1, 13):

        factor = seasonal_factors.get(m, 1.0)

        projected_ca += avg_monthly_ca * factor

        projected_ebitda += avg_monthly_ebitda * factor



    # Total annuel projeté = réalisé + projeté

    total_projected_ca = model["ca"] + projected_ca

    total_projected_ebitda = model["ebitda"] + projected_ebitda



    # Comparaison avec historique/budget

    hist_annual = HISTORICAL_ANNUAL_SUMMARY.get(year, {})

    hist_ca = hist_annual.get("ca_reel", 0) * 1e9

    hist_ebitda = hist_annual.get("ebitda_reel", 0) * 1e9



    return {

        "months_elapsed": months_elapsed,

        "months_remaining": months_remaining,

        "avg_monthly_ca": avg_monthly_ca,

        "avg_monthly_ebitda": avg_monthly_ebitda,

        "projected_ca_remaining": projected_ca,

        "projected_ebitda_remaining": projected_ebitda,

        "total_projected_ca": total_projected_ca,

        "total_projected_ebitda": total_projected_ebitda,

        "vs_historical_ca": safe_div(total_projected_ca - hist_ca, hist_ca, 0) * 100 if hist_ca > 0 else 0,

        "vs_historical_ebitda": safe_div(total_projected_ebitda - hist_ebitda, hist_ebitda, 0) * 100 if hist_ebitda > 0 else 0,

        "seasonal_adjustment": True,

        "confidence": "MOYENNE" if months_elapsed >= 3 else "FAIBLE"

    }


def generate_corrective_actions(comparison, projection=None):

    """Génère des suggestions d'actions correctives basées sur les écarts."""

    

    actions = []

    ca_ecart_pct = comparison.get("ca", {}).get("ecart_pct", 0)
    ca_ecart_abs = comparison.get("ca", {}).get("ecart_abs", 0)
    ebitda_ecart_pct = comparison.get("ebitda", {}).get("ecart_pct", 0)
    ebitda_ecart_abs = comparison.get("ebitda", {}).get("ecart_abs", 0)

    # Actions basées sur les écarts CA

    if ca_ecart_pct < -10:

        actions.append({

            "priority": "HAUTE",

            "category": "COMMERCIAL",

            "icon": "📈",

            "title": "Relance des volumes de vente",

            "description": f"Le CA modèle est {abs(ca_ecart_pct):.1f}% inférieur à l'historique. Actions recommandées : intensification force commerciale, relance grands comptes BTP, promotion CPJ 32.5 saison pluie.",

            "impact": f"Potentiel de récupération : {format_xof(abs(ca_ecart_abs))}",

            "timeline": "Immédiat (2-4 semaines)"

        })

    

    elif ca_ecart_pct > 15:

        actions.append({

            "priority": "MOYENNE",

            "category": "PRODUCTION",

            "icon": "🏭",

            "title": "Anticipation capacité production",

            "description": "Surperformance CA supérieure à l'historique. Vérifier capacité de production et stocks pour satisfaire la demande accrue.",

            "impact": "Risque rupture de stock si non anticipé",

            "timeline": "Court terme (1-2 mois)"

        })

    

    # Actions basées sur les écarts EBITDA

    if ebitda_ecart_pct < -15:

        actions.append({

            "priority": "CRITIQUE",

            "category": "FINANCIER",

            "icon": "💰",

            "title": "Plan d'urgence rentabilité",

            "description": f"EBITDA {abs(ebitda_ecart_pct):.1f}% sous historique. Négociation clinker, optimisation énergie, réduction coûts fixes.",

            "impact": f"Potentiel : {format_xof(abs(ebitda_ecart_abs))}",

            "timeline": "Urgent (1-4 semaines)"

        })

        

        actions.append({

            "priority": "HAUTE",

            "category": "COÛTS",

            "icon": "⚡",

            "title": "Réduction consommation énergétique",

            "description": "Analyser kWh/t par produit et site. Cible : CPA < 35 kWh/t, CPJ42 < 32 kWh/t, CPJ32 < 30 kWh/t.",

            "impact": f"Économie potentielle : {format_xof(500000000)}",

            "timeline": "Moyen terme (1-3 mois)"

        })

    

    # Actions basées sur la marge
    marge_ecart_abs = comparison.get("marge_ebitda", {}).get("ecart_abs", 0)
    if marge_ecart_abs < -3:

        actions.append({

            "priority": "HAUTE",

            "category": "PRIX",

            "icon": "💵",

            "title": "Révision politique de prix",

            "description": "Marge EBITDA inférieure de plus de 3 points. Analyse prix par segment, optimisation mix Vrac/Sac, révision primes DDP.",

            "impact": "+1 à +2 points de marge potentiels",

            "timeline": "Court terme (2-4 semaines)"

        })

    

    # Actions basées sur la projection

    if projection and projection["vs_historical_ebitda"] < -10:

        actions.append({

            "priority": "CRITIQUE",

            "category": "STRATÉGIQUE",

            "icon": "🎯",

            "title": "Révision annuelle des objectifs",

            "description": f"Projection annuelle EBITDA {projection['vs_historical_ebitda']:.1f}% sous historique. Nécessite réunion direction + ajustement budget.",

            "impact": "Alignement réaliste des attentes",

            "timeline": "Immédiat"

        })

    

    # Actions génériques si peu d'actions spécifiques

    if len(actions) < 2:

        actions.append({

            "priority": "MOYENNE",

            "category": "OPTIMISATION",

            "icon": "🔧",

            "title": "Maintenance prédictive",

            "description": "Déployer capteurs IoT sur broyeurs pour réduire arrêts imprévus. Objectif : OEE > 90%.",

            "impact": "-15% pannes imprévues",

            "timeline": "Moyen terme (3-6 mois)"

        })

        

        actions.append({

            "priority": "MOYENNE",

            "category": "TRÉSORERIE",

            "icon": "🏦",

            "title": "Optimisation BFR",

            "description": "Réduire DSO cible à 30 jours, négocier DPO à 45 jours. Affacturage créances si nécessaire.",

            "impact": f"Libération potentielle : {format_xof(2000000000)}",

            "timeline": "Court terme (1-2 mois)"

        })

    

    return actions







def build_historical_report_html(tf_type, year, month, hist, model, comparison, projection, current_year, current_month, detail_view="mensuel"):

    """Construit le HTML du rapport comparatif avec projections, budget, marge, croissance, saisonnalité, production."""



    # Générer les actions correctives

    actions = generate_corrective_actions(comparison, projection)



    # Déterminer le titre de période

    realized_suffix = ""

    if tf_type == "year":

        period_title = f"Année {year}"

        period_subtitle = "Comparaison annuelle complète"

        _realized_months = sorted(
            int(k.split("-")[1])
            for k in HISTORICAL_FINANCIAL_DATA.keys()
            if k.startswith(f"{year}-")
        )

        if _realized_months and len(_realized_months) < 12:
            realized_suffix = (
                f" <span style='font-size:0.6em; color:#8fa0b8; font-weight:600;'>"
                f"(Réalisé : {len(_realized_months)}/12 mois — "
                f"{MONTHS[_realized_months[0]-1]} → {MONTHS[_realized_months[-1]-1]})</span>"
            )
        elif _realized_months:
            realized_suffix = " <span style='font-size:0.6em; color:#8fa0b8; font-weight:600;'>(Réalisé : 12/12 mois)</span>"

    elif tf_type == "semester":

        period_title = f"S{month} {year}"

        period_subtitle = "Analyse semestrielle détaillée"

    elif tf_type == "quarter":

        period_title = f"T{month} {year}"

        period_subtitle = "Analyse trimestrielle détaillée"

    else:

        period_title = f"{MONTHS[month-1]} {year}"

        period_subtitle = "Analyse mensuelle détaillée"



    # Couleurs selon performance

    perf_color = {
        "SUPÉRIEUR": "#10b981", "SUP. vs BUDGET": "#10b981", "SUP. vs MODÈLE": "#10b981",
        "CONFORME": "#F58220", "INFÉRIEUR": "#ef4444", "INF. vs BUDGET": "#ef4444", "INF. vs MODÈLE": "#ef4444"
    }
    perf_bg = {
        "SUPÉRIEUR": "rgba(16,185,129,0.1)", "SUP. vs BUDGET": "rgba(16,185,129,0.1)", "SUP. vs MODÈLE": "rgba(16,185,129,0.1)",
        "CONFORME": "rgba(251,191,36,0.1)", "INFÉRIEUR": "rgba(239,68,68,0.1)", "INF. vs BUDGET": "rgba(239,68,68,0.1)", "INF. vs MODÈLE": "rgba(239,68,68,0.1)"
    }
    obj_color = {"AMBITIEUX": "#E85D04", "ALIGNÉS": "#1E4D8F", "CONSERVATEURS": "#3b82f6"}
    obj_bg = {"AMBITIEUX": "rgba(232,93,4,0.1)", "ALIGNÉS": "rgba(30,77,143,0.1)", "CONSERVATEURS": "rgba(59,130,246,0.1)"}
    status = comparison.get("performance_status", "NEUTRE")
    obj_status = comparison.get("objective_status", "NEUTRE")



