    hist_budget_ebitda = hist.get("ebitda_budget", 0)

    hist_budget_marge = hist.get("marge_budget", 0) * 100 if hist.get("marge_budget", 0) else 0



    # Taux de réalisation

    tr_ca = safe_div(hist.get("ca_reel", 0), hist_budget_ca, 0) * 100 if hist_budget_ca > 0 else 0

    tr_ebitda = safe_div(hist.get("ebitda_reel", 0), hist_budget_ebitda, 0) * 100 if hist_budget_ebitda > 0 else 0



