    def kpi_card(label, value, delta_text, delta_class="neu", details=None):

        """Render a KPI card with hover-triggered popover showing formula details."""

        with st.container():

            card_id = f"kpi_{label.replace(' ', '_').replace('/', '_').replace('(', '').replace(')', '').replace('%', 'pct')[:30]}"

            if details:

                # Inject tooltip HTML directly into the card

                card_html = f"""<div class="kpi-card" id="{card_id}">{details}<div><div class="kpi-label">{label}</div><div class="kpi-value">{value}</div><div class="kpi-delta {delta_class}">{delta_text}</div></div></div>"""

            else:

                card_html = f"""<div class="kpi-card" id="{card_id}"><div><div class="kpi-label">{label}</div><div class="kpi-value">{value}</div><div class="kpi-delta {delta_class}">{delta_text}</div></div></div>"""

            st.html(card_html)



