                    row = {
                        "Produit": prod,
                        "Mois": m,
                        "Cout_Revient_XOF_t": r["cout_revient"],
                        "Prix_Vente_XOF_t": r["prix_vente"],
                        "Marge_XOF_t": r["marge"],
                        "Marge_Pct": r["marge_pct"],
                        "Annee": dyn_year,
                        "Mode_Expedition": dyn_expedition_mode,
                        "Cout_Transport_XOF_t": dyn_transport_cost if dyn_transport_on else 0,
                        "Ristourne_XOF_t": dyn_ristourne if dyn_ristourne_on else 0,
                        "Marge_Cible_Pct": dyn_marge_cible,
                    }
                    # Add adjustment details
                    details = r["details"]
                    for factor in ["saisonnalite", "transport", "ristourne", "expedition"]:
                        if factor in details["adjustments"]:
                            adj = details["adjustments"][factor]
