if active_tab == 6:  # Expedition


    st.html("<div class='section-title'>📦 Parametres d'Expedition par Produit sur 12 Mois</div>")

    st.info("Le mix expedition est defini par 4 combinaisons: Vrac-EXW, Vrac-DDP, Sac-EXW, Sac-DDP. Chaque combinaison a son propre prix et impact financier.")



    # Build monthly expedition data with 4-way split

    monthly_exp_data = []

    for month_idx in range(12):

        factor = get_monthly_factor(month_idx)

        for prod in PRODUCTS:

            pk = normalize_product_key(prod)

            base_price = get_val(f"price_{pk}")



            # Get 4 mix percentages

            vrac_exw_pct = get_val(f"vrac_exw_pct_{pk}")

            vrac_ddp_pct = get_val(f"vrac_ddp_pct_{pk}")

            sac_exw_pct = get_val(f"sac_exw_pct_{pk}")

            sac_ddp_pct = get_val(f"sac_ddp_pct_{pk}")



            total_vol = sum(get_val(f"vol_{pk}_site{s[-1]}") for s in SITES) * factor



            # Calculate volumes per expedition type

            vol_vrac_exw = total_vol * vrac_exw_pct

            vol_vrac_ddp = total_vol * vrac_ddp_pct

            vol_sac_exw = total_vol * sac_exw_pct

            vol_sac_ddp = total_vol * sac_ddp_pct



            # Calculate prices per expedition type

            price_vrac_exw = base_price + get_val("vrac_premium")

            price_vrac_ddp = base_price + get_val("vrac_premium") + get_val("ddp_premium")

            price_sac_exw = base_price

            price_sac_ddp = base_price + get_val("ddp_premium")



            # Calculate revenues per expedition type

            ca_vrac_exw = vol_vrac_exw * price_vrac_exw / 1e6

            ca_vrac_ddp = vol_vrac_ddp * price_vrac_ddp / 1e6

            ca_sac_exw = vol_sac_exw * price_sac_exw / 1e6

            ca_sac_ddp = vol_sac_ddp * price_sac_ddp / 1e6



            # Weighted average effective price

            total_mix = vrac_exw_pct + vrac_ddp_pct + sac_exw_pct + sac_ddp_pct

            if total_mix > 0:

                effective = (vrac_exw_pct * price_vrac_exw + vrac_ddp_pct * price_vrac_ddp + 

                            sac_exw_pct * price_sac_exw + sac_ddp_pct * price_sac_ddp) / total_mix

            else:

                effective = base_price



            monthly_exp_data.append({

                "Mois": MONTHS[month_idx],

                "Mois_Idx": month_idx,

                "Produit": prod,

                "Volume (t)": total_vol,

                "Vrac-EXW %": vrac_exw_pct * 100,

                "Vrac-DDP %": vrac_ddp_pct * 100,

                "Sac-EXW %": sac_exw_pct * 100,

                "Sac-DDP %": sac_ddp_pct * 100,

                "Prix Base (XOF/t)": base_price,

                "Prix Effectif (XOF/t)": effective,

                "CA Vrac-EXW (M XOF)": ca_vrac_exw,

                "CA Vrac-DDP (M XOF)": ca_vrac_ddp,

                "CA Sac-EXW (M XOF)": ca_sac_exw,

                "CA Sac-DDP (M XOF)": ca_sac_ddp,

            })



    exp_df = pd.DataFrame(monthly_exp_data)



    # Charts

    st.html("<div class='chart-container'>")



    # Chart 1: Monthly revenue by expedition type

    exp_rev_monthly = exp_df.groupby("Mois")[["CA Vrac-EXW (M XOF)", "CA Vrac-DDP (M XOF)", "CA Sac-EXW (M XOF)", "CA Sac-DDP (M XOF)"]].sum().reset_index()

    exp_rev_melted = exp_rev_monthly.melt(id_vars=["Mois"], var_name="Type Expedition", value_name="CA (M XOF)")

    fig1_data = exp_rev_melted

